-- ─── routines/acquire.pre.sql ───
-- CHECK value_constraints_ok of acquire.crawl_schema_version (BR-168)
-- The domain of every extracted field: when value_constraints is given it is an object with
-- min <= max; with `require_numeric_domain` (an active schema) every number, percent or money
-- field declares min, max and unit. IMMUTABLE so it can sit in a CHECK.
CREATE FUNCTION acquire.value_constraints_ok(fields jsonb, require_numeric_domain boolean)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT jsonb_typeof(fields) = 'array' AND NOT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(fields) AS f(field)
    WHERE (
        field ? 'value_constraints' AND jsonb_typeof(field->'value_constraints') <> 'null' AND (
          jsonb_typeof(field->'value_constraints') <> 'object'
          OR (field->'value_constraints' ? 'min' AND field->'value_constraints' ? 'max'
              AND (field->'value_constraints'->>'min')::numeric > (field->'value_constraints'->>'max')::numeric)
        )
      )
      OR (
        require_numeric_domain
        AND field->>'type' IN ('number', 'percent', 'money')
        AND NOT (coalesce(jsonb_typeof(field->'value_constraints') = 'object', false)
                 AND field->'value_constraints' ?& ARRAY['min', 'max', 'unit'])
      )
  )
$$;


-- ═══ schema org ═══
CREATE TABLE org.organization (
  id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  industry_code text,
  status text NOT NULL DEFAULT 'active',
  locale text NOT NULL DEFAULT 'vi-VN',
  time_zone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  identity_provider jsonb NOT NULL DEFAULT '{}',
  settings jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT organization_pkey PRIMARY KEY (id),
  UNIQUE (code),
  CHECK (status IN ('active','suspended'))
);
COMMENT ON TABLE org.organization IS 'Tổ chức (khách hàng) dùng hệ thống; gốc của org_id. Use case: UC-11-08.';
COMMENT ON COLUMN org.organization.code IS 'Mã tổ chức, duy nhất toàn hệ thống';
COMMENT ON COLUMN org.organization.industry_code IS 'Ngành chính, khớp pack.industry_pack.code; chỉ để gợi ý gói';
COMMENT ON COLUMN org.organization.status IS 'active, suspended';
COMMENT ON COLUMN org.organization.locale IS 'Ngôn ngữ mặc định';
COMMENT ON COLUMN org.organization.identity_provider IS 'Kiểu nguồn danh tính (ad, ldap, oidc) và tham chiếu cấu hình Keycloak; không chứa bí mật';
COMMENT ON COLUMN org.organization.settings IS 'Ngưỡng chung, ví dụ tỷ lệ đúng tối thiểu để mở Data Space (NFR-07)';

CREATE TABLE org.app_user (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  kind text NOT NULL DEFAULT 'human',
  external_id text,
  username text NOT NULL,
  display_name text NOT NULL,
  email text,
  department text,
  attributes jsonb NOT NULL DEFAULT '{}',
  owner_user_id uuid,
  status text NOT NULL DEFAULT 'active',
  default_data_space_id uuid,
  last_synced_at timestamptz,
  last_login_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT app_user_pkey PRIMARY KEY (id),
  CHECK (kind IN ('human','agent','service')),
  CHECK (status IN ('active','disabled','left')),
  CHECK (kind <> 'agent' OR owner_user_id IS NOT NULL),
  UNIQUE (org_id, external_id),
  UNIQUE (org_id, username)
);
COMMENT ON TABLE org.app_user IS 'Người dùng, tài khoản agent và tài khoản dịch vụ; người dùng đồng bộ từ nguồn danh tính. Use case: UC-11-01, UC-11-08, UC-13-01.';
COMMENT ON COLUMN org.app_user.kind IS 'human, agent, service';
COMMENT ON COLUMN org.app_user.external_id IS 'Mã ở nguồn danh tính (objectGUID, sub); null với agent';
COMMENT ON COLUMN org.app_user.email IS 'Dữ liệu cá nhân';
COMMENT ON COLUMN org.app_user.department IS 'Đơn vị, dùng cho phạm vi dòng';
COMMENT ON COLUMN org.app_user.attributes IS 'Thuộc tính đồng bộ (chi nhánh, khối, vùng) dùng trong điều kiện chính sách';
COMMENT ON COLUMN org.app_user.owner_user_id IS 'Chủ sở hữu khi kind = agent (BR-147); FK app_user';
COMMENT ON COLUMN org.app_user.status IS 'active, disabled, left';
COMMENT ON COLUMN org.app_user.default_data_space_id IS 'Data Space mở sẵn sau đăng nhập; FK data_space';

CREATE TABLE org.user_group (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  external_id text NOT NULL,
  name text NOT NULL,
  source text NOT NULL DEFAULT 'ad',
  member_count integer NOT NULL DEFAULT 0,
  last_synced_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT user_group_pkey PRIMARY KEY (id),
  UNIQUE (org_id, external_id),
  CHECK (source IN ('ad','ldap','oidc','local'))
);
COMMENT ON TABLE org.user_group IS 'Nhóm người dùng đồng bộ từ nguồn danh tính. Use case: UC-11-01.';
COMMENT ON COLUMN org.user_group.external_id IS 'Mã nhóm ở nguồn danh tính';
COMMENT ON COLUMN org.user_group.name IS 'Ví dụ GRP-RISK-ANALYST';
COMMENT ON COLUMN org.user_group.source IS 'ad, ldap, oidc, local';

CREATE TABLE org.user_group_member (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  group_id uuid NOT NULL,
  user_id uuid NOT NULL,
  synced_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_group_member_pkey PRIMARY KEY (id),
  UNIQUE (group_id, user_id)
);
COMMENT ON TABLE org.user_group_member IS 'Thành viên của nhóm theo lần đồng bộ gần nhất. Use case: UC-11-01.';
COMMENT ON COLUMN org.user_group_member.group_id IS 'FK user_group';
COMMENT ON COLUMN org.user_group_member.user_id IS 'FK app_user';

CREATE TABLE org.role (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  capabilities text[] NOT NULL DEFAULT '{}',
  is_system boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT role_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code)
);
COMMENT ON TABLE org.role IS 'Vai trò và năng lực của vai trò. Use case: UC-11-01.';
COMMENT ON COLUMN org.role.code IS 'AC01 đến AC11 hoặc mã do tổ chức thêm';
COMMENT ON COLUMN org.role.capabilities IS 'Ví dụ ask, view_detail, approve, run_agent, create_agent, admin, audit_read';
COMMENT ON COLUMN org.role.is_system IS 'Vai trò dựng sẵn, không xoá được';

CREATE TABLE org.user_role (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  user_id uuid NOT NULL,
  role_id uuid NOT NULL,
  source text NOT NULL,
  source_ref uuid,
  valid_until timestamptz,
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT user_role_pkey PRIMARY KEY (id),
  CHECK (source IN ('group_mapping','emergency','manual')),
  CHECK (source <> 'emergency' OR (valid_until IS NOT NULL AND approved_by IS NOT NULL)),
  UNIQUE (user_id, role_id, source)
);
COMMENT ON TABLE org.user_role IS 'Vai trò cấp toàn tổ chức (không gắn Data Space), ví dụ Quản trị hệ thống, Kiểm soát. Use case: UC-11-01.';
COMMENT ON COLUMN org.user_role.user_id IS 'FK app_user';
COMMENT ON COLUMN org.user_role.role_id IS 'FK role';
COMMENT ON COLUMN org.user_role.source IS 'group_mapping, emergency, manual';
COMMENT ON COLUMN org.user_role.source_ref IS 'Mã ánh xạ nhóm hoặc yêu cầu khẩn cấp';
COMMENT ON COLUMN org.user_role.valid_until IS 'Bắt buộc với emergency, tối đa 24 giờ (BR-44)';
COMMENT ON COLUMN org.user_role.approved_by IS 'Người thứ hai duyệt tài khoản khẩn cấp';

CREATE TABLE org.data_space (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  steward_id uuid NOT NULL,
  backup_steward_id uuid,
  status text NOT NULL DEFAULT 'draft',
  default_policy jsonb NOT NULL DEFAULT '{}',
  pack_install_id uuid,
  work_calendar_id uuid,
  opened_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_space_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code),
  CHECK (status IN ('draft','onboarding','active','read_only','archived'))
);
COMMENT ON TABLE org.data_space IS 'Không gian dữ liệu của một nhóm nghiệp vụ; ranh giới quyền, nguồn, chỉ số và agent. Use case: UC-04-04, UC-11-08.';
COMMENT ON COLUMN org.data_space.steward_id IS 'Người phụ trách dữ liệu; FK app_user';
COMMENT ON COLUMN org.data_space.backup_steward_id IS 'Người dự phòng (BR-143); FK app_user';
COMMENT ON COLUMN org.data_space.status IS 'draft, onboarding, active, read_only, archived';
COMMENT ON COLUMN org.data_space.default_policy IS 'Bốn cờ trên màn Tạo Data Space: mask_pii, agent_write_derived_only, show_filed_and_current, allow_external_channels';
COMMENT ON COLUMN org.data_space.pack_install_id IS 'logic → pack.pack_install';
COMMENT ON COLUMN org.data_space.work_calendar_id IS 'FK work_calendar';
COMMENT ON COLUMN org.data_space.opened_at IS 'Lúc mở cho người dùng sau khi bộ đánh giá đạt (BR-122)';
COMMENT ON COLUMN org.data_space.deleted_at IS 'Xoá mềm';

CREATE TABLE org.data_space_member (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  principal_type text NOT NULL,
  principal_id uuid NOT NULL,
