  row_scope jsonb,
  source text NOT NULL DEFAULT 'manual',
  source_ref uuid,
  valid_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_space_member_pkey PRIMARY KEY (id),
  CHECK (principal_type IN ('user','group','agent')),
  CHECK (source IN ('group_mapping','manual','access_request')),
  CHECK (source <> 'access_request' OR valid_until IS NOT NULL),
  UNIQUE (data_space_id, principal_type, principal_id, role_id)
);
COMMENT ON TABLE org.data_space_member IS 'Người dùng, nhóm hoặc agent thuộc Data Space, kèm vai trò, phạm vi dòng và hạn dùng. Use case: UC-11-01, UC-11-07, UC-11-08, UC-13-01.';
COMMENT ON COLUMN org.data_space_member.data_space_id IS 'FK data_space';
COMMENT ON COLUMN org.data_space_member.principal_type IS 'user, group, agent';
COMMENT ON COLUMN org.data_space_member.principal_id IS 'app_user.id hoặc user_group.id';
COMMENT ON COLUMN org.data_space_member.role_id IS 'FK role';
COMMENT ON COLUMN org.data_space_member.row_scope IS 'Điều kiện phạm vi dòng, ví dụ {"branch":["HN01","HN02","HN03"]}; null là toàn bộ';
COMMENT ON COLUMN org.data_space_member.source IS 'group_mapping, manual, access_request';
COMMENT ON COLUMN org.data_space_member.source_ref IS 'Mã ánh xạ nhóm hoặc access_request';
COMMENT ON COLUMN org.data_space_member.valid_until IS 'Hết hạn tự thu hồi (BR-142)';

CREATE TABLE org.group_mapping (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  group_id uuid NOT NULL,
  role_id uuid NOT NULL,
  data_space_id uuid,
  row_scope jsonb,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT group_mapping_pkey PRIMARY KEY (id),
  CHECK (status IN ('active','disabled')),
  UNIQUE NULLS NOT DISTINCT (group_id, role_id, data_space_id)
);
COMMENT ON TABLE org.group_mapping IS 'Ánh xạ nhóm sang vai trò, trong một Data Space hoặc toàn tổ chức. Use case: UC-11-01, UC-11-08.';
COMMENT ON COLUMN org.group_mapping.group_id IS 'FK user_group';
COMMENT ON COLUMN org.group_mapping.role_id IS 'FK role';
COMMENT ON COLUMN org.group_mapping.data_space_id IS 'FK data_space; null là vai trò toàn tổ chức';
COMMENT ON COLUMN org.group_mapping.row_scope IS 'Phạm vi dòng áp cho mọi thành viên của nhóm';
COMMENT ON COLUMN org.group_mapping.status IS 'active, disabled';

CREATE TABLE org.access_request (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  requester_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  capability text NOT NULL,
  reason text NOT NULL,
  requested_until date NOT NULL,
  status text NOT NULL DEFAULT 'pending',
  needs_compliance boolean NOT NULL DEFAULT false,
  approver_id uuid,
  decided_at timestamptz,
  decision_note text,
  granted_scope jsonb,
  member_id uuid,
  hitl_request_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT access_request_pkey PRIMARY KEY (id),
  CHECK (capability IN ('view_aggregate','view_detail','ask','run_agent')),
  CHECK (status IN ('pending','approved','narrowed','rejected','expired','cancelled')),
  CHECK (status IN ('pending','cancelled','expired') OR (approver_id IS NOT NULL AND decided_at IS NOT NULL))
);
COMMENT ON TABLE org.access_request IS 'Yêu cầu cấp quyền vào Data Space. Use case: UC-11-07.';
COMMENT ON COLUMN org.access_request.requester_id IS 'FK app_user';
COMMENT ON COLUMN org.access_request.data_space_id IS 'FK data_space';
COMMENT ON COLUMN org.access_request.capability IS 'view_aggregate, view_detail, ask, run_agent';
COMMENT ON COLUMN org.access_request.requested_until IS 'Tối đa 90 ngày kể từ ngày gửi (BR-142)';
COMMENT ON COLUMN org.access_request.status IS 'pending, approved, narrowed, rejected, expired, cancelled';
COMMENT ON COLUMN org.access_request.needs_compliance IS 'Yêu cầu xem chi tiết dữ liệu cá nhân, cần thêm AC06';
COMMENT ON COLUMN org.access_request.approver_id IS 'FK app_user';
COMMENT ON COLUMN org.access_request.granted_scope IS 'Phạm vi thực cấp nếu chủ sở hữu thu hẹp';
COMMENT ON COLUMN org.access_request.member_id IS 'FK data_space_member tạo ra khi duyệt';
COMMENT ON COLUMN org.access_request.hitl_request_id IS 'logic → inbox.hitl_request';

CREATE TABLE org.work_calendar (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  time_zone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  weekend_days smallint[] NOT NULL DEFAULT '{6,7}',
  is_default boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT work_calendar_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code)
);
COMMENT ON TABLE org.work_calendar IS 'Lịch làm việc của tổ chức, dùng cho lịch quét, pipeline, báo cáo, trigger và hạn xử lý. Use case: UC-02-04, UC-04-05, UC-06-03, UC-13-03.';
COMMENT ON COLUMN org.work_calendar.weekend_days IS 'Ngày nghỉ hằng tuần theo ISO (1 = thứ Hai)';
COMMENT ON COLUMN org.work_calendar.is_default IS 'Mỗi tổ chức đúng một lịch mặc định';

CREATE TABLE org.work_calendar_day (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  calendar_id uuid NOT NULL,
  day date NOT NULL,
  kind text NOT NULL,
  name text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT work_calendar_day_pkey PRIMARY KEY (id),
  CHECK (kind IN ('holiday','working_override')),
  UNIQUE (calendar_id, day)
);
COMMENT ON TABLE org.work_calendar_day IS 'Ngày nghỉ lễ và ngày làm việc bù của một lịch. Use case: UC-02-04, UC-04-05, UC-06-03.';
COMMENT ON COLUMN org.work_calendar_day.calendar_id IS 'FK work_calendar';
COMMENT ON COLUMN org.work_calendar_day.kind IS 'holiday, working_override';
COMMENT ON COLUMN org.work_calendar_day.name IS 'Ví dụ Quốc khánh';

CREATE TABLE org.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE org.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON org.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE org.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON org.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA org TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON org.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON org.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON org.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX user_group_member_user_id_idx ON org.user_group_member (user_id);
CREATE INDEX data_space_member_principal_type_principal_id_idx ON org.data_space_member (principal_type, principal_id);
CREATE INDEX data_space_member_valid_until_idx ON org.data_space_member (valid_until) WHERE valid_until IS NOT NULL;
CREATE INDEX access_request_data_space_id_idx ON org.access_request (data_space_id) WHERE status = 'pending';
CREATE UNIQUE INDEX work_calendar_org_id_key ON org.work_calendar (org_id) WHERE is_default;

-- ═══ schema governance ═══
CREATE TABLE governance.access_policy (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  name text NOT NULL,
  kind text NOT NULL,
  applies_to jsonb NOT NULL DEFAULT '{}',
  condition_expr text,
  columns text[],
  mask_method text,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'draft',
  simulated_at timestamptz,
  activated_at timestamptz,
  activated_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT access_policy_pkey PRIMARY KEY (id),
  CHECK (kind IN ('row','column','mask')),
  CHECK (status IN ('draft','active','disabled')),
  CHECK ((kind = 'row' AND condition_expr IS NOT NULL) OR (kind IN ('column','mask') AND columns IS NOT NULL)),
  CHECK (kind <> 'mask' OR mask_method IN ('hash','partial','last4','null')),
  CHECK (status <> 'active' OR simulated_at IS NOT NULL)
);
COMMENT ON TABLE governance.access_policy IS 'Chính sách dữ liệu theo dòng, theo cột và che giá trị; Policy engine viết lại SQL trước khi chạy. Use case: UC-11-02.';
COMMENT ON COLUMN governance.access_policy.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN governance.access_policy.dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN governance.access_policy.kind IS 'row, column, mask';
COMMENT ON COLUMN governance.access_policy.applies_to IS 'Vai trò, nhóm hoặc người áp dụng; rỗng là mọi người';
COMMENT ON COLUMN governance.access_policy.condition_expr IS 'Điều kiện dòng theo thuộc tính người dùng, ví dụ branch_code = :user.branch';
COMMENT ON COLUMN governance.access_policy.columns IS 'Cột bị ẩn hoặc che';
COMMENT ON COLUMN governance.access_policy.mask_method IS 'hash, partial, last4, null';
COMMENT ON COLUMN governance.access_policy.status IS 'draft, active, disabled';
COMMENT ON COLUMN governance.access_policy.simulated_at IS 'Phải mô phỏng trước khi bật';

CREATE TABLE governance.behavior_policy (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  scope text NOT NULL,
  data_space_id uuid,
  subject_id uuid,
  kind text NOT NULL,
  description text NOT NULL,
  condition jsonb NOT NULL DEFAULT '{}',
  action jsonb NOT NULL DEFAULT '{}',
  exceptions jsonb NOT NULL DEFAULT '[]',
  origin text NOT NULL DEFAULT 'manual',
  origin_ref uuid,
  status text NOT NULL DEFAULT 'draft',
  review_at date,
  override_count smallint NOT NULL DEFAULT 0,
  approved_by uuid,
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT behavior_policy_pkey PRIMARY KEY (id),
  CHECK (scope IN ('system','org','data_space','agent','user')),
  CHECK (kind IN ('block','mask','require_approval','auto_handle','allow','budget')),
  CHECK (origin IN ('manual','hitl','pack')),
  CHECK (status IN ('draft','active','disabled','expired')),
  CHECK (origin <> 'hitl' OR review_at IS NOT NULL),
  CHECK (scope <> 'data_space' OR data_space_id IS NOT NULL)
);
COMMENT ON TABLE governance.behavior_policy IS 'Chính sách hành vi của agent và hệ thống: chặn, che, cần duyệt, tự xử lý, cho phép, ngân sách. Use case: UC-07-04, UC-07-08, UC-11-02, UC-13-02.';
COMMENT ON COLUMN governance.behavior_policy.scope IS 'system, org, data_space, agent, user';
COMMENT ON COLUMN governance.behavior_policy.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN governance.behavior_policy.subject_id IS 'Agent hoặc người dùng khi scope là agent, user';
COMMENT ON COLUMN governance.behavior_policy.kind IS 'block, mask, require_approval, auto_handle, allow, budget';
COMMENT ON COLUMN governance.behavior_policy.description IS 'Mô tả bằng lời hiện trên giao diện';
COMMENT ON COLUMN governance.behavior_policy.condition IS 'Điều kiện, ví dụ lệch dưới 0,05% và là ngày chốt kỳ';
COMMENT ON COLUMN governance.behavior_policy.action IS 'Hành động, ví dụ dùng nguồn A, không hỏi lại';
COMMENT ON COLUMN governance.behavior_policy.exceptions IS 'Trường hợp vẫn phải hỏi người';
COMMENT ON COLUMN governance.behavior_policy.origin IS 'manual, hitl, pack';
COMMENT ON COLUMN governance.behavior_policy.origin_ref IS 'logic → inbox.hitl_request khi origin = hitl';
COMMENT ON COLUMN governance.behavior_policy.status IS 'draft, active, disabled, expired';
COMMENT ON COLUMN governance.behavior_policy.review_at IS 'Hạn xem lại; quy tắc từ HITL là 90 ngày (BR-65)';
COMMENT ON COLUMN governance.behavior_policy.override_count IS 'Số lần người dùng sửa kết quả; đến 2 thì tự vô hiệu (BR-65)';

CREATE TABLE governance.policy_backtest (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  policy_kind text NOT NULL,
  policy_id uuid NOT NULL,
  window_from timestamptz NOT NULL,
  window_to timestamptz NOT NULL,
  matched_count integer NOT NULL DEFAULT 0,
  auto_handled_count integer NOT NULL DEFAULT 0,
  blocked_count integer NOT NULL DEFAULT 0,
  changed_result_count integer NOT NULL DEFAULT 0,
  affected_agent_ids uuid[] NOT NULL DEFAULT '{}',
  detail_ref text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT policy_backtest_pkey PRIMARY KEY (id),
  CHECK (policy_kind IN ('access','behavior')),
  CHECK (window_to > window_from)
);
COMMENT ON TABLE governance.policy_backtest IS 'Kết quả chạy thử một chính sách trên dữ liệu lịch sử. Use case: UC-07-08, UC-11-02.';
COMMENT ON COLUMN governance.policy_backtest.policy_kind IS 'access, behavior';
COMMENT ON COLUMN governance.policy_backtest.policy_id IS 'access_policy.id hoặc behavior_policy.id';
COMMENT ON COLUMN governance.policy_backtest.changed_result_count IS 'Số truy vấn đổi kết quả (UC-11-02 bước 4)';
COMMENT ON COLUMN governance.policy_backtest.detail_ref IS 'Đường dẫn MinIO tới chi tiết';

CREATE TABLE governance.retention_policy (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_kind text NOT NULL,
  retain_days integer NOT NULL,
  action text NOT NULL DEFAULT 'archive',
  target text NOT NULL,
  legal_basis text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT retention_policy_pkey PRIMARY KEY (id),
  UNIQUE (org_id, data_kind),
  CHECK (action IN ('delete','archive','anonymize')),
  CHECK (retain_days > 0)
);
COMMENT ON TABLE governance.retention_policy IS 'Thời hạn lưu theo loại dữ liệu; job lưu trữ đọc bảng này. Quy tắc: BR-47, BR-57, BR-105.';
COMMENT ON COLUMN governance.retention_policy.data_kind IS 'Ví dụ audit_log, query_run, dlq_record, upload_table, prompt_log';
COMMENT ON COLUMN governance.retention_policy.action IS 'delete, archive, anonymize';
COMMENT ON COLUMN governance.retention_policy.target IS 'schema.bảng hoặc bucket MinIO';

CREATE TABLE governance.dsr_request (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  subject_hash text NOT NULL,
  request_kind text NOT NULL,
  received_at timestamptz NOT NULL,
  due_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'open',
  handler_id uuid NOT NULL,
  response_ref text,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT dsr_request_pkey PRIMARY KEY (id),
  CHECK (request_kind IN ('access','copy','delete','correct')),
  CHECK (status IN ('open','searching','review','executing','done','rejected'))
);
COMMENT ON TABLE governance.dsr_request IS 'Yêu cầu của chủ thể dữ liệu (biết, nhận bản sao, xoá, sửa). Use case: UC-11-06.';
COMMENT ON COLUMN governance.dsr_request.subject_hash IS 'HMAC-SHA256 của định danh đã chuẩn hoá, khoá theo tổ chức lưu trong OpenBao (băm trần của số CCCD dò ngược được); không lưu định danh gốc. Sửa 12/10/2026';
COMMENT ON COLUMN governance.dsr_request.request_kind IS 'access, copy, delete, correct';
COMMENT ON COLUMN governance.dsr_request.due_at IS 'Hạn luật định; nhắc trước 5 ngày làm việc (BR-141)';
COMMENT ON COLUMN governance.dsr_request.status IS 'open, searching, review, executing, done, rejected';
COMMENT ON COLUMN governance.dsr_request.handler_id IS 'AC06; logic → org.app_user';
COMMENT ON COLUMN governance.dsr_request.response_ref IS 'Biên bản trả lời trong MinIO';

CREATE TABLE governance.dsr_item (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  dsr_request_id uuid NOT NULL,
  location_kind text NOT NULL,
  location_ref text NOT NULL,
  proposed_action text NOT NULL,
  legal_basis text,
  decision text NOT NULL DEFAULT 'pending',
  executed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT dsr_item_pkey PRIMARY KEY (id),
  CHECK (proposed_action IN ('delete','provide','retain')),
  CHECK (decision IN ('pending','done','retained')),
  CHECK (proposed_action <> 'retain' OR legal_basis IS NOT NULL)
);
COMMENT ON TABLE governance.dsr_item IS 'Một vị trí tìm thấy dữ liệu của chủ thể và cách xử lý. Use case: UC-11-06.';
COMMENT ON COLUMN governance.dsr_item.dsr_request_id IS 'FK dsr_request';
COMMENT ON COLUMN governance.dsr_item.location_kind IS 'chunk, tile_snapshot, derived_table, conversation, agent_memory, source_system';
COMMENT ON COLUMN governance.dsr_item.location_ref IS 'schema.bảng:id hoặc mô tả vị trí ở nguồn';
COMMENT ON COLUMN governance.dsr_item.proposed_action IS 'delete, provide, retain';
COMMENT ON COLUMN governance.dsr_item.legal_basis IS 'Bắt buộc khi retain';
COMMENT ON COLUMN governance.dsr_item.decision IS 'pending, done, retained';

CREATE TABLE governance.model_config (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  task text NOT NULL,
  version integer NOT NULL,
  model_name text NOT NULL,
  endpoint text NOT NULL,
  fallback_model text,
  limits jsonb NOT NULL DEFAULT '{}',
  rollout_pct smallint NOT NULL DEFAULT 100,
  eval_run_id uuid,
  status text NOT NULL DEFAULT 'draft',
  activated_at timestamptz,
  activated_by uuid,
  provider_id uuid NOT NULL,
  route_role text NOT NULL DEFAULT 'primary',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT model_config_pkey PRIMARY KEY (id),
  UNIQUE (org_id, task, version),
  CHECK (status IN ('draft','testing','active','retired')),
  CHECK (rollout_pct BETWEEN 0 AND 100),
  CHECK (status <> 'active' OR task IN ('embedding','ocr') OR eval_run_id IS NOT NULL),
  CHECK (route_role IN ('primary','frontier_candidate'))
);
COMMENT ON TABLE governance.model_config IS 'Mô hình AI theo tác vụ, có phiên bản; phiên bản mới chỉ áp dụng khi bộ đánh giá đạt. Use case: UC-11-05, UC-13-04.';
COMMENT ON COLUMN governance.model_config.task IS 'planning, sql_generation, answer_writing, doc_reading, embedding, reranking, ocr, pii_classification';
COMMENT ON COLUMN governance.model_config.model_name IS 'Ví dụ Qwen3-Coder-32B';
COMMENT ON COLUMN governance.model_config.endpoint IS 'Cụm và địa chỉ phục vụ trong mạng nội bộ';
COMMENT ON COLUMN governance.model_config.limits IS 'max_tokens, concurrency, ngân sách theo Data Space';
COMMENT ON COLUMN governance.model_config.rollout_pct IS 'Chuyển dần, ví dụ 10% trong 24 giờ';
COMMENT ON COLUMN governance.model_config.eval_run_id IS 'logic → eval.eval_run';
COMMENT ON COLUMN governance.model_config.status IS 'draft, testing, active, retired';
COMMENT ON COLUMN governance.model_config.provider_id IS 'FK model_provider; bản cài tạo sẵn provider onprem-vllm và gán cho mọi dòng cũ (thêm 10/10/2026, ADR-41)';
COMMENT ON COLUMN governance.model_config.route_role IS 'primary (mô hình tại chỗ mặc định), frontier_candidate (chỉ dùng khi lời gọi đạt BR-180)';

CREATE TABLE governance.ai_setting (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  key text NOT NULL,
  value jsonb NOT NULL,
  version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT ai_setting_pkey PRIMARY KEY (id),
  UNIQUE (org_id, key)
);
COMMENT ON TABLE governance.ai_setting IS 'Quy định AI dạng khoá–giá trị: chi phí tối đa mỗi lượt chạy, bộ lọc đầu vào, đầu ra, thời hạn lưu prompt. Use case: UC-11-05.';
COMMENT ON COLUMN governance.ai_setting.key IS 'max_cost_per_run, input_filter, output_filter, prompt_log_retention_days, frontier_routing ({enabled, tasks, data_space_ids}; cờ bật định tuyến frontier theo tổ chức, mặc định {"enabled": false}, BR-180)';
COMMENT ON COLUMN governance.ai_setting.version IS 'Tăng mỗi lần sửa; bản cũ ghi vào audit_log';

CREATE TABLE governance.model_usage (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid,
  task text NOT NULL,
  model_name text NOT NULL,
  caller_kind text NOT NULL,
  caller_id uuid,
  input_tokens integer NOT NULL DEFAULT 0,
  output_tokens integer NOT NULL DEFAULT 0,
  latency_ms integer NOT NULL DEFAULT 0,
  outcome text NOT NULL DEFAULT 'ok',
  called_at timestamptz NOT NULL DEFAULT now(),
  provider_id uuid,
  route_decision_id uuid,
  CONSTRAINT model_usage_pkey PRIMARY KEY (id, called_at),
  CHECK (outcome IN ('ok','error','fallback'))
) PARTITION BY RANGE (called_at);
CREATE TABLE governance.model_usage_default PARTITION OF governance.model_usage DEFAULT;
COMMENT ON TABLE governance.model_usage IS 'Số token và thời gian của từng lượt gọi mô hình. Use case: UC-11-04, UC-11-05.';
COMMENT ON COLUMN governance.model_usage.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN governance.model_usage.caller_kind IS 'question, agent_run, skill_run, document, eval';
COMMENT ON COLUMN governance.model_usage.outcome IS 'ok, error, fallback';
COMMENT ON COLUMN governance.model_usage.provider_id IS 'FK model_provider; null với dòng trước 10/10/2026';
COMMENT ON COLUMN governance.model_usage.route_decision_id IS 'logic → model_route_decision (bảng phân vùng); có khi tác vụ có ứng viên frontier';

CREATE TABLE governance.model_provider (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  display_name text NOT NULL,
  kind text NOT NULL,
  api_style text NOT NULL DEFAULT 'openai_compatible',
  endpoint text NOT NULL,
  secret_ref text,
  data_region text,
  zero_retention boolean NOT NULL DEFAULT false,
  contract_ref text,
  max_classification text NOT NULL DEFAULT 'restricted',
  enabled boolean NOT NULL DEFAULT false,
  enabled_by uuid,
  approved_by uuid,
  approved_at timestamptz,
  price jsonb NOT NULL DEFAULT '{}',
  monthly_budget_vnd numeric(14,0),
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT model_provider_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code),
  CHECK (code ~ '^[a-z0-9][a-z0-9-]{1,39}$'),
  CHECK (kind IN ('on_prem','frontier')),
  CHECK (api_style IN ('openai_compatible','anthropic_messages','google_genai','other')),
  CHECK (max_classification IN ('public','internal','confidential','restricted')),
  CHECK (status IN ('active','suspended','retired')),
  CHECK (kind <> 'frontier' OR (endpoint LIKE 'https://%' AND secret_ref IS NOT NULL AND data_region IS NOT NULL AND max_classification = 'public')),
  CHECK (NOT (kind = 'frontier' AND enabled) OR (zero_retention AND enabled_by IS NOT NULL AND approved_by IS NOT NULL AND approved_at IS NOT NULL AND approved_by <> enabled_by)),
  CHECK (monthly_budget_vnd IS NULL OR monthly_budget_vnd >= 0)
);
COMMENT ON TABLE governance.model_provider IS 'Provider mô hình khai báo theo tổ chức: tại chỗ (vLLM) hoặc frontier (API bên ngoài). Tên nhà cung cấp là dữ liệu cấu hình, mã nguồn không rẽ nhánh theo tên; khoá API chỉ nằm ở OpenBao (BR-180, BR-181, ADR-41). Thêm 10/10/2026. Use case: UC-11-05, UC-01-07.';
COMMENT ON COLUMN governance.model_provider.code IS 'Mã do quản trị đặt, ví dụ onprem-vllm, frontier-a';
COMMENT ON COLUMN governance.model_provider.display_name IS 'Tên hiển thị trên biên nhận, ví dụ “vLLM tại chỗ”, “Nhà cung cấp A (API)”';
COMMENT ON COLUMN governance.model_provider.kind IS 'on_prem, frontier';
COMMENT ON COLUMN governance.model_provider.api_style IS 'openai_compatible, anthropic_messages, google_genai, other; LiteLLM chọn bộ chuyển theo giá trị này';
COMMENT ON COLUMN governance.model_provider.endpoint IS 'URL gốc; với frontier phải là https và có trong danh sách đích của egress proxy';
COMMENT ON COLUMN governance.model_provider.secret_ref IS 'Đường dẫn khoá API trong OpenBao, ví dụ kv/data-agent/providers/frontier-a; bắt buộc với frontier; CSDL không lưu khoá';
COMMENT ON COLUMN governance.model_provider.data_region IS 'Vùng xử lý dữ liệu theo hợp đồng, ví dụ ap-southeast-1; bắt buộc với frontier';
COMMENT ON COLUMN governance.model_provider.zero_retention IS 'Hợp đồng cam kết không lưu và không dùng dữ liệu để huấn luyện; frontier chỉ bật được khi true';
COMMENT ON COLUMN governance.model_provider.contract_ref IS 'Số hợp đồng, phụ lục xử lý dữ liệu';
COMMENT ON COLUMN governance.model_provider.max_classification IS 'Mức phân loại cao nhất được gửi; on_prem mặc định restricted; frontier bắt buộc public';
COMMENT ON COLUMN governance.model_provider.enabled IS 'Cờ bật theo tổ chức';
COMMENT ON COLUMN governance.model_provider.enabled_by IS 'logic → org.app_user (AC05)';
COMMENT ON COLUMN governance.model_provider.approved_by IS 'logic → org.app_user (AC06); bắt buộc khi frontier enabled, khác enabled_by';
COMMENT ON COLUMN governance.model_provider.price IS 'Giá theo triệu token vào, ra cho từng mô hình, để tính chi phí (UC-11-04)';
COMMENT ON COLUMN governance.model_provider.monthly_budget_vnd IS 'Ngân sách tháng; vượt thì Model gateway ngừng đường frontier tới đầu tháng sau';
COMMENT ON COLUMN governance.model_provider.status IS 'active, suspended, retired';

CREATE TABLE governance.model_route_decision (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid,
  task text NOT NULL,
  caller_kind text NOT NULL,
  caller_id uuid,
  data_product_id uuid,
  product_scope text NOT NULL,
  context_labels text[] NOT NULL DEFAULT '{}',
  max_classification text NOT NULL,
  contains_internal_data boolean NOT NULL,
  pii_redactions integer NOT NULL DEFAULT 0,
  candidate_provider_id uuid,
  decision text NOT NULL,
  reasons text[] NOT NULL DEFAULT '{}',
  chosen_provider_id uuid NOT NULL,
  model_name text NOT NULL,
  prompt_sha256 text NOT NULL,
  input_tokens integer,
  output_tokens integer,
  outcome text NOT NULL DEFAULT 'pending',
  model_usage_id uuid,
  decided_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT model_route_decision_pkey PRIMARY KEY (id, decided_at),
  CHECK (caller_kind IN ('question','agent_run','skill_run','document','eval')),
  CHECK (product_scope IN ('in_scope','out_of_scope','not_applicable')),
  CHECK (max_classification IN ('public','internal','confidential','restricted')),
  CHECK (context_labels <@ ARRAY['public','internal','confidential','restricted','unlabeled']),
  CHECK (decision IN ('on_prem_default','frontier_allowed','frontier_blocked')),
  CHECK (outcome IN ('pending','ok','error','fallback_on_prem')),
  CHECK (pii_redactions >= 0),
  CHECK (prompt_sha256 ~ '^[0-9a-f]{64}$'),
  CHECK (decision <> 'frontier_allowed' OR (candidate_provider_id IS NOT NULL AND chosen_provider_id = candidate_provider_id AND NOT ('pii_remaining' = ANY(reasons)) AND (max_classification = 'public' OR (product_scope = 'out_of_scope' AND NOT contains_internal_data)))),
  CHECK (decision = 'frontier_allowed' OR candidate_provider_id IS NULL OR chosen_provider_id <> candidate_provider_id),
  CHECK (decision <> 'frontier_blocked' OR cardinality(reasons) > 0)
) PARTITION BY RANGE (decided_at);
CREATE TABLE governance.model_route_decision_default PARTITION OF governance.model_route_decision DEFAULT;
COMMENT ON TABLE governance.model_route_decision IS 'Quyết định định tuyến của mỗi lời gọi mô hình mà tác vụ có ứng viên frontier: nhãn dữ liệu trong ngữ cảnh, phạm vi data product, lý do, provider được chọn, mã băm prompt sau khi che, số token. Ghi trước khi gọi; lời gọi bị chặn sang tại chỗ cũng ghi (BR-180, BR-181). Không lưu nội dung prompt. Thêm 10/10/2026. Use case: UC-11-05, UC-01-07.';
COMMENT ON COLUMN governance.model_route_decision.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN governance.model_route_decision.task IS 'Tác vụ như model_config.task';
COMMENT ON COLUMN governance.model_route_decision.caller_kind IS 'question, agent_run, skill_run, document, eval';
COMMENT ON COLUMN governance.model_route_decision.data_product_id IS 'logic → context.data_product; null khi ngoài phạm vi';
COMMENT ON COLUMN governance.model_route_decision.product_scope IS 'in_scope, out_of_scope, not_applicable';
COMMENT ON COLUMN governance.model_route_decision.context_labels IS 'Nhãn của mọi phần trong ngữ cảnh: public, internal, confidential, restricted, unlabeled';
COMMENT ON COLUMN governance.model_route_decision.max_classification IS 'Mức cao nhất; phần unlabeled tính là internal';
COMMENT ON COLUMN governance.model_route_decision.contains_internal_data IS 'Prompt có kết quả truy vấn nội bộ, đoạn tài liệu nội bộ, tên bảng cột, ghi nhớ agent hoặc thực thể nội bộ trong câu hỏi';
COMMENT ON COLUMN governance.model_route_decision.pii_redactions IS 'Số cụm dữ liệu cá nhân đã che trước khi xét';
COMMENT ON COLUMN governance.model_route_decision.candidate_provider_id IS 'FK model_provider; provider frontier ứng viên';
COMMENT ON COLUMN governance.model_route_decision.decision IS 'on_prem_default, frontier_allowed, frontier_blocked';
COMMENT ON COLUMN governance.model_route_decision.reasons IS 'org_disabled, task_not_allowed, provider_disabled, budget_exceeded, label_not_public, internal_data, pii_remaining, allowed_public_only, allowed_out_of_scope';
COMMENT ON COLUMN governance.model_route_decision.chosen_provider_id IS 'FK model_provider đã gọi';
COMMENT ON COLUMN governance.model_route_decision.prompt_sha256 IS 'SHA-256 của prompt sau khi che, đúng nội dung gửi đi';
COMMENT ON COLUMN governance.model_route_decision.input_tokens IS 'Điền sau lời gọi';
COMMENT ON COLUMN governance.model_route_decision.outcome IS 'pending, ok, error, fallback_on_prem';
COMMENT ON COLUMN governance.model_route_decision.model_usage_id IS 'logic → model_usage';

CREATE TABLE governance.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE governance.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON governance.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE governance.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON governance.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA governance TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON governance.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON governance.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON governance.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX access_policy_dataset_id_idx ON governance.access_policy (dataset_id) WHERE status = 'active';
CREATE INDEX behavior_policy_scope_data_space_id_idx ON governance.behavior_policy (scope, data_space_id) WHERE status = 'active';
CREATE INDEX behavior_policy_review_at_idx ON governance.behavior_policy (review_at) WHERE status = 'active';
CREATE INDEX policy_backtest_policy_kind_policy_id_idx ON governance.policy_backtest (policy_kind, policy_id);
CREATE INDEX dsr_request_due_at_idx ON governance.dsr_request (due_at) WHERE status NOT IN ('done','rejected');
CREATE INDEX model_config_org_id_task_idx ON governance.model_config (org_id, task) WHERE status = 'active';
CREATE UNIQUE INDEX model_config_org_id_task_route_role_key ON governance.model_config (org_id, task, route_role) WHERE status = 'active' AND rollout_pct = 100;
CREATE INDEX model_usage_data_space_id_called_at_idx ON governance.model_usage (data_space_id, called_at);
CREATE INDEX model_usage_provider_id_called_at_idx ON governance.model_usage (provider_id, called_at);
CREATE INDEX model_provider_org_id_kind_idx ON governance.model_provider (org_id, kind) WHERE enabled AND status = 'active';
CREATE INDEX model_route_decision_caller_kind_caller_id_idx ON governance.model_route_decision (caller_kind, caller_id);
CREATE INDEX model_route_decision_chosen_provider_id_decided_at_idx ON governance.model_route_decision (chosen_provider_id, decided_at);
CREATE INDEX model_route_decision_decision_decided_at_idx ON governance.model_route_decision (decision, decided_at) WHERE decision <> 'on_prem_default';

-- ═══ schema integration ═══
CREATE TABLE integration.api_client (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  name text NOT NULL,
  kind text NOT NULL,
  identity_mode text NOT NULL DEFAULT 'on_behalf_of_user',
  owner_user_id uuid NOT NULL,
  keycloak_client_id text NOT NULL,
  secret_ref text NOT NULL,
  tools text[] NOT NULL DEFAULT '{}',
  data_space_ids uuid[] NOT NULL DEFAULT '{}',
  quota_per_minute integer NOT NULL DEFAULT 60,
  quota_per_day integer NOT NULL DEFAULT 5000,
  expires_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'active',
  owner_confirmed_at timestamptz,
  secret_rotated_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT api_client_pkey PRIMARY KEY (id),
  CHECK (kind IN ('rest','mcp')),
  CHECK (identity_mode IN ('on_behalf_of_user','own_identity')),
  CHECK (status IN ('pending_owner','active','paused','revoked','expired')),
  CHECK (status NOT IN ('active','paused') OR owner_confirmed_at IS NOT NULL),
  CHECK (expires_at <= created_at + interval '12 months'),
  UNIQUE (org_id, keycloak_client_id)
);
COMMENT ON TABLE integration.api_client IS 'Client gọi Data Agent qua REST hoặc MCP; thông tin đăng ký trong Keycloak, bí mật trong OpenBao. Use case: UC-12-01, UC-12-02, UC-12-04.';
COMMENT ON COLUMN integration.api_client.name IS 'Ví dụ Copilot nội bộ, Excel add-in';
COMMENT ON COLUMN integration.api_client.kind IS 'rest, mcp';
COMMENT ON COLUMN integration.api_client.identity_mode IS 'on_behalf_of_user (token exchange) hoặc own_identity (BR-48)';
COMMENT ON COLUMN integration.api_client.owner_user_id IS 'Đầu mối của client; logic → org.app_user';
COMMENT ON COLUMN integration.api_client.secret_ref IS 'Đường dẫn OpenBao; không lưu bí mật';
COMMENT ON COLUMN integration.api_client.tools IS 'Công cụ được gọi, ví dụ ask, get_metric, run_skill; hỗ trợ dấu * (hitl.*)';
COMMENT ON COLUMN integration.api_client.data_space_ids IS 'Data Space được phép; logic → org.data_space';
COMMENT ON COLUMN integration.api_client.expires_at IS 'Tối đa 12 tháng kể từ khi cấp (BR-144); giao diện hiện “Sắp hết hạn” khi còn dưới 30 ngày';
COMMENT ON COLUMN integration.api_client.status IS 'pending_owner, active, paused, revoked, expired; pending_owner khi người cấp không phải người phụ trách: client chưa gọi được cho tới khi người phụ trách xác nhận (BR-48)';
COMMENT ON COLUMN integration.api_client.owner_confirmed_at IS 'Lúc người phụ trách đồng ý để client hành động với quyền của mình (BR-48); bằng created_at khi người cấp chính là người phụ trách. Mở rộng tools hoặc data_space_ids bởi người khác đặt lại về rỗng và status về pending_owner';
COMMENT ON COLUMN integration.api_client.secret_rotated_at IS 'Bí mật cũ còn hiệu lực 24 giờ sau lần xoay';

CREATE TABLE integration.webhook_subscription (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  api_client_id uuid NOT NULL,
  event_types text[] NOT NULL,
  target_url text NOT NULL,
  signing_key_ref text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  consecutive_failures smallint NOT NULL DEFAULT 0,
  paused_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT webhook_subscription_pkey PRIMARY KEY (id),
  CHECK (status IN ('active','paused')),
  CHECK (target_url ~ '^https://')
);
COMMENT ON TABLE integration.webhook_subscription IS 'Đăng ký nhận sự kiện của một client; mỗi lần gửi có chữ ký HMAC. Use case: UC-12-03.';
COMMENT ON COLUMN integration.webhook_subscription.api_client_id IS 'FK api_client';
COMMENT ON COLUMN integration.webhook_subscription.event_types IS 'Loại sự kiện ở mục 9.3, ví dụ hitl.created, report.delivered';
COMMENT ON COLUMN integration.webhook_subscription.target_url IS 'Phải nằm trong danh sách đích được phép của proxy ra ngoài';
COMMENT ON COLUMN integration.webhook_subscription.signing_key_ref IS 'Khoá HMAC trong OpenBao';
COMMENT ON COLUMN integration.webhook_subscription.status IS 'active, paused';
COMMENT ON COLUMN integration.webhook_subscription.consecutive_failures IS 'Đến 3 thì tự tạm dừng (UC-12-03 E1)';

CREATE TABLE integration.webhook_delivery (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  subscription_id uuid NOT NULL,
  event_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL,
  attempt_count smallint NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'pending',
  last_status_code smallint,
  last_error text,
  next_attempt_at timestamptz,
  delivered_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT webhook_delivery_pkey PRIMARY KEY (id, created_at),
  CHECK (status IN ('pending','delivered','retrying','failed')),
  CHECK (attempt_count BETWEEN 0 AND 6)
) PARTITION BY RANGE (created_at);
CREATE TABLE integration.webhook_delivery_default PARTITION OF integration.webhook_delivery DEFAULT;
COMMENT ON TABLE integration.webhook_delivery IS 'Một lần gửi một sự kiện tới một đăng ký, kèm các lần thử lại. Use case: UC-12-03.';
COMMENT ON COLUMN integration.webhook_delivery.subscription_id IS 'logic → webhook_subscription (không đặt khoá ngoại vì bảng phân vùng)';
COMMENT ON COLUMN integration.webhook_delivery.event_id IS 'Mã sự kiện, gửi ở header để bên nhận chống trùng';
COMMENT ON COLUMN integration.webhook_delivery.payload IS 'Chỉ mã đối tượng và tóm tắt, không có dữ liệu chi tiết (BR-145)';
COMMENT ON COLUMN integration.webhook_delivery.attempt_count IS 'Tối đa 6 lần trong 24 giờ';
COMMENT ON COLUMN integration.webhook_delivery.status IS 'pending, delivered, retrying, failed';

CREATE TABLE integration.usage_counter (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  api_client_id uuid NOT NULL,
  tool text NOT NULL,
  data_space_id uuid,
  minute timestamptz NOT NULL,
  calls integer NOT NULL DEFAULT 0,
  errors integer NOT NULL DEFAULT 0,
  blocked_by_permission integer NOT NULL DEFAULT 0,
  blocked_by_quota integer NOT NULL DEFAULT 0,
  p95_ms integer,
  CONSTRAINT usage_counter_pkey PRIMARY KEY (id, minute),
  UNIQUE (api_client_id, tool, data_space_id, minute)
) PARTITION BY RANGE (minute);
CREATE TABLE integration.usage_counter_default PARTITION OF integration.usage_counter DEFAULT;
COMMENT ON TABLE integration.usage_counter IS 'Đếm lượt gọi theo phút cho mỗi client, công cụ, Data Space; nguồn của màn Client & sử dụng. Use case: UC-12-02, UC-12-04.';
COMMENT ON COLUMN integration.usage_counter.api_client_id IS 'logic → api_client';
COMMENT ON COLUMN integration.usage_counter.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN integration.usage_counter.minute IS 'Đầu phút';
COMMENT ON COLUMN integration.usage_counter.blocked_by_permission IS 'Lượt bị chặn do người dùng không có quyền dữ liệu';

CREATE TABLE integration.idempotency_key (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  key text NOT NULL,
  principal_id uuid NOT NULL,
  request_hash text NOT NULL,
  response_status smallint,
  response_ref text,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '24 hours',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT idempotency_key_pkey PRIMARY KEY (id),
  UNIQUE (org_id, principal_id, key)
);
COMMENT ON TABLE integration.idempotency_key IS 'Khoá chống gửi trùng ở gateway: cùng khoá trong 24 giờ trả lại kết quả cũ. Tham chiếu: mục 9.1.';
COMMENT ON COLUMN integration.idempotency_key.key IS 'Header Idempotency-Key do client gửi';
COMMENT ON COLUMN integration.idempotency_key.principal_id IS 'Người hoặc client gửi';
COMMENT ON COLUMN integration.idempotency_key.request_hash IS 'Băm phương thức, đường dẫn và thân; khác băm thì trả 422';
COMMENT ON COLUMN integration.idempotency_key.response_ref IS 'Thân phản hồi lưu tạm (Redis hoặc MinIO)';

CREATE TABLE integration.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE integration.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON integration.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE integration.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON integration.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA integration TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON integration.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON integration.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON integration.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX api_client_expires_at_idx ON integration.api_client (expires_at) WHERE status = 'active';
CREATE INDEX webhook_delivery_next_attempt_at_idx ON integration.webhook_delivery (next_attempt_at) WHERE status IN ('pending','retrying');
CREATE INDEX webhook_delivery_subscription_id_created_at_idx ON integration.webhook_delivery (subscription_id, created_at);
CREATE INDEX usage_counter_api_client_id_minute_idx ON integration.usage_counter (api_client_id, minute);
CREATE INDEX idempotency_key_expires_at_idx ON integration.idempotency_key (expires_at);

-- ═══ schema catalog ═══
CREATE TABLE catalog.source (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  name text NOT NULL,
  kind text NOT NULL,
  connector_icon text,
  host text,
  port integer,
  database_name text,
  conn_options jsonb NOT NULL DEFAULT '{}',
  secret_ref text NOT NULL,
  writeback_secret_ref text,
  writeback_tables text[] NOT NULL DEFAULT '{}',
  mode text NOT NULL DEFAULT 'federated',
  authority_level text NOT NULL DEFAULT 'reference',
  freshness_sla interval,
  max_concurrency smallint NOT NULL DEFAULT 4,
  query_timeout_s integer NOT NULL DEFAULT 120,
  scan_schemas text[] NOT NULL DEFAULT '{}',
  scan_cron text,
  profile_cron text,
  scan_window jsonb,
  work_calendar_id uuid,
  status text NOT NULL DEFAULT 'draft',
  status_reason text,
  last_checked_at timestamptz,
  db_version text,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT source_pkey PRIMARY KEY (id),
  CHECK (kind IN ('postgresql','oracle','sqlserver','mysql','snowflake','bigquery','databricks','clickhouse','kafka_cdc','object_store','file','sftp','sharepoint','rest_api','other')),
  CHECK (mode IN ('federated','ingest')),
  CHECK (mode = 'ingest' OR kind IN ('postgresql','oracle','sqlserver','mysql','snowflake','bigquery','databricks','clickhouse')),
  CHECK (authority_level IN ('level_1','level_2','level_3','reference')),
  CHECK (status IN ('draft','testing','active','needs_fix','paused','archived')),
  CHECK (max_concurrency BETWEEN 1 AND 64 AND query_timeout_s BETWEEN 5 AND 3600),
  UNIQUE (data_space_id, name)
);
COMMENT ON TABLE catalog.source IS 'Kết nối tới một nguồn dữ liệu của tổ chức (CSDL, kho dữ liệu, API, tệp, CDC). Use case: UC-04-01, UC-04-04, UC-04-05, UC-07-05.';
COMMENT ON COLUMN catalog.source.data_space_id IS 'Data Space sở hữu; logic → org.data_space';
COMMENT ON COLUMN catalog.source.name IS 'Ví dụ Core banking, DWH bán lẻ';
COMMENT ON COLUMN catalog.source.kind IS 'postgresql, oracle, sqlserver, mysql, snowflake, bigquery, databricks, clickhouse, kafka_cdc, object_store, file, sftp, sharepoint, rest_api, other';
COMMENT ON COLUMN catalog.source.connector_icon IS 'Mã biểu tượng ConnectorIcon trên giao diện';
COMMENT ON COLUMN catalog.source.conn_options IS 'TLS, schema mặc định, tham số riêng của từng loại';
COMMENT ON COLUMN catalog.source.secret_ref IS 'Đường dẫn OpenBao (BR-14); không lưu mật khẩu';
COMMENT ON COLUMN catalog.source.writeback_secret_ref IS 'Tài khoản ghi ngược riêng (UC-06-04); null là không cho ghi ngược';
COMMENT ON COLUMN catalog.source.writeback_tables IS 'Bảng đích được phép ghi ngược (schema.bảng); rỗng là không bảng nào (UC-06-04, thêm 12/10/2026)';
COMMENT ON COLUMN catalog.source.mode IS 'federated (truy vấn tại chỗ) hoặc ingest (nạp về)';
COMMENT ON COLUMN catalog.source.authority_level IS 'level_1, level_2, level_3, reference';
COMMENT ON COLUMN catalog.source.freshness_sla IS 'Hạn độ mới; quá hạn thì trạng thái needs_fix (BR-56)';
COMMENT ON COLUMN catalog.source.max_concurrency IS 'BR-99';
COMMENT ON COLUMN catalog.source.query_timeout_s IS 'BR-99';
COMMENT ON COLUMN catalog.source.scan_schemas IS 'Schema được quét';
COMMENT ON COLUMN catalog.source.scan_window IS 'Khung giờ được phép quét theo ngày trong tuần (BR-103)';
COMMENT ON COLUMN catalog.source.work_calendar_id IS 'logic → org.work_calendar';
COMMENT ON COLUMN catalog.source.status IS 'draft, testing, active, needs_fix, paused, archived';
COMMENT ON COLUMN catalog.source.status_reason IS 'Ví dụ trễ quá hạn độ mới, lỗi kết nối';
COMMENT ON COLUMN catalog.source.db_version IS 'Phiên bản CSDL nguồn đọc được khi kiểm tra';
COMMENT ON COLUMN catalog.source.deleted_at IS 'Xoá mềm';

CREATE TABLE catalog.scan_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  source_id uuid NOT NULL,
  kind text NOT NULL,
  trigger text NOT NULL,
  workflow_id text,
  status text NOT NULL DEFAULT 'running',
  tables_total integer,
  tables_scanned integer NOT NULL DEFAULT 0,
  tables_skipped jsonb NOT NULL DEFAULT '[]',
  resume_from text,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT scan_run_pkey PRIMARY KEY (id),
  CHECK (kind IN ('schema','profile')),
  CHECK (trigger IN ('initial','schedule','manual','query_error','cdc_schema_change')),
  CHECK (status IN ('running','succeeded','partial','failed','cancelled'))
);
COMMENT ON TABLE catalog.scan_run IS 'Một lần quét schema hoặc thống kê của một nguồn. Use case: UC-04-01, UC-04-02, UC-04-05.';
COMMENT ON COLUMN catalog.scan_run.source_id IS 'FK source';
COMMENT ON COLUMN catalog.scan_run.kind IS 'schema, profile';
COMMENT ON COLUMN catalog.scan_run.trigger IS 'initial, schedule, manual, query_error, cdc_schema_change';
COMMENT ON COLUMN catalog.scan_run.workflow_id IS 'Mã workflow Temporal';
COMMENT ON COLUMN catalog.scan_run.status IS 'running, succeeded, partial, failed, cancelled';
COMMENT ON COLUMN catalog.scan_run.tables_skipped IS 'Bảng bỏ qua kèm lý do (UC-04-02 E1)';
COMMENT ON COLUMN catalog.scan_run.resume_from IS 'Bảng tiếp tục ở lượt sau khi hết khung giờ (BR-103)';

CREATE TABLE catalog.dataset (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  source_id uuid,
  data_space_id uuid NOT NULL,
  origin text NOT NULL DEFAULT 'source',
  schema_name text NOT NULL,
  table_name text NOT NULL,
  object_kind text NOT NULL DEFAULT 'table',
  display_name text,
  description text,
  description_status text NOT NULL DEFAULT 'none',
  row_estimate bigint,
  history_kind text NOT NULL DEFAULT 'none',
  business_date_col text,
  knowledge_time_col text,
  enabled boolean NOT NULL DEFAULT false,
  steward_id uuid,
  scope text NOT NULL DEFAULT 'data_space',
  expires_at timestamptz,
  current_version integer NOT NULL DEFAULT 1,
  quality_state text NOT NULL DEFAULT 'unknown',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT dataset_pkey PRIMARY KEY (id),
  CHECK (origin IN ('source','derived','upload','data_product','consolidated')),
  CHECK ((origin = 'source') = (source_id IS NOT NULL)),
  CHECK (object_kind IN ('table','view','materialized_view')),
  CHECK (description_status IN ('none','suggested','approved')),
  CHECK (history_kind IN ('none','scd2','snapshot','temporal')),
  CHECK (scope IN ('personal','data_space')),
  CHECK (quality_state IN ('unknown','ok','warning','blocked')),
  CHECK (origin <> 'upload' OR expires_at IS NOT NULL),
  UNIQUE NULLS NOT DISTINCT (data_space_id, source_id, schema_name, table_name)
);
COMMENT ON TABLE catalog.dataset IS 'Bảng hoặc view ở nguồn, hoặc bảng dẫn xuất và bảng tải tay trong vùng làm việc. Use case: UC-04-02, UC-04-04, UC-04-06, UC-04-08, UC-06-01, UC-06-02, UC-06-05.';
COMMENT ON COLUMN catalog.dataset.source_id IS 'FK source; null với bảng dẫn xuất, bảng tải tay';
COMMENT ON COLUMN catalog.dataset.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN catalog.dataset.origin IS 'source, derived, upload, data_product, consolidated (dataset hợp nhất của P14, UC-14-05)';
COMMENT ON COLUMN catalog.dataset.object_kind IS 'table, view, materialized_view';
COMMENT ON COLUMN catalog.dataset.description_status IS 'none, suggested, approved (BR-100)';
COMMENT ON COLUMN catalog.dataset.history_kind IS 'none, scd2, snapshot, temporal';
COMMENT ON COLUMN catalog.dataset.business_date_col IS 'Cột ngày nghiệp vụ, dùng cho hỏi theo thời điểm (UC-10-01)';
COMMENT ON COLUMN catalog.dataset.knowledge_time_col IS 'Cột thời điểm ghi nhận, dùng cho chế độ at';
COMMENT ON COLUMN catalog.dataset.enabled IS 'Chỉ bảng bật mới vào ngữ cảnh và truy vấn được (BR-102)';
COMMENT ON COLUMN catalog.dataset.steward_id IS 'logic → org.app_user';
COMMENT ON COLUMN catalog.dataset.scope IS 'personal, data_space (BR-111)';
COMMENT ON COLUMN catalog.dataset.expires_at IS 'Bảng tải tay, mặc định 90 ngày (BR-105)';
COMMENT ON COLUMN catalog.dataset.current_version IS 'Khớp dataset_version mới nhất';
COMMENT ON COLUMN catalog.dataset.quality_state IS 'unknown, ok, warning, blocked (BR-116)';
COMMENT ON COLUMN catalog.dataset.deleted_at IS 'Xoá mềm';

CREATE TABLE catalog.dataset_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  version integer NOT NULL,
  schema_hash text NOT NULL,
  diff jsonb,
  change_kind text NOT NULL DEFAULT 'initial',
  proposal_id uuid,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  scan_run_id uuid,
  certified_at timestamptz,
  certified_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT dataset_version_pkey PRIMARY KEY (id),
  UNIQUE (dataset_id, version),
  CHECK (change_kind IN ('initial','additive','breaking')),
  CHECK (change_kind <> 'breaking' OR proposal_id IS NOT NULL),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  CHECK ((certified_at IS NULL) = (certified_by IS NULL)),
  CHECK (certified_by IS NULL OR (created_by IS NOT NULL AND certified_by <> created_by))
);
COMMENT ON TABLE catalog.dataset_version IS 'Phiên bản cấu trúc của một bảng; ánh xạ cũ đóng valid_to thay vì xoá (BR-16). Use case: UC-04-02, UC-04-03, UC-04-06, UC-04-07, UC-10-01.';
COMMENT ON COLUMN catalog.dataset_version.dataset_id IS 'FK dataset';
COMMENT ON COLUMN catalog.dataset_version.schema_hash IS 'Băm danh sách cột và kiểu';
COMMENT ON COLUMN catalog.dataset_version.diff IS 'So với bản trước: cột thêm, xoá, đổi tên, đổi kiểu';
COMMENT ON COLUMN catalog.dataset_version.change_kind IS 'initial, additive, breaking';
COMMENT ON COLUMN catalog.dataset_version.proposal_id IS 'logic → inbox.proposal; null khi chỉ thêm cột (UC-04-03 1a)';
COMMENT ON COLUMN catalog.dataset_version.scan_run_id IS 'FK scan_run';
COMMENT ON COLUMN catalog.dataset_version.certified_at IS 'Lúc người phụ trách dữ liệu chứng nhận phiên bản dataset hợp nhất; null là chưa chứng nhận hoặc đã thu hồi, khi đó không dùng làm số báo cáo cơ quan quản lý (BR-156). Trạng thái hiện hành, lịch sử ở dataset_version_certification';
COMMENT ON COLUMN catalog.dataset_version.certified_by IS 'logic → org.app_user; người phụ trách dữ liệu (steward_id hoặc backup_steward_id của Data Space chứa dataset), khác created_by (BR-156)';

CREATE TABLE catalog.dataset_version_certification (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  dataset_version_id uuid NOT NULL,
  action text NOT NULL,
  actor_id uuid NOT NULL,
  note text,
  reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT dataset_version_certification_pkey PRIMARY KEY (id),
  CHECK (action IN ('certify','revoke')),
  CHECK (action <> 'revoke' OR (reason IS NOT NULL AND btrim(reason) <> ''))
);
COMMENT ON TABLE catalog.dataset_version_certification IS 'Lịch sử chứng nhận và thu hồi chứng nhận phiên bản dataset hợp nhất, chỉ ghi thêm (D1 mục 6). Mỗi lần chứng nhận hoặc thu hồi là một dòng; trigger áp dòng mới vào certified_at, certified_by của dataset_version và ghi catalog.outbox trong cùng giao dịch. Thêm 10/10/2026 (BR-156). Use case: UC-14-05.';
COMMENT ON COLUMN catalog.dataset_version_certification.dataset_version_id IS 'FK dataset_version';
COMMENT ON COLUMN catalog.dataset_version_certification.action IS 'certify, revoke';
COMMENT ON COLUMN catalog.dataset_version_certification.actor_id IS 'logic → org.app_user; người phụ trách dữ liệu chứng nhận hoặc thu hồi';
COMMENT ON COLUMN catalog.dataset_version_certification.note IS 'Ghi chú khi chứng nhận';
COMMENT ON COLUMN catalog.dataset_version_certification.reason IS 'Lý do thu hồi; bắt buộc khi action = revoke';

CREATE TABLE catalog.column_meta (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  dataset_version integer NOT NULL,
  removed_in_version integer,
  name text NOT NULL,
  ordinal smallint NOT NULL,
  data_type text NOT NULL,
  normalized_type text NOT NULL,
  is_nullable boolean NOT NULL DEFAULT true,
  is_key boolean NOT NULL DEFAULT false,
  display_name text,
  description text,
  description_status text NOT NULL DEFAULT 'none',
  unit text,
  pii_label text,
  pii_confirmed boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT column_meta_pkey PRIMARY KEY (id),
  UNIQUE (dataset_id, name, dataset_version),
  CHECK (normalized_type IN ('string','integer','decimal','boolean','date','timestamp','json','binary')),
  CHECK (description_status IN ('none','suggested','approved')),
  CHECK (pii_label IS NULL OR pii_label IN ('national_id','phone','email','account_no','name','address','other'))
);
COMMENT ON TABLE catalog.column_meta IS 'Cột của một bảng theo phiên bản cấu trúc. Use case: UC-04-02, UC-04-03, UC-04-04, UC-04-08.';
COMMENT ON COLUMN catalog.column_meta.dataset_id IS 'FK dataset';
COMMENT ON COLUMN catalog.column_meta.dataset_version IS 'Phiên bản đầu tiên có cột này';
COMMENT ON COLUMN catalog.column_meta.removed_in_version IS 'Phiên bản cột bị xoá';
COMMENT ON COLUMN catalog.column_meta.data_type IS 'Kiểu ở nguồn';
COMMENT ON COLUMN catalog.column_meta.normalized_type IS 'string, integer, decimal, boolean, date, timestamp, json, binary';
COMMENT ON COLUMN catalog.column_meta.description_status IS 'none, suggested, approved';
COMMENT ON COLUMN catalog.column_meta.unit IS 'Ví dụ VND, triệu VND, %';
COMMENT ON COLUMN catalog.column_meta.pii_label IS 'Nhãn dữ liệu cá nhân: national_id, phone, email, account_no, name, address, other';
COMMENT ON COLUMN catalog.column_meta.pii_confirmed IS 'Người phụ trách đã xác nhận cách che (UC-04-04 bước 3)';

CREATE TABLE catalog.column_profile (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  column_id uuid NOT NULL,
  scan_run_id uuid NOT NULL,
  sample_rows integer NOT NULL,
  null_ratio numeric(6,5),
  distinct_est bigint,
  min_value text,
  max_value text,
  top_values jsonb,
  pattern_hint text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT column_profile_pkey PRIMARY KEY (id),
  UNIQUE (column_id, scan_run_id),
  CHECK (null_ratio IS NULL OR null_ratio BETWEEN 0 AND 1)
);
COMMENT ON TABLE catalog.column_profile IS 'Thống kê giá trị của một cột ở một lần quét; giá trị phổ biến của cột có nhãn cá nhân đã được che. Use case: UC-04-02.';
COMMENT ON COLUMN catalog.column_profile.column_id IS 'FK column_meta';
COMMENT ON COLUMN catalog.column_profile.scan_run_id IS 'FK scan_run';
COMMENT ON COLUMN catalog.column_profile.top_values IS '[{value, count}], đã che nếu có nhãn cá nhân';
COMMENT ON COLUMN catalog.column_profile.pattern_hint IS 'Mẫu giá trị nhận ra, ví dụ số điện thoại, ngày dd/mm/yyyy';

CREATE TABLE catalog.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE catalog.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON catalog.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE catalog.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON catalog.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA catalog TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON catalog.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON catalog.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON catalog.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX source_data_space_id_idx ON catalog.source (data_space_id) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX scan_run_source_id_kind_key ON catalog.scan_run (source_id, kind) WHERE status = 'running';
CREATE INDEX dataset_data_space_id_idx ON catalog.dataset (data_space_id) WHERE enabled AND deleted_at IS NULL;
CREATE INDEX dataset_expires_at_idx ON catalog.dataset (expires_at) WHERE origin = 'upload';
CREATE INDEX dataset_version_certification_dataset_version_id_created_at ON catalog.dataset_version_certification (dataset_version_id, created_at DESC);
CREATE INDEX column_meta_dataset_id_idx ON catalog.column_meta (dataset_id) WHERE removed_in_version IS NULL;
CREATE INDEX column_meta_dataset_id_idx_2 ON catalog.column_meta (dataset_id) WHERE pii_label IS NOT NULL;

-- ═══ schema context ═══
CREATE TABLE context.semantic_entity (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  primary_dataset_id uuid NOT NULL,
  key_columns text[] NOT NULL,
  canonical_entity_id uuid,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT semantic_entity_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (status IN ('draft','active','retired'))
);
COMMENT ON TABLE context.semantic_entity IS 'Thực thể trong mô hình ngữ nghĩa của Data Space (ví dụ khách hàng, hợp đồng, giao dịch), ánh xạ tới một bảng chính. Use case: UC-07-01, UC-07-02.';
COMMENT ON COLUMN context.semantic_entity.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN context.semantic_entity.primary_dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN context.semantic_entity.canonical_entity_id IS 'logic → pack.canonical_entity nếu sinh từ gói ngành';
COMMENT ON COLUMN context.semantic_entity.status IS 'draft, active, retired';

CREATE TABLE context.semantic_dimension (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  entity_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  expression text NOT NULL,
  parent_dimension_id uuid,
  value_index_enabled boolean NOT NULL DEFAULT true,
  is_time boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT semantic_dimension_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code)
);
COMMENT ON TABLE context.semantic_dimension IS 'Chiều phân tích (ví dụ vùng, đơn vị, sản phẩm, kênh), có thể phân cấp. Use case: UC-07-01.';
COMMENT ON COLUMN context.semantic_dimension.entity_id IS 'FK semantic_entity';
COMMENT ON COLUMN context.semantic_dimension.expression IS 'Cột hoặc biểu thức SQL';
COMMENT ON COLUMN context.semantic_dimension.parent_dimension_id IS 'Chiều cha trong phân cấp, ví dụ chi nhánh thuộc vùng';
COMMENT ON COLUMN context.semantic_dimension.value_index_enabled IS 'Lập chỉ mục giá trị để khớp tên gọi trong câu hỏi';

CREATE TABLE context.semantic_measure (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  entity_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  expression text NOT NULL,
  aggregation text NOT NULL,
  unit text,
  additivity text NOT NULL DEFAULT 'full',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT semantic_measure_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (aggregation IN ('sum','count','count_distinct','avg','min','max','last')),
  CHECK (additivity IN ('full','semi','none'))
);
COMMENT ON TABLE context.semantic_measure IS 'Độ đo gốc để ghép thành chỉ số (ví dụ tổng giá trị, số lượng). Use case: UC-07-01.';
COMMENT ON COLUMN context.semantic_measure.entity_id IS 'FK semantic_entity';
COMMENT ON COLUMN context.semantic_measure.expression IS 'Ví dụ SUM(outstanding_amt)';
COMMENT ON COLUMN context.semantic_measure.aggregation IS 'sum, count, count_distinct, avg, min, max, last';
COMMENT ON COLUMN context.semantic_measure.additivity IS 'full, semi (không cộng theo thời gian), none (BR-117)';

CREATE TABLE context.metric (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  owner_id uuid NOT NULL,
  consumer_group text,
  canonical_dataset_id uuid,
  pack_metric_id uuid,
  current_version integer,
  in_filed_report boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT metric_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (status IN ('draft','active','retired'))
);
COMMENT ON TABLE context.metric IS 'Chỉ số nghiệp vụ; định nghĩa nằm ở metric_version. Mã không đổi sau khi phát hành (BR-26). Use case: UC-07-01.';
COMMENT ON COLUMN context.metric.code IS 'Ví dụ NPL_RATIO';
COMMENT ON COLUMN context.metric.owner_id IS 'Chủ sở hữu duyệt mọi thay đổi; logic → org.app_user';
COMMENT ON COLUMN context.metric.consumer_group IS 'Người dùng chính, nhận thông báo khi đổi phiên bản';
COMMENT ON COLUMN context.metric.canonical_dataset_id IS 'Nguồn chuẩn; logic → catalog.dataset';
COMMENT ON COLUMN context.metric.pack_metric_id IS 'logic → pack.pack_metric nếu đến từ gói ngành';
COMMENT ON COLUMN context.metric.current_version IS 'Phiên bản đang dùng';
COMMENT ON COLUMN context.metric.in_filed_report IS 'Có trong báo cáo đã nộp; không xoá được (BR-27)';
COMMENT ON COLUMN context.metric.status IS 'draft, active, retired';

CREATE TABLE context.metric_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  metric_id uuid NOT NULL,
  version integer NOT NULL,
  display_name text NOT NULL,
  description text,
  expression text NOT NULL,
  filters jsonb NOT NULL DEFAULT '[]',
  unit text,
  decimals smallint NOT NULL DEFAULT 2,
  direction text NOT NULL DEFAULT 'neutral',
  period_semantics text NOT NULL,
  time_grain text NOT NULL DEFAULT 'day',
  allowed_dimensions uuid[] NOT NULL DEFAULT '{}',
  additivity text NOT NULL DEFAULT 'none',
  legal_basis text,
  override_id uuid,
  change_note text,
  status text NOT NULL DEFAULT 'draft',
  certified_by uuid,
  certified_at timestamptz,
  valid_from timestamptz,
  valid_to timestamptz,
  proposal_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT metric_version_pkey PRIMARY KEY (id),
  UNIQUE (metric_id, version),
  CHECK (direction IN ('higher_better','lower_better','neutral')),
  CHECK (period_semantics IN ('end_of_period','sum_over_period','average_over_period')),
  CHECK (time_grain IN ('day','month','quarter','year')),
  CHECK (additivity IN ('full','semi','none')),
  CHECK (status IN ('draft','testing','pending_review','certified','superseded','broken')),
  CHECK (status NOT IN ('certified','superseded') OR (certified_by IS NOT NULL AND certified_at IS NOT NULL AND valid_from IS NOT NULL))
);
COMMENT ON TABLE context.metric_version IS 'Định nghĩa của chỉ số theo phiên bản: công thức, đơn vị, chiều, kỳ, căn cứ, chứng nhận. Use case: UC-01-02, UC-02-02, UC-04-03, UC-06-05, UC-07-01, UC-09-03, UC-10-03.';
COMMENT ON COLUMN context.metric_version.metric_id IS 'FK metric';
COMMENT ON COLUMN context.metric_version.display_name IS 'Ví dụ Nợ xấu (%)';
COMMENT ON COLUMN context.metric_version.description IS 'Định nghĩa bằng lời';
COMMENT ON COLUMN context.metric_version.expression IS 'Công thức trên độ đo, có bộ lọc';
COMMENT ON COLUMN context.metric_version.filters IS 'Bộ lọc mặc định';
COMMENT ON COLUMN context.metric_version.direction IS 'higher_better, lower_better, neutral (“Chiều tốt” trên màn Chỉ số)';
COMMENT ON COLUMN context.metric_version.period_semantics IS 'end_of_period, sum_over_period, average_over_period';
COMMENT ON COLUMN context.metric_version.time_grain IS 'day, month, quarter, year';
COMMENT ON COLUMN context.metric_version.allowed_dimensions IS 'logic → semantic_dimension';
COMMENT ON COLUMN context.metric_version.additivity IS 'full, semi, none (BR-117)';
COMMENT ON COLUMN context.metric_version.legal_basis IS 'Căn cứ, ví dụ điều khoản văn bản';
COMMENT ON COLUMN context.metric_version.override_id IS 'logic → pack.metric_override nếu là bản hiệu chỉnh (BR-129)';
COMMENT ON COLUMN context.metric_version.change_note IS 'Ví dụ Loại vay nội bộ';
COMMENT ON COLUMN context.metric_version.status IS 'draft, testing, pending_review, certified, superseded, broken';
COMMENT ON COLUMN context.metric_version.proposal_id IS 'logic → inbox.proposal';

CREATE TABLE context.relationship (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  from_dataset_id uuid NOT NULL,
  from_columns text[] NOT NULL,
  to_dataset_id uuid NOT NULL,
  to_columns text[] NOT NULL,
  cardinality text NOT NULL,
  origin text NOT NULL DEFAULT 'declared',
  overlap_ratio numeric(5,4),
  status text NOT NULL DEFAULT 'pending_review',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT relationship_pkey PRIMARY KEY (id),
  CHECK (cardinality IN ('one_to_one','many_to_one','one_to_many')),
  CHECK (origin IN ('declared','inferred','manual','pack')),
  CHECK (status IN ('pending_review','active','rejected')),
  CHECK (origin <> 'inferred' OR status <> 'active' OR updated_by IS NOT NULL)
);
COMMENT ON TABLE context.relationship IS 'Quan hệ giữa hai bảng; quan hệ suy ra chỉ dùng sau khi duyệt (BR-100). Use case: UC-04-02, UC-07-02.';
COMMENT ON COLUMN context.relationship.from_dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN context.relationship.cardinality IS 'one_to_one, many_to_one, one_to_many';
COMMENT ON COLUMN context.relationship.origin IS 'declared, inferred, manual, pack';
COMMENT ON COLUMN context.relationship.overlap_ratio IS 'Độ trùng giá trị khi suy ra';
COMMENT ON COLUMN context.relationship.status IS 'pending_review, active, rejected';

CREATE TABLE context.synonym (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  phrase text NOT NULL,
  phrase_norm text NOT NULL,
  target_kind text NOT NULL,
  target_id uuid NOT NULL,
  target_value text,
  origin text NOT NULL DEFAULT 'manual',
  status text NOT NULL DEFAULT 'pending_review',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT synonym_pkey PRIMARY KEY (id),
  CHECK (target_kind IN ('metric','dimension','measure','entity','value','column')),
  CHECK (origin IN ('manual','agent_suggested','pack')),
  CHECK (status IN ('pending_review','active','rejected'))
);
COMMENT ON TABLE context.synonym IS 'Cách gọi khác của chỉ số, chiều, cột hoặc giá trị. Use case: UC-07-01, UC-07-02, UC-07-09.';
COMMENT ON COLUMN context.synonym.phrase IS 'Cụm từ người dùng hay nói';
COMMENT ON COLUMN context.synonym.phrase_norm IS 'Đã bỏ dấu, chữ thường, dùng để khớp';
COMMENT ON COLUMN context.synonym.target_kind IS 'metric, dimension, measure, entity, value, column';
COMMENT ON COLUMN context.synonym.target_value IS 'Giá trị cụ thể khi target_kind = value';
COMMENT ON COLUMN context.synonym.origin IS 'manual, agent_suggested, pack';
COMMENT ON COLUMN context.synonym.status IS 'pending_review, active, rejected';

CREATE TABLE context.value_index (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  dimension_id uuid NOT NULL,
  value_code text NOT NULL,
  value_label text NOT NULL,
  label_norm text NOT NULL,
  row_count bigint,
  refreshed_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT value_index_pkey PRIMARY KEY (id),
  UNIQUE (dimension_id, value_code)
);
COMMENT ON TABLE context.value_index IS 'Giá trị phân loại của chiều, dùng để khớp tên gọi trong câu hỏi (ví dụ “Hải Phòng” khớp mã HP01). Use case: UC-07-02.';
COMMENT ON COLUMN context.value_index.dimension_id IS 'FK semantic_dimension';

CREATE TABLE context.example_query (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  question text NOT NULL,
  sql text NOT NULL,
  metric_ids uuid[] NOT NULL DEFAULT '{}',
  qdrant_point_id uuid,
  origin text NOT NULL DEFAULT 'manual',
  last_verified_at timestamptz,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT example_query_pkey PRIMARY KEY (id),
  CHECK (origin IN ('manual','agent_suggested','feedback','pack')),
  CHECK (status IN ('draft','pending_review','active','stale','rejected'))
);
COMMENT ON TABLE context.example_query IS 'Câu hỏi mẫu kèm SQL đúng; chỉ dùng làm mẫu khi đã duyệt và còn chạy đúng (BR-118). Use case: UC-07-02.';
COMMENT ON COLUMN context.example_query.qdrant_point_id IS 'Điểm vector trong collection example_queries';
COMMENT ON COLUMN context.example_query.origin IS 'manual, agent_suggested, feedback, pack';
COMMENT ON COLUMN context.example_query.status IS 'draft, pending_review, active, stale, rejected';

CREATE TABLE context.glossary_term (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  term text NOT NULL,
  term_norm text NOT NULL,
  definition text NOT NULL,
  meanings jsonb NOT NULL DEFAULT '[]',
  default_meaning smallint,
  legal_basis text,
  status text NOT NULL DEFAULT 'pending_review',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT glossary_term_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, term_norm),
  CHECK (status IN ('pending_review','active','retired'))
);
COMMENT ON TABLE context.glossary_term IS 'Thuật ngữ nghiệp vụ: định nghĩa, ánh xạ, nghĩa mặc định khi có nhiều nghĩa. Use case: UC-07-09.';
COMMENT ON COLUMN context.glossary_term.term IS 'Ví dụ nợ xấu';
COMMENT ON COLUMN context.glossary_term.meanings IS 'Các nghĩa và ánh xạ đích, mỗi nghĩa có điều kiện phải hỏi';
COMMENT ON COLUMN context.glossary_term.default_meaning IS 'Chỉ số trong meanings';
COMMENT ON COLUMN context.glossary_term.status IS 'pending_review, active, retired';

CREATE TABLE context.unmapped_phrase (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  phrase_norm text NOT NULL,
  sample_questions text[] NOT NULL DEFAULT '{}',
  ask_count integer NOT NULL DEFAULT 1,
  suggested_target jsonb,
  first_seen_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  status text NOT NULL DEFAULT 'open',
  CONSTRAINT unmapped_phrase_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, phrase_norm),
  CHECK (status IN ('open','mapped','ignored'))
);
COMMENT ON TABLE context.unmapped_phrase IS 'Cụm từ người dùng hỏi mà chưa ánh xạ được (BR-80). Use case: UC-01-03, UC-07-09.';
COMMENT ON COLUMN context.unmapped_phrase.sample_questions IS 'Tối đa 5 câu ví dụ, đã che dữ liệu cá nhân';
COMMENT ON COLUMN context.unmapped_phrase.suggested_target IS 'Gợi ý ánh xạ của agent';
COMMENT ON COLUMN context.unmapped_phrase.status IS 'open, mapped, ignored';

CREATE TABLE context.user_term_pref (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  user_id uuid NOT NULL,
  glossary_term_id uuid NOT NULL,
  meaning_index smallint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT user_term_pref_pkey PRIMARY KEY (id),
  UNIQUE (user_id, glossary_term_id)
);
COMMENT ON TABLE context.user_term_pref IS 'Cách hiểu riêng của một người với thuật ngữ; không áp cho báo cáo phát hành (BR-123). Use case: UC-07-09.';
COMMENT ON COLUMN context.user_term_pref.user_id IS 'logic → org.app_user';
COMMENT ON COLUMN context.user_term_pref.glossary_term_id IS 'FK glossary_term';

CREATE TABLE context.knowledge_page (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  kind text NOT NULL,
  subject_kind text NOT NULL,
  subject_ref text,
  slug text NOT NULL,
  title text NOT NULL,
  index_summary text NOT NULL DEFAULT '',
  tags text[] NOT NULL DEFAULT '{}',
  owner_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  stale_reason text,
  current_version_id uuid,
  latest_version_no integer NOT NULL DEFAULT 0,
  required_data_space_ids uuid[] NOT NULL DEFAULT '{}',
  classification text NOT NULL DEFAULT 'internal',
  pii_column_refs text[] NOT NULL DEFAULT '{}',
  has_external_source boolean NOT NULL DEFAULT false,
  certification_suspended boolean NOT NULL DEFAULT false,
  policy_state text NOT NULL DEFAULT 'pending',
  policy_computed_at timestamptz,
  last_read_at timestamptz,
  read_count_30d integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT knowledge_page_pkey PRIMARY KEY (id),
  CHECK (kind IN ('metric','entity','source','topic')),
  CHECK (kind = 'topic' OR subject_ref IS NOT NULL),
  CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,79}$'),
  CHECK (char_length(index_summary) <= 300),
  CHECK (status IN ('draft','active','stale','retired')),
  CHECK (status NOT IN ('active','stale') OR current_version_id IS NOT NULL),
  CHECK (status <> 'stale' OR stale_reason IS NOT NULL),
  CHECK (classification IN ('public','internal','confidential','restricted')),
  CHECK (policy_state IN ('pending','current')),
  UNIQUE (data_space_id, slug)
);
COMMENT ON TABLE context.knowledge_page IS 'Trang tri thức của Data Space: loại (chỉ số, thực thể, nguồn, chủ đề), chủ thể, dòng mục lục, phiên bản đang phục vụ và chính sách tính từ nguồn (BR-163). Trang không xoá; ngừng bằng status = retired. Thêm 10/10/2026. Use case: UC-07-10, UC-07-11, UC-07-12.';
COMMENT ON COLUMN context.knowledge_page.data_space_id IS 'logic → org.data_space; Data Space chủ của trang';
COMMENT ON COLUMN context.knowledge_page.kind IS 'metric, entity, source, topic';
COMMENT ON COLUMN context.knowledge_page.subject_kind IS 'metric, organization, product, segment, branch, channel, dataset, document_collection, crawl_source, topic; không có loại cá nhân (BR-167)';
COMMENT ON COLUMN context.knowledge_page.subject_ref IS 'Mã chỉ số, khoá thực thể chuẩn (ví dụ NHB), id nguồn; null với trang chủ đề';
COMMENT ON COLUMN context.knowledge_page.slug IS 'Tên ngắn dùng trong liên kết [[slug]], ví dụ ngan-hang-b';
COMMENT ON COLUMN context.knowledge_page.index_summary IS 'Một dòng tối đa 300 ký tự cho mục lục planner đọc trước';
COMMENT ON COLUMN context.knowledge_page.owner_id IS 'logic → org.app_user; người phụ trách trang';
COMMENT ON COLUMN context.knowledge_page.status IS 'draft, active, stale, retired';
COMMENT ON COLUMN context.knowledge_page.stale_reason IS 'Loại phát hiện làm trang cần xem lại; bắt buộc khi stale';
COMMENT ON COLUMN context.knowledge_page.current_version_id IS 'FK knowledge_page_version đang phục vụ (reviewed hoặc certified)';
COMMENT ON COLUMN context.knowledge_page.latest_version_no IS 'Số phiên bản lớn nhất đã tạo';
COMMENT ON COLUMN context.knowledge_page.required_data_space_ids IS 'Hợp Data Space của mọi nguồn phiên bản đang phục vụ; người đọc cần quyền trên tất cả (BR-163)';
COMMENT ON COLUMN context.knowledge_page.classification IS 'public, internal, confidential, restricted; mức cao nhất của nguồn';
COMMENT ON COLUMN context.knowledge_page.pii_column_refs IS 'Cột dữ liệu cá nhân mà chỗ giữ số chạm tới; số được che theo quyền người đọc';
COMMENT ON COLUMN context.knowledge_page.has_external_source IS 'Có nguồn ngoài (dataset hợp nhất P14); câu trả lời mang nhãn nguồn ngoài (BR-165)';
COMMENT ON COLUMN context.knowledge_page.certification_suspended IS 'Nguồn ngoài bị thu hồi chứng nhận; trang tạm mất hiệu lực chứng nhận (BR-165)';
COMMENT ON COLUMN context.knowledge_page.policy_state IS 'pending, current; pending thì ẩn với người đọc (BR-163)';
COMMENT ON COLUMN context.knowledge_page.last_read_at IS 'Lần đọc gần nhất; dùng rà trang mồ côi';

CREATE TABLE context.knowledge_page_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  page_id uuid NOT NULL,
  version integer NOT NULL,
  parent_version_id uuid,
  status text NOT NULL DEFAULT 'draft',
  origin text NOT NULL,
  body text NOT NULL,
  body_sha256 text NOT NULL,
  summary text NOT NULL DEFAULT '',
  change_note text,
  change_size text NOT NULL DEFAULT 'minor',
  knowledge_run_id uuid,
  agent_run_id uuid,
  source_answer_id uuid,
  proposal_id uuid,
  reviewed_by uuid,
  reviewed_at timestamptz,
  certified_by uuid,
  certified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT knowledge_page_version_pkey PRIMARY KEY (id),
  UNIQUE (page_id, version),
  CHECK (version > 0),
  CHECK (status IN ('draft','pending_review','reviewed','certified','rejected','superseded')),
  CHECK (origin IN ('ingest','lint_fix','saveback','manual')),
  CHECK (change_size IN ('minor','major')),
  CHECK (char_length(body) BETWEEN 1 AND 20000),
  CHECK (body_sha256 ~ '^[0-9a-f]{64}$'),
  CHECK (origin <> 'saveback' OR source_answer_id IS NOT NULL),
  CHECK (status NOT IN ('reviewed','certified','superseded') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CHECK (reviewed_by IS NULL OR reviewed_by <> created_by)
);
COMMENT ON TABLE context.knowledge_page_version IS 'Một phiên bản trang: mẫu thân trang, trạng thái duyệt, người duyệt và người chứng nhận. Nội dung bất biến; sửa là tạo phiên bản mới (BR-164, ADR-13). Thêm 10/10/2026. Use case: UC-07-10, UC-07-11, UC-07-12.';
COMMENT ON COLUMN context.knowledge_page_version.page_id IS 'FK knowledge_page';
COMMENT ON COLUMN context.knowledge_page_version.version IS 'Tăng dần theo trang, trigger điền';
COMMENT ON COLUMN context.knowledge_page_version.parent_version_id IS 'FK knowledge_page_version; mặc định là phiên bản đang phục vụ';
COMMENT ON COLUMN context.knowledge_page_version.status IS 'draft, pending_review, reviewed, certified, rejected, superseded';
COMMENT ON COLUMN context.knowledge_page_version.origin IS 'ingest, lint_fix, saveback, manual';
COMMENT ON COLUMN context.knowledge_page_version.body IS 'Mẫu thân trang Markdown với {{claim:..}}, {{metric:..}}, {{agg:..}}, [[slug]]; tối đa 20.000 ký tự; không có số viết tay (BR-162)';
COMMENT ON COLUMN context.knowledge_page_version.body_sha256 IS 'Mã băm thân trang, trigger tính';
COMMENT ON COLUMN context.knowledge_page_version.summary IS 'Tóm tắt thay đổi cho người duyệt';
COMMENT ON COLUMN context.knowledge_page_version.change_size IS 'minor, major; major đi qua Cần bạn trước khi viết (BR-166)';
COMMENT ON COLUMN context.knowledge_page_version.knowledge_run_id IS 'FK knowledge_run';
COMMENT ON COLUMN context.knowledge_page_version.agent_run_id IS 'logic → agent.agent_run';
COMMENT ON COLUMN context.knowledge_page_version.source_answer_id IS 'logic → qa.answer; bắt buộc khi origin = saveback';
COMMENT ON COLUMN context.knowledge_page_version.proposal_id IS 'logic → inbox.proposal (kind knowledge_page)';
COMMENT ON COLUMN context.knowledge_page_version.reviewed_by IS 'logic → org.app_user; khác created_by (BR-164)';
COMMENT ON COLUMN context.knowledge_page_version.certified_by IS 'logic → org.app_user; khác created_by và reviewed_by (BR-164)';

CREATE TABLE context.knowledge_source_link (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  page_version_id uuid NOT NULL,
  source_kind text NOT NULL,
  source_ref uuid NOT NULL,
  source_label text NOT NULL,
  dataset_version_id uuid,
  external boolean NOT NULL DEFAULT false,
  content_sha256 text NOT NULL,
  data_space_id uuid NOT NULL,
  classification text NOT NULL DEFAULT 'internal',
  pii_column_refs text[] NOT NULL DEFAULT '{}',
  policy_updated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT knowledge_source_link_pkey PRIMARY KEY (id),
  CHECK (source_kind IN ('conflict_claim','dataset_version','document_version','document_chunk','metric_version','answer','glossary_term','knowledge_page')),
  CHECK (NOT external OR dataset_version_id IS NOT NULL),
  CHECK (source_kind <> 'dataset_version' OR dataset_version_id = source_ref),
  CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
  UNIQUE (page_version_id, source_kind, source_ref)
);
COMMENT ON TABLE context.knowledge_source_link IS 'Danh sách nguồn (sources[]) của một phiên bản kèm mã băm phần nguồn đã dùng; dùng để tìm trang bị ảnh hưởng khi nguồn đổi và để tính chính sách trang. Nội dung bất biến; chỉ thuộc tính quyền đổi được. Thêm 10/10/2026. Use case: UC-07-10, UC-07-11, UC-07-12.';
COMMENT ON COLUMN context.knowledge_source_link.page_version_id IS 'FK knowledge_page_version';
COMMENT ON COLUMN context.knowledge_source_link.source_kind IS 'conflict_claim, dataset_version, document_version, document_chunk, metric_version, answer, glossary_term, knowledge_page';
COMMENT ON COLUMN context.knowledge_source_link.source_ref IS 'logic → bảng nguồn theo source_kind';
COMMENT ON COLUMN context.knowledge_source_link.source_label IS 'Tên hiển thị trong trích dẫn';
COMMENT ON COLUMN context.knowledge_source_link.dataset_version_id IS 'logic → catalog.dataset_version; bắt buộc khi external';
COMMENT ON COLUMN context.knowledge_source_link.external IS 'Nguồn ngoài (BR-156, BR-165)';
COMMENT ON COLUMN context.knowledge_source_link.content_sha256 IS 'Mã băm phần nguồn dùng để biên soạn; nguồn mới cùng mã băm thì bỏ qua (BR-166)';
COMMENT ON COLUMN context.knowledge_source_link.data_space_id IS 'logic → org.data_space của nguồn; cập nhật khi nguồn đổi quyền (BR-163)';
COMMENT ON COLUMN context.knowledge_source_link.classification IS 'public, internal, confidential, restricted';

CREATE TABLE context.knowledge_claim (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  page_version_id uuid NOT NULL,
  anchor text NOT NULL,
  statement text NOT NULL,
  subject_key text,
  attribute text,
  period text,
  source_link_id uuid NOT NULL,
  valid_from date NOT NULL,
  valid_to date,
  figure_condition jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT knowledge_claim_pkey PRIMARY KEY (id),
  CHECK (anchor ~ '^[a-z][a-z0-9_]{0,31}$'),
  CHECK (char_length(statement) BETWEEN 1 AND 1000),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  UNIQUE (page_version_id, anchor)
);
COMMENT ON TABLE context.knowledge_claim IS 'Khẳng định của một phiên bản, mỗi khẳng định một nguồn và một khoảng hiệu lực (BR-161); chỉ ghi thêm. Thêm 10/10/2026. Use case: UC-07-10, UC-07-11, UC-07-12.';
COMMENT ON COLUMN context.knowledge_claim.page_version_id IS 'FK knowledge_page_version';
COMMENT ON COLUMN context.knowledge_claim.anchor IS 'c1, c2...; thân trang chèn bằng {{claim:c1}}';
COMMENT ON COLUMN context.knowledge_claim.statement IS 'Câu khẳng định; số chỉ ở dạng chỗ giữ số (BR-162)';
COMMENT ON COLUMN context.knowledge_claim.subject_key IS 'Ví dụ NHB; cùng attribute, period dùng rà mâu thuẫn';
COMMENT ON COLUMN context.knowledge_claim.attribute IS 'Ví dụ lai_suat_huy_dong_12t';
COMMENT ON COLUMN context.knowledge_claim.period IS 'Ví dụ 2026-W41';
COMMENT ON COLUMN context.knowledge_claim.source_link_id IS 'FK knowledge_source_link của cùng phiên bản (BR-161)';
COMMENT ON COLUMN context.knowledge_claim.valid_to IS 'Null là còn hiệu lực';
COMMENT ON COLUMN context.knowledge_claim.figure_condition IS 'Điều kiện số giữ cho khẳng định định tính còn đúng, ví dụ {"left":"f1","op":">","right":"f2"}';

CREATE TABLE context.knowledge_figure (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  page_version_id uuid NOT NULL,
  token text NOT NULL,
  binding_kind text NOT NULL,
  metric_code text,
  aggregate_code text,
  dataset_id uuid,
  params jsonb NOT NULL DEFAULT '{}',
  display_format text NOT NULL DEFAULT 'auto',
  source_link_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT knowledge_figure_pkey PRIMARY KEY (id),
  CHECK (token ~ '^\{\{(metric|agg):[a-z0-9_]+(\|[a-z_]+=[^|{}]+)*\}\}$'),
  CHECK (display_format IN ('auto','percent_2','amount_billion','count')),
  UNIQUE (page_version_id, token)
);
COMMENT ON TABLE context.knowledge_figure IS 'Ràng buộc của chỗ giữ số trong thân trang và khẳng định tới chỉ số semantic hoặc bảng tổng hợp đã hợp nhất; số điền khi hiển thị (BR-162); chỉ ghi thêm. Thêm 10/10/2026. Use case: UC-07-10, UC-07-12.';
COMMENT ON COLUMN context.knowledge_figure.page_version_id IS 'FK knowledge_page_version';
COMMENT ON COLUMN context.knowledge_figure.token IS 'Nguyên văn chỗ giữ số, ví dụ {{metric:lai_suat_huy_dong_12t_tb';
COMMENT ON COLUMN context.knowledge_figure.binding_kind IS 'metric, aggregate';
COMMENT ON COLUMN context.knowledge_figure.metric_code IS 'logic → context.metric; bắt buộc khi metric';
COMMENT ON COLUMN context.knowledge_figure.aggregate_code IS 'Mã bảng tổng hợp của dataset hợp nhất; bắt buộc khi aggregate';
COMMENT ON COLUMN context.knowledge_figure.dataset_id IS 'logic → catalog.dataset (origin consolidated)';
COMMENT ON COLUMN context.knowledge_figure.params IS 'period, chiều, bộ lọc';
COMMENT ON COLUMN context.knowledge_figure.display_format IS 'auto, percent_2, amount_billion, count';
COMMENT ON COLUMN context.knowledge_figure.source_link_id IS 'FK knowledge_source_link (phiên bản chỉ số hoặc dataset)';

CREATE TABLE context.knowledge_link (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  from_version_id uuid NOT NULL,
  from_page_id uuid NOT NULL,
  to_page_id uuid NOT NULL,
  link_kind text NOT NULL DEFAULT 'see_also',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT knowledge_link_pkey PRIMARY KEY (id),
  CHECK (link_kind IN ('see_also','defines','part_of','competitor_of','uses_metric','derived_from')),
  CHECK (from_page_id <> to_page_id),
  UNIQUE (from_version_id, to_page_id, link_kind)
);
COMMENT ON TABLE context.knowledge_link IS 'Liên kết từ một phiên bản trang tới trang khác ([[slug]]); dùng tìm trang mồ côi và mở rộng ngữ cảnh khi trả lời; chỉ ghi thêm. Thêm 10/10/2026. Use case: UC-07-10, UC-07-11.';
COMMENT ON COLUMN context.knowledge_link.from_version_id IS 'FK knowledge_page_version chứa liên kết';
COMMENT ON COLUMN context.knowledge_link.from_page_id IS 'FK knowledge_page';
COMMENT ON COLUMN context.knowledge_link.to_page_id IS 'FK knowledge_page';
COMMENT ON COLUMN context.knowledge_link.link_kind IS 'see_also, defines, part_of, competitor_of, uses_metric, derived_from';

CREATE TABLE context.knowledge_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  kind text NOT NULL,
  trigger text NOT NULL,
  trigger_event text,
  source_kind text,
  source_ref uuid,
  status text NOT NULL DEFAULT 'queued',
  page_limit integer NOT NULL DEFAULT 20,
  sources_seen integer NOT NULL DEFAULT 0,
  sources_skipped_unchanged integer NOT NULL DEFAULT 0,
  pages_analyzed integer NOT NULL DEFAULT 0,
  pages_changed integer NOT NULL DEFAULT 0,
  pages_deferred integer NOT NULL DEFAULT 0,
  findings_count integer NOT NULL DEFAULT 0,
  hitl_count integer NOT NULL DEFAULT 0,
  agent_run_id uuid,
  cost numeric(12,4),
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT knowledge_run_pkey PRIMARY KEY (id),
  CHECK (kind IN ('ingest','lint')),
  CHECK (trigger IN ('event','schedule','manual','saveback')),
  CHECK (status IN ('queued','analyzing','writing','checking','completed','partial','failed')),
  CHECK (page_limit BETWEEN 1 AND 50),
  CHECK (pages_changed <= page_limit),
  CHECK (status NOT IN ('completed','partial','failed') OR finished_at IS NOT NULL)
);
COMMENT ON TABLE context.knowledge_run IS 'Một lượt biên soạn (ingest) hoặc rà soát (lint) của Agent Tri thức: số nguồn bỏ qua nhờ mã băm, số trang sửa, số trang dời, phát hiện và mục Cần bạn (BR-166). Thêm 10/10/2026. Use case: UC-07-10, UC-07-11.';
COMMENT ON COLUMN context.knowledge_run.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN context.knowledge_run.kind IS 'ingest, lint';
COMMENT ON COLUMN context.knowledge_run.trigger IS 'event, schedule, manual, saveback';
COMMENT ON COLUMN context.knowledge_run.trigger_event IS 'Ví dụ acquire.dataset.published';
COMMENT ON COLUMN context.knowledge_run.status IS 'queued, analyzing, writing, checking, completed, partial, failed';
COMMENT ON COLUMN context.knowledge_run.page_limit IS 'Số trang tối đa được sửa mỗi lượt, 1 đến 50 (BR-166)';
COMMENT ON COLUMN context.knowledge_run.sources_skipped_unchanged IS 'Nguồn bỏ qua vì mã băm không đổi';
COMMENT ON COLUMN context.knowledge_run.pages_changed IS 'Trigger đếm; không vượt page_limit';
COMMENT ON COLUMN context.knowledge_run.pages_deferred IS 'Trang dời sang lượt sau';
COMMENT ON COLUMN context.knowledge_run.hitl_count IS 'Mục Cần bạn đã tạo';
COMMENT ON COLUMN context.knowledge_run.agent_run_id IS 'logic → agent.agent_run';
COMMENT ON COLUMN context.knowledge_run.cost IS 'Chi phí mô hình';

CREATE TABLE context.knowledge_lint_finding (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  page_id uuid,
  related_page_id uuid,
  kind text NOT NULL,
  severity text NOT NULL,
  fingerprint text NOT NULL,
  detail jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'open',
  action text,
  action_reason text,
  page_version_id uuid,
  proposal_id uuid,
  hitl_request_id uuid,
  suppressed_until timestamptz,
  resolved_by uuid,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT knowledge_lint_finding_pkey PRIMARY KEY (id),
  CHECK (kind IN ('metric_without_page','undefined_term') OR page_id IS NOT NULL),
  CHECK (severity IN ('low','medium','high')),
  CHECK (status IN ('open','actioned','resolved','dismissed')),
  CHECK (status = 'open' OR action IS NOT NULL)
);
COMMENT ON TABLE context.knowledge_lint_finding IS 'Phát hiện của lượt rà soát với tập hành động cố định; bỏ qua cần lý do và ẩn 90 ngày (BR-166). Thêm 10/10/2026. Use case: UC-07-11.';
COMMENT ON COLUMN context.knowledge_lint_finding.run_id IS 'FK knowledge_run';
COMMENT ON COLUMN context.knowledge_lint_finding.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN context.knowledge_lint_finding.page_id IS 'FK knowledge_page; null với metric_without_page, undefined_term';
COMMENT ON COLUMN context.knowledge_lint_finding.related_page_id IS 'FK knowledge_page; trang mâu thuẫn';
COMMENT ON COLUMN context.knowledge_lint_finding.kind IS 'contradiction, expired_claim, orphan_page, metric_without_page, undefined_term, source_decertified, stale_condition, policy_drift';
COMMENT ON COLUMN context.knowledge_lint_finding.severity IS 'low, medium, high';
COMMENT ON COLUMN context.knowledge_lint_finding.fingerprint IS 'Mã băm loại và đối tượng; không báo lặp';
COMMENT ON COLUMN context.knowledge_lint_finding.detail IS 'Khẳng định, số, nguồn liên quan';
COMMENT ON COLUMN context.knowledge_lint_finding.status IS 'open, actioned, resolved, dismissed';
COMMENT ON COLUMN context.knowledge_lint_finding.action IS 'propose_edit, mark_stale, retire_page, create_page, dismiss, reassign';
COMMENT ON COLUMN context.knowledge_lint_finding.action_reason IS 'Bắt buộc khi dismiss';
COMMENT ON COLUMN context.knowledge_lint_finding.page_version_id IS 'FK knowledge_page_version; bản nháp sửa khi propose_edit';
COMMENT ON COLUMN context.knowledge_lint_finding.proposal_id IS 'logic → inbox.proposal';
COMMENT ON COLUMN context.knowledge_lint_finding.hitl_request_id IS 'logic → inbox.hitl_request (kind knowledge_finding)';
COMMENT ON COLUMN context.knowledge_lint_finding.suppressed_until IS 'Bỏ qua thì ẩn 90 ngày (BR-166)';
COMMENT ON COLUMN context.knowledge_lint_finding.resolved_by IS 'logic → org.app_user';

CREATE TABLE context.data_product (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text NOT NULL,
  sample_questions jsonb NOT NULL DEFAULT '[]',
  scope_entities jsonb NOT NULL DEFAULT '[]',
  period_grain text NOT NULL,
  period_from date NOT NULL,
  period_to date,
  out_of_scope_note text,
  owner_id uuid NOT NULL,
  steward_id uuid NOT NULL,
  freshness_statement text NOT NULL,
  classification text NOT NULL DEFAULT 'internal',
  eval_set_id uuid,
  pack_version_id uuid,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'draft',
  suspended_reason text,
  proposal_id uuid,
  activated_by uuid,
  activated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_product_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (code ~ '^[a-z][a-z0-9_]{2,63}$'),
  CHECK (char_length(description) <= 2000),
  CHECK (jsonb_typeof(sample_questions) = 'array'),
  CHECK (jsonb_typeof(scope_entities) = 'array'),
  CHECK (period_grain IN ('day','week','month','quarter','year','event')),
  CHECK (period_to IS NULL OR period_to >= period_from),
  CHECK (owner_id <> steward_id),
  CHECK (classification IN ('public','internal','confidential','restricted')),
  CHECK (status IN ('draft','pending_review','active','suspended','retired')),
  CHECK (status <> 'suspended' OR suspended_reason IS NOT NULL),
  CHECK (status <> 'pending_review' OR proposal_id IS NOT NULL),
  CHECK (status NOT IN ('active','suspended') OR (activated_by IS NOT NULL AND activated_at IS NOT NULL AND eval_set_id IS NOT NULL AND jsonb_array_length(sample_questions) >= 10)),
  CHECK (activated_by IS NULL OR activated_by <> created_by)
);
COMMENT ON TABLE context.data_product IS 'Data product: phạm vi trả lời có cam kết của một Data Space, gồm câu hỏi trả lời được, dataset đã chuẩn hoá, chỉ số đã chứng nhận, owner và steward có tên, cam kết độ tươi và trạng thái (BR-175, ADR-42). Ví dụ POC: “Giá xăng dầu trong nước”. Khác pipeline.data_product của P06 (hợp đồng một bảng hoặc mart chia sẻ giữa Data Space); bảng này có thể chứa một sản phẩm P06 làm thành phần. Thêm 10/10/2026. Use case: UC-07-13, UC-07-14, UC-01-07, UC-01-01.';
COMMENT ON COLUMN context.data_product.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN context.data_product.code IS 'Mã ngắn, không đổi sau khi active, ví dụ gia_xang_dau_trong_nuoc';
COMMENT ON COLUMN context.data_product.name IS 'Ví dụ Giá xăng dầu trong nước';
COMMENT ON COLUMN context.data_product.description IS 'Phạm vi câu hỏi trả lời được, bằng lời; tối đa 2.000 ký tự';
COMMENT ON COLUMN context.data_product.sample_questions IS 'Mảng {text, metric_code, period, expected}; tối thiểu 10 câu khi active, mỗi câu là một eval_item của eval_set_id';
COMMENT ON COLUMN context.data_product.scope_entities IS 'Chiều và giá trị trong phạm vi, ví dụ [{"dimension":"mat_hang","values":["E5RON92","RON95-III","DO 0,05S-II"]}]; mảng rỗng là mọi giá trị của chiều hợp lệ';
COMMENT ON COLUMN context.data_product.period_grain IS 'day, week, month, quarter, year, event (kỳ theo lịch sự kiện, ví dụ kỳ điều hành giá)';
COMMENT ON COLUMN context.data_product.period_from IS 'Kỳ sớm nhất trả lời được, ví dụ 2024-01-01';
COMMENT ON COLUMN context.data_product.period_to IS 'Null là đến hiện tại';
COMMENT ON COLUMN context.data_product.out_of_scope_note IS 'Câu hỏi gần phạm vi nhưng không trả lời, ví dụ giá bán tại một cửa hàng cụ thể';
COMMENT ON COLUMN context.data_product.owner_id IS 'logic → org.app_user; người chịu trách nhiệm cam kết (data owner)';
COMMENT ON COLUMN context.data_product.steward_id IS 'logic → org.app_user; người giữ định nghĩa, xử lý Error Book; khác owner_id';
COMMENT ON COLUMN context.data_product.freshness_statement IS 'Cam kết hiển thị cho người dùng, ví dụ “Giá xăng dầu trong nước: cập nhật trước 16:30 ngày điều hành”';
COMMENT ON COLUMN context.data_product.classification IS 'public, internal, confidential, restricted; mức cao nhất của các thành phần, trigger tính; dùng cho định tuyến mô hình (BR-180)';
COMMENT ON COLUMN context.data_product.eval_set_id IS 'logic → eval.eval_set (subject_type context) chứa câu hỏi mẫu và ca hồi quy Error Book';
COMMENT ON COLUMN context.data_product.pack_version_id IS 'logic → pack.pack_version nếu dựng từ mẫu của gói ngành';
COMMENT ON COLUMN context.data_product.version IS 'Tăng khi đổi phạm vi, thành phần primary hoặc cam kết sau khi active';
COMMENT ON COLUMN context.data_product.status IS 'draft, pending_review, active, suspended, retired';
COMMENT ON COLUMN context.data_product.suspended_reason IS 'Bắt buộc khi suspended, ví dụ metric_decertified, dataset_decertified, manual';
COMMENT ON COLUMN context.data_product.proposal_id IS 'logic → inbox.proposal (kind data_product) đang chờ duyệt';
COMMENT ON COLUMN context.data_product.activated_by IS 'logic → org.app_user; người duyệt kích hoạt, khác created_by';

CREATE TABLE context.data_product_member (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_product_id uuid NOT NULL,
  member_kind text NOT NULL,
  member_ref uuid NOT NULL,
  role text NOT NULL DEFAULT 'primary',
  sla_kind text NOT NULL DEFAULT 'none',
  sla_cron text,
  sla_event_calendar_code text,
  sla_timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  sla_work_calendar_id uuid,
  sla_max_age interval,
  sla_grace interval NOT NULL DEFAULT '0',
  as_of_col text,
  last_as_of timestamptz,
  last_loaded_at timestamptz,
  expected_as_of timestamptz,
  next_due_at timestamptz,
  freshness_state text NOT NULL DEFAULT 'unknown',
  last_checked_at timestamptz,
  classification text NOT NULL DEFAULT 'internal',
  classification_confirmed_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_product_member_pkey PRIMARY KEY (id),
  CHECK (member_kind IN ('dataset','metric','knowledge_page','document_collection','shared_product')),
  CHECK (role IN ('primary','reference')),
  CHECK (sla_kind IN ('none','schedule','max_age')),
  CHECK (sla_kind = 'none' OR member_kind = 'dataset'),
  CHECK (sla_kind <> 'schedule' OR sla_cron IS NOT NULL OR sla_event_calendar_code IS NOT NULL),
  CHECK (sla_kind <> 'max_age' OR sla_max_age IS NOT NULL),
  CHECK (NOT (member_kind = 'dataset' AND role = 'primary') OR sla_kind <> 'none'),
  CHECK (sla_grace >= interval '0' AND sla_grace <= interval '1 day'),
  CHECK (freshness_state IN ('unknown','fresh','overdue','missing')),
  CHECK (classification IN ('public','internal','confidential','restricted')),
  CHECK (classification <> 'public' OR classification_confirmed_by IS NOT NULL),
  UNIQUE (data_product_id, member_kind, member_ref)
);
COMMENT ON TABLE context.data_product_member IS 'Thành phần của data product: dataset, chỉ số, trang tri thức, bộ sưu tập tài liệu, sản phẩm dữ liệu dùng chung của P06. Dataset primary mang cam kết độ tươi theo lịch và trạng thái độ tươi hiện tại cho cổng độ tươi (BR-178). Thêm 10/10/2026. Use case: UC-07-13, UC-01-07, UC-01-01.';
COMMENT ON COLUMN context.data_product_member.data_product_id IS 'FK data_product';
COMMENT ON COLUMN context.data_product_member.member_kind IS 'dataset, metric, knowledge_page, document_collection, shared_product';
COMMENT ON COLUMN context.data_product_member.member_ref IS 'logic → catalog.dataset, context.metric, context.knowledge_page, document.collection hoặc pipeline.data_product theo member_kind';
COMMENT ON COLUMN context.data_product_member.role IS 'primary, reference; chỉ số đọc từ dataset primary mới qua cổng độ tươi';
COMMENT ON COLUMN context.data_product_member.sla_kind IS 'none, schedule, max_age; dataset primary phải khác none';
COMMENT ON COLUMN context.data_product_member.sla_cron IS 'Lịch cập nhật cam kết theo giờ địa phương, cron 5 trường, ví dụ ''30 16 * * 4'' (16:30 thứ Năm, ngày điều hành giá xăng dầu)';
COMMENT ON COLUMN context.data_product_member.sla_event_calendar_code IS 'logic → monitor.external_calendar.code cùng data_space_id (UNIQUE (data_space_id, code)); mã lịch sự kiện ngoài do P08 quản lý (ví dụ fuel_price_regulation, lịch điều hành giá xăng dầu); có thì hạn lấy theo lịch này, sla_cron chỉ cho giờ trong ngày';
COMMENT ON COLUMN context.data_product_member.sla_work_calendar_id IS 'logic → org.work_calendar; hạn rơi vào ngày nghỉ thì dời sang ngày làm việc kế tiếp';
COMMENT ON COLUMN context.data_product_member.sla_max_age IS 'Với max_age: tuổi dữ liệu tối đa, ví dụ 1 day cho tỷ giá';
COMMENT ON COLUMN context.data_product_member.sla_grace IS 'Ân hạn sau hạn trước khi che số, ví dụ 30 minutes; tối đa 1 ngày';
COMMENT ON COLUMN context.data_product_member.as_of_col IS 'Cột ngày dữ liệu dùng đo độ tươi; null thì dùng catalog.dataset.business_date_col';
COMMENT ON COLUMN context.data_product_member.last_as_of IS 'Ngày dữ liệu mới nhất đã có trong dataset; Connector hoặc Ingestion service cập nhật sau mỗi lượt nạp';
COMMENT ON COLUMN context.data_product_member.last_loaded_at IS 'Thời điểm lượt nạp gần nhất xong';
COMMENT ON COLUMN context.data_product_member.expected_as_of IS 'Ngày dữ liệu phải có theo hạn gần nhất đã qua';
COMMENT ON COLUMN context.data_product_member.next_due_at IS 'Hạn kế tiếp tính từ lịch';
COMMENT ON COLUMN context.data_product_member.freshness_state IS 'unknown, fresh, overdue, missing';
COMMENT ON COLUMN context.data_product_member.classification IS 'public, internal, confidential, restricted; với knowledge_page lấy từ trang; public chỉ khi dữ liệu là thông tin công bố (ví dụ giá điều hành của Bộ Công Thương) và có AC06 xác nhận; dùng cho định tuyến mô hình (BR-180)';
COMMENT ON COLUMN context.data_product_member.classification_confirmed_by IS 'logic → org.app_user (AC06); bắt buộc khi classification = public';

CREATE TABLE context.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE context.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON context.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE context.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON context.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA context TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON context.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON context.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON context.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX metric_version_metric_id_key ON context.metric_version (metric_id) WHERE status = 'certified';
CREATE UNIQUE INDEX synonym_data_space_id_phrase_norm_target_kind_ta_key ON context.synonym (data_space_id, phrase_norm, target_kind, target_id) WHERE status = 'active';
CREATE INDEX value_index_data_space_id_label_norm_idx ON context.value_index (data_space_id, label_norm);
CREATE UNIQUE INDEX knowledge_page_data_space_id_kind_subject_ref_key ON context.knowledge_page (data_space_id, kind, subject_ref) WHERE subject_ref IS NOT NULL AND status <> 'retired';
CREATE INDEX knowledge_page_data_space_id_status_idx ON context.knowledge_page (data_space_id, status);
CREATE INDEX knowledge_page_tags_idx ON context.knowledge_page USING gin (tags);
CREATE INDEX knowledge_page_title_index_summary_idx ON context.knowledge_page USING gin (to_tsvector('simple', title || ' ' || index_summary));
CREATE UNIQUE INDEX knowledge_page_version_page_id_key ON context.knowledge_page_version (page_id) WHERE status IN ('draft','pending_review');
CREATE INDEX knowledge_page_version_knowledge_run_id_idx ON context.knowledge_page_version (knowledge_run_id);
CREATE INDEX knowledge_page_version_source_answer_id_idx ON context.knowledge_page_version (source_answer_id);
CREATE INDEX knowledge_source_link_source_kind_source_ref_idx ON context.knowledge_source_link (source_kind, source_ref);
CREATE INDEX knowledge_source_link_dataset_version_id_idx ON context.knowledge_source_link (dataset_version_id);
CREATE INDEX knowledge_claim_subject_key_attribute_period_idx ON context.knowledge_claim (subject_key, attribute, period);
CREATE INDEX knowledge_claim_valid_to_idx ON context.knowledge_claim (valid_to);
CREATE INDEX knowledge_figure_metric_code_idx ON context.knowledge_figure (metric_code);
CREATE INDEX knowledge_figure_dataset_id_idx ON context.knowledge_figure (dataset_id);
CREATE INDEX knowledge_link_to_page_id_idx ON context.knowledge_link (to_page_id);
CREATE UNIQUE INDEX knowledge_run_data_space_id_kind_key ON context.knowledge_run (data_space_id, kind) WHERE status IN ('queued','analyzing','writing','checking');
CREATE INDEX knowledge_run_data_space_id_created_at_idx ON context.knowledge_run (data_space_id, created_at DESC);
CREATE UNIQUE INDEX knowledge_lint_finding_data_space_id_fingerprint_key ON context.knowledge_lint_finding (data_space_id, fingerprint) WHERE status IN ('open','actioned');
CREATE INDEX knowledge_lint_finding_run_id_idx ON context.knowledge_lint_finding (run_id);
CREATE INDEX knowledge_lint_finding_page_id_status_idx ON context.knowledge_lint_finding (page_id, status);
CREATE INDEX data_product_data_space_id_status_idx ON context.data_product (data_space_id, status);
CREATE INDEX data_product_name_description_idx ON context.data_product USING gin (to_tsvector('simple', name || ' ' || description));
CREATE INDEX data_product_member_member_kind_member_ref_idx ON context.data_product_member (member_kind, member_ref);
CREATE INDEX data_product_member_next_due_at_idx ON context.data_product_member (next_due_at) WHERE sla_kind <> 'none';

-- ═══ schema qa ═══
CREATE TABLE qa.conversation (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  user_id uuid NOT NULL,
  channel text NOT NULL DEFAULT 'web',
  api_client_id uuid,
  title text,
  workspace_id uuid,
  last_question_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT conversation_pkey PRIMARY KEY (id),
  CHECK (channel IN ('web','mobile','teams','zalo','mcp','api'))
);
COMMENT ON TABLE qa.conversation IS 'Một chuỗi hỏi đáp; câu hỏi tiếp theo kế thừa cách hiểu (UC-01-04). Use case: UC-01-01, UC-01-04.';
COMMENT ON COLUMN qa.conversation.user_id IS 'logic → org.app_user';
COMMENT ON COLUMN qa.conversation.channel IS 'web, mobile, teams, zalo, mcp, api';
COMMENT ON COLUMN qa.conversation.api_client_id IS 'logic → integration.api_client khi gọi qua client';
COMMENT ON COLUMN qa.conversation.workspace_id IS 'logic → workspace.workspace nếu đã đưa vào phiên';
COMMENT ON COLUMN qa.conversation.deleted_at IS 'Xoá mềm';

CREATE TABLE qa.question (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  conversation_id uuid NOT NULL,
  seq integer NOT NULL,
  text text NOT NULL,
  parent_question_id uuid,
  as_of date,
  knowledge_mode text NOT NULL DEFAULT 'latest',
  knowledge_at timestamptz,
  purpose text,
  status text NOT NULL DEFAULT 'received',
  received_at timestamptz NOT NULL DEFAULT now(),
  answered_at timestamptz,
  CONSTRAINT question_pkey PRIMARY KEY (id),
  CHECK (knowledge_mode IN ('latest','period_close','at')),
  CHECK (knowledge_mode <> 'at' OR knowledge_at IS NOT NULL),
  CHECK (status IN ('received','clarifying','planning','running','answered','refused','failed')),
  UNIQUE (conversation_id, seq)
);
COMMENT ON TABLE qa.question IS 'Một lượt hỏi, kèm thời điểm và chế độ dữ liệu. Use case: UC-01-01, UC-01-03, UC-01-04, UC-10-01, UC-12-02.';
COMMENT ON COLUMN qa.question.conversation_id IS 'FK conversation';
COMMENT ON COLUMN qa.question.seq IS 'Thứ tự trong cuộc hội thoại';
COMMENT ON COLUMN qa.question.text IS 'Đã che dữ liệu cá nhân trước khi lưu';
COMMENT ON COLUMN qa.question.parent_question_id IS 'Câu được kế thừa cách hiểu';
COMMENT ON COLUMN qa.question.as_of IS 'Ngày nghiệp vụ hỏi tới';
COMMENT ON COLUMN qa.question.knowledge_mode IS 'latest, period_close, at';
COMMENT ON COLUMN qa.question.knowledge_at IS 'Bắt buộc khi knowledge_mode = at';
COMMENT ON COLUMN qa.question.purpose IS 'Mục đích khai báo, dùng cho BR-59';
COMMENT ON COLUMN qa.question.status IS 'received, clarifying, planning, running, answered, refused, failed';

CREATE TABLE qa.plan (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  question_id uuid,
  agent_run_id uuid,
  version integer NOT NULL DEFAULT 1,
  chips jsonb NOT NULL,
  steps jsonb NOT NULL DEFAULT '[]',
  confidence numeric(4,3),
  edited_by_user boolean NOT NULL DEFAULT false,
  edit_note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT plan_pkey PRIMARY KEY (id),
  CHECK ((question_id IS NULL) <> (agent_run_id IS NULL)),
  UNIQUE NULLS NOT DISTINCT (question_id, agent_run_id, version)
);
COMMENT ON TABLE qa.plan IS 'Cách hệ thống hiểu câu hỏi (chip) và kế hoạch chạy; sửa chip tạo phiên bản mới. Use case: UC-01-01, UC-01-02, UC-01-03, UC-01-04, UC-07-09, UC-10-01, UC-13-06.';
COMMENT ON COLUMN qa.plan.question_id IS 'FK question; null với kế hoạch của lượt chạy agent';
COMMENT ON COLUMN qa.plan.agent_run_id IS 'logic → agent.agent_run';
COMMENT ON COLUMN qa.plan.chips IS 'Chỉ số, phạm vi, kỳ, chiều, chế độ dữ liệu; mỗi chip ghi nguồn gốc (mặc định, cách hiểu riêng, người sửa)';
COMMENT ON COLUMN qa.plan.steps IS 'Plan IR: các bước truy vấn, kỹ năng, tài liệu';
COMMENT ON COLUMN qa.plan.confidence IS 'Dưới 0,8 thì hỏi lại';

CREATE TABLE qa.answer (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  question_id uuid NOT NULL,
  plan_id uuid NOT NULL,
  kind text NOT NULL DEFAULT 'data',
  forecast_job_id uuid,
  number_check jsonb NOT NULL DEFAULT '{}',
  text text NOT NULL,
  figures jsonb NOT NULL DEFAULT '[]',
  chart_spec jsonb,
  citations jsonb NOT NULL DEFAULT '[]',
  filed_vs_current jsonb,
  reconcile_badge text,
  agent_name text,
  latency_ms integer,
  lineage_hash text,
  data_product_id uuid,
  product_scope text NOT NULL DEFAULT 'not_applicable',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT answer_pkey PRIMARY KEY (id),
  CHECK (kind IN ('data','document','mixed','clarification','refusal','forecast')),
  CHECK (kind <> 'forecast' OR forecast_job_id IS NOT NULL),
  CHECK (reconcile_badge IS NULL OR reconcile_badge IN ('matched_filed','differs_from_filed','not_filed')),
  CHECK (product_scope IN ('in_scope','out_of_scope','not_applicable')),
  CHECK ((product_scope = 'in_scope') = (data_product_id IS NOT NULL))
);
COMMENT ON TABLE qa.answer IS 'Câu trả lời: văn bản, số, biểu đồ, trích dẫn và trạng thái kiểm tra. Use case: UC-01-01, UC-01-02, UC-01-03, UC-01-04, UC-01-05, UC-05-04.';
COMMENT ON COLUMN qa.answer.question_id IS 'FK question';
COMMENT ON COLUMN qa.answer.plan_id IS 'FK plan dùng để trả lời';
COMMENT ON COLUMN qa.answer.kind IS 'data, document, mixed, clarification, refusal, forecast';
COMMENT ON COLUMN qa.answer.forecast_job_id IS 'logic → forecast.forecast_job; bắt buộc khi kind = forecast (UC-15-01)';
COMMENT ON COLUMN qa.answer.number_check IS 'Kết quả kiểm số (BR-171): {numbers_total, traced, untraceable_draft, regenerated, sentences_dropped, untraceable_final}; CHECK untraceable_final = 0. DDL ở dataagent.sql';
COMMENT ON COLUMN qa.answer.figures IS 'Các số trong câu trả lời kèm query_run_id, metric_version_id để truy nguồn';
COMMENT ON COLUMN qa.answer.citations IS 'chunk_id, document_id, trang, đoạn; đã kiểm tra tồn tại (UC-05-04 bước 4)';
COMMENT ON COLUMN qa.answer.filed_vs_current IS 'Hai số đã nộp và hiện tại khi hỏi về kỳ đã nộp (BR-39)';
COMMENT ON COLUMN qa.answer.reconcile_badge IS 'matched_filed, differs_from_filed, not_filed (nhãn “Khớp số đã nộp” trên màn Hỏi đáp)';
COMMENT ON COLUMN qa.answer.agent_name IS 'Ví dụ Agent Phân tích';
COMMENT ON COLUMN qa.answer.lineage_hash IS 'SHA-256 khi dùng kỳ đã chốt (UC-01-02)';
COMMENT ON COLUMN qa.answer.data_product_id IS 'logic → context.data_product; có khi product_scope = in_scope (BR-175, thêm 10/10/2026)';
COMMENT ON COLUMN qa.answer.product_scope IS 'in_scope, out_of_scope, not_applicable (làm rõ, từ chối); out_of_scope hiển thị nhãn “Ngoài phạm vi data product, không có biên nhận”';

CREATE TABLE qa.feedback (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  answer_id uuid NOT NULL,
  user_id uuid NOT NULL,
  rating text NOT NULL,
  error_kind text,
  expected_value text,
  comment text,
  status text NOT NULL DEFAULT 'open',
  reviewer_id uuid,
  decided_at timestamptz,
  reason text,
  proposal_id uuid,
  eval_item_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT feedback_pkey PRIMARY KEY (id),
  CHECK (rating IN ('up','down','wrong')),
  CHECK (rating <> 'wrong' OR error_kind IN ('wrong_metric','wrong_scope','wrong_period','wrong_number','wrong_document','other')),
  CHECK (status IN ('open','in_review','confirmed','rejected')),
  CHECK (status NOT IN ('confirmed','rejected') OR (reviewer_id IS NOT NULL AND decided_at IS NOT NULL))
);
COMMENT ON TABLE qa.feedback IS 'Đánh giá và báo sai của người dùng; báo sai đã xác nhận thành mục đánh giá (UC-01-05). Use case: UC-01-05, UC-07-06.';
COMMENT ON COLUMN qa.feedback.answer_id IS 'FK answer';
COMMENT ON COLUMN qa.feedback.rating IS 'up, down, wrong';
COMMENT ON COLUMN qa.feedback.error_kind IS 'wrong_metric, wrong_scope, wrong_period, wrong_number, wrong_document, other';
COMMENT ON COLUMN qa.feedback.status IS 'open, in_review, confirmed, rejected';
COMMENT ON COLUMN qa.feedback.proposal_id IS 'logic → inbox.proposal';
COMMENT ON COLUMN qa.feedback.eval_item_id IS 'logic → eval.eval_item';

CREATE TABLE qa.export_job (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  answer_id uuid,
  artifact_id uuid,
  requested_by uuid NOT NULL,
  format text NOT NULL,
  include_detail_rows boolean NOT NULL DEFAULT false,
  row_count integer,
  status text NOT NULL DEFAULT 'queued',
  hitl_request_id uuid,
  object_key text,
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT export_job_pkey PRIMARY KEY (id),
  CHECK (format IN ('xlsx','csv','pdf','png')),
  CHECK (status IN ('queued','waiting_approval','running','ready','failed','expired')),
  CHECK (answer_id IS NOT NULL OR artifact_id IS NOT NULL),
  CHECK (status <> 'ready' OR (object_key IS NOT NULL AND expires_at IS NOT NULL))
);
COMMENT ON TABLE qa.export_job IS 'Việc xuất kết quả ra tệp; liên kết tải hết hạn sau 24 giờ (BR-86). Use case: UC-01-06.';
COMMENT ON COLUMN qa.export_job.answer_id IS 'FK answer';
COMMENT ON COLUMN qa.export_job.artifact_id IS 'logic → workspace.artifact';
COMMENT ON COLUMN qa.export_job.format IS 'xlsx, csv, pdf, png';
COMMENT ON COLUMN qa.export_job.include_detail_rows IS 'Dòng chi tiết; có dữ liệu cá nhân thì cần duyệt';
COMMENT ON COLUMN qa.export_job.status IS 'queued, waiting_approval, running, ready, failed, expired';
COMMENT ON COLUMN qa.export_job.hitl_request_id IS 'logic → inbox.hitl_request';
COMMENT ON COLUMN qa.export_job.object_key IS 'MinIO da-exports';

CREATE TABLE qa.answer_receipt (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  answer_id uuid NOT NULL,
  receipt_no text NOT NULL,
  data_product_id uuid NOT NULL,
  data_product_code text NOT NULL,
  data_product_version integer NOT NULL,
  plan_id uuid NOT NULL,
  answered_at timestamptz NOT NULL,
  knowledge_mode text NOT NULL,
  knowledge_at timestamptz,
  compiler_version text NOT NULL,
  runtime_version text NOT NULL,
  models jsonb NOT NULL DEFAULT '[]',
  frontier_used boolean NOT NULL DEFAULT false,
  freshness jsonb NOT NULL DEFAULT '[]',
  figure_count integer NOT NULL DEFAULT 0,
  masked_count integer NOT NULL DEFAULT 0,
  receipt_sha256 text,
  sealed_at timestamptz,
  retain_until date NOT NULL DEFAULT (now() + interval '7 years')::date,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT answer_receipt_pkey PRIMARY KEY (id),
  UNIQUE (answer_id),
  UNIQUE (org_id, receipt_no),
  CHECK (receipt_no ~ '^BN-[0-9]{8}-[0-9]{6}$'),
  CHECK (knowledge_mode IN ('latest','period_close','at')),
  CHECK (knowledge_mode <> 'at' OR knowledge_at IS NOT NULL),
  CHECK (jsonb_typeof(models) = 'array' AND jsonb_typeof(freshness) = 'array'),
  CHECK (masked_count BETWEEN 0 AND figure_count),
  CHECK ((sealed_at IS NULL) = (receipt_sha256 IS NULL)),
  CHECK (receipt_sha256 IS NULL OR receipt_sha256 ~ '^[0-9a-f]{64}$')
);
COMMENT ON TABLE qa.answer_receipt IS 'Biên nhận của một câu trả lời trong phạm vi data product: data product và phiên bản, phiên bản bộ biên dịch và Agent runtime, mô hình và provider của mọi lần gọi, độ tươi lúc trả lời, mã băm toàn biên nhận. Ghi cùng giao dịch với qa.answer, khoá ngay, chỉ ghi thêm (BR-176, ADR-43). Câu trả lời ngoài phạm vi không có biên nhận. Thêm 10/10/2026. Use case: UC-01-07, UC-01-01, UC-07-14.';
COMMENT ON COLUMN qa.answer_receipt.answer_id IS 'FK answer; một biên nhận mỗi câu trả lời';
COMMENT ON COLUMN qa.answer_receipt.receipt_no IS 'Mã hiển thị theo ngày, ví dụ BN-20260702-000184; trigger cấp';
COMMENT ON COLUMN qa.answer_receipt.data_product_id IS 'logic → context.data_product';
COMMENT ON COLUMN qa.answer_receipt.data_product_code IS 'Chép lại để đọc được cả khi product đã retired';
COMMENT ON COLUMN qa.answer_receipt.plan_id IS 'FK plan; plan dùng để dựng lại truy vấn khi chạy lại';
COMMENT ON COLUMN qa.answer_receipt.answered_at IS 'Mốc point-in-time khi chạy lại';
COMMENT ON COLUMN qa.answer_receipt.knowledge_mode IS 'latest, period_close, at; chép từ qa.question';
COMMENT ON COLUMN qa.answer_receipt.compiler_version IS 'Phiên bản semantic compiler, ví dụ semcomp 1.8.2+4f2a91c';
COMMENT ON COLUMN qa.answer_receipt.runtime_version IS 'Phiên bản Agent runtime và Verifier';
COMMENT ON COLUMN qa.answer_receipt.models IS 'Mỗi lần gọi mô hình của lượt: {task, provider_code, provider_kind, provider_display_name, model_name, model_config_version, route_decision_id}';
COMMENT ON COLUMN qa.answer_receipt.frontier_used IS 'Có ít nhất một lời gọi tới provider frontier (BR-181)';
COMMENT ON COLUMN qa.answer_receipt.freshness IS 'Mỗi dataset primary lúc trả lời: {dataset_id, last_as_of, expected_as_of, due_at, state}';
COMMENT ON COLUMN qa.answer_receipt.masked_count IS 'Số figure bị che do quá hạn hoặc chưa có (BR-178)';
COMMENT ON COLUMN qa.answer_receipt.receipt_sha256 IS 'SHA-256 của JSON chuẩn hoá gồm các cột trên và mọi dòng answer_receipt_figure xếp theo figure_key; trigger tính khi khoá';
COMMENT ON COLUMN qa.answer_receipt.sealed_at IS 'Thời điểm khoá; sau khi khoá không thêm figure';
COMMENT ON COLUMN qa.answer_receipt.retain_until IS 'Hạn giữ theo NFR-20; dữ liệu dùng để chạy lại phải giữ tới cùng hạn';

CREATE TABLE qa.answer_receipt_figure (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  receipt_id uuid NOT NULL,
  figure_key text NOT NULL,
  label text NOT NULL,
  value numeric,
  unit text,
  display_state text NOT NULL DEFAULT 'shown',
  stale_note text,
  requested_period text,
  metric_id uuid,
  metric_version_id uuid,
  metric_version_no integer,
  metric_certified_by uuid,
  metric_certified_at timestamptz,
  source_kind text NOT NULL,
  query_run_id uuid,
  compute_run_id uuid,
  published_result_id uuid,
  compiled_sql_sha256 text,
  expr_sha256 text,
  result_sha256 text,
  dataset_versions jsonb NOT NULL DEFAULT '[]',
  as_of date,
  freshness_state text NOT NULL,
  due_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT answer_receipt_figure_pkey PRIMARY KEY (id),
  UNIQUE (receipt_id, figure_key),
  CHECK (display_state IN ('shown','masked_stale','not_available')),
  CHECK (source_kind IN ('query_run','compute_run','period_result')),
  CHECK (freshness_state IN ('fresh','overdue','missing','not_applicable')),
  CHECK ((display_state = 'shown') = (value IS NOT NULL)),
  CHECK (display_state <> 'shown' OR freshness_state IN ('fresh','not_applicable')),
  CHECK (display_state <> 'masked_stale' OR (stale_note IS NOT NULL AND freshness_state = 'overdue')),
  CHECK (display_state <> 'not_available' OR freshness_state = 'missing'),
  CHECK (source_kind <> 'query_run' OR (query_run_id IS NOT NULL AND compiled_sql_sha256 ~ '^[0-9a-f]{64}$')),
  CHECK (source_kind <> 'compute_run' OR (compute_run_id IS NOT NULL AND expr_sha256 ~ '^[0-9a-f]{64}$')),
  CHECK (source_kind <> 'period_result' OR published_result_id IS NOT NULL),
  CHECK (metric_version_id IS NULL OR (metric_certified_by IS NOT NULL AND metric_certified_at IS NOT NULL)),
  CHECK (jsonb_typeof(dataset_versions) = 'array')
);
COMMENT ON TABLE qa.answer_receipt_figure IS 'Một số trong biên nhận: giá trị, chỉ số và phiên bản đã chứng nhận kèm người ký, nguồn, dataset_version và as_of, mã băm truy vấn đã biên dịch, độ tươi và trạng thái che. Chỉ ghi thêm (BR-176, BR-178). Thêm 10/10/2026. Use case: UC-01-07, UC-01-02.';
COMMENT ON COLUMN qa.answer_receipt_figure.receipt_id IS 'FK answer_receipt';
COMMENT ON COLUMN qa.answer_receipt_figure.figure_key IS 'F1…Fn như qa.answer.figures (tab 5 G5.15)';
COMMENT ON COLUMN qa.answer_receipt_figure.label IS 'Ví dụ Giá trần E5RON92 kỳ 02/07/2026';
COMMENT ON COLUMN qa.answer_receipt_figure.value IS 'Giá trị đủ chữ số; null khi bị che hoặc chưa có';
COMMENT ON COLUMN qa.answer_receipt_figure.unit IS 'Ví dụ đ/lít, USD/thùng, %, tỷ đồng';
COMMENT ON COLUMN qa.answer_receipt_figure.display_state IS 'shown, masked_stale, not_available';
COMMENT ON COLUMN qa.answer_receipt_figure.stale_note IS 'Ví dụ “dữ liệu đến 25/06/2026, đã quá hạn cập nhật”; bắt buộc khi masked_stale';
COMMENT ON COLUMN qa.answer_receipt_figure.requested_period IS 'Kỳ câu hỏi yêu cầu, ví dụ 2026-07-02 hoặc latest';
COMMENT ON COLUMN qa.answer_receipt_figure.metric_id IS 'logic → context.metric';
COMMENT ON COLUMN qa.answer_receipt_figure.metric_version_id IS 'logic → context.metric_version; phiên bản certified lúc trả lời';
COMMENT ON COLUMN qa.answer_receipt_figure.metric_certified_by IS 'logic → org.app_user; người ký định nghĩa';
COMMENT ON COLUMN qa.answer_receipt_figure.source_kind IS 'query_run, compute_run, period_result';
COMMENT ON COLUMN qa.answer_receipt_figure.query_run_id IS 'logic → query.query_run';
COMMENT ON COLUMN qa.answer_receipt_figure.compute_run_id IS 'logic → lượt compute.run của Agent runtime (G5.10)';
COMMENT ON COLUMN qa.answer_receipt_figure.published_result_id IS 'logic → period.published_result khi đọc số đã công bố';
COMMENT ON COLUMN qa.answer_receipt_figure.compiled_sql_sha256 IS 'SHA-256 của query_run.sql_executed sau chuẩn hoá khoảng trắng';
COMMENT ON COLUMN qa.answer_receipt_figure.expr_sha256 IS 'SHA-256 của phép tính khai báo với compute_run';
COMMENT ON COLUMN qa.answer_receipt_figure.result_sha256 IS 'query_run.result_hash lúc trả lời; dùng so khi chạy lại';
COMMENT ON COLUMN qa.answer_receipt_figure.dataset_versions IS '[{dataset_id, dataset_version_id, version, as_of}] của mọi bảng truy vấn đọc';
COMMENT ON COLUMN qa.answer_receipt_figure.as_of IS 'Ngày dữ liệu của số, ví dụ 2026-07-02';
COMMENT ON COLUMN qa.answer_receipt_figure.freshness_state IS 'fresh, overdue, missing, not_applicable (số đọc từ dataset reference hoặc kỳ đã qua)';
COMMENT ON COLUMN qa.answer_receipt_figure.due_at IS 'Hạn cập nhật áp cho số';

CREATE TABLE qa.receipt_replay (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  receipt_id uuid NOT NULL,
  requested_by uuid NOT NULL,
  reason text,
  mode text NOT NULL DEFAULT 'figures',
  compiler_version_used text NOT NULL,
  status text NOT NULL DEFAULT 'running',
  outcome text,
  figure_results jsonb NOT NULL DEFAULT '[]',
  differs_count integer NOT NULL DEFAULT 0,
  cause_summary text,
  retro_change_ids uuid[] NOT NULL DEFAULT '{}',
  replay_text text,
  replay_model text,
  query_run_ids uuid[] NOT NULL DEFAULT '{}',
  error_book_entry_id uuid,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT receipt_replay_pkey PRIMARY KEY (id),
  CHECK (mode IN ('figures','figures_and_text')),
  CHECK (status IN ('running','completed','failed')),
  CHECK (outcome IS NULL OR outcome IN ('identical','differs_explained','differs','not_reproducible')),
  CHECK (status <> 'completed' OR (outcome IS NOT NULL AND finished_at IS NOT NULL)),
  CHECK (outcome <> 'identical' OR differs_count = 0),
  CHECK (outcome NOT IN ('differs','differs_explained') OR differs_count > 0),
  CHECK (outcome <> 'differs_explained' OR cardinality(retro_change_ids) > 0 OR cause_summary IS NOT NULL),
  CHECK (mode = 'figures_and_text' OR replay_text IS NULL)
);
COMMENT ON TABLE qa.receipt_replay IS 'Một lần chạy lại biên nhận tại thời điểm cũ: dựng lại truy vấn từ plan với cùng phiên bản chỉ số, bộ biên dịch, dataset_version và knowledge_at = answered_at, so mã băm và giá trị từng số. Số tái lập y hệt; câu chữ chỉ sinh lại khi người dùng chọn và luôn mang nhãn có thể khác (BR-177). Thêm 10/10/2026. Use case: UC-01-07, UC-07-14.';
COMMENT ON COLUMN qa.receipt_replay.receipt_id IS 'FK answer_receipt';
COMMENT ON COLUMN qa.receipt_replay.requested_by IS 'logic → org.app_user; truy vấn chạy với quyền của người này';
COMMENT ON COLUMN qa.receipt_replay.reason IS 'Ví dụ Kiểm toán nội bộ quý 4/2026';
COMMENT ON COLUMN qa.receipt_replay.mode IS 'figures (chỉ số), figures_and_text (sinh lại cả câu chữ bằng mô hình hiện hành)';
COMMENT ON COLUMN qa.receipt_replay.compiler_version_used IS 'Bộ biên dịch đã dùng; bình thường trùng bản gốc lấy từ kho artefact';
COMMENT ON COLUMN qa.receipt_replay.status IS 'running, completed, failed';
COMMENT ON COLUMN qa.receipt_replay.outcome IS 'identical, differs_explained, differs, not_reproducible';
COMMENT ON COLUMN qa.receipt_replay.figure_results IS 'Mỗi figure: {figure_key, original_value, replay_value, sql_sha256_match, result_sha256_match, cause}';
COMMENT ON COLUMN qa.receipt_replay.cause_summary IS 'Ví dụ nguồn hiệu chỉnh hồi tố ngày 10/07/2026 (period.retro_change)';
COMMENT ON COLUMN qa.receipt_replay.retro_change_ids IS 'logic → period.retro_change giải thích khác biệt';
COMMENT ON COLUMN qa.receipt_replay.replay_text IS 'Câu chữ sinh lại khi mode = figures_and_text';
COMMENT ON COLUMN qa.receipt_replay.replay_model IS 'Mô hình đã sinh lại câu chữ';
COMMENT ON COLUMN qa.receipt_replay.query_run_ids IS 'logic → query.query_run (caller_kind receipt_replay)';
COMMENT ON COLUMN qa.receipt_replay.error_book_entry_id IS 'logic → eval.error_book_entry khi khác biệt không giải thích được';

CREATE TABLE qa.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE qa.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON qa.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE qa.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON qa.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA qa TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON qa.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON qa.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON qa.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX conversation_user_id_last_question_at_idx ON qa.conversation (user_id, last_question_at DESC);
CREATE INDEX answer_question_id_idx ON qa.answer (question_id);
CREATE INDEX answer_data_product_id_created_at_idx ON qa.answer (data_product_id, created_at) WHERE data_product_id IS NOT NULL;
CREATE INDEX feedback_status_idx ON qa.feedback (status) WHERE status IN ('open','in_review');
CREATE INDEX answer_receipt_data_product_id_answered_at_idx ON qa.answer_receipt (data_product_id, answered_at DESC);
CREATE INDEX answer_receipt_answered_at_idx ON qa.answer_receipt (answered_at) WHERE frontier_used;
CREATE INDEX answer_receipt_figure_metric_version_id_idx ON qa.answer_receipt_figure (metric_version_id);
CREATE INDEX answer_receipt_figure_query_run_id_idx ON qa.answer_receipt_figure (query_run_id);
CREATE INDEX receipt_replay_receipt_id_started_at_idx ON qa.receipt_replay (receipt_id, started_at DESC);

-- ═══ schema query ═══
CREATE TABLE query.query_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  caller_kind text NOT NULL,
  caller_id uuid NOT NULL,
  principal_id uuid NOT NULL,
  source_id uuid,
  route text NOT NULL,
  period_close_id uuid,
  sql_generated text NOT NULL,
  sql_executed text NOT NULL,
  policies_applied uuid[] NOT NULL DEFAULT '{}',
  metric_version_ids uuid[] NOT NULL DEFAULT '{}',
  as_of date,
  row_count integer,
  result_hash text,
  result_ref text,
  duration_ms integer,
  status text NOT NULL DEFAULT 'running',
  error text,
  started_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT query_run_pkey PRIMARY KEY (id, started_at),
  CHECK (caller_kind IN ('question','tile','skill_run','agent_run','pipeline','period','eval','receipt_replay','ad_hoc')),
  CHECK (route IN ('live','history','period_snapshot')),
  CHECK (route <> 'period_snapshot' OR period_close_id IS NOT NULL),
  CHECK (status IN ('queued','running','succeeded','failed','cancelled','timeout'))
) PARTITION BY RANGE (started_at);
CREATE TABLE query.query_run_default PARTITION OF query.query_run DEFAULT;
COMMENT ON TABLE query.query_run IS 'Một lần chạy SQL: SQL đã viết lại theo chính sách, nguồn, thời điểm, số dòng, thời gian. Use case: UC-01-01, UC-01-02, UC-01-03, UC-01-04, UC-01-06, UC-02-02, UC-03-01, UC-03-02, UC-10-01, UC-10-05, UC-12-02.';
COMMENT ON COLUMN query.query_run.caller_kind IS 'question, tile, skill_run, agent_run, pipeline, period, eval, receipt_replay (UC-01-07), ad_hoc (SQL người dùng gửi qua POST /v1/query-runs, thêm 12/10/2026)';
COMMENT ON COLUMN query.query_run.principal_id IS 'Danh tính chạy truy vấn (người hoặc giao quyền của agent)';
COMMENT ON COLUMN query.query_run.source_id IS 'logic → catalog.source; null khi đọc kỳ chốt';
COMMENT ON COLUMN query.query_run.route IS 'live, history, period_snapshot (bộ định tuyến thời điểm)';
COMMENT ON COLUMN query.query_run.period_close_id IS 'logic → period.period_close';
COMMENT ON COLUMN query.query_run.sql_executed IS 'Sau khi Policy engine viết lại';
COMMENT ON COLUMN query.query_run.policies_applied IS 'logic → governance.access_policy';
COMMENT ON COLUMN query.query_run.result_ref IS 'MinIO da-results';
COMMENT ON COLUMN query.query_run.status IS 'queued, running, succeeded, failed, cancelled, timeout';

CREATE TABLE query.query_result (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  query_run_id uuid NOT NULL,
  columns jsonb NOT NULL,
  rows jsonb NOT NULL,
  truncated boolean NOT NULL DEFAULT false,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '30 days',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT query_result_pkey PRIMARY KEY (id),
  UNIQUE (query_run_id)
);
COMMENT ON TABLE query.query_result IS 'Kết quả rút gọn (tối đa 1.000 dòng) để hiển thị lại nhanh; giữ 30 ngày, bản đủ ở MinIO. Use case: UC-01-02, UC-02-02.';
COMMENT ON COLUMN query.query_result.query_run_id IS 'logic → query_run (bảng phân vùng)';
COMMENT ON COLUMN query.query_result.columns IS 'Tên, kiểu, đơn vị';
COMMENT ON COLUMN query.query_result.rows IS 'Đã che theo chính sách của người chạy';

CREATE TABLE query.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE query.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON query.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE query.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON query.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA query TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON query.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON query.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON query.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX query_run_caller_kind_caller_id_idx ON query.query_run (caller_kind, caller_id);
CREATE INDEX query_run_source_id_started_at_idx ON query.query_run (source_id, started_at) WHERE status = 'running';
CREATE INDEX query_result_expires_at_idx ON query.query_result (expires_at);

-- ═══ schema agent ═══
CREATE TABLE agent.agent_def (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  kind text NOT NULL,
  owner_user_id uuid NOT NULL,
  account_user_id uuid NOT NULL,
  template_ref uuid,
  current_config_version integer,
  status text NOT NULL DEFAULT 'draft',
  paused_reason text,
  status_before_lock text,
  monthly_budget numeric(14,2),
  spent_this_month numeric(14,2) NOT NULL DEFAULT 0,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT agent_def_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (kind IN ('analysis','monitor','report','reconcile','data_prep','data_quality','document','custom')),
  CHECK (status IN ('draft','testing','running','paused','retired','locked')),
  CHECK ((status = 'locked') = (status_before_lock IS NOT NULL))
);
COMMENT ON TABLE agent.agent_def IS 'Agent: tên, loại, chủ sở hữu, tài khoản agent, trạng thái; cấu hình chi tiết nằm ở agent_config. Use case: UC-08-01, UC-13-01.';
COMMENT ON COLUMN agent.agent_def.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN agent.agent_def.name IS 'Ví dụ Agent Đối soát';
COMMENT ON COLUMN agent.agent_def.kind IS 'analysis, monitor, report, reconcile, data_prep, data_quality, document, custom';
COMMENT ON COLUMN agent.agent_def.owner_user_id IS 'Người thật sở hữu (BR-147); logic → org.app_user';
COMMENT ON COLUMN agent.agent_def.account_user_id IS 'Tài khoản agent (app_user.kind = agent)';
COMMENT ON COLUMN agent.agent_def.template_ref IS 'logic → pack.pack_skill nếu tạo từ agent mẫu';
COMMENT ON COLUMN agent.agent_def.status IS 'draft, testing, running, paused, retired, locked (khoá khẩn cấp qua POST /v1/agents/{id}:lock, thêm 12/10/2026)';
COMMENT ON COLUMN agent.agent_def.paused_reason IS 'Ví dụ chủ sở hữu rời tổ chức';
COMMENT ON COLUMN agent.agent_def.status_before_lock IS 'Trạng thái trước khi khoá, mở khoá trả về trạng thái này; chỉ có giá trị khi locked (thêm 12/10/2026)';
COMMENT ON COLUMN agent.agent_def.monthly_budget IS 'Ngân sách tháng (BR-71)';
COMMENT ON COLUMN agent.agent_def.deleted_at IS 'Xoá mềm';

CREATE TABLE agent.agent_config (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_id uuid NOT NULL,
  version integer NOT NULL,
  goal text NOT NULL,
  data_scope jsonb NOT NULL DEFAULT '{}',
  skill_ids uuid[] NOT NULL DEFAULT '{}',
  autonomy text NOT NULL DEFAULT 'propose_approve',
  checkpoints jsonb NOT NULL DEFAULT '[]',
  denied_actions text[] NOT NULL DEFAULT '{}',
  limits jsonb NOT NULL DEFAULT '{}',
  model_by_task jsonb NOT NULL DEFAULT '{}',
  change_note text,
  status text NOT NULL DEFAULT 'draft',
  eval_run_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT agent_config_pkey PRIMARY KEY (id),
  UNIQUE (agent_id, version),
  CHECK (autonomy IN ('suggest_only','propose_approve','act_then_report')),
  CHECK (status IN ('draft','testing','passed','deployed','superseded')),
  CHECK (status NOT IN ('passed','deployed') OR eval_run_id IS NOT NULL)
);
COMMENT ON TABLE agent.agent_config IS 'Cấu hình agent theo phiên bản; sửa luôn tạo phiên bản mới (BR-69). Các trường khớp màn P13 · Agent · Cấu hình & trigger. Use case: UC-03-06, UC-13-01, UC-13-02.';
COMMENT ON COLUMN agent.agent_config.agent_id IS 'FK agent_def';
COMMENT ON COLUMN agent.agent_config.goal IS 'Mục tiêu một câu';
COMMENT ON COLUMN agent.agent_config.data_scope IS 'Nguồn, bảng, chỉ số, bộ sưu tập được đọc; không vượt quyền chủ sở hữu';
COMMENT ON COLUMN agent.agent_config.skill_ids IS 'logic → skill.skill';
COMMENT ON COLUMN agent.agent_config.autonomy IS 'suggest_only (Chỉ gợi ý), propose_approve (Đề xuất, người duyệt), act_then_report (Tự làm, báo sau)';
COMMENT ON COLUMN agent.agent_config.checkpoints IS 'Điều kiện phải dừng và hỏi, ví dụ hai nguồn lệch vượt ngưỡng';
COMMENT ON COLUMN agent.agent_config.denied_actions IS 'Ví dụ sửa dữ liệu gốc, xem số tài khoản, gửi ra ngoài';
COMMENT ON COLUMN agent.agent_config.limits IS 'max_steps, max_tokens, query_timeout_s, max_cost_per_run, max_duration_min';
COMMENT ON COLUMN agent.agent_config.model_by_task IS 'Mô hình theo loại việc; trống thì dùng governance.model_config';
COMMENT ON COLUMN agent.agent_config.status IS 'draft, testing, passed, deployed, superseded';
COMMENT ON COLUMN agent.agent_config.eval_run_id IS 'logic → eval.eval_run';

CREATE TABLE agent.agent_tool (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_config_id uuid NOT NULL,
  tool text NOT NULL,
  permission_level text NOT NULL,
  requires_checkpoint boolean NOT NULL DEFAULT false,
  allowed_targets uuid[],
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT agent_tool_pkey PRIMARY KEY (id),
  UNIQUE (agent_config_id, tool),
  CHECK (permission_level IN ('read','write_derived','send_external')),
  CHECK (permission_level <> 'send_external' OR requires_checkpoint)
);
COMMENT ON TABLE agent.agent_tool IS 'Công cụ một phiên bản cấu hình được dùng và mức quyền. Use case: UC-13-01, UC-13-02.';
COMMENT ON COLUMN agent.agent_tool.agent_config_id IS 'FK agent_config';
COMMENT ON COLUMN agent.agent_tool.tool IS 'Ví dụ query, run_skill, create_proposal, notify, agent.call';
COMMENT ON COLUMN agent.agent_tool.permission_level IS 'read, write_derived, send_external';
COMMENT ON COLUMN agent.agent_tool.requires_checkpoint IS 'Bắt buộc true với write_derived trừ khi act_then_report và có chính sách; luôn true với send_external (BR-70)';
COMMENT ON COLUMN agent.agent_tool.allowed_targets IS 'Với agent.call: danh sách agent được gọi';

CREATE TABLE agent.tool_def (
  id uuid NOT NULL,
  code text NOT NULL,
  permission_level text NOT NULL,
  owner_service text NOT NULL,
  endpoints text[] NOT NULL,
  model_description text NOT NULL,
  toolsets text[] NOT NULL DEFAULT '{}',
  execution_kinds text[] NOT NULL,
  restricted_agent_kinds text[] NOT NULL DEFAULT '{}',
  mcp_exposed boolean NOT NULL DEFAULT false,
  default_checkpoint text NOT NULL,
  use_cases text[] NOT NULL,
  schema_sha256 text,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tool_def_pkey PRIMARY KEY (id),
  UNIQUE (code),
  CHECK (code ~ '^[a-z]+(\.[a-z_]+)+$'),
  CHECK (permission_level IN ('read','write_derived','send_external')),
  CHECK (default_checkpoint IN ('none','on_condition','before','always')),
  CHECK (status IN ('draft','active','deprecated')),
  CHECK (execution_kinds <@ ARRAY['interactive','plan','workflow'] AND cardinality(execution_kinds) > 0),
  CHECK (char_length(model_description) <= 400),
  CHECK (permission_level <> 'send_external' OR (default_checkpoint = 'always' AND NOT mcp_exposed)),
  CHECK (status <> 'active' OR cardinality(use_cases) > 0),
  CHECK (NOT mcp_exposed OR code !~ '^exec\.')
);
COMMENT ON TABLE agent.tool_def IS 'Sổ công cụ của agent (tab 5 G2, G2.1): một dòng mỗi công cụ, là nguồn cho mô tả gửi mô hình, bộ công cụ theo ý định, quyền lộ ra MCP và bài kiểm phủ use case. Bảng dùng chung cho mọi tổ chức, nạp bằng migration cùng bản phát hành; không sửa qua API. Use case: UC-12-02, UC-13-01, UC-13-02.';
COMMENT ON COLUMN agent.tool_def.code IS 'Mã công cụ, ví dụ query.semantic';
COMMENT ON COLUMN agent.tool_def.permission_level IS 'read, write_derived, send_external';
COMMENT ON COLUMN agent.tool_def.owner_service IS 'Dịch vụ sở hữu, ví dụ Context service';
COMMENT ON COLUMN agent.tool_def.endpoints IS 'Endpoint ở tab 4 mà công cụ gọi, ví dụ {POST /v1/search/documents}';
COMMENT ON COLUMN agent.tool_def.model_description IS 'Mô tả cho mô hình, viết tay: dùng khi nào, không dùng khi nào; tối đa 400 ký tự';
COMMENT ON COLUMN agent.tool_def.toolsets IS 'Bộ công cụ theo ý định của Planner kiểu A: metric_lookup, explain_change, document, forecast, provenance, explore_sql';
COMMENT ON COLUMN agent.tool_def.execution_kinds IS 'interactive, plan, workflow';
COMMENT ON COLUMN agent.tool_def.restricted_agent_kinds IS 'Chỉ cấp cho các loại agent này; rỗng là không hạn chế';
COMMENT ON COLUMN agent.tool_def.mcp_exposed IS 'Lộ ra cho client MCP có phạm vi phù hợp (UC-12-02)';
COMMENT ON COLUMN agent.tool_def.default_checkpoint IS 'none, on_condition, before, always';
COMMENT ON COLUMN agent.tool_def.use_cases IS 'UC dùng công cụ, khớp ma trận tab 2 mục 11.4';
COMMENT ON COLUMN agent.tool_def.schema_sha256 IS 'Băm JSON Schema sinh từ OpenAPI ở lần build gần nhất (ADR-48)';
COMMENT ON COLUMN agent.tool_def.status IS 'draft, active, deprecated';

CREATE TABLE agent.agent_trigger (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_id uuid NOT NULL,
  kind text NOT NULL,
  cron text,
  work_calendar_id uuid,
  event_type text,
  condition jsonb NOT NULL DEFAULT '{}',
  min_interval interval,
  no_overlap boolean NOT NULL DEFAULT true,
  combine text NOT NULL DEFAULT 'any',
  enabled boolean NOT NULL DEFAULT true,
  temporal_schedule_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT agent_trigger_pkey PRIMARY KEY (id),
  CHECK (kind IN ('schedule','event','threshold','agent_call','manual')),
  CHECK (combine IN ('any','all')),
  CHECK ((kind <> 'schedule' OR cron IS NOT NULL) AND (kind <> 'event' OR event_type IS NOT NULL))
);
COMMENT ON TABLE agent.agent_trigger IS 'Khi nào agent chạy: lịch, sự kiện, ngưỡng, agent khác gọi, thủ công. Use case: UC-08-01, UC-13-03.';
COMMENT ON COLUMN agent.agent_trigger.agent_id IS 'FK agent_def';
COMMENT ON COLUMN agent.agent_trigger.kind IS 'schedule, event, threshold, agent_call, manual';
COMMENT ON COLUMN agent.agent_trigger.work_calendar_id IS 'logic → org.work_calendar';
COMMENT ON COLUMN agent.agent_trigger.event_type IS 'Ví dụ period.closed, job.succeeded';
COMMENT ON COLUMN agent.agent_trigger.condition IS 'Ví dụ lệch > 0,1% so với hôm qua';
COMMENT ON COLUMN agent.agent_trigger.min_interval IS 'Khoảng cách tối thiểu giữa hai lượt; tín hiệu lặp được gộp (BR-72)';
COMMENT ON COLUMN agent.agent_trigger.combine IS 'any, all';

CREATE TABLE agent.agent_deployment (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_id uuid NOT NULL,
  config_version integer NOT NULL,
  previous_version integer,
  traffic_pct smallint NOT NULL DEFAULT 10,
  gates jsonb NOT NULL,
  observed jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'pending_approval',
  rollback_reason text,
  approved_by uuid,
  hitl_request_id uuid,
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT agent_deployment_pkey PRIMARY KEY (id),
  CHECK (traffic_pct BETWEEN 0 AND 100),
  CHECK (status IN ('pending_approval','rolling','completed','rolled_back','cancelled')),
  CHECK (status <> 'rolled_back' OR rollback_reason IS NOT NULL)
);
COMMENT ON TABLE agent.agent_deployment IS 'Triển khai một phiên bản cấu hình theo tỷ lệ lượt, kèm cổng chất lượng và quay lui (SD-17). Use case: UC-13-05.';
COMMENT ON COLUMN agent.agent_deployment.agent_id IS 'FK agent_def';
COMMENT ON COLUMN agent.agent_deployment.traffic_pct IS '10, 50, 100';
COMMENT ON COLUMN agent.agent_deployment.gates IS 'Ngưỡng quay lui (BR-148): lỗi, tỷ lệ cần người, chi phí, số lượt tối thiểu';
COMMENT ON COLUMN agent.agent_deployment.observed IS 'Số đo trong cửa sổ quan sát';
COMMENT ON COLUMN agent.agent_deployment.status IS 'pending_approval, rolling, completed, rolled_back, cancelled';
COMMENT ON COLUMN agent.agent_deployment.hitl_request_id IS 'logic → inbox.hitl_request';

CREATE TABLE agent.agent_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_id uuid NOT NULL,
  config_version integer NOT NULL,
  data_space_id uuid NOT NULL,
  trigger_kind text NOT NULL,
  trigger_ref text,
  initiated_by uuid,
  parent_run_id uuid,
  depth smallint NOT NULL DEFAULT 0,
  is_test boolean NOT NULL DEFAULT false,
  workflow_id text,
  as_of date,
  status text NOT NULL DEFAULT 'queued',
  current_step integer,
  narrative jsonb NOT NULL DEFAULT '[]',
  cost numeric(14,2) NOT NULL DEFAULT 0,
  tokens integer NOT NULL DEFAULT 0,
  waiting_since timestamptz,
  started_at timestamptz,
  finished_at timestamptz,
  error text,
  stop_reason text,
  stop_detail jsonb NOT NULL DEFAULT '{}',
  snapshot_refs jsonb NOT NULL DEFAULT '[]',
  retry_of uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT agent_run_pkey PRIMARY KEY (id),
  CHECK (trigger_kind IN ('schedule','event','threshold','agent_call','manual','test')),
  CHECK (status IN ('queued','planning','running','waiting_human','paused','succeeded','failed','cancelled')),
  CHECK (depth BETWEEN 0 AND 3),
  CHECK ((parent_run_id IS NULL) = (depth = 0)),
  CHECK (stop_reason IS NULL OR stop_reason IN ('completed','loop_detected','no_progress','budget_steps','budget_tokens','budget_cost','budget_duration','user_cancelled','waiting_timeout','error')),
  CHECK (status NOT IN ('succeeded','failed','cancelled') OR stop_reason IS NOT NULL)
);
COMMENT ON TABLE agent.agent_run IS 'Một lượt chạy của agent (màn Lượt chạy); lượt con của điều phối nhiều agent trỏ về lượt cha. Use case: UC-02-05, UC-02-06, UC-07-07, UC-08-05, UC-11-03, UC-13-04, UC-13-05, UC-13-06, UC-13-07, UC-13-08.';
COMMENT ON COLUMN agent.agent_run.agent_id IS 'FK agent_def';
COMMENT ON COLUMN agent.agent_run.config_version IS 'Giữ nguyên suốt lượt chạy (BR-69)';
COMMENT ON COLUMN agent.agent_run.trigger_kind IS 'schedule, event, threshold, agent_call, manual, test';
COMMENT ON COLUMN agent.agent_run.trigger_ref IS 'Mã sự kiện hoặc lịch';
COMMENT ON COLUMN agent.agent_run.initiated_by IS 'Người giao việc hoặc khởi chạy';
COMMENT ON COLUMN agent.agent_run.parent_run_id IS 'Lượt cha (UC-13-08)';
COMMENT ON COLUMN agent.agent_run.depth IS 'Tối đa 3 (BR-77)';
COMMENT ON COLUMN agent.agent_run.is_test IS 'Chạy thử: công cụ ghi và gửi ở chế độ giả lập';
COMMENT ON COLUMN agent.agent_run.workflow_id IS 'Temporal';
COMMENT ON COLUMN agent.agent_run.status IS 'queued, planning, running, waiting_human, paused, succeeded, failed, cancelled';
COMMENT ON COLUMN agent.agent_run.narrative IS 'Diễn biến kể thành câu cho màn Đang làm gì';
COMMENT ON COLUMN agent.agent_run.cost IS 'Chi phí đã tốn';
COMMENT ON COLUMN agent.agent_run.waiting_since IS 'Chờ người quá 7 ngày thì tự huỷ (UC-13-06 E2)';
COMMENT ON COLUMN agent.agent_run.stop_reason IS 'completed, loop_detected, no_progress, budget_steps, budget_tokens, budget_cost, budget_duration, user_cancelled, waiting_timeout, error; bắt buộc khi succeeded, failed, cancelled (BR-170)';
COMMENT ON COLUMN agent.agent_run.stop_detail IS 'Chi tiết dừng: công cụ và call_fingerprint lặp, số lần, bước cuối có tiến triển, ngân sách đã dùng so với trần';
COMMENT ON COLUMN agent.agent_run.snapshot_refs IS 'Phiên bản kỹ năng, mô hình, bản chụp đã đọc để chạy lại cho cùng kết quả (BR-75)';
COMMENT ON COLUMN agent.agent_run.retry_of IS 'Lượt thất bại mà lượt này chạy lại với cùng đầu vào và phiên bản cấu hình (POST /v1/runs/{id}:retry, thêm 12/10/2026)';

CREATE TABLE agent.agent_step (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  seq integer NOT NULL,
  kind text NOT NULL,
  name text NOT NULL,
  input jsonb,
  output jsonb,
  summary text,
  status text NOT NULL,
  attempt smallint NOT NULL DEFAULT 1,
  child_run_id uuid,
  langfuse_span_id text,
  cost numeric(12,4) NOT NULL DEFAULT 0,
  started_at timestamptz NOT NULL,
  duration_ms integer,
  call_fingerprint text,
  result_hash text,
  CONSTRAINT agent_step_pkey PRIMARY KEY (id, started_at),
  CHECK (kind IN ('plan','llm_call','tool_call','query','skill','agent_call','checkpoint','message')),
  CHECK (status IN ('ok','error','retried','skipped','simulated'))
) PARTITION BY RANGE (started_at);
CREATE TABLE agent.agent_step_default PARTITION OF agent.agent_step DEFAULT;
COMMENT ON TABLE agent.agent_step IS 'Một bước trong lượt chạy: gọi mô hình, công cụ, SQL, agent khác; nguồn của màn Lượt chạy · Kỹ thuật. Use case: UC-08-05, UC-11-03, UC-13-06, UC-13-08.';
COMMENT ON COLUMN agent.agent_step.run_id IS 'logic → agent_run (bảng phân vùng)';
COMMENT ON COLUMN agent.agent_step.kind IS 'plan, llm_call, tool_call, query, skill, agent_call, checkpoint, message';
COMMENT ON COLUMN agent.agent_step.name IS 'Tên công cụ hoặc bước';
COMMENT ON COLUMN agent.agent_step.input IS 'Đã che dữ liệu cá nhân';
COMMENT ON COLUMN agent.agent_step.summary IS 'Câu kể cho người dùng';
COMMENT ON COLUMN agent.agent_step.status IS 'ok, error, retried, skipped, simulated';
COMMENT ON COLUMN agent.agent_step.attempt IS 'Thử lại tối đa 3 lần (UC-13-06 E1)';
COMMENT ON COLUMN agent.agent_step.child_run_id IS 'Khi kind = agent_call';
COMMENT ON COLUMN agent.agent_step.call_fingerprint IS 'SHA-256 của tên công cụ và tham số đã chuẩn hoá (khoá sắp xếp, bỏ khoảng trắng, ngày về ISO, bỏ idempotency_key); dùng phát hiện lặp (BR-170)';
COMMENT ON COLUMN agent.agent_step.result_hash IS 'SHA-256 của kết quả đã chuẩn hoá (hoặc của thông báo lỗi đã che); cùng call_fingerprint và result_hash từ 3 lần trong một lượt là lặp (BR-170)';

CREATE TABLE agent.agent_checkpoint_hit (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  checkpoint text NOT NULL,
  hitl_request_id uuid NOT NULL,
  resolved_at timestamptz,
  outcome text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT agent_checkpoint_hit_pkey PRIMARY KEY (id),
  CHECK (outcome IS NULL OR outcome IN ('approved','rejected','edited','expired'))
);
COMMENT ON TABLE agent.agent_checkpoint_hit IS 'Lần lượt chạy dừng ở một checkpoint và tạo yêu cầu cho người. Use case: UC-07-07, UC-13-06.';
COMMENT ON COLUMN agent.agent_checkpoint_hit.run_id IS 'FK agent_run';
COMMENT ON COLUMN agent.agent_checkpoint_hit.checkpoint IS 'Điều kiện đã khớp';
COMMENT ON COLUMN agent.agent_checkpoint_hit.hitl_request_id IS 'logic → inbox.hitl_request';
COMMENT ON COLUMN agent.agent_checkpoint_hit.outcome IS 'approved, rejected, edited, expired';

CREATE TABLE agent.agent_memory (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  agent_id uuid,
  data_space_id uuid NOT NULL,
  scope text NOT NULL,
  user_id uuid,
  kind text NOT NULL,
  content text NOT NULL,
  source_kind text NOT NULL,
  source_ref uuid,
  expires_at timestamptz,
  use_count integer NOT NULL DEFAULT 0,
  correction_count smallint NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT agent_memory_pkey PRIMARY KEY (id),
  CHECK (scope IN ('agent','user','data_space')),
  CHECK ((scope = 'agent' AND agent_id IS NOT NULL) OR (scope = 'user' AND user_id IS NOT NULL) OR scope = 'data_space'),
  CHECK (kind IN ('decision','preference','data_insight','domain_context')),
  CHECK (source_kind IN ('hitl','run','manual','pack')),
  CHECK (status IN ('pending_review','active','disabled','conflict')),
  CHECK (scope <> 'data_space' OR status <> 'active' OR updated_by IS NOT NULL)
);
COMMENT ON TABLE agent.agent_memory IS 'Ghi nhớ của agent; không chứa dữ liệu cá nhân, chính sách luôn thắng (BR-76). Use case: UC-13-07.';
COMMENT ON COLUMN agent.agent_memory.agent_id IS 'FK agent_def; null khi dùng chung cả Data Space';
COMMENT ON COLUMN agent.agent_memory.scope IS 'agent, user, data_space';
COMMENT ON COLUMN agent.agent_memory.user_id IS 'Khi scope = user';
COMMENT ON COLUMN agent.agent_memory.kind IS 'decision, preference, data_insight, domain_context';
COMMENT ON COLUMN agent.agent_memory.source_kind IS 'hitl, run, manual, pack';
COMMENT ON COLUMN agent.agent_memory.correction_count IS 'Đến 2 thì tự vô hiệu';
COMMENT ON COLUMN agent.agent_memory.status IS 'pending_review, active, disabled, conflict';

CREATE TABLE agent.background_task (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  requested_by uuid NOT NULL,
  agent_id uuid NOT NULL,
  description text NOT NULL,
  due_at timestamptz,
  workspace_id uuid,
  run_id uuid,
  status text NOT NULL DEFAULT 'pending_confirmation',
  result_artifact_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT background_task_pkey PRIMARY KEY (id),
  CHECK (status IN ('pending_confirmation','running','done','failed','cancelled'))
);
COMMENT ON TABLE agent.background_task IS 'Việc người dùng giao bằng lời cho agent chạy nền. Use case: UC-08-05.';
COMMENT ON COLUMN agent.background_task.agent_id IS 'FK agent_def';
COMMENT ON COLUMN agent.background_task.workspace_id IS 'logic → workspace.workspace nơi đổ kết quả';
COMMENT ON COLUMN agent.background_task.run_id IS 'FK agent_run';
COMMENT ON COLUMN agent.background_task.status IS 'pending_confirmation, running, done, failed, cancelled';
COMMENT ON COLUMN agent.background_task.result_artifact_id IS 'logic → workspace.artifact';

CREATE TABLE agent.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE agent.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON agent.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE agent.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON agent.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA agent TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON agent.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON agent.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON agent.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX tool_def_toolsets_idx ON agent.tool_def USING gin (toolsets);
CREATE INDEX tool_def_use_cases_idx ON agent.tool_def USING gin (use_cases);
CREATE UNIQUE INDEX agent_deployment_agent_id_key ON agent.agent_deployment (agent_id) WHERE status IN ('pending_approval','rolling');
CREATE INDEX agent_run_agent_id_idx ON agent.agent_run (agent_id) WHERE status IN ('queued','planning','running','waiting_human','paused');
CREATE INDEX agent_run_parent_run_id_idx ON agent.agent_run (parent_run_id) WHERE parent_run_id IS NOT NULL;
CREATE INDEX agent_step_run_id_seq_idx ON agent.agent_step (run_id, seq);

-- ═══ schema eval ═══
CREATE TABLE eval.eval_set (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid,
  subject_type text NOT NULL,
  subject_id uuid,
  name text NOT NULL,
  pass_threshold numeric(5,4) NOT NULL DEFAULT 0.95,
  min_items integer NOT NULL DEFAULT 100,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT eval_set_pkey PRIMARY KEY (id),
  CHECK (subject_type IN ('context','skill','agent','pack')),
  CHECK ((subject_type = 'context' AND data_space_id IS NOT NULL) OR (subject_type <> 'context' AND subject_id IS NOT NULL)),
  CHECK (status IN ('active','archived'))
);
COMMENT ON TABLE eval.eval_set IS 'Bộ đánh giá dùng chung cho lớp ngữ cảnh, kỹ năng, agent và gói ngành. Use case: UC-07-03, UC-07-06, UC-13-04.';
COMMENT ON COLUMN eval.eval_set.data_space_id IS 'Null với bộ của gói ngành';
COMMENT ON COLUMN eval.eval_set.subject_type IS 'context, skill, agent, pack';
COMMENT ON COLUMN eval.eval_set.subject_id IS 'Kỹ năng, agent hoặc phiên bản gói; null với lớp ngữ cảnh của Data Space';
COMMENT ON COLUMN eval.eval_set.pass_threshold IS 'Tỷ lệ đạt tối thiểu';
COMMENT ON COLUMN eval.eval_set.min_items IS 'Lớp ngữ cảnh cần ít nhất 100 câu';
COMMENT ON COLUMN eval.eval_set.status IS 'active, archived';

CREATE TABLE eval.eval_item (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  eval_set_id uuid NOT NULL,
  category text NOT NULL DEFAULT 'correct_result',
  input jsonb NOT NULL,
  as_of date,
  expected jsonb NOT NULL,
  tolerance numeric(10,6),
  origin text NOT NULL DEFAULT 'manual',
  origin_ref uuid,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT eval_item_pkey PRIMARY KEY (id),
  CHECK (category IN ('correct_result','ask_at_right_time','respect_permission','correct_format','refusal')),
  CHECK (origin IN ('manual','feedback','real_run','hitl_rule','generated','pack','error_book')),
  CHECK (origin <> 'error_book' OR origin_ref IS NOT NULL),
  CHECK (status IN ('active','needs_update','retired'))
);
COMMENT ON TABLE eval.eval_item IS 'Một mục đánh giá kèm đáp án: câu hỏi chuẩn, ca kiểm thử kỹ năng, tình huống thử agent. Use case: UC-01-05, UC-03-03, UC-03-04, UC-07-06, UC-13-04.';
COMMENT ON COLUMN eval.eval_item.eval_set_id IS 'FK eval_set';
COMMENT ON COLUMN eval.eval_item.category IS 'correct_result, ask_at_right_time, respect_permission, correct_format, refusal';
COMMENT ON COLUMN eval.eval_item.input IS 'Câu hỏi hoặc tham số đầu vào, đã che dữ liệu cá nhân (BR-74)';
COMMENT ON COLUMN eval.eval_item.expected IS 'Cách hiểu, con số kèm dung sai, hành vi mong đợi';
COMMENT ON COLUMN eval.eval_item.origin IS 'manual, feedback, real_run, hitl_rule, generated, pack, error_book (ca hồi quy từ Error Book, origin_ref = eval.error_book_entry.id, UC-07-14)';
COMMENT ON COLUMN eval.eval_item.origin_ref IS 'Ví dụ qa.feedback.id';
COMMENT ON COLUMN eval.eval_item.status IS 'active, needs_update, retired';

CREATE TABLE eval.eval_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  eval_set_id uuid NOT NULL,
  subject_version text NOT NULL,
  trigger text NOT NULL,
  trigger_ref uuid,
  item_count integer NOT NULL DEFAULT 0,
  passed integer NOT NULL DEFAULT 0,
  failed integer NOT NULL DEFAULT 0,
  correct_refusals integer NOT NULL DEFAULT 0,
  pass_rate numeric(5,4),
  baseline_run_id uuid,
  regressions integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'running',
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT eval_run_pkey PRIMARY KEY (id),
  CHECK (trigger IN ('proposal','nightly','model_change','manual','deploy')),
  CHECK (status IN ('running','completed','failed'))
);
COMMENT ON TABLE eval.eval_run IS 'Một lần chạy bộ đánh giá trên một phiên bản đối tượng (bản đang dùng hoặc bản nháp). Use case: UC-07-03, UC-07-06, UC-11-05, UC-13-04.';
COMMENT ON COLUMN eval.eval_run.eval_set_id IS 'FK eval_set';
COMMENT ON COLUMN eval.eval_run.subject_version IS 'Ví dụ context@draft-proposal, agent_config v6, model_config sql_generation v3';
COMMENT ON COLUMN eval.eval_run.trigger IS 'proposal, nightly, model_change, manual, deploy';
COMMENT ON COLUMN eval.eval_run.trigger_ref IS 'Ví dụ inbox.proposal.id';
COMMENT ON COLUMN eval.eval_run.baseline_run_id IS 'Lần chạy so sánh';
COMMENT ON COLUMN eval.eval_run.regressions IS 'Số mục đang đạt chuyển sang trượt; lớn hơn 0 thì người duyệt phải xem từng mục (BR-28)';
COMMENT ON COLUMN eval.eval_run.status IS 'running, completed, failed';

CREATE TABLE eval.eval_result (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  eval_run_id uuid NOT NULL,
  eval_item_id uuid NOT NULL,
  understanding_ok boolean,
  value_ok boolean,
  behavior_ok boolean,
  passed boolean NOT NULL,
  actual jsonb,
  cause text,
  changed_from_baseline boolean NOT NULL DEFAULT false,
  reviewed_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT eval_result_pkey PRIMARY KEY (id),
  UNIQUE (eval_run_id, eval_item_id)
);
COMMENT ON TABLE eval.eval_result IS 'Kết quả một mục trong một lần đánh giá, chấm ba tầng: cách hiểu, con số, hành vi. Use case: UC-07-03, UC-07-06.';
COMMENT ON COLUMN eval.eval_result.eval_run_id IS 'FK eval_run';
COMMENT ON COLUMN eval.eval_result.eval_item_id IS 'FK eval_item';
COMMENT ON COLUMN eval.eval_result.actual IS 'Cách agent hiểu, giá trị trả về';
COMMENT ON COLUMN eval.eval_result.cause IS 'Nguyên nhân sai do hệ thống gợi ý';
COMMENT ON COLUMN eval.eval_result.reviewed_by IS 'Người duyệt đã xem mục đổi kết quả';

CREATE TABLE eval.error_book_entry (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  entry_no text NOT NULL,
  data_space_id uuid NOT NULL,
  data_product_id uuid,
  source_kind text NOT NULL,
  feedback_id uuid,
  answer_id uuid,
  receipt_id uuid,
  hitl_request_id uuid,
  replay_id uuid,
  accuracy_log_id uuid,
  forecast_detail jsonb,
  lint_finding_id uuid,
  title text NOT NULL,
  detail jsonb NOT NULL DEFAULT '{}',
  severity text NOT NULL DEFAULT 'medium',
  error_kind text,
  root_cause text,
  assignee_id uuid,
  fix_kind text,
  fix_proposal_id uuid,
  fix_ref text,
  fixed_by uuid,
  fixed_at timestamptz,
  eval_item_id uuid,
  regression_run_id uuid,
  status text NOT NULL DEFAULT 'open',
  dismiss_reason text,
  duplicate_of_id uuid,
  reopened_count integer NOT NULL DEFAULT 0,
  pack_contribution text NOT NULL DEFAULT 'none',
  pack_proposal_ref text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT error_book_entry_pkey PRIMARY KEY (id),
  UNIQUE (org_id, entry_no),
  CHECK (source_kind IN ('user_report','number_check','reviewer_reject','replay_mismatch','forecast_miss','knowledge_lint')),
  CHECK (source_kind <> 'user_report' OR feedback_id IS NOT NULL),
  CHECK (source_kind <> 'reviewer_reject' OR hitl_request_id IS NOT NULL),
  CHECK (source_kind <> 'replay_mismatch' OR replay_id IS NOT NULL),
  CHECK (source_kind <> 'forecast_miss' OR (accuracy_log_id IS NOT NULL AND forecast_detail IS NOT NULL)),
  CHECK (source_kind <> 'knowledge_lint' OR lint_finding_id IS NOT NULL),
  CHECK (source_kind NOT IN ('user_report','number_check','reviewer_reject') OR answer_id IS NOT NULL),
  CHECK (severity IN ('low','medium','high')),
  CHECK (error_kind IS NULL OR error_kind IN ('definition','synonym','data','freshness','model','formula','retrieval')),
  CHECK (fix_kind IS NULL OR fix_kind IN ('metric_version','synonym','example','knowledge_page','pack_version','source_data','model_config','prompt','code','none')),
  CHECK (status IN ('open','fixed','regression_added','dismissed')),
  CHECK (status NOT IN ('fixed','regression_added') OR (error_kind IS NOT NULL AND root_cause IS NOT NULL AND assignee_id IS NOT NULL AND fix_kind IS NOT NULL AND fixed_by IS NOT NULL AND fixed_at IS NOT NULL)),
  CHECK (status NOT IN ('fixed','regression_added') OR fix_kind = 'none' OR fix_proposal_id IS NOT NULL OR fix_ref IS NOT NULL),
  CHECK (status <> 'regression_added' OR (eval_item_id IS NOT NULL AND regression_run_id IS NOT NULL)),
  CHECK (status <> 'dismissed' OR dismiss_reason IS NOT NULL OR duplicate_of_id IS NOT NULL),
  CHECK (duplicate_of_id IS NULL OR duplicate_of_id <> id),
  CHECK (pack_contribution IN ('none','proposed','accepted','rejected')),
  CHECK (pack_contribution = 'none' OR status IN ('fixed','regression_added'))
);
COMMENT ON TABLE eval.error_book_entry IS 'Mục Error Book: một lỗi đã xác nhận của câu trả lời hoặc một dự báo lệch vượt ngưỡng, kèm loại lỗi, nguyên nhân gốc, người xử lý, cách sửa và ca hồi quy tự thêm vào bộ đánh giá chạy trong CI. Trạng thái open → fixed → regression_added; dismissed khi không phải lỗi hoặc trùng (BR-179). Là kênh “tốt dần theo thời gian” cùng gói ngành: cách sửa dùng chung được đề xuất về P09. Thêm 10/10/2026. Use case: UC-07-14, UC-01-05, UC-01-07, UC-15-06.';
COMMENT ON COLUMN eval.error_book_entry.entry_no IS 'Mã hiển thị, ví dụ EB-0042; trigger cấp theo tổ chức';
COMMENT ON COLUMN eval.error_book_entry.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN eval.error_book_entry.data_product_id IS 'logic → context.data_product; null khi câu hỏi ngoài phạm vi';
COMMENT ON COLUMN eval.error_book_entry.source_kind IS 'user_report, number_check, reviewer_reject, replay_mismatch, forecast_miss, knowledge_lint';
COMMENT ON COLUMN eval.error_book_entry.feedback_id IS 'logic → qa.feedback; bắt buộc khi user_report';
COMMENT ON COLUMN eval.error_book_entry.answer_id IS 'logic → qa.answer';
COMMENT ON COLUMN eval.error_book_entry.receipt_id IS 'logic → qa.answer_receipt';
COMMENT ON COLUMN eval.error_book_entry.hitl_request_id IS 'logic → inbox.hitl_request; bắt buộc khi reviewer_reject';
COMMENT ON COLUMN eval.error_book_entry.replay_id IS 'logic → qa.receipt_replay; bắt buộc khi replay_mismatch';
COMMENT ON COLUMN eval.error_book_entry.accuracy_log_id IS 'logic → forecast.accuracy_log; bắt buộc khi forecast_miss';
COMMENT ON COLUMN eval.error_book_entry.forecast_detail IS 'Với forecast_miss: {model_version_id, period, actual, point, lo95, hi95, abs_scaled_error, threshold_rule, ledger_entry_id} (ledger_entry_id khi mục từ sổ dự báo, ngưỡng theo BR-186) do Eval service lấy từ payload sự kiện forecast.ledger.missed';
COMMENT ON COLUMN eval.error_book_entry.lint_finding_id IS 'logic → context.knowledge_lint_finding; bắt buộc khi knowledge_lint';
COMMENT ON COLUMN eval.error_book_entry.title IS 'Ví dụ Mức giảm E5RON92 kỳ 02/07/2026 ghi 1.155 đ/lít, công bố 1.055 đ/lít';
COMMENT ON COLUMN eval.error_book_entry.detail IS 'Số đúng, số sai, câu hỏi đã che dữ liệu cá nhân, chip, figure_key';
COMMENT ON COLUMN eval.error_book_entry.severity IS 'low, medium, high; high khi số đã vào báo cáo phát hành hoặc lệch dự báo gấp 2 lần ngưỡng';
COMMENT ON COLUMN eval.error_book_entry.error_kind IS 'definition, synonym, data, freshness, model, formula, retrieval; bắt buộc từ fixed';
COMMENT ON COLUMN eval.error_book_entry.root_cause IS 'Nguyên nhân gốc bằng lời; bắt buộc từ fixed';
COMMENT ON COLUMN eval.error_book_entry.assignee_id IS 'logic → org.app_user; mặc định steward của data product, không có thì người phụ trách Data Space';
COMMENT ON COLUMN eval.error_book_entry.fix_kind IS 'metric_version, synonym, example, knowledge_page, pack_version, source_data, model_config, prompt, code, none';
COMMENT ON COLUMN eval.error_book_entry.fix_proposal_id IS 'logic → inbox.proposal; đề xuất sửa chỉ số, đồng nghĩa, trang tri thức, gói ngành';
COMMENT ON COLUMN eval.error_book_entry.fix_ref IS 'Tham chiếu khác: mã commit, phiên bản model_config, phiên bản dataset đã sửa';
COMMENT ON COLUMN eval.error_book_entry.fixed_by IS 'logic → org.app_user';
COMMENT ON COLUMN eval.error_book_entry.eval_item_id IS 'logic → eval.eval_item (origin error_book)';
COMMENT ON COLUMN eval.error_book_entry.regression_run_id IS 'FK eval_run; lần chạy CI đầu tiên sau fixed_at mà ca hồi quy đạt';
COMMENT ON COLUMN eval.error_book_entry.status IS 'open, fixed, regression_added, dismissed';
COMMENT ON COLUMN eval.error_book_entry.dismiss_reason IS 'Bắt buộc khi dismissed mà không trùng mục khác';
COMMENT ON COLUMN eval.error_book_entry.duplicate_of_id IS 'FK error_book_entry';
COMMENT ON COLUMN eval.error_book_entry.reopened_count IS 'Ca hồi quy trượt sau khi đóng thì mở lại và tăng';
COMMENT ON COLUMN eval.error_book_entry.pack_contribution IS 'none, proposed, accepted, rejected; đề xuất đưa cách sửa về gói ngành (UC-09-05)';
COMMENT ON COLUMN eval.error_book_entry.pack_proposal_ref IS 'Mã đề xuất phía gói ngành, đã bỏ dữ liệu của khách';

CREATE TABLE eval.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE eval.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON eval.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE eval.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON eval.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA eval TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON eval.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON eval.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON eval.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX error_book_entry_feedback_id_key ON eval.error_book_entry (feedback_id) WHERE feedback_id IS NOT NULL;
CREATE UNIQUE INDEX error_book_entry_accuracy_log_id_key ON eval.error_book_entry (accuracy_log_id) WHERE accuracy_log_id IS NOT NULL;
CREATE UNIQUE INDEX error_book_entry_replay_id_key ON eval.error_book_entry (replay_id) WHERE replay_id IS NOT NULL;
CREATE INDEX error_book_entry_data_space_id_status_idx ON eval.error_book_entry (data_space_id, status);
CREATE INDEX error_book_entry_data_product_id_status_idx ON eval.error_book_entry (data_product_id, status);
CREATE INDEX error_book_entry_assignee_id_idx ON eval.error_book_entry (assignee_id) WHERE status = 'open';

-- ═══ schema inbox ═══
CREATE TABLE inbox.proposal (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  kind text NOT NULL,
  target_service text NOT NULL,
  target_ref uuid,
  title text NOT NULL,
  diff jsonb NOT NULL DEFAULT '{}',
  reason text,
  evidence jsonb NOT NULL DEFAULT '[]',
  impact jsonb NOT NULL DEFAULT '{}',
  impact_level text NOT NULL DEFAULT 'low',
  proposed_by uuid NOT NULL,
  assignee_id uuid,
  eval_run_id uuid,
  requires_compliance boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'open',
  expires_at timestamptz NOT NULL DEFAULT now() + interval '30 days',
  applied_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT proposal_pkey PRIMARY KEY (id),
  CHECK (kind IN ('metric_change','synonym','relationship','example','glossary','schema_change','skill_publish','pack_activate','pack_upgrade','metric_override','source_authority','writeback','document_validity','feedback_fix','knowledge_page','data_product')),
  CHECK (impact_level IN ('low','medium','high')),
  CHECK (status IN ('open','evaluating','pending_review','accepted','applied','apply_failed','rejected','expired','withdrawn'))
);
COMMENT ON TABLE inbox.proposal IS 'Đề xuất thay đổi chờ duyệt: lớp ngữ cảnh, schema, kỹ năng, gói ngành, ghi ngược, hiệu lực văn bản. Use case: UC-01-05, UC-03-05, UC-04-03, UC-05-05, UC-06-04, UC-07-01, UC-07-02, UC-07-03, UC-07-05, UC-07-06, UC-09-02, UC-09-03, UC-09-04.';
COMMENT ON COLUMN inbox.proposal.kind IS 'metric_change, synonym, relationship, example, glossary, schema_change, skill_publish, pack_activate, pack_upgrade, metric_override, source_authority, writeback, document_validity, feedback_fix, data_product (kích hoạt hoặc đổi phiên bản data product, UC-07-13), knowledge_page';
COMMENT ON COLUMN inbox.proposal.target_service IS 'Dịch vụ sở hữu đối tượng, sẽ phát hành khi chấp nhận';
COMMENT ON COLUMN inbox.proposal.target_ref IS 'Đối tượng bị thay đổi';
COMMENT ON COLUMN inbox.proposal.evidence IS 'Ví dụ 4 câu hỏi bị sửa giống nhau';
COMMENT ON COLUMN inbox.proposal.impact IS 'Số agent, ô, báo cáo, kỹ năng bị ảnh hưởng';
COMMENT ON COLUMN inbox.proposal.impact_level IS 'low, medium, high';
COMMENT ON COLUMN inbox.proposal.proposed_by IS 'Người hoặc tài khoản agent';
COMMENT ON COLUMN inbox.proposal.eval_run_id IS 'logic → eval.eval_run';
COMMENT ON COLUMN inbox.proposal.requires_compliance IS 'Đổi chỉ số dùng trong báo cáo đã nộp cần thêm AC06 (BR-119)';
COMMENT ON COLUMN inbox.proposal.status IS 'open, evaluating, pending_review, accepted, applied, apply_failed, rejected, expired, withdrawn';
COMMENT ON COLUMN inbox.proposal.expires_at IS 'Quá hạn chuyển expired (BR-29)';

CREATE TABLE inbox.proposal_review (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  proposal_id uuid NOT NULL,
  step smallint NOT NULL DEFAULT 1,
  reviewer_id uuid NOT NULL,
  decision text NOT NULL,
  note text,
  reviewed_regressions boolean NOT NULL DEFAULT false,
  decided_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT proposal_review_pkey PRIMARY KEY (id),
  CHECK (decision IN ('accept','accept_with_edit','reject','request_changes')),
  CHECK (decision <> 'reject' OR note IS NOT NULL),
  UNIQUE (proposal_id, step, reviewer_id)
);
COMMENT ON TABLE inbox.proposal_review IS 'Một quyết định duyệt; người duyệt phải khác người đề xuất (kiểm ở tầng ứng dụng). Use case: UC-07-03.';
COMMENT ON COLUMN inbox.proposal_review.proposal_id IS 'FK proposal';
COMMENT ON COLUMN inbox.proposal_review.step IS 'Bước trong chuỗi duyệt nhiều người';
COMMENT ON COLUMN inbox.proposal_review.decision IS 'accept, accept_with_edit, reject, request_changes';
COMMENT ON COLUMN inbox.proposal_review.note IS 'Bắt buộc khi reject (UC-07-03 4b)';
COMMENT ON COLUMN inbox.proposal_review.reviewed_regressions IS 'Đã xem từng mục bị đổi kết quả (BR-28)';

CREATE TABLE inbox.hitl_request (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid,
  kind text NOT NULL,
  risk text NOT NULL DEFAULT 'medium',
  title text NOT NULL,
  context jsonb NOT NULL DEFAULT '{}',
  options jsonb NOT NULL DEFAULT '[]',
  source_service text NOT NULL,
  source_ref uuid,
  parent_run_label text,
  assignee_id uuid,
  assignee_group text,
  assignee_capability text,
  due_at timestamptz,
  status text NOT NULL DEFAULT 'open',
  response jsonb,
  remember_as_rule boolean NOT NULL DEFAULT false,
  resolved_by uuid,
  resolved_at timestamptz,
  channel_card_ids uuid[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT hitl_request_pkey PRIMARY KEY (id),
  CHECK (kind IN ('approve_proposal','conflict','clarification','checkpoint','budget','access','export','writeback','period_exception','retro_change','deploy','memory_share','schema_drift','report_publish','data_review','entity_match','forecast_assumption','forecast_model','legal_review','knowledge_finding','formula_component')),
  CHECK (risk IN ('low','medium','high')),
  CHECK (status IN ('open','answered','approved','rejected','changes_requested','reassigned','expired','cancelled')),
  CHECK (status IN ('open','reassigned') OR resolved_at IS NOT NULL),
  CHECK (assignee_id IS NOT NULL OR assignee_group IS NOT NULL OR assignee_capability IS NOT NULL)
);
COMMENT ON TABLE inbox.hitl_request IS 'Yêu cầu người quyết định trong Cần bạn; mọi dịch vụ tạo yêu cầu qua đây. Use case: UC-01-05, UC-01-06, UC-02-07, UC-03-05, UC-04-07, UC-06-04, UC-07-03, UC-07-04, UC-07-07, UC-07-08, UC-08-04, UC-08-06, UC-10-02, UC-10-04, UC-11-07, UC-13-05, UC-13-07, UC-13-08.';
COMMENT ON COLUMN inbox.hitl_request.data_space_id IS 'Rỗng với yêu cầu toàn tổ chức (bản xuất nhật ký kiểm toán, quyền khẩn cấp); khi đó năng lực của người duyệt xét ở cấp tổ chức. Sửa 12/10/2026';
COMMENT ON COLUMN inbox.hitl_request.kind IS 'approve_proposal, conflict, clarification, checkpoint, budget, access, export, writeback, period_exception, retro_change, deploy, memory_share, schema_drift, report_publish, data_review, entity_match, forecast_assumption, forecast_model, legal_review, knowledge_finding';
COMMENT ON COLUMN inbox.hitl_request.risk IS 'low, medium, high';
COMMENT ON COLUMN inbox.hitl_request.context IS 'Dữ liệu để người quyết định, ví dụ hai nguồn và mức lệch';
COMMENT ON COLUMN inbox.hitl_request.options IS 'Các phương án';
COMMENT ON COLUMN inbox.hitl_request.source_ref IS 'Ví dụ agent_run, proposal, conflict';
COMMENT ON COLUMN inbox.hitl_request.parent_run_label IS 'Tên lượt chạy cha khi từ lượt con (BR-77)';
COMMENT ON COLUMN inbox.hitl_request.assignee_capability IS 'Năng lực của người duyệt (steward, compliance, audit_read…): ai có năng lực này trong Data Space của yêu cầu, hoặc ở cấp tổ chức khi data_space_id rỗng, thấy và duyệt được. Thêm 12/10/2026';
COMMENT ON COLUMN inbox.hitl_request.status IS 'open, answered, approved, rejected, changes_requested, reassigned, expired, cancelled';
COMMENT ON COLUMN inbox.hitl_request.response IS 'Phương án chọn và ghi chú';
COMMENT ON COLUMN inbox.hitl_request.remember_as_rule IS 'Bật “Ghi nhớ thành quy tắc” (UC-07-08)';
COMMENT ON COLUMN inbox.hitl_request.channel_card_ids IS 'logic → notify.channel_delivery';

CREATE TABLE inbox.hitl_approval_step (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  hitl_request_id uuid NOT NULL,
  step smallint NOT NULL,
  approver_role text NOT NULL,
  approver_id uuid,
  decision text,
  note text,
  decided_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT hitl_approval_step_pkey PRIMARY KEY (id),
  UNIQUE (hitl_request_id, step),
  CHECK (decision IS NULL OR decision IN ('approve','reject')),
  CHECK (decision IS NULL OR (approver_id IS NOT NULL AND decided_at IS NOT NULL))
);
COMMENT ON TABLE inbox.hitl_approval_step IS 'Một bước trong chuỗi duyệt nhiều người, ví dụ ngoại lệ kỳ chốt cần hai người (BR-132). Use case: UC-07-07, UC-10-02.';
COMMENT ON COLUMN inbox.hitl_approval_step.hitl_request_id IS 'FK hitl_request';
COMMENT ON COLUMN inbox.hitl_approval_step.approver_role IS 'Năng lực người duyệt bước này phải có, ví dụ steward, compliance; mỗi bước một người khác (BR-132)';
COMMENT ON COLUMN inbox.hitl_approval_step.decision IS 'approve, reject';

CREATE TABLE inbox.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE inbox.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON inbox.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE inbox.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON inbox.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA inbox TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON inbox.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON inbox.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON inbox.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX proposal_data_space_id_status_idx ON inbox.proposal (data_space_id, status) WHERE status IN ('open','evaluating','pending_review');
CREATE INDEX proposal_assignee_id_idx ON inbox.proposal (assignee_id) WHERE status = 'pending_review';
CREATE INDEX hitl_request_assignee_id_status_due_at_idx ON inbox.hitl_request (assignee_id, status, due_at) WHERE status = 'open';
CREATE INDEX hitl_request_source_service_source_ref_idx ON inbox.hitl_request (source_service, source_ref);

-- ═══ schema workspace ═══
CREATE TABLE workspace.workspace (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  title text NOT NULL,
  description text,
  params jsonb NOT NULL DEFAULT '{}',
  template_of_skill_id uuid,
  created_from text NOT NULL DEFAULT 'blank',
  created_from_ref uuid,
  tile_count integer NOT NULL DEFAULT 0,
  last_refreshed_at timestamptz,
  status text NOT NULL DEFAULT 'active',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT workspace_pkey PRIMARY KEY (id),
  CHECK (created_from IN ('blank','conversation','template','agent_run')),
  CHECK (tile_count BETWEEN 0 AND 200),
  CHECK (status IN ('active','archived'))
);
COMMENT ON TABLE workspace.workspace IS 'Phiên làm việc dạng notebook của người dùng; có tham số dùng chung cho các ô. Use case: UC-02-01, UC-02-06, UC-03-03, UC-03-07.';
COMMENT ON COLUMN workspace.workspace.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN workspace.workspace.title IS 'Ví dụ Nợ xấu bán lẻ T9';
COMMENT ON COLUMN workspace.workspace.params IS 'Tham số phiên, ví dụ kỳ, vùng';
COMMENT ON COLUMN workspace.workspace.template_of_skill_id IS 'logic → skill.skill nếu tạo từ kỹ năng';
COMMENT ON COLUMN workspace.workspace.created_from IS 'blank, conversation, template, agent_run';
COMMENT ON COLUMN workspace.workspace.tile_count IS 'Tối đa 200 ô (UC-02-01)';
COMMENT ON COLUMN workspace.workspace.status IS 'active, archived';
COMMENT ON COLUMN workspace.workspace.deleted_at IS 'Xoá mềm';

CREATE TABLE workspace.tile (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  position integer NOT NULL,
  kind text NOT NULL,
  title text,
  spec jsonb NOT NULL DEFAULT '{}',
  depends_on uuid[] NOT NULL DEFAULT '{}',
  author_kind text NOT NULL DEFAULT 'user',
  agent_suggestion_state text,
  latest_snapshot_id uuid,
  stale boolean NOT NULL DEFAULT false,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT tile_pkey PRIMARY KEY (id),
  CHECK (kind IN ('question','sql','chart','text','skill_run','agent_result','table')),
  CHECK (author_kind IN ('user','agent')),
  CHECK (agent_suggestion_state IS NULL OR agent_suggestion_state IN ('suggested','accepted','dismissed'))
);
COMMENT ON TABLE workspace.tile IS 'Một ô trong phiên: câu hỏi, SQL, biểu đồ, văn bản, kỹ năng, kết quả agent. Use case: UC-02-01, UC-02-02, UC-02-06, UC-03-03, UC-03-07, UC-06-05.';
COMMENT ON COLUMN workspace.tile.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.tile.kind IS 'question, sql, chart, text, skill_run, agent_result, table';
COMMENT ON COLUMN workspace.tile.spec IS 'Câu hỏi, SQL đã kiểm, cấu hình biểu đồ, tham số kỹ năng';
COMMENT ON COLUMN workspace.tile.depends_on IS 'Ô phụ thuộc; làm mới theo thứ tự phụ thuộc (UC-02-02)';
COMMENT ON COLUMN workspace.tile.author_kind IS 'user, agent';
COMMENT ON COLUMN workspace.tile.agent_suggestion_state IS 'suggested, accepted, dismissed khi ô do agent đề xuất';
COMMENT ON COLUMN workspace.tile.latest_snapshot_id IS 'FK tile_snapshot';
COMMENT ON COLUMN workspace.tile.stale IS 'Có dữ liệu mới, cần chạy lại';
COMMENT ON COLUMN workspace.tile.deleted_at IS 'Xoá mềm';

CREATE TABLE workspace.tile_snapshot (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  tile_id uuid NOT NULL,
  query_run_ids uuid[] NOT NULL DEFAULT '{}',
  as_of date,
  period_close_id uuid,
  data_time jsonb NOT NULL DEFAULT '{}',
  result_ref text,
  summary jsonb,
  status text NOT NULL,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT tile_snapshot_pkey PRIMARY KEY (id),
  CHECK (status IN ('ok','failed','partial'))
);
COMMENT ON TABLE workspace.tile_snapshot IS 'Kết quả lưu của một lần làm mới ô; đọc kỳ đã chốt thì ghi mã kỳ. Use case: UC-02-01, UC-02-02.';
COMMENT ON COLUMN workspace.tile_snapshot.tile_id IS 'FK tile';
COMMENT ON COLUMN workspace.tile_snapshot.query_run_ids IS 'logic → query.query_run';
COMMENT ON COLUMN workspace.tile_snapshot.period_close_id IS 'logic → period.period_close';
COMMENT ON COLUMN workspace.tile_snapshot.data_time IS 'Thời điểm dữ liệu từng nguồn; khác nhau thì hiện nhãn (UC-02-02)';
COMMENT ON COLUMN workspace.tile_snapshot.result_ref IS 'MinIO da-results';
COMMENT ON COLUMN workspace.tile_snapshot.summary IS 'Bản rút gọn để hiển thị nhanh';
COMMENT ON COLUMN workspace.tile_snapshot.status IS 'ok, failed, partial';

CREATE TABLE workspace.workspace_share (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  principal_type text NOT NULL,
  principal_id uuid NOT NULL,
  permission text NOT NULL,
  granted_by uuid NOT NULL,
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT workspace_share_pkey PRIMARY KEY (id),
  CHECK (principal_type IN ('user','group')),
  CHECK (permission IN ('view','comment','edit')),
  UNIQUE (workspace_id, principal_type, principal_id)
);
COMMENT ON TABLE workspace.workspace_share IS 'Chia sẻ phiên cho người hoặc nhóm, có hạn; người xem thấy số theo quyền của chính họ (BR-89). Use case: UC-02-03.';
COMMENT ON COLUMN workspace.workspace_share.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.workspace_share.principal_type IS 'user, group';
COMMENT ON COLUMN workspace.workspace_share.permission IS 'view, comment, edit';

CREATE TABLE workspace.ws_comment (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  tile_id uuid,
  parent_id uuid,
  author_id uuid NOT NULL,
  body text NOT NULL,
  mentions uuid[] NOT NULL DEFAULT '{}',
  assignee_id uuid,
  due_at timestamptz,
  status text NOT NULL DEFAULT 'open',
  resolved_at timestamptz,
  agent_run_id uuid,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT ws_comment_pkey PRIMARY KEY (id),
  CHECK (status IN ('open','done') AND (status = 'open' OR resolved_at IS NOT NULL))
);
COMMENT ON TABLE workspace.ws_comment IS 'Bình luận trên phiên hoặc ô, có @nhắc người và agent, có thể thành việc được giao. Use case: UC-02-05.';
COMMENT ON COLUMN workspace.ws_comment.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.ws_comment.tile_id IS 'FK tile';
COMMENT ON COLUMN workspace.ws_comment.parent_id IS 'Bình luận cha';
COMMENT ON COLUMN workspace.ws_comment.mentions IS 'Người hoặc agent được nhắc; nhắc agent tạo lượt chạy';
COMMENT ON COLUMN workspace.ws_comment.assignee_id IS 'Khi bình luận là việc được giao';
COMMENT ON COLUMN workspace.ws_comment.status IS 'open, done';
COMMENT ON COLUMN workspace.ws_comment.agent_run_id IS 'logic → agent.agent_run';
COMMENT ON COLUMN workspace.ws_comment.deleted_at IS 'Xoá mềm';

CREATE TABLE workspace.ws_participant (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  principal_type text NOT NULL,
  principal_id uuid NOT NULL,
  role text NOT NULL,
  joined_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ws_participant_pkey PRIMARY KEY (id),
  CHECK (principal_type IN ('user','agent')),
  CHECK (role IN ('owner','editor','viewer','agent_helper')),
  UNIQUE (workspace_id, principal_type, principal_id)
);
COMMENT ON TABLE workspace.ws_participant IS 'Người và agent tham gia phiên, với vai trò trong phiên. Use case: UC-02-01, UC-02-03, UC-02-06.';
COMMENT ON COLUMN workspace.ws_participant.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.ws_participant.principal_type IS 'user, agent';
COMMENT ON COLUMN workspace.ws_participant.role IS 'owner, editor, viewer, agent_helper';

CREATE TABLE workspace.artifact (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  tile_id uuid,
  kind text NOT NULL,
  title text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  content_ref text,
  content jsonb,
  produced_by_kind text NOT NULL,
  produced_by_ref uuid,
  evidence_state text NOT NULL DEFAULT 'unchecked',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT artifact_pkey PRIMARY KEY (id),
  CHECK (kind IN ('table','chart','proposal','dataset','file','text')),
  CHECK (produced_by_kind IN ('user','agent_run','skill_run')),
  CHECK (evidence_state IN ('unchecked','grounded','ungrounded'))
);
COMMENT ON TABLE workspace.artifact IS 'Kết quả có phiên bản trong phiên: bảng, biểu đồ, đề xuất, bộ dữ liệu, tệp. Use case: UC-02-06, UC-02-07, UC-08-05.';
COMMENT ON COLUMN workspace.artifact.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.artifact.tile_id IS 'FK tile';
COMMENT ON COLUMN workspace.artifact.kind IS 'table, chart, proposal, dataset, file, text';
COMMENT ON COLUMN workspace.artifact.content_ref IS 'MinIO da-results';
COMMENT ON COLUMN workspace.artifact.content IS 'Nội dung nhỏ lưu thẳng';
COMMENT ON COLUMN workspace.artifact.produced_by_kind IS 'user, agent_run, skill_run';
COMMENT ON COLUMN workspace.artifact.evidence_state IS 'unchecked, grounded, ungrounded (mỗi số có căn cứ hay không)';

CREATE TABLE workspace.session_report (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  workspace_id uuid NOT NULL,
  version integer NOT NULL DEFAULT 1,
  title text NOT NULL,
  body_ref text NOT NULL,
  checks jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'draft',
  approved_by uuid,
  published_at timestamptz,
  hitl_request_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT session_report_pkey PRIMARY KEY (id),
  CHECK (status IN ('draft','checking','ready','pending_approval','published','failed_checks')),
  CHECK (status <> 'published' OR (approved_by IS NOT NULL AND published_at IS NOT NULL)),
  UNIQUE (workspace_id, version)
);
COMMENT ON TABLE workspace.session_report IS 'Báo cáo sinh từ phiên và kết quả bốn kiểm tra trước khi phát hành (UC-02-07). Use case: UC-02-04, UC-02-07, UC-06-05, UC-08-03.';
COMMENT ON COLUMN workspace.session_report.workspace_id IS 'FK workspace';
COMMENT ON COLUMN workspace.session_report.body_ref IS 'Nội dung báo cáo trong MinIO';
COMMENT ON COLUMN workspace.session_report.checks IS 'Số có căn cứ, khớp số đã nộp, quyền người nhận, dữ liệu cá nhân; mỗi mục pass hoặc fail kèm chi tiết';
COMMENT ON COLUMN workspace.session_report.status IS 'draft, checking, ready, pending_approval, published, failed_checks';
COMMENT ON COLUMN workspace.session_report.hitl_request_id IS 'logic → inbox.hitl_request';

CREATE TABLE workspace.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE workspace.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON workspace.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE workspace.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON workspace.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA workspace TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON workspace.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON workspace.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON workspace.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX workspace_owner_id_idx ON workspace.workspace (owner_id) WHERE deleted_at IS NULL;
CREATE INDEX tile_snapshot_tile_id_created_at_idx ON workspace.tile_snapshot (tile_id, created_at DESC);
CREATE INDEX ws_comment_assignee_id_idx ON workspace.ws_comment (assignee_id) WHERE status = 'open';

-- ═══ schema skill ═══
CREATE TABLE skill.skill (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  category text NOT NULL,
  scope text NOT NULL DEFAULT 'personal',
  owner_id uuid NOT NULL,
  origin text NOT NULL DEFAULT 'manual',
  origin_ref uuid,
  current_version integer,
  replaced_by_skill_id uuid,
  run_count_30d integer NOT NULL DEFAULT 0,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT skill_pkey PRIMARY KEY (id),
  CHECK (category IN ('decomposition','causal','forecast','reconciliation','quality','report','custom')),
  CHECK (scope IN ('personal','data_space','org')),
  CHECK (scope = 'org' OR data_space_id IS NOT NULL),
  CHECK (origin IN ('manual','from_session','agent_suggested','pack')),
  UNIQUE NULLS NOT DISTINCT (org_id, data_space_id, code)
);
COMMENT ON TABLE skill.skill IS 'Kỹ năng phân tích dùng lại được (ví dụ phân rã biến động); phạm vi cá nhân, Data Space hoặc toàn tổ chức. Use case: UC-03-01, UC-03-03, UC-03-05, UC-03-06, UC-03-07.';
COMMENT ON COLUMN skill.skill.data_space_id IS 'Null khi phạm vi toàn tổ chức';
COMMENT ON COLUMN skill.skill.category IS 'decomposition, causal, forecast, reconciliation, quality, report, custom';
COMMENT ON COLUMN skill.skill.scope IS 'personal, data_space, org (BR-96)';
COMMENT ON COLUMN skill.skill.origin IS 'manual, from_session, agent_suggested, pack';
COMMENT ON COLUMN skill.skill.replaced_by_skill_id IS 'Khi ngừng dùng có kỹ năng thay thế (UC-03-06)';
COMMENT ON COLUMN skill.skill.deleted_at IS 'Xoá mềm';

CREATE TABLE skill.skill_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  skill_id uuid NOT NULL,
  version integer NOT NULL,
  params_schema jsonb NOT NULL,
  steps jsonb NOT NULL,
  template_md text,
  metric_version_ids uuid[] NOT NULL DEFAULT '{}',
  sandbox_limits jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'draft',
  eval_run_id uuid,
  approved_by uuid,
  approved_at timestamptz,
  approval_steps smallint NOT NULL DEFAULT 1,
  retire_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT skill_version_pkey PRIMARY KEY (id),
  UNIQUE (skill_id, version),
  CHECK (status IN ('draft','testing','pending_review','published','needs_review','retired')),
  CHECK (status NOT IN ('published','needs_review') OR (eval_run_id IS NOT NULL AND approved_by IS NOT NULL))
);
COMMENT ON TABLE skill.skill_version IS 'Phiên bản của kỹ năng: tham số, các bước, mẫu kết luận, ràng buộc sandbox. Use case: UC-03-01, UC-03-03, UC-03-04, UC-03-05, UC-03-06, UC-03-07.';
COMMENT ON COLUMN skill.skill_version.skill_id IS 'FK skill';
COMMENT ON COLUMN skill.skill_version.params_schema IS 'JSON Schema của tham số';
COMMENT ON COLUMN skill.skill_version.steps IS 'Các bước SQL, Python, gọi kỹ năng khác';
COMMENT ON COLUMN skill.skill_version.template_md IS 'Mẫu kết luận';
COMMENT ON COLUMN skill.skill_version.metric_version_ids IS 'Chỉ số dùng; đổi chỉ số thì chạy lại kiểm định (BR-13)';
COMMENT ON COLUMN skill.skill_version.sandbox_limits IS 'CPU, bộ nhớ, thời gian, không mạng (BR-94)';
COMMENT ON COLUMN skill.skill_version.status IS 'draft, testing, pending_review, published, needs_review, retired';
COMMENT ON COLUMN skill.skill_version.eval_run_id IS 'logic → eval.eval_run';
COMMENT ON COLUMN skill.skill_version.approval_steps IS 'Toàn tổ chức cần duyệt hai bước (BR-96)';
COMMENT ON COLUMN skill.skill_version.retire_at IS 'Ngừng sau 30 ngày chuyển tiếp (BR-97)';

CREATE TABLE skill.skill_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  skill_version_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  caller_kind text NOT NULL,
  caller_ref uuid,
  principal_id uuid NOT NULL,
  params jsonb NOT NULL,
  as_of date,
  status text NOT NULL DEFAULT 'queued',
  result jsonb,
  result_ref text,
  started_at timestamptz,
  finished_at timestamptz,
  error text,
  mode text NOT NULL DEFAULT 'run',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT skill_run_pkey PRIMARY KEY (id),
  CHECK (caller_kind IN ('user','tile','agent_run','alert','eval')),
  CHECK (mode IN ('run','try')),
  CHECK (status IN ('queued','running','succeeded','failed','cancelled'))
);
COMMENT ON TABLE skill.skill_run IS 'Một lần chạy kỹ năng với tham số cụ thể. Use case: UC-03-01, UC-03-02, UC-03-04, UC-08-02.';
COMMENT ON COLUMN skill.skill_run.skill_version_id IS 'FK skill_version';
COMMENT ON COLUMN skill.skill_run.caller_kind IS 'user, tile, agent_run, alert, eval';
COMMENT ON COLUMN skill.skill_run.status IS 'queued, running, succeeded, failed, cancelled';
COMMENT ON COLUMN skill.skill_run.result IS 'Kết luận và số chính';
COMMENT ON COLUMN skill.skill_run.mode IS 'run, try: try là chạy thử từ màn soạn kỹ năng (POST /v1/skill-versions/{id}:try), kết quả không dùng cho ô, cảnh báo hay agent (thêm 12/10/2026)';

CREATE TABLE skill.skill_run_step (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  skill_run_id uuid NOT NULL,
  seq smallint NOT NULL,
  name text NOT NULL,
  query_run_id uuid,
  output jsonb,
  status text NOT NULL,
  duration_ms integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT skill_run_step_pkey PRIMARY KEY (id),
  UNIQUE (skill_run_id, seq),
  CHECK (status IN ('ok','error','skipped'))
);
COMMENT ON TABLE skill.skill_run_step IS 'Kết quả từng bước của một lần chạy kỹ năng. Use case: UC-03-02.';
COMMENT ON COLUMN skill.skill_run_step.skill_run_id IS 'FK skill_run';
COMMENT ON COLUMN skill.skill_run_step.query_run_id IS 'logic → query.query_run';
COMMENT ON COLUMN skill.skill_run_step.status IS 'ok, error, skipped';

CREATE TABLE skill.skill_suggestion (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  pattern jsonb NOT NULL,
  session_ids uuid[] NOT NULL DEFAULT '{}',
  user_count integer NOT NULL,
  status text NOT NULL DEFAULT 'open',
  dismissed_until timestamptz,
  accepted_skill_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT skill_suggestion_pkey PRIMARY KEY (id),
  CHECK (status IN ('open','accepted','dismissed')),
  CHECK (status <> 'dismissed' OR dismissed_until IS NOT NULL)
);
COMMENT ON TABLE skill.skill_suggestion IS 'Kỹ năng agent đề xuất từ chuỗi bước người dùng lặp lại; chỉ dựa trên cấu trúc, không dùng dữ liệu của người khác. Use case: UC-03-07.';
COMMENT ON COLUMN skill.skill_suggestion.pattern IS 'Chuỗi bước đã khái quát, chỉ cấu trúc: loại bước, tên tham số, params_schema; không có giá trị, kết quả, mẫu dòng hay nội dung ô của phiên (BR-98, sửa 12/10/2026)';
COMMENT ON COLUMN skill.skill_suggestion.session_ids IS 'logic → workspace.workspace';
COMMENT ON COLUMN skill.skill_suggestion.status IS 'open, accepted, dismissed';
COMMENT ON COLUMN skill.skill_suggestion.dismissed_until IS 'Không đề xuất lại trong 90 ngày';
COMMENT ON COLUMN skill.skill_suggestion.accepted_skill_id IS 'FK skill';

CREATE TABLE skill.external_series (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  provider text NOT NULL,
  frequency text NOT NULL,
  unit text,
  ingest_mode text NOT NULL,
  last_observation_date date,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT external_series_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code),
  CHECK (frequency IN ('daily','weekly','monthly','quarterly')),
  CHECK (ingest_mode IN ('proxy','manual_upload'))
);
COMMENT ON TABLE skill.external_series IS 'Chuỗi dữ liệu bên ngoài (ví dụ CPI, tỷ giá, lãi suất thị trường), thẩm quyền tham khảo. Use case: UC-03-02.';
COMMENT ON COLUMN skill.external_series.provider IS 'Đơn vị công bố';
COMMENT ON COLUMN skill.external_series.frequency IS 'daily, weekly, monthly, quarterly';
COMMENT ON COLUMN skill.external_series.ingest_mode IS 'proxy, manual_upload';

CREATE TABLE skill.external_observation (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  series_id uuid NOT NULL,
  observation_date date NOT NULL,
  published_at timestamptz NOT NULL,
  value numeric NOT NULL,
  revision smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT external_observation_pkey PRIMARY KEY (id),
  UNIQUE (series_id, observation_date, revision)
);
COMMENT ON TABLE skill.external_observation IS 'Một giá trị của chuỗi ngoài; có ngày công bố để phân tích không “nhìn trước” (BR-93). Use case: UC-03-02.';
COMMENT ON COLUMN skill.external_observation.series_id IS 'FK external_series';
COMMENT ON COLUMN skill.external_observation.observation_date IS 'Ngày dữ liệu';
COMMENT ON COLUMN skill.external_observation.published_at IS 'Ngày công bố; chỉ dùng giá trị đã công bố trước as_of';
COMMENT ON COLUMN skill.external_observation.revision IS 'Lần điều chỉnh số liệu của đơn vị công bố';

CREATE TABLE skill.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE skill.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON skill.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE skill.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON skill.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA skill TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON skill.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON skill.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON skill.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX skill_version_skill_id_key ON skill.skill_version (skill_id) WHERE status = 'published';
CREATE INDEX skill_run_skill_version_id_created_at_idx ON skill.skill_run (skill_version_id, created_at DESC);

-- ═══ schema monitor ═══
CREATE TABLE monitor.monitor (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  agent_def_id uuid,
  metric_id uuid NOT NULL,
  scope_filter jsonb NOT NULL DEFAULT '{}',
  rule_kind text NOT NULL,
  rule jsonb NOT NULL,
  schedule_cron text NOT NULL,
  notify_mode text NOT NULL DEFAULT 'alert_only',
  recipients jsonb NOT NULL DEFAULT '[]',
  backtest jsonb,
  status text NOT NULL DEFAULT 'active',
  paused_reason text,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT monitor_pkey PRIMARY KEY (id),
  CHECK (rule_kind IN ('threshold','change_vs_previous','seasonal_anomaly')),
  CHECK (notify_mode IN ('alert_only','with_analysis')),
  CHECK (status IN ('draft','active','paused'))
);
COMMENT ON TABLE monitor.monitor IS 'Theo dõi chỉ số: luật ngưỡng, thay đổi so kỳ trước hoặc bất thường theo mùa vụ; do một agent thực hiện. Use case: UC-08-01, UC-08-02.';
COMMENT ON COLUMN monitor.monitor.agent_def_id IS 'logic → agent.agent_def';
COMMENT ON COLUMN monitor.monitor.metric_id IS 'logic → context.metric';
COMMENT ON COLUMN monitor.monitor.scope_filter IS 'Vùng, sản phẩm, chi nhánh';
COMMENT ON COLUMN monitor.monitor.rule_kind IS 'threshold, change_vs_previous, seasonal_anomaly';
COMMENT ON COLUMN monitor.monitor.rule IS 'Ngưỡng, hướng, độ nhạy';
COMMENT ON COLUMN monitor.monitor.notify_mode IS 'alert_only, with_analysis';
COMMENT ON COLUMN monitor.monitor.recipients IS 'Người, nhóm và kênh';
COMMENT ON COLUMN monitor.monitor.backtest IS 'Số lần sẽ báo trong 12 kỳ; trên 30% thì cảnh báo nhiễu (BR-32)';
COMMENT ON COLUMN monitor.monitor.status IS 'draft, active, paused';
COMMENT ON COLUMN monitor.monitor.paused_reason IS 'Ví dụ chỉ số đổi định nghĩa';
COMMENT ON COLUMN monitor.monitor.deleted_at IS 'Xoá mềm';

CREATE TABLE monitor.alert (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  monitor_id uuid NOT NULL,
  fired_at timestamptz NOT NULL DEFAULT now(),
  period_label text,
  value numeric,
  threshold_value numeric,
  summary text NOT NULL,
  skill_run_id uuid,
  dedup_key text NOT NULL,
  occurrences integer NOT NULL DEFAULT 1,
  kind text NOT NULL DEFAULT 'metric',
  status text NOT NULL DEFAULT 'open',
  assigned_to uuid,
  close_note text,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT alert_pkey PRIMARY KEY (id),
  CHECK (kind IN ('metric','data_stale')),
  CHECK (status IN ('open','ack','assigned','closed')),
  CHECK (status <> 'closed' OR closed_at IS NOT NULL),
  CHECK (status <> 'closed' OR occurrences <= 2 OR close_note IS NOT NULL)
);
COMMENT ON TABLE monitor.alert IS 'Cảnh báo phát sinh khi luật khớp; gộp tín hiệu lặp trong 24 giờ (BR-33). Use case: UC-08-01, UC-08-02, UC-08-04.';
COMMENT ON COLUMN monitor.alert.monitor_id IS 'FK monitor';
COMMENT ON COLUMN monitor.alert.period_label IS 'Ví dụ T9/2026';
COMMENT ON COLUMN monitor.alert.summary IS 'Ba dòng: điều gì đổi, vì sao, cần làm gì';
COMMENT ON COLUMN monitor.alert.skill_run_id IS 'logic → skill.skill_run phân tích nguyên nhân';
COMMENT ON COLUMN monitor.alert.kind IS 'metric, data_stale';
COMMENT ON COLUMN monitor.alert.status IS 'open, ack, assigned, closed';
COMMENT ON COLUMN monitor.alert.close_note IS 'Bắt buộc khi vượt ngưỡng hơn 2 lần (BR-124)';

CREATE TABLE monitor.report_schedule (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  kind text NOT NULL DEFAULT 'report',
  workspace_id uuid,
  owner_id uuid NOT NULL,
  title text NOT NULL,
  cron text NOT NULL,
  work_calendar_id uuid,
  cutoff_time time,
  as_of_rule text NOT NULL,
  formats text[] NOT NULL DEFAULT '{pdf}',
  require_publish_check boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'active',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT report_schedule_pkey PRIMARY KEY (id),
  CHECK (kind IN ('report','digest')),
  CHECK (kind = 'digest' OR workspace_id IS NOT NULL),
  CHECK (status IN ('draft','active','paused'))
);
COMMENT ON TABLE monitor.report_schedule IS 'Báo cáo định kỳ hoặc bản tin lãnh đạo, chạy theo lịch làm việc. Use case: UC-02-04, UC-03-06, UC-08-03, UC-08-04.';
COMMENT ON COLUMN monitor.report_schedule.kind IS 'report, digest';
COMMENT ON COLUMN monitor.report_schedule.workspace_id IS 'logic → workspace.workspace; null với bản tin';
COMMENT ON COLUMN monitor.report_schedule.work_calendar_id IS 'logic → org.work_calendar';
COMMENT ON COLUMN monitor.report_schedule.cutoff_time IS 'Giờ chốt dữ liệu';
COMMENT ON COLUMN monitor.report_schedule.as_of_rule IS 'Ví dụ end_of_previous_month';
COMMENT ON COLUMN monitor.report_schedule.formats IS 'pdf, xlsx, html';
COMMENT ON COLUMN monitor.report_schedule.require_publish_check IS 'Chạy bốn kiểm tra trước khi gửi';
COMMENT ON COLUMN monitor.report_schedule.status IS 'draft, active, paused';
COMMENT ON COLUMN monitor.report_schedule.deleted_at IS 'Xoá mềm';

CREATE TABLE monitor.report_recipient (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  report_schedule_id uuid NOT NULL,
  principal_type text NOT NULL,
  principal_id uuid NOT NULL,
  channels text[] NOT NULL DEFAULT '{email}',
  permission_group text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_recipient_pkey PRIMARY KEY (id),
  CHECK (principal_type IN ('user','group')),
  UNIQUE (report_schedule_id, principal_type, principal_id)
);
COMMENT ON TABLE monitor.report_recipient IS 'Người nhận báo cáo và nhóm quyền dùng để sinh bản riêng (BR-34). Use case: UC-02-07, UC-08-03.';
COMMENT ON COLUMN monitor.report_recipient.report_schedule_id IS 'FK report_schedule';
COMMENT ON COLUMN monitor.report_recipient.principal_type IS 'user, group';
COMMENT ON COLUMN monitor.report_recipient.channels IS 'email, teams, zalo, in_app';
COMMENT ON COLUMN monitor.report_recipient.permission_group IS 'Băm của tập quyền; người cùng tập quyền nhận cùng một bản';

CREATE TABLE monitor.report_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  report_schedule_id uuid NOT NULL,
  kind text NOT NULL DEFAULT 'report',
  as_of date NOT NULL,
  workflow_id text,
  trigger text NOT NULL DEFAULT 'schedule',
  checks jsonb NOT NULL DEFAULT '{}',
  outputs jsonb NOT NULL DEFAULT '[]',
  status text NOT NULL DEFAULT 'running',
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT report_run_pkey PRIMARY KEY (id),
  CHECK (kind IN ('report','digest')),
  CHECK (trigger IN ('schedule','run_now')),
  CHECK (status IN ('running','sent','partially_sent','blocked_by_checks','failed'))
);
COMMENT ON TABLE monitor.report_run IS 'Một lần chạy báo cáo hoặc bản tin, mỗi nhóm quyền một tệp kết quả. Use case: UC-08-03, UC-08-04.';
COMMENT ON COLUMN monitor.report_run.report_schedule_id IS 'FK report_schedule';
COMMENT ON COLUMN monitor.report_run.kind IS 'report, digest';
COMMENT ON COLUMN monitor.report_run.trigger IS 'schedule, run_now';
COMMENT ON COLUMN monitor.report_run.checks IS 'Kết quả kiểm tra trước khi gửi';
COMMENT ON COLUMN monitor.report_run.outputs IS 'Mỗi phần tử: permission_group, định dạng, object_key, trạng thái gửi';
COMMENT ON COLUMN monitor.report_run.status IS 'running, sent, partially_sent, blocked_by_checks, failed';

CREATE TABLE monitor.external_calendar (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  owner_id uuid NOT NULL,
  legal_basis text,
  recurrence_hint text,
  default_local_time time,
  timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
  work_calendar_id uuid,
  detection_source_id uuid,
  forecast_model_ids uuid[] NOT NULL DEFAULT '{}',
  pre_bulletin_days_before smallint NOT NULL DEFAULT 1,
  pre_bulletin_local_time time NOT NULL DEFAULT '20:00',
  forecast_lead interval NOT NULL DEFAULT '2 hours',
  post_bulletin boolean NOT NULL DEFAULT true,
  post_wait_max interval NOT NULL DEFAULT '12 hours',
  status text NOT NULL DEFAULT 'active',
  temporal_schedule_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT external_calendar_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (status IN ('active','paused','retired')),
  CHECK (pre_bulletin_days_before >= 0 AND pre_bulletin_days_before <= 7),
  CHECK (forecast_lead > interval '0' AND forecast_lead <= interval '24 hours'),
  CHECK (post_wait_max > interval '0' AND post_wait_max <= interval '72 hours'),
  CHECK (status <> 'active' OR detection_source_id IS NOT NULL OR recurrence_hint IS NOT NULL)
);
COMMENT ON TABLE monitor.external_calendar IS 'Lịch sự kiện ngoài tổ chức do người khai báo hoặc agent phát hiện, ví dụ kỳ điều hành giá xăng dầu; mỗi kỳ là một external_event, ngày giờ kỳ không viết cứng trong mã (BR-187). Use case: UC-08-08.';
COMMENT ON COLUMN monitor.external_calendar.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN monitor.external_calendar.code IS 'Ví dụ fuel_price_regulation; context.data_product_member.sla_event_calendar_code tham chiếu logic tới mã này để tính hạn độ tươi (BR-178)';
COMMENT ON COLUMN monitor.external_calendar.name IS 'Ví dụ Kỳ điều hành giá xăng dầu';
COMMENT ON COLUMN monitor.external_calendar.owner_id IS 'logic → org.app_user; người xác nhận kỳ khi phát hiện không chắc';
COMMENT ON COLUMN monitor.external_calendar.legal_basis IS 'Căn cứ của nhịp thường lệ, ví dụ Nghị định 80/2023/NĐ-CP';
COMMENT ON COLUMN monitor.external_calendar.recurrence_hint IS 'RRULE gợi ý, ví dụ FREQ=WEEKLY;BYDAY=TH; chỉ dùng để dự kiến kỳ, kỳ thật lấy từ khai báo hoặc phát hiện';
COMMENT ON COLUMN monitor.external_calendar.default_local_time IS 'Giờ áp dụng thường lệ, ví dụ 15:00';
COMMENT ON COLUMN monitor.external_calendar.work_calendar_id IS 'logic → org.work_calendar; ngày nghỉ làm kỳ dự kiến cần xác nhận';
COMMENT ON COLUMN monitor.external_calendar.detection_source_id IS 'logic → acquire.crawl_source; nguồn phát hiện thông báo kỳ và kết quả kỳ, ví dụ trang tin điều hành giá trên moit.gov.vn';
COMMENT ON COLUMN monitor.external_calendar.forecast_model_ids IS 'logic → forecast.forecast_model; mô hình chạy trước mỗi kỳ';
COMMENT ON COLUMN monitor.external_calendar.pre_bulletin_days_before IS 'Số ngày trước kỳ gửi bản tin dự báo';
COMMENT ON COLUMN monitor.external_calendar.pre_bulletin_local_time IS 'Giờ gửi bản tin dự báo theo timezone';
COMMENT ON COLUMN monitor.external_calendar.forecast_lead IS 'Chạy dự báo trước giờ gửi bao lâu';
COMMENT ON COLUMN monitor.external_calendar.post_bulletin IS 'Gửi bản tin kết quả kèm chấm điểm sau kỳ';
COMMENT ON COLUMN monitor.external_calendar.post_wait_max IS 'Chờ kết quả tối đa sau expected_at; quá thì hỏi người phụ trách';
COMMENT ON COLUMN monitor.external_calendar.status IS 'active, paused, retired';
COMMENT ON COLUMN monitor.external_calendar.temporal_schedule_id IS 'Schedule kiểm phát hiện kỳ và dự kiến kỳ mới (ADR-33)';

CREATE TABLE monitor.external_event (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  calendar_id uuid NOT NULL,
  period_label text NOT NULL,
  expected_at timestamptz NOT NULL,
  origin text NOT NULL,
  status text NOT NULL DEFAULT 'expected',
  confirmed_by uuid,
  evidence jsonb NOT NULL DEFAULT '{}',
  shifted_from timestamptz,
  occurred_at timestamptz,
  pre_bulletin_at timestamptz,
  workflow_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT external_event_pkey PRIMARY KEY (id),
  CHECK (origin IN ('recurrence','declared','detected')),
  CHECK (status IN ('expected','confirmed','shifted','occurred','cancelled')),
  CHECK (status <> 'occurred' OR occurred_at IS NOT NULL),
  CHECK (status <> 'shifted' OR shifted_from IS NOT NULL),
  CHECK (origin <> 'declared' OR confirmed_by IS NOT NULL),
  CHECK (origin <> 'detected' OR evidence <> '{}'::jsonb),
  CHECK (pre_bulletin_at IS NULL OR pre_bulletin_at < expected_at)
);
COMMENT ON TABLE monitor.external_event IS 'Một kỳ của lịch sự kiện ngoài: dự kiến từ nhịp thường lệ, do người khai, hoặc phát hiện từ nguồn; mỗi kỳ có một workflow bản tin (BR-187). Use case: UC-08-08, UC-15-08.';
COMMENT ON COLUMN monitor.external_event.calendar_id IS 'FK external_calendar';
COMMENT ON COLUMN monitor.external_event.period_label IS 'Nhãn kỳ, ví dụ 2026-07-09';
COMMENT ON COLUMN monitor.external_event.expected_at IS 'Thời điểm dự kiến áp dụng, ví dụ 2026-07-09 15:00 +07';
COMMENT ON COLUMN monitor.external_event.origin IS 'recurrence (dự kiến từ recurrence_hint), declared (người khai), detected (phát hiện từ nguồn)';
COMMENT ON COLUMN monitor.external_event.status IS 'expected, confirmed, shifted, occurred, cancelled';
COMMENT ON COLUMN monitor.external_event.confirmed_by IS 'logic → org.app_user; null khi xác nhận từ nguồn';
COMMENT ON COLUMN monitor.external_event.evidence IS '{extracted_record_id, url, quote} của thông báo kỳ hoặc bản tin kết quả';
COMMENT ON COLUMN monitor.external_event.shifted_from IS 'expected_at cũ khi kỳ dời';
COMMENT ON COLUMN monitor.external_event.occurred_at IS 'Thời điểm áp dụng thực tế theo bản tin, ví dụ 2026-07-02 16:00 +07';
COMMENT ON COLUMN monitor.external_event.pre_bulletin_at IS 'Tính từ lịch, ví dụ 2026-07-08 20:00 +07; tính lại khi kỳ dời';
COMMENT ON COLUMN monitor.external_event.workflow_id IS 'Workflow bản tin của kỳ (Temporal từ R3; trước R3 là lượt quét định kỳ, G8.11)';

CREATE TABLE monitor.event_subscription (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  calendar_id uuid NOT NULL,
  user_id uuid NOT NULL,
  kinds text[] NOT NULL DEFAULT '{pre,post}',
  channels text[] NOT NULL DEFAULT '{in_app}',
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_subscription_pkey PRIMARY KEY (id),
  UNIQUE (calendar_id, user_id),
  CHECK (cardinality(kinds) > 0 AND kinds <@ ARRAY['pre','post']::text[]),
  CHECK (channels <@ ARRAY['in_app','email','teams','zalo','mobile_push']::text[] AND 'in_app' = ANY (channels)),
  CHECK (status IN ('active','paused'))
);
COMMENT ON TABLE monitor.event_subscription IS 'Người theo dõi một lịch sự kiện ngoài: loại bản tin và kênh nhận; kênh và giờ yên lặng vẫn theo notify.notification_pref (BR-127). Use case: UC-08-08.';
COMMENT ON COLUMN monitor.event_subscription.calendar_id IS 'FK external_calendar';
COMMENT ON COLUMN monitor.event_subscription.user_id IS 'logic → org.app_user';
COMMENT ON COLUMN monitor.event_subscription.kinds IS 'pre (bản tin dự báo trước kỳ), post (bản tin kết quả và chấm điểm)';
COMMENT ON COLUMN monitor.event_subscription.channels IS 'in_app, email, teams, zalo, mobile_push';
COMMENT ON COLUMN monitor.event_subscription.status IS 'active, paused';

CREATE TABLE monitor.event_bulletin (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  event_id uuid NOT NULL,
  kind text NOT NULL,
  status text NOT NULL DEFAULT 'preparing',
  ledger_entry_ids uuid[] NOT NULL DEFAULT '{}',
  gate_result jsonb NOT NULL DEFAULT '{}',
  content jsonb NOT NULL DEFAULT '{}',
  recipients_count integer NOT NULL DEFAULT 0,
  sent_at timestamptz,
  web_link text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT event_bulletin_pkey PRIMARY KEY (id),
  UNIQUE (event_id, kind),
  CHECK (kind IN ('pre','post')),
  CHECK (status IN ('preparing','sent','sent_no_forecast','blocked','failed')),
  CHECK (status NOT IN ('sent','sent_no_forecast') OR sent_at IS NOT NULL),
  CHECK (status <> 'sent' OR cardinality(ledger_entry_ids) > 0),
  CHECK (status <> 'sent_no_forecast' OR kind = 'pre'),
  CHECK (recipients_count >= 0)
);
COMMENT ON TABLE monitor.event_bulletin IS 'Một bản tin của một kỳ: trước kỳ (dự báo) hoặc sau kỳ (kết quả và chấm điểm); nội dung lấy từ sổ dự báo, không có số nào ngoài ledger_entry và dataset đã chứng nhận (BR-187). Use case: UC-08-08.';
COMMENT ON COLUMN monitor.event_bulletin.event_id IS 'FK external_event';
COMMENT ON COLUMN monitor.event_bulletin.kind IS 'pre, post';
COMMENT ON COLUMN monitor.event_bulletin.status IS 'preparing, sent, sent_no_forecast, blocked, failed';
COMMENT ON COLUMN monitor.event_bulletin.ledger_entry_ids IS 'logic → forecast.ledger_entry; mỗi mặt hàng một dòng';
COMMENT ON COLUMN monitor.event_bulletin.gate_result IS 'Kết quả cổng: tham số certified đủ, độ tươi đầu vào, mô hình đã duyệt, kỳ đã xác nhận hay dự kiến (BR-183, BR-187)';
COMMENT ON COLUMN monitor.event_bulletin.content IS 'Khối nội dung thẻ: tiêu đề, bảng mặt hàng, phân rã, sổ N kỳ, câu bắt buộc';
COMMENT ON COLUMN monitor.event_bulletin.web_link IS 'Liên kết SCR-70 (bản tin trước kỳ) hoặc SCR-71 (sau kỳ)';

CREATE TABLE monitor.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE monitor.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON monitor.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE monitor.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON monitor.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA monitor TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON monitor.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON monitor.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON monitor.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX alert_monitor_id_dedup_key_key ON monitor.alert (monitor_id, dedup_key) WHERE status <> 'closed';
CREATE UNIQUE INDEX external_event_calendar_id_period_label_key ON monitor.external_event (calendar_id, period_label) WHERE status <> 'cancelled';
CREATE INDEX external_event_status_pre_bulletin_at_idx ON monitor.external_event (status, pre_bulletin_at) WHERE status IN ('expected','confirmed','shifted');
CREATE INDEX event_bulletin_status_created_at_idx ON monitor.event_bulletin (status, created_at DESC);

-- ═══ schema notify ═══
CREATE TABLE notify.notification (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  user_id uuid NOT NULL,
  data_space_id uuid,
  kind text NOT NULL,
  title text NOT NULL,
  body text,
  link text,
  source_ref uuid,
  priority text NOT NULL DEFAULT 'normal',
  batched_into uuid,
  read_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT notification_pkey PRIMARY KEY (id, created_at),
  CHECK (kind IN ('alert','hitl','digest','task_done','comment','share','report','system')),
  CHECK (priority IN ('low','normal','high'))
) PARTITION BY RANGE (created_at);
CREATE TABLE notify.notification_default PARTITION OF notify.notification DEFAULT;
COMMENT ON TABLE notify.notification IS 'Thông báo gửi cho một người; mọi dịch vụ phát qua sự kiện, Notification service ghi bảng này. Use case: UC-02-03, UC-02-04, UC-02-05, UC-08-02, UC-08-03, UC-08-04, UC-08-06, UC-08-07.';
COMMENT ON COLUMN notify.notification.user_id IS 'logic → org.app_user';
COMMENT ON COLUMN notify.notification.kind IS 'alert, hitl, digest, task_done, comment, share, report, system';
COMMENT ON COLUMN notify.notification.body IS 'Không chứa dữ liệu chi tiết hay dữ liệu cá nhân';
COMMENT ON COLUMN notify.notification.link IS 'Đường dẫn trong ứng dụng';
COMMENT ON COLUMN notify.notification.priority IS 'low, normal, high';
COMMENT ON COLUMN notify.notification.batched_into IS 'Thông báo gộp chứa thông báo này';

CREATE TABLE notify.notification_pref (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  user_id uuid NOT NULL,
  kind text NOT NULL,
  channels text[] NOT NULL DEFAULT '{in_app}',
  quiet_hours jsonb,
  batch_mode text NOT NULL DEFAULT 'instant',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT notification_pref_pkey PRIMARY KEY (id),
  UNIQUE (user_id, kind),
  CHECK (batch_mode IN ('instant','15m','daily')),
  CHECK (kind <> 'hitl' OR 'in_app' = ANY (channels))
);
COMMENT ON TABLE notify.notification_pref IS 'Cài đặt nhận thông báo: kênh theo loại sự kiện, giờ yên lặng, mức gộp (BR-127). Use case: UC-08-06, UC-08-07.';
COMMENT ON COLUMN notify.notification_pref.kind IS 'Loại sự kiện như ở notification.kind';
COMMENT ON COLUMN notify.notification_pref.channels IS 'in_app, email, teams, zalo, mobile_push';
COMMENT ON COLUMN notify.notification_pref.quiet_hours IS 'Ví dụ {from: 22:00, to: 07:00}';
COMMENT ON COLUMN notify.notification_pref.batch_mode IS 'instant, 15m, daily';

CREATE TABLE notify.channel_binding (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  user_id uuid NOT NULL,
  channel text NOT NULL,
  external_address text NOT NULL,
  verified_at timestamptz,
  status text NOT NULL DEFAULT 'pending',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT channel_binding_pkey PRIMARY KEY (id),
  CHECK (channel IN ('teams','zalo','email','mobile_push')),
  CHECK (status IN ('pending','active','revoked')),
  CHECK (status <> 'active' OR verified_at IS NOT NULL),
  UNIQUE (user_id, channel)
);
COMMENT ON TABLE notify.channel_binding IS 'Liên kết tài khoản người dùng với Teams, Zalo, email công ty, ứng dụng di động. Use case: UC-08-06, UC-08-07.';
COMMENT ON COLUMN notify.channel_binding.channel IS 'teams, zalo, email, mobile_push';
COMMENT ON COLUMN notify.channel_binding.external_address IS 'Mã người dùng ở kênh; dữ liệu cá nhân';
COMMENT ON COLUMN notify.channel_binding.verified_at IS 'Zalo OA cần xác nhận số điện thoại công ty';
COMMENT ON COLUMN notify.channel_binding.status IS 'pending, active, revoked';

CREATE TABLE notify.channel_delivery (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  notification_id uuid,
  hitl_request_id uuid,
  user_id uuid NOT NULL,
  channel text NOT NULL,
  external_message_id text,
  status text NOT NULL DEFAULT 'queued',
  action_taken jsonb,
  acted_at timestamptz,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT channel_delivery_pkey PRIMARY KEY (id),
  CHECK (channel IN ('teams','zalo','email','mobile_push')),
  CHECK (status IN ('queued','sent','delivered','acted','expired','failed')),
  CHECK (notification_id IS NOT NULL OR hitl_request_id IS NOT NULL)
);
COMMENT ON TABLE notify.channel_delivery IS 'Bản sao một thẻ (yêu cầu duyệt, cảnh báo, bản tin) trên một kênh và trạng thái; trả lời trên kênh quay về đây. Use case: UC-07-07, UC-08-02, UC-08-06.';
COMMENT ON COLUMN notify.channel_delivery.notification_id IS 'logic → notification (bảng phân vùng)';
COMMENT ON COLUMN notify.channel_delivery.hitl_request_id IS 'logic → inbox.hitl_request';
COMMENT ON COLUMN notify.channel_delivery.channel IS 'teams, zalo, email, mobile_push';
COMMENT ON COLUMN notify.channel_delivery.status IS 'queued, sent, delivered, acted, expired, failed';
COMMENT ON COLUMN notify.channel_delivery.action_taken IS 'Phương án người dùng bấm trên kênh';

CREATE TABLE notify.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE notify.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON notify.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE notify.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON notify.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA notify TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON notify.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON notify.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON notify.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX notification_user_id_created_at_idx ON notify.notification (user_id, created_at DESC) WHERE read_at IS NULL;
CREATE INDEX channel_delivery_hitl_request_id_idx ON notify.channel_delivery (hitl_request_id) WHERE hitl_request_id IS NOT NULL;

-- ═══ schema document ═══
CREATE TABLE document.collection (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  media_kinds text[] NOT NULL DEFAULT '{}',
  purpose text NOT NULL,
  pii_policy text NOT NULL DEFAULT 'mask',
  retention_days integer,
  extraction_schema_id uuid,
  qdrant_collection text NOT NULL,
  embed_model text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT collection_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code),
  CHECK (pii_policy IN ('mask','keep_for_authorized','reject')),
  CHECK (status IN ('active','reindexing','archived'))
);
COMMENT ON TABLE document.collection IS 'Bộ sưu tập tài liệu theo mục đích; tài liệu kế thừa quyền và mục đích của bộ sưu tập (BR-59, BR-107). Use case: UC-05-01, UC-05-06.';
COMMENT ON COLUMN document.collection.media_kinds IS 'pdf, image, docx, email, audio, html';
COMMENT ON COLUMN document.collection.purpose IS 'Mục đích sử dụng; lượt chạy có mục đích khác không đọc được';
COMMENT ON COLUMN document.collection.pii_policy IS 'mask, keep_for_authorized, reject';
COMMENT ON COLUMN document.collection.extraction_schema_id IS 'FK extraction_schema đang dùng';
COMMENT ON COLUMN document.collection.qdrant_collection IS 'Tên collection Qdrant chứa vector đoạn';
COMMENT ON COLUMN document.collection.embed_model IS 'Mô hình embedding; đổi mô hình thì lập chỉ mục mới song song (BR-18)';
COMMENT ON COLUMN document.collection.status IS 'active, reindexing, archived';
COMMENT ON COLUMN document.collection.deleted_at IS 'Xoá mềm';

CREATE TABLE document.document_source (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  collection_id uuid NOT NULL,
  kind text NOT NULL,
  location text NOT NULL,
  secret_ref text,
  sync_cron text NOT NULL,
  last_synced_at timestamptz,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT document_source_pkey PRIMARY KEY (id),
  CHECK (kind IN ('smb_folder','sharepoint','imap_mailbox','call_recording_api','object_store')),
  CHECK (status IN ('active','paused','error'))
);
COMMENT ON TABLE document.document_source IS 'Thư mục, hộp thư hoặc nguồn ghi âm đồng bộ vào một bộ sưu tập theo lịch. Use case: UC-05-01.';
COMMENT ON COLUMN document.document_source.collection_id IS 'FK collection';
COMMENT ON COLUMN document.document_source.kind IS 'smb_folder, sharepoint, imap_mailbox, call_recording_api, object_store';
COMMENT ON COLUMN document.document_source.location IS 'Đường dẫn hoặc địa chỉ';
COMMENT ON COLUMN document.document_source.secret_ref IS 'OpenBao';
COMMENT ON COLUMN document.document_source.status IS 'active, paused, error';

CREATE TABLE document.document (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  collection_id uuid NOT NULL,
  document_source_id uuid,
  sha256 text NOT NULL,
  media text NOT NULL,
  file_name text NOT NULL,
  object_key text NOT NULL,
  size_bytes bigint NOT NULL,
  title text,
  doc_no text,
  issued_on date,
  effective_from date,
  effective_to date,
  supersedes_id uuid,
  parent_document_id uuid,
  page_count integer,
  status text NOT NULL DEFAULT 'received',
  workflow_id text,
  error text,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT document_pkey PRIMARY KEY (id),
  CHECK (media IN ('pdf','image','docx','email','audio','html')),
  CHECK (status IN ('received','processing','waiting_review','ready','failed','removed')),
  CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
  CHECK (size_bytes <= 209715200),
  UNIQUE (collection_id, sha256)
);
COMMENT ON TABLE document.document IS 'Tài liệu đã nạp: bản gốc ở MinIO, trạng thái xử lý, số hiệu, hiệu lực, văn bản bị thay thế. Use case: UC-05-01, UC-05-04, UC-05-05.';
COMMENT ON COLUMN document.document.collection_id IS 'FK collection';
COMMENT ON COLUMN document.document.document_source_id IS 'FK document_source khi đồng bộ';
COMMENT ON COLUMN document.document.sha256 IS 'Trùng mã băm trong cùng bộ sưu tập thì không nạp lại';
COMMENT ON COLUMN document.document.media IS 'pdf, image, docx, email, audio, html';
COMMENT ON COLUMN document.document.object_key IS 'MinIO da-raw-docs';
COMMENT ON COLUMN document.document.size_bytes IS 'Tối đa 200 MB';
COMMENT ON COLUMN document.document.doc_no IS 'Số hiệu văn bản';
COMMENT ON COLUMN document.document.supersedes_id IS 'Văn bản bị thay thế';
COMMENT ON COLUMN document.document.parent_document_id IS 'Email chứa tệp đính kèm này (UC-05-01 3a)';
COMMENT ON COLUMN document.document.status IS 'received, processing, waiting_review, ready, failed, removed';
COMMENT ON COLUMN document.document.workflow_id IS 'Temporal doc_ingest';
COMMENT ON COLUMN document.document.deleted_at IS 'Xoá mềm';

CREATE TABLE document.document_page (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  page_no integer NOT NULL,
  page_hash text NOT NULL,
  text_layer boolean NOT NULL DEFAULT false,
  ocr_conf numeric(4,3),
  layout_ref text,
  image_ref text,
  text text,
  human_corrected boolean NOT NULL DEFAULT false,
  usable boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT document_page_pkey PRIMARY KEY (id),
  UNIQUE (document_id, page_no),
  CHECK (NOT usable OR ocr_conf IS NULL OR ocr_conf >= 0.85 OR human_corrected)
);
COMMENT ON TABLE document.document_page IS 'Trang của tài liệu; mỗi bước xử lý lưu theo mã băm trang để chỉ xử lý lại trang đổi (BR-17). Use case: UC-05-01, UC-05-02, UC-05-03, UC-05-04.';
COMMENT ON COLUMN document.document_page.document_id IS 'FK document';
COMMENT ON COLUMN document.document_page.text_layer IS 'Trang có lớp chữ thì đọc trực tiếp, không OCR';
COMMENT ON COLUMN document.document_page.ocr_conf IS 'Dưới 0,85 thì không dùng để trả lời cho đến khi duyệt (BR-19)';
COMMENT ON COLUMN document.document_page.layout_ref IS 'MinIO da-doc-derived';
COMMENT ON COLUMN document.document_page.text IS 'Văn bản đã chuẩn hoá Unicode NFC, đã che theo chính sách';
COMMENT ON COLUMN document.document_page.human_corrected IS 'Đã sửa tay; không ghi đè khi xử lý lại (BR-108)';

CREATE TABLE document.chunk (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  collection_id uuid NOT NULL,
  page_from integer NOT NULL,
  page_to integer NOT NULL,
  section_path text,
  context_header text,
  text text NOT NULL,
  tokens integer NOT NULL,
  qdrant_point_id uuid,
  embed_model text,
  effective_from date,
  effective_to date,
  human_corrected boolean NOT NULL DEFAULT false,
  injection_suspected boolean NOT NULL DEFAULT false,
  pii_masked boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT chunk_pkey PRIMARY KEY (id),
  CHECK (page_to >= page_from),
  CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from)
);
COMMENT ON TABLE document.chunk IS 'Đoạn đã chia theo cấu trúc (Điều, Khoản, bảng); vector nằm ở Qdrant, bảng giữ văn bản và mã điểm. Chỉ mục toàn văn trên cột text dùng cho tìm theo từ khoá (Postgres FTS). Use case: UC-05-02, UC-05-03, UC-05-04, UC-05-05.';
COMMENT ON COLUMN document.chunk.document_id IS 'FK document';
COMMENT ON COLUMN document.chunk.collection_id IS 'Để lọc nhanh theo bộ sưu tập';
COMMENT ON COLUMN document.chunk.section_path IS 'Ví dụ Điều 5 > Khoản 2';
COMMENT ON COLUMN document.chunk.context_header IS 'Tên văn bản, số hiệu, đường dẫn mục, ghép trước đoạn khi tạo vector';
COMMENT ON COLUMN document.chunk.qdrant_point_id IS 'Null khi chưa lập chỉ mục';
COMMENT ON COLUMN document.chunk.effective_from IS 'Hiệu lực ở mức đoạn khi sửa đổi từng phần (BR-109)';
COMMENT ON COLUMN document.chunk.injection_suspected IS 'Có câu ra lệnh cho mô hình (UC-05-02 E2)';

CREATE TABLE document.quality_issue (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  page_no integer,
  chunk_id uuid,
  extracted_record_id uuid,
  kind text NOT NULL,
  severity text NOT NULL DEFAULT 'blocking',
  detail jsonb NOT NULL DEFAULT '{}',
  requires_role text,
  status text NOT NULL DEFAULT 'open',
  resolution text,
  old_value text,
  resolved_by uuid,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT quality_issue_pkey PRIMARY KEY (id),
  CHECK (kind IN ('low_ocr','pii_unmasked','garbled_text','empty_chunk','low_confidence_field','field_mismatch')),
  CHECK (severity IN ('blocking','warning')),
  CHECK (status IN ('open','resolved','dismissed')),
  CHECK (status = 'open' OR (resolved_by IS NOT NULL AND resolved_at IS NOT NULL))
);
COMMENT ON TABLE document.quality_issue IS 'Vấn đề chất lượng chờ người xử lý: OCR kém, nghi dữ liệu cá nhân chưa che, trường độ tin thấp hoặc lệch CSDL. Use case: UC-05-02, UC-05-03, UC-05-06.';
COMMENT ON COLUMN document.quality_issue.document_id IS 'FK document';
COMMENT ON COLUMN document.quality_issue.kind IS 'low_ocr, pii_unmasked, garbled_text, empty_chunk, low_confidence_field, field_mismatch';
COMMENT ON COLUMN document.quality_issue.severity IS 'blocking, warning';
COMMENT ON COLUMN document.quality_issue.requires_role IS 'AC03 hoặc AC06 với vấn đề dữ liệu cá nhân';
COMMENT ON COLUMN document.quality_issue.status IS 'open, resolved, dismissed';
COMMENT ON COLUMN document.quality_issue.resolution IS 'corrected, confirmed_mask, page_dropped, value_fixed';
COMMENT ON COLUMN document.quality_issue.old_value IS 'Giá trị trước khi sửa (BR-108)';

CREATE TABLE document.extraction_schema (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  collection_id uuid NOT NULL,
  version integer NOT NULL,
  fields jsonb NOT NULL,
  target_dataset_id uuid,
  join_key jsonb,
  sample_accuracy jsonb,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT extraction_schema_pkey PRIMARY KEY (id),
  UNIQUE (collection_id, version),
  CHECK (status IN ('draft','testing','active','superseded')),
  CHECK (status <> 'active' OR sample_accuracy IS NOT NULL)
);
COMMENT ON TABLE document.extraction_schema IS 'Lược đồ trích xuất trường từ tài liệu ra bảng, có phiên bản; chỉ kích hoạt khi đạt độ chính xác (BR-110). Use case: UC-05-06.';
COMMENT ON COLUMN document.extraction_schema.collection_id IS 'FK collection';
COMMENT ON COLUMN document.extraction_schema.fields IS 'Tên, kiểu, bắt buộc, có phải dữ liệu cá nhân, cột đích';
COMMENT ON COLUMN document.extraction_schema.target_dataset_id IS 'logic → catalog.dataset (bảng đích trong vùng dữ liệu)';
COMMENT ON COLUMN document.extraction_schema.join_key IS 'Cách nối với dữ liệu có cấu trúc, ví dụ số hợp đồng với mã khoản vay';
COMMENT ON COLUMN document.extraction_schema.sample_accuracy IS 'Độ chính xác từng trường trên mẫu';
COMMENT ON COLUMN document.extraction_schema.status IS 'draft, testing, active, superseded';

CREATE TABLE document.extracted_record (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  extraction_schema_id uuid NOT NULL,
  values jsonb NOT NULL,
  confidence jsonb NOT NULL DEFAULT '{}',
  source_spans jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'extracted',
  loaded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT extracted_record_pkey PRIMARY KEY (id),
  CHECK (status IN ('extracted','needs_review','confirmed','loaded'))
);
COMMENT ON TABLE document.extracted_record IS 'Bản ghi trích từ một tài liệu theo một phiên bản lược đồ. Use case: UC-05-02, UC-05-03, UC-05-06.';
COMMENT ON COLUMN document.extracted_record.document_id IS 'FK document';
COMMENT ON COLUMN document.extracted_record.extraction_schema_id IS 'FK extraction_schema';
COMMENT ON COLUMN document.extracted_record.values IS 'Giá trị từng trường, đã che dữ liệu cá nhân';
COMMENT ON COLUMN document.extracted_record.confidence IS 'Độ tin từng trường';
COMMENT ON COLUMN document.extracted_record.source_spans IS 'Trang và vị trí lấy giá trị';
COMMENT ON COLUMN document.extracted_record.status IS 'extracted, needs_review, confirmed, loaded';
COMMENT ON COLUMN document.extracted_record.loaded_at IS 'Đã đổ ra bảng đích';

CREATE TABLE document.transcript_segment (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  seq integer NOT NULL,
  speaker text,
  start_ms integer NOT NULL,
  end_ms integer NOT NULL,
  text text NOT NULL,
  confidence numeric(4,3),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT transcript_segment_pkey PRIMARY KEY (id),
  UNIQUE (document_id, seq),
  CHECK (end_ms > start_ms)
);
COMMENT ON TABLE document.transcript_segment IS 'Đoạn chép lời của ghi âm, có người nói và mốc thời gian. Use case: UC-05-02, UC-05-06.';
COMMENT ON COLUMN document.transcript_segment.document_id IS 'FK document (media = audio)';
COMMENT ON COLUMN document.transcript_segment.speaker IS 'Ví dụ agent, customer';
COMMENT ON COLUMN document.transcript_segment.text IS 'Đã che dữ liệu cá nhân';

CREATE TABLE document.email_message (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  document_id uuid NOT NULL,
  thread_key text NOT NULL,
  message_id text NOT NULL,
  sender_hash text NOT NULL,
  subject text,
  sent_at timestamptz NOT NULL,
  in_reply_to text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT email_message_pkey PRIMARY KEY (id),
  UNIQUE (document_id)
);
COMMENT ON TABLE document.email_message IS 'Thư trong một luồng email; tệp đính kèm là tài liệu con. Use case: UC-05-06.';
COMMENT ON COLUMN document.email_message.document_id IS 'FK document (media = email)';
COMMENT ON COLUMN document.email_message.message_id IS 'Message-ID của thư';
COMMENT ON COLUMN document.email_message.sender_hash IS 'Băm địa chỉ gửi';

CREATE TABLE document.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE document.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON document.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE document.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON document.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA document TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON document.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON document.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON document.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX document_collection_id_doc_no_idx ON document.document (collection_id, doc_no);
CREATE INDEX chunk_document_id_page_from_idx ON document.chunk (document_id, page_from);
CREATE INDEX quality_issue_kind_severity_idx ON document.quality_issue (kind, severity) WHERE status = 'open';
CREATE UNIQUE INDEX extraction_schema_collection_id_key ON document.extraction_schema (collection_id) WHERE status = 'active';
CREATE INDEX email_message_thread_key_sent_at_idx ON document.email_message (thread_key, sent_at);

-- ═══ schema conflict ═══
CREATE TABLE conflict.claim (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  subject_key text NOT NULL,
  attribute text NOT NULL,
  value_text text,
  value_num numeric,
  unit text,
  valid_from date,
  valid_to date,
  source_kind text NOT NULL,
  source_ref uuid NOT NULL,
  source_id uuid,
  extracted_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT claim_pkey PRIMARY KEY (id),
  CHECK (source_kind IN ('dataset','document','published_result','external')),
  CHECK (value_text IS NOT NULL OR value_num IS NOT NULL)
);
COMMENT ON TABLE conflict.claim IS 'Khẳng định trích từ nguồn: chủ thể, thuộc tính, giá trị, hiệu lực. Use case: UC-05-02, UC-07-04.';
COMMENT ON COLUMN conflict.claim.subject_key IS 'Ví dụ khoản vay HD-001, chỉ tiêu dư nợ T9';
COMMENT ON COLUMN conflict.claim.source_kind IS 'dataset, document, published_result, external';
COMMENT ON COLUMN conflict.claim.source_ref IS 'Bảng, đoạn tài liệu hoặc số đã nộp';
COMMENT ON COLUMN conflict.claim.source_id IS 'logic → catalog.source, để áp thẩm quyền';

CREATE TABLE conflict.conflict (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  kind text NOT NULL,
  detected_at_stage text NOT NULL,
  subject_key text NOT NULL,
  attribute text NOT NULL,
  delta numeric,
  delta_pct numeric,
  material boolean NOT NULL,
  chosen_claim_id uuid,
  rule_id uuid,
  outcome text,
  hitl_request_id uuid,
  decision_note text,
  affected_answer_ids uuid[] NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'open',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT conflict_pkey PRIMARY KEY (id),
  CHECK (kind IN ('value','definition','validity','scope','identity','language','entry_error')),
  CHECK (detected_at_stage IN ('ingest','answer','scheduled_check')),
  CHECK (outcome IS NULL OR outcome IN ('noted','auto_resolved','both_presented','resolved_by_human','waiting_data')),
  CHECK (status IN ('open','resolved','insufficient_basis')),
  CHECK (status <> 'resolved' OR outcome IS NOT NULL)
);
COMMENT ON TABLE conflict.conflict IS 'Một vụ xung đột giữa các nguồn: loại, mức chênh, trọng yếu hay không, kết cục. Use case: UC-07-04.';
COMMENT ON COLUMN conflict.conflict.kind IS 'value, definition, validity, scope, identity, language, entry_error (bảy loại ở UC-07-04)';
COMMENT ON COLUMN conflict.conflict.detected_at_stage IS 'ingest, answer, scheduled_check';
COMMENT ON COLUMN conflict.conflict.chosen_claim_id IS 'FK claim được chọn cho câu trả lời';
COMMENT ON COLUMN conflict.conflict.rule_id IS 'FK resolution_rule đã áp';
COMMENT ON COLUMN conflict.conflict.outcome IS 'noted, auto_resolved, both_presented, resolved_by_human, waiting_data';
COMMENT ON COLUMN conflict.conflict.hitl_request_id IS 'logic → inbox.hitl_request';
COMMENT ON COLUMN conflict.conflict.affected_answer_ids IS 'Câu trả lời đã dùng số bị loại, được đánh dấu lại';
COMMENT ON COLUMN conflict.conflict.status IS 'open, resolved, insufficient_basis';

CREATE TABLE conflict.conflict_claim (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  conflict_id uuid NOT NULL,
  claim_id uuid NOT NULL,
  role text NOT NULL,
  CONSTRAINT conflict_claim_pkey PRIMARY KEY (id),
  CHECK (role IN ('primary','competing')),
  UNIQUE (conflict_id, claim_id)
);
COMMENT ON TABLE conflict.conflict_claim IS 'Khẳng định tham gia một vụ xung đột. Use case: UC-07-04.';
COMMENT ON COLUMN conflict.conflict_claim.conflict_id IS 'FK conflict';
COMMENT ON COLUMN conflict.conflict_claim.claim_id IS 'FK claim';
COMMENT ON COLUMN conflict.conflict_claim.role IS 'primary, competing';

CREATE TABLE conflict.resolution_rule (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  data_kind text NOT NULL,
  condition jsonb NOT NULL,
  action jsonb NOT NULL,
  origin text NOT NULL DEFAULT 'manual',
  behavior_policy_id uuid,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT resolution_rule_pkey PRIMARY KEY (id),
  CHECK (origin IN ('manual','hitl')),
  CHECK (status IN ('active','disabled'))
);
COMMENT ON TABLE conflict.resolution_rule IS 'Quy tắc giải quyết xung đột đã duyệt; áp trước thẩm quyền nguồn (BR-30). Use case: UC-07-04.';
COMMENT ON COLUMN conflict.resolution_rule.condition IS 'Ví dụ lệch dưới 0,05% và là ngày chốt kỳ';
COMMENT ON COLUMN conflict.resolution_rule.action IS 'Ví dụ chọn nguồn Core banking';
COMMENT ON COLUMN conflict.resolution_rule.origin IS 'manual, hitl';
COMMENT ON COLUMN conflict.resolution_rule.behavior_policy_id IS 'logic → governance.behavior_policy khi sinh từ quyết định';
COMMENT ON COLUMN conflict.resolution_rule.status IS 'active, disabled';

CREATE TABLE conflict.source_authority (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  data_kind text NOT NULL,
  ranking uuid[] NOT NULL,
  materiality jsonb NOT NULL DEFAULT '{"amount_pct": 0.0005, "count": 0}',
  backtest jsonb,
  approved_by uuid,
  approved_at timestamptz,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT source_authority_pkey PRIMARY KEY (id),
  CHECK (status IN ('draft','active','superseded')),
  CHECK (status NOT IN ('active','superseded') OR approved_by IS NOT NULL)
);
COMMENT ON TABLE conflict.source_authority IS 'Thứ tự ưu tiên nguồn theo loại dữ liệu và ngưỡng trọng yếu. Use case: UC-07-04, UC-07-05.';
COMMENT ON COLUMN conflict.source_authority.data_kind IS 'Ví dụ dư nợ, số khách, văn bản pháp quy';
COMMENT ON COLUMN conflict.source_authority.ranking IS 'Danh sách source_id theo thứ tự ưu tiên; nguồn tải tay và bên ngoài không đứng trên cấp 1 (BR-121)';
COMMENT ON COLUMN conflict.source_authority.materiality IS 'Ngưỡng trọng yếu (BR-120)';
COMMENT ON COLUMN conflict.source_authority.backtest IS 'Kết quả chạy thử trên xung đột 90 ngày';
COMMENT ON COLUMN conflict.source_authority.status IS 'draft, active, superseded';

CREATE TABLE conflict.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE conflict.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON conflict.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE conflict.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON conflict.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA conflict TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON conflict.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON conflict.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON conflict.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX claim_data_space_id_subject_key_attribute_idx ON conflict.claim (data_space_id, subject_key, attribute);
CREATE INDEX conflict_data_space_id_idx ON conflict.conflict (data_space_id) WHERE status = 'open';
CREATE UNIQUE INDEX source_authority_data_space_id_data_kind_key ON conflict.source_authority (data_space_id, data_kind) WHERE status = 'active';
CREATE UNIQUE INDEX source_authority_data_space_id_data_kind_key_2 ON conflict.source_authority (data_space_id, data_kind) WHERE status = 'draft';

-- ═══ schema pack ═══
CREATE TABLE pack.industry_pack (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  industry_code text NOT NULL,
  publisher text NOT NULL,
  publisher_key_id text,
  origin text NOT NULL DEFAULT 'vendor',
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT industry_pack_pkey PRIMARY KEY (id),
  UNIQUE (org_id, code),
  CHECK (origin IN ('vendor','organisation')),
  CHECK (origin = 'organisation' OR publisher_key_id IS NOT NULL)
);
COMMENT ON TABLE pack.industry_pack IS 'Gói ngành do nhà cung cấp hoặc khối kiến trúc phát hành. Use case: UC-09-01.';
COMMENT ON COLUMN pack.industry_pack.code IS 'Ví dụ banking, retail, hospitality';
COMMENT ON COLUMN pack.industry_pack.publisher IS 'Nhà cung cấp hoặc khối kiến trúc của tổ chức';
COMMENT ON COLUMN pack.industry_pack.publisher_key_id IS 'Khoá công khai dùng kiểm chữ ký (BR-128); bắt buộc với gói vendor, gói của tổ chức có khoá khi phát hành phiên bản đầu (sửa 12/10/2026)';
COMMENT ON COLUMN pack.industry_pack.origin IS 'vendor, organisation: organisation là gói tổ chức tự soạn qua POST /v1/packs; industry_code lấy theo organization.industry_code (thêm 12/10/2026)';

CREATE TABLE pack.pack_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_id uuid NOT NULL,
  version text NOT NULL,
  manifest jsonb NOT NULL,
  signature text NOT NULL,
  signature_verified_at timestamptz,
  min_core_version text NOT NULL,
  release_notes text,
  breaking_changes jsonb NOT NULL DEFAULT '[]',
  object_key text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  released_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT pack_version_pkey PRIMARY KEY (id),
  UNIQUE (pack_id, version),
  CHECK (status IN ('draft','released','available','withdrawn')),
  CHECK (status <> 'available' OR signature_verified_at IS NOT NULL)
);
COMMENT ON TABLE pack.pack_version IS 'Phiên bản gói ngành: manifest, chữ ký, ghi chú phát hành, thay đổi phá vỡ. Use case: UC-09-01, UC-09-05.';
COMMENT ON COLUMN pack.pack_version.pack_id IS 'FK industry_pack';
COMMENT ON COLUMN pack.pack_version.version IS 'Ví dụ 2026.3';
COMMENT ON COLUMN pack.pack_version.breaking_changes IS 'Có thì bắt buộc kèm hướng dẫn chuyển đổi và báo trước 30 ngày (BR-131)';
COMMENT ON COLUMN pack.pack_version.object_key IS 'MinIO da-packs';
COMMENT ON COLUMN pack.pack_version.status IS 'draft, released, available, withdrawn';

CREATE TABLE pack.canonical_entity (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  key_attributes text[] NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT canonical_entity_pkey PRIMARY KEY (id),
  UNIQUE (pack_version_id, code)
);
COMMENT ON TABLE pack.canonical_entity IS 'Thực thể trong mô hình chuẩn của ngành (ví dụ khoản vay, khách hàng). Use case: UC-09-01, UC-09-05.';
COMMENT ON COLUMN pack.canonical_entity.pack_version_id IS 'FK pack_version';

CREATE TABLE pack.canonical_attribute (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  entity_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  data_type text NOT NULL,
  required boolean NOT NULL DEFAULT false,
  code_list jsonb,
  pii boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT canonical_attribute_pkey PRIMARY KEY (id),
  UNIQUE (entity_id, code),
  CHECK (data_type IN ('string','integer','decimal','boolean','date','timestamp','code'))
);
COMMENT ON TABLE pack.canonical_attribute IS 'Thuộc tính của thực thể chuẩn, kèm kiểu, bắt buộc, bảng mã chuẩn. Use case: UC-09-01, UC-09-05.';
COMMENT ON COLUMN pack.canonical_attribute.entity_id IS 'FK canonical_entity';
COMMENT ON COLUMN pack.canonical_attribute.data_type IS 'string, integer, decimal, boolean, date, timestamp, code';
COMMENT ON COLUMN pack.canonical_attribute.code_list IS 'Bảng mã chuẩn khi data_type = code';

CREATE TABLE pack.pack_metric (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  expression text NOT NULL,
  unit text,
  additivity text NOT NULL DEFAULT 'none',
  legal_basis text,
  is_internal boolean NOT NULL DEFAULT false,
  in_regulatory_report boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pack_metric_pkey PRIMARY KEY (id),
  UNIQUE (pack_version_id, code),
  CHECK (is_internal OR legal_basis IS NOT NULL),
  CHECK (additivity IN ('full','semi','none'))
);
COMMENT ON TABLE pack.pack_metric IS 'Chỉ số chuẩn của gói, kèm căn cứ pháp lý hoặc nhãn “chỉ số nội bộ”. Use case: UC-09-01, UC-09-03, UC-09-05.';
COMMENT ON COLUMN pack.pack_metric.pack_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_metric.code IS 'Không tái sử dụng cho nghĩa khác (BR-131)';
COMMENT ON COLUMN pack.pack_metric.expression IS 'Công thức trên thực thể và thuộc tính chuẩn';
COMMENT ON COLUMN pack.pack_metric.additivity IS 'full, semi, none';
COMMENT ON COLUMN pack.pack_metric.is_internal IS 'Chỉ số nội bộ, không có căn cứ pháp lý';
COMMENT ON COLUMN pack.pack_metric.in_regulatory_report IS 'Có trong báo cáo gửi cơ quan quản lý (BR-36)';

CREATE TABLE pack.validation_rule (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  code text NOT NULL,
  description text NOT NULL,
  expression text NOT NULL,
  tolerance numeric,
  severity text NOT NULL DEFAULT 'blocking',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT validation_rule_pkey PRIMARY KEY (id),
  UNIQUE (pack_version_id, code),
  CHECK (severity IN ('blocking','warning'))
);
COMMENT ON TABLE pack.validation_rule IS 'Luật kiểm tra của gói (ví dụ tổng khớp sổ cái, mỗi bản ghi có đúng một phân loại). Use case: UC-09-01, UC-09-05.';
COMMENT ON COLUMN pack.validation_rule.pack_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.validation_rule.severity IS 'blocking, warning';

CREATE TABLE pack.pack_skill (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  kind text NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  definition jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pack_skill_pkey PRIMARY KEY (id),
  UNIQUE (pack_version_id, kind, code),
  CHECK (kind IN ('skill','agent_template','eval_set'))
);
COMMENT ON TABLE pack.pack_skill IS 'Kỹ năng, agent mẫu và bộ câu hỏi mẫu đi kèm gói ngành. Use case: UC-09-01, UC-13-01.';
COMMENT ON COLUMN pack.pack_skill.pack_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_skill.kind IS 'skill, agent_template, eval_set';
COMMENT ON COLUMN pack.pack_skill.definition IS 'Định nghĩa kỹ năng, cấu hình agent mẫu hoặc danh sách câu hỏi';

CREATE TABLE pack.pack_install (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  previous_pack_version_id uuid,
  status text NOT NULL DEFAULT 'mapping',
  activated_at timestamptz,
  activated_by uuid,
  proposal_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT pack_install_pkey PRIMARY KEY (id),
  CHECK (status IN ('mapping','calibrating','pending_activation','active','upgrading','rolled_back','uninstalled'))
);
COMMENT ON TABLE pack.pack_install IS 'Gói đã cài ở một Data Space; mỗi Data Space một bản cài đang hoạt động. Use case: UC-09-02, UC-09-04.';
COMMENT ON COLUMN pack.pack_install.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN pack.pack_install.pack_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_install.previous_pack_version_id IS 'Giữ 30 ngày để quay lại sau nâng cấp';
COMMENT ON COLUMN pack.pack_install.status IS 'mapping, calibrating, pending_activation, active, upgrading, rolled_back, uninstalled';
COMMENT ON COLUMN pack.pack_install.proposal_id IS 'logic → inbox.proposal';

CREATE TABLE pack.entity_mapping (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_install_id uuid NOT NULL,
  attribute_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  column_expr text NOT NULL,
  confidence numeric(4,3),
  origin text NOT NULL DEFAULT 'suggested',
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to timestamptz,
  confirmed_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT entity_mapping_pkey PRIMARY KEY (id),
  CHECK (origin IN ('suggested','confirmed','manual')),
  CHECK (valid_to IS NULL OR valid_to > valid_from)
);
COMMENT ON TABLE pack.entity_mapping IS 'Ánh xạ thuộc tính chuẩn sang bảng, cột của tổ chức; có thời hiệu (BR-16, BR-37). Use case: UC-04-03, UC-09-02, UC-09-04, UC-10-01.';
COMMENT ON COLUMN pack.entity_mapping.pack_install_id IS 'FK pack_install';
COMMENT ON COLUMN pack.entity_mapping.attribute_id IS 'FK canonical_attribute';
COMMENT ON COLUMN pack.entity_mapping.dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN pack.entity_mapping.column_expr IS 'Cột hoặc biểu thức';
COMMENT ON COLUMN pack.entity_mapping.confidence IS 'Độ tin của đề xuất ánh xạ';
COMMENT ON COLUMN pack.entity_mapping.origin IS 'suggested, confirmed, manual';

CREATE TABLE pack.code_mapping (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_install_id uuid NOT NULL,
  attribute_id uuid NOT NULL,
  source_code text NOT NULL,
  canonical_code text NOT NULL,
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_to timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT code_mapping_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE pack.code_mapping IS 'Bảng mã của tổ chức sang mã chuẩn (ví dụ phân loại, loại tiền). Use case: UC-09-02.';
COMMENT ON COLUMN pack.code_mapping.pack_install_id IS 'FK pack_install';
COMMENT ON COLUMN pack.code_mapping.attribute_id IS 'FK canonical_attribute (data_type = code)';

CREATE TABLE pack.metric_override (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_install_id uuid NOT NULL,
  pack_metric_code text NOT NULL,
  expression text NOT NULL,
  scope_condition text,
  reason text NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  approved_by uuid,
  compliance_approved_by uuid,
  calibration_run_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT metric_override_pkey PRIMARY KEY (id),
  CHECK (status IN ('draft','pending_review','active','superseded')),
  CHECK (status <> 'active' OR approved_by IS NOT NULL)
);
COMMENT ON TABLE pack.metric_override IS 'Hiệu chỉnh chỉ số ở lớp tổ chức kèm lý do; tham gia gộp ba chiều khi nâng cấp (BR-129). Use case: UC-09-02, UC-09-03, UC-09-04.';
COMMENT ON COLUMN pack.metric_override.pack_install_id IS 'FK pack_install';
COMMENT ON COLUMN pack.metric_override.pack_metric_code IS 'Mã chỉ số chuẩn; giữ qua các phiên bản gói';
COMMENT ON COLUMN pack.metric_override.scope_condition IS 'Chỉ áp cho một phạm vi (UC-09-03 2a)';
COMMENT ON COLUMN pack.metric_override.status IS 'draft, pending_review, active, superseded';
COMMENT ON COLUMN pack.metric_override.compliance_approved_by IS 'Chỉ số báo cáo cơ quan quản lý cần thêm AC06';
COMMENT ON COLUMN pack.metric_override.calibration_run_id IS 'FK calibration_run; lần chạy thử công thức trên dữ liệu thật (UC-09-03 bước 3, thêm 12/10/2026)';

CREATE TABLE pack.calibration_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_install_id uuid NOT NULL,
  trigger text NOT NULL,
  periods text[] NOT NULL,
  tolerance_pp numeric(6,4) NOT NULL DEFAULT 0.01,
  passed integer NOT NULL DEFAULT 0,
  failed integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'running',
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT calibration_run_pkey PRIMARY KEY (id),
  CHECK (trigger IN ('onboarding','override','upgrade')),
  CHECK (status IN ('running','passed','failed'))
);
COMMENT ON TABLE pack.calibration_run IS 'Một lần đối chiếu số khi đưa vào ngành, hiệu chỉnh hoặc nâng cấp gói. Use case: UC-09-02, UC-09-03, UC-09-04.';
COMMENT ON COLUMN pack.calibration_run.pack_install_id IS 'FK pack_install';
COMMENT ON COLUMN pack.calibration_run.trigger IS 'onboarding, override, upgrade';
COMMENT ON COLUMN pack.calibration_run.periods IS 'Kỳ đối chiếu, ví dụ 2 kỳ gần nhất';
COMMENT ON COLUMN pack.calibration_run.tolerance_pp IS 'Ngưỡng lệch, mặc định 0,01 điểm phần trăm (BR-36)';
COMMENT ON COLUMN pack.calibration_run.status IS 'running, passed, failed';

CREATE TABLE pack.calibration_item (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  calibration_run_id uuid NOT NULL,
  item_kind text NOT NULL,
  item_code text NOT NULL,
  period text,
  computed_value numeric,
  filed_value numeric,
  delta numeric,
  passed boolean NOT NULL,
  suggested_cause text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT calibration_item_pkey PRIMARY KEY (id),
  CHECK (item_kind IN ('metric','rule'))
);
COMMENT ON TABLE pack.calibration_item IS 'Kết quả đối chiếu một chỉ số hoặc một luật trong một lần đối chiếu. Use case: UC-09-02.';
COMMENT ON COLUMN pack.calibration_item.calibration_run_id IS 'FK calibration_run';
COMMENT ON COLUMN pack.calibration_item.item_kind IS 'metric, rule';

CREATE TABLE pack.pack_upgrade (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_install_id uuid NOT NULL,
  from_version_id uuid NOT NULL,
  to_version_id uuid NOT NULL,
  merge_result jsonb NOT NULL DEFAULT '{}',
  conflicts_open integer NOT NULL DEFAULT 0,
  calibration_run_id uuid,
  status text NOT NULL DEFAULT 'available',
  apply_from_period text,
  rollback_until timestamptz,
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT pack_upgrade_pkey PRIMARY KEY (id),
  CHECK (status IN ('available','merging','needs_decision','testing','pending_approval','applied','rolled_back','cancelled')),
  CHECK (status <> 'applied' OR (conflicts_open = 0 AND approved_by IS NOT NULL))
);
COMMENT ON TABLE pack.pack_upgrade IS 'Một lần nâng cấp gói bằng gộp ba chiều (SD-21); không làm khi có kỳ đang chốt (BR-38). Use case: UC-09-04.';
COMMENT ON COLUMN pack.pack_upgrade.pack_install_id IS 'FK pack_install';
COMMENT ON COLUMN pack.pack_upgrade.from_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_upgrade.to_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_upgrade.merge_result IS 'Theo từng chỉ số và ánh xạ: lấy gói mới, giữ của tổ chức, xung đột';
COMMENT ON COLUMN pack.pack_upgrade.calibration_run_id IS 'FK calibration_run';
COMMENT ON COLUMN pack.pack_upgrade.status IS 'available, merging, needs_decision, testing, pending_approval, applied, rolled_back, cancelled';
COMMENT ON COLUMN pack.pack_upgrade.apply_from_period IS 'Áp dụng từ kỳ sau; kỳ đã chốt không đổi';
COMMENT ON COLUMN pack.pack_upgrade.rollback_until IS '30 ngày sau khi áp dụng';

CREATE TABLE pack.pack_check_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pack_version_id uuid NOT NULL,
  checks jsonb NOT NULL,
  passed boolean NOT NULL,
  ran_by uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pack_check_run_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE pack.pack_check_run IS 'Kết quả kiểm tra một phiên bản gói trước khi phát hành. Use case: UC-09-05.';
COMMENT ON COLUMN pack.pack_check_run.pack_version_id IS 'FK pack_version';
COMMENT ON COLUMN pack.pack_check_run.checks IS 'Căn cứ đầy đủ; chạy trên 3 bộ dữ liệu mẫu lệch ≤ 0,01%; câu hỏi mẫu không giảm';

CREATE TABLE pack.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE pack.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON pack.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE pack.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON pack.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA pack TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON pack.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON pack.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON pack.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX pack_install_data_space_id_key ON pack.pack_install (data_space_id) WHERE status NOT IN ('uninstalled','rolled_back');
CREATE UNIQUE INDEX entity_mapping_pack_install_id_attribute_id_key ON pack.entity_mapping (pack_install_id, attribute_id) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX code_mapping_pack_install_id_attribute_id_source_code_key ON pack.code_mapping (pack_install_id, attribute_id, source_code) WHERE valid_to IS NULL;
CREATE UNIQUE INDEX metric_override_pack_install_id_pack_metric_code_key ON pack.metric_override (pack_install_id, pack_metric_code) WHERE status = 'active';

-- ═══ schema period ═══
CREATE TABLE period.period_calendar (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  period_kind text NOT NULL,
  close_rule text NOT NULL,
  work_calendar_id uuid,
  dataset_ids uuid[] NOT NULL,
  reconciliation_items jsonb NOT NULL DEFAULT '[]',
  report_codes text[] NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT period_calendar_pkey PRIMARY KEY (id),
  CHECK (period_kind IN ('month','quarter','year','custom')),
  CHECK (status IN ('active','paused'))
);
COMMENT ON TABLE period.period_calendar IS 'Lịch chốt kỳ của Data Space: loại kỳ, ngày chốt dự kiến, bảng thuộc kỳ, chỉ tiêu đối soát. Use case: UC-10-02.';
COMMENT ON COLUMN period.period_calendar.period_kind IS 'month, quarter, year, custom';
COMMENT ON COLUMN period.period_calendar.close_rule IS 'Ví dụ ngày làm việc thứ 3 của tháng sau';
COMMENT ON COLUMN period.period_calendar.work_calendar_id IS 'logic → org.work_calendar';
COMMENT ON COLUMN period.period_calendar.dataset_ids IS 'Bảng được chụp khi chốt; logic → catalog.dataset';
COMMENT ON COLUMN period.period_calendar.reconciliation_items IS 'Chỉ tiêu đối soát và dung sai, ví dụ tổng dư nợ khớp sổ cái';
COMMENT ON COLUMN period.period_calendar.report_codes IS 'Báo cáo cần đóng băng, khai báo bởi gói ngành hoặc tổ chức';
COMMENT ON COLUMN period.period_calendar.status IS 'active, paused';

CREATE TABLE period.period_close (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  period_calendar_id uuid,
  period_label text NOT NULL,
  business_date date NOT NULL,
  version integer NOT NULL DEFAULT 1,
  status text NOT NULL DEFAULT 'open',
  snapshot_hash text,
  workflow_id text,
  closed_by uuid,
  closed_at timestamptz,
  filed_report_code text,
  filed_at date,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT period_close_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, period_label, version),
  CHECK (status IN ('open','closing','close_failed','closed','filed','retro_detected')),
  CHECK (status NOT IN ('closed','filed','retro_detected') OR (snapshot_hash IS NOT NULL AND closed_at IS NOT NULL))
);
COMMENT ON TABLE period.period_close IS 'Một kỳ chốt; bản 1 không bao giờ đổi, hồi tố tạo version + 1 (BR-43). Use case: UC-10-01, UC-10-02, UC-10-03, UC-10-04, UC-10-05.';
COMMENT ON COLUMN period.period_close.period_calendar_id IS 'FK period_calendar';
COMMENT ON COLUMN period.period_close.period_label IS 'Ví dụ 2026-09';
COMMENT ON COLUMN period.period_close.business_date IS 'Ngày nghiệp vụ cuối kỳ';
COMMENT ON COLUMN period.period_close.status IS 'open, closing, close_failed, closed, filed, retro_detected';
COMMENT ON COLUMN period.period_close.snapshot_hash IS 'SHA-256 cả bản chụp';
COMMENT ON COLUMN period.period_close.closed_by IS 'Người bấm Chốt kỳ';

CREATE TABLE period.period_snapshot_file (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  period_close_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  dataset_version integer NOT NULL,
  object_key text NOT NULL,
  row_count bigint NOT NULL,
  sha256 text NOT NULL,
  written_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT period_snapshot_file_pkey PRIMARY KEY (id),
  UNIQUE (period_close_id, dataset_id)
);
COMMENT ON TABLE period.period_snapshot_file IS 'Tệp Parquet của một bảng trong kỳ chốt, ở bucket WORM (BR-41). Use case: UC-10-01, UC-10-02, UC-10-05.';
COMMENT ON COLUMN period.period_snapshot_file.period_close_id IS 'FK period_close';
COMMENT ON COLUMN period.period_snapshot_file.dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN period.period_snapshot_file.dataset_version IS 'Phiên bản cấu trúc tại lúc chụp';
COMMENT ON COLUMN period.period_snapshot_file.object_key IS 'MinIO da-period-close';
COMMENT ON COLUMN period.period_snapshot_file.sha256 IS 'Kiểm trước khi đọc (BR-135)';

CREATE TABLE period.period_reconciliation (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  period_close_id uuid NOT NULL,
  item_code text NOT NULL,
  snapshot_value numeric NOT NULL,
  ledger_value numeric NOT NULL,
  tolerance numeric NOT NULL,
  delta numeric NOT NULL,
  status text NOT NULL,
  cause_rows_ref text,
  hitl_request_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT period_reconciliation_pkey PRIMARY KEY (id),
  UNIQUE (period_close_id, item_code),
  CHECK (status IN ('matched','mismatched','exception_pending','exception_approved')),
  CHECK (status <> 'matched' OR abs(delta) <= tolerance),
  CHECK (status NOT IN ('exception_pending','exception_approved') OR hitl_request_id IS NOT NULL)
);
COMMENT ON TABLE period.period_reconciliation IS 'Kết quả đối soát một chỉ tiêu khi chốt kỳ; ngoại lệ cần hai người duyệt (BR-132). Use case: UC-10-02.';
COMMENT ON COLUMN period.period_reconciliation.period_close_id IS 'FK period_close';
COMMENT ON COLUMN period.period_reconciliation.item_code IS 'Ví dụ tổng dư nợ, số khoản vay';
COMMENT ON COLUMN period.period_reconciliation.ledger_value IS 'Giá trị ở sổ cái hoặc nguồn đối chiếu';
COMMENT ON COLUMN period.period_reconciliation.status IS 'matched, mismatched, exception_pending, exception_approved';
COMMENT ON COLUMN period.period_reconciliation.cause_rows_ref IS 'Dòng gây lệch trong MinIO';
COMMENT ON COLUMN period.period_reconciliation.hitl_request_id IS 'logic → inbox.hitl_request khi xin ngoại lệ';

CREATE TABLE period.published_result (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  period_close_id uuid NOT NULL,
  metric_version_id uuid NOT NULL,
  dimension_key jsonb NOT NULL DEFAULT '{}',
  value numeric NOT NULL,
  reported_value numeric,
  manual_override boolean NOT NULL DEFAULT false,
  override_reason text,
  approved_by uuid,
  report_ref text NOT NULL,
  sha256 text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT published_result_pkey PRIMARY KEY (id),
  UNIQUE (period_close_id, metric_version_id, dimension_key),
  CHECK (NOT manual_override OR (reported_value IS NOT NULL AND override_reason IS NOT NULL AND approved_by IS NOT NULL))
);
COMMENT ON TABLE period.published_result IS 'Con số đã công bố, đóng băng; chỉ thêm, không sửa, không xoá (BR-42): vai trò CSDL của Period service chỉ có quyền INSERT và SELECT trên bảng này. Use case: UC-01-02, UC-10-01, UC-10-03, UC-10-04, UC-10-05.';
COMMENT ON COLUMN period.published_result.period_close_id IS 'FK period_close';
COMMENT ON COLUMN period.published_result.metric_version_id IS 'logic → context.metric_version';
COMMENT ON COLUMN period.published_result.dimension_key IS 'Lát cắt nếu báo cáo có chiều';
COMMENT ON COLUMN period.published_result.value IS 'Giá trị hệ thống tính trên bản chụp';
COMMENT ON COLUMN period.published_result.reported_value IS 'Giá trị trên báo cáo thực tế đã nộp';
COMMENT ON COLUMN period.published_result.manual_override IS 'Số nhập tay khác số hệ thống; cần AC06 duyệt (BR-133)';
COMMENT ON COLUMN period.published_result.report_ref IS 'Mã báo cáo';
COMMENT ON COLUMN period.published_result.sha256 IS 'Băm giá trị, phiên bản định nghĩa và bản chụp';

CREATE TABLE period.retro_change (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  period_close_id uuid NOT NULL,
  published_result_id uuid NOT NULL,
  current_value numeric NOT NULL,
  delta numeric NOT NULL,
  below_materiality boolean NOT NULL DEFAULT false,
  cause_rows_ref text,
  decision text,
  decision_note text,
  new_period_close_id uuid,
  compliance_notified boolean NOT NULL DEFAULT false,
  detected_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT retro_change_pkey PRIMARY KEY (id),
  CHECK (decision IS NULL OR decision IN ('new_version','no_action')),
  CHECK (decision IS NULL OR decision_note IS NOT NULL)
);
COMMENT ON TABLE period.retro_change IS 'Thay đổi hồi tố phát hiện sau ngày chốt trên một số đã công bố. Use case: UC-10-04.';
COMMENT ON COLUMN period.retro_change.period_close_id IS 'FK period_close';
COMMENT ON COLUMN period.retro_change.published_result_id IS 'FK published_result';
COMMENT ON COLUMN period.retro_change.below_materiality IS 'Dưới ngưỡng trọng yếu thì không tạo yêu cầu';
COMMENT ON COLUMN period.retro_change.cause_rows_ref IS 'Dòng có thời điểm ghi nhận sau ngày chốt';
COMMENT ON COLUMN period.retro_change.decision IS 'new_version, no_action';
COMMENT ON COLUMN period.retro_change.new_period_close_id IS 'Bản 2 nếu có';
COMMENT ON COLUMN period.retro_change.compliance_notified IS 'Chỉ số gửi cơ quan quản lý vượt ngưỡng luôn báo AC06 (BR-134)';

CREATE TABLE period.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE period.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON period.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE period.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON period.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA period TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON period.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON period.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON period.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE UNIQUE INDEX period_close_data_space_id_key ON period.period_close (data_space_id) WHERE status = 'closing';

-- ═══ schema pipeline ═══
CREATE TABLE pipeline.pipeline (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  name text NOT NULL,
  owner_id uuid NOT NULL,
  input_dataset_ids uuid[] NOT NULL,
  steps jsonb NOT NULL DEFAULT '[]',
  target_dataset_id uuid,
  scope text NOT NULL DEFAULT 'personal',
  status text NOT NULL DEFAULT 'draft',
  cron text,
  work_calendar_id uuid,
  trigger_on_job_id uuid,
  depends_on_pipeline_ids uuid[] NOT NULL DEFAULT '{}',
  no_overlap boolean NOT NULL DEFAULT true,
  on_failure text NOT NULL DEFAULT 'notify',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT pipeline_pkey PRIMARY KEY (id),
  CHECK (scope IN ('personal','data_space')),
  CHECK (status IN ('draft','active','paused')),
  CHECK (on_failure IN ('notify','retry_then_notify','skip')),
  UNIQUE (data_space_id, name)
);
COMMENT ON TABLE pipeline.pipeline IS 'Pipeline biến đổi: các bước làm sạch, join, tính cột; chạy trong vùng làm việc, không ghi vào nguồn (BR-22). Use case: UC-06-01, UC-06-02, UC-06-03.';
COMMENT ON COLUMN pipeline.pipeline.input_dataset_ids IS 'logic → catalog.dataset';
COMMENT ON COLUMN pipeline.pipeline.steps IS 'Mỗi bước: loại, mô tả bằng lời, mã SQL hoặc Python, số dòng bị loại và điều kiện (BR-23)';
COMMENT ON COLUMN pipeline.pipeline.target_dataset_id IS 'logic → catalog.dataset sau khi lưu thành bảng';
COMMENT ON COLUMN pipeline.pipeline.scope IS 'personal, data_space (BR-111)';
COMMENT ON COLUMN pipeline.pipeline.status IS 'draft, active, paused';
COMMENT ON COLUMN pipeline.pipeline.trigger_on_job_id IS 'logic → ingest.ingestion_job';
COMMENT ON COLUMN pipeline.pipeline.depends_on_pipeline_ids IS 'Chỉ chạy khi pipeline gốc cùng kỳ đã thành công (BR-112)';
COMMENT ON COLUMN pipeline.pipeline.on_failure IS 'notify, retry_then_notify, skip';
COMMENT ON COLUMN pipeline.pipeline.deleted_at IS 'Xoá mềm';

CREATE TABLE pipeline.pipeline_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  pipeline_id uuid NOT NULL,
  mode text NOT NULL,
  sample_rows integer,
  rows_in bigint,
  rows_out bigint,
  rows_dropped jsonb NOT NULL DEFAULT '[]',
  totals_check jsonb,
  status text NOT NULL DEFAULT 'running',
  workflow_id text,
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pipeline_run_pkey PRIMARY KEY (id),
  CHECK (mode IN ('preview','full','scheduled')),
  CHECK (status IN ('running','succeeded','failed','skipped_overlap'))
);
COMMENT ON TABLE pipeline.pipeline_run IS 'Một lần chạy pipeline, kể cả chạy thử trên mẫu. Use case: UC-06-01, UC-06-02, UC-06-03, UC-06-07.';
COMMENT ON COLUMN pipeline.pipeline_run.pipeline_id IS 'FK pipeline';
COMMENT ON COLUMN pipeline.pipeline_run.mode IS 'preview, full, scheduled';
COMMENT ON COLUMN pipeline.pipeline_run.sample_rows IS 'Chạy thử trên 10.000 dòng';
COMMENT ON COLUMN pipeline.pipeline_run.rows_dropped IS 'Theo từng bước';
COMMENT ON COLUMN pipeline.pipeline_run.totals_check IS 'Tổng trước và sau của cột tiền; lệch thì không lưu (UC-06-01 E2)';
COMMENT ON COLUMN pipeline.pipeline_run.status IS 'running, succeeded, failed, skipped_overlap';

CREATE TABLE pipeline.lineage_edge (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  from_kind text NOT NULL,
  from_id uuid NOT NULL,
  to_kind text NOT NULL,
  to_id uuid NOT NULL,
  via text,
  via_ref uuid,
  valid_to timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT lineage_edge_pkey PRIMARY KEY (id),
  CHECK (from_kind IN ('source','dataset','column','metric','tile','report','skill','agent','data_product') AND to_kind IN ('source','dataset','column','metric','tile','report','skill','agent','data_product')),
  UNIQUE NULLS NOT DISTINCT (from_kind, from_id, to_kind, to_id, valid_to)
);
COMMENT ON TABLE pipeline.lineage_edge IS 'Cạnh dòng dữ liệu giữa hai đối tượng; mọi dịch vụ tạo đối tượng dẫn xuất phải phát sự kiện để ghi cạnh (BR-114). Use case: UC-01-02, UC-02-07, UC-06-02, UC-06-05, UC-06-06.';
COMMENT ON COLUMN pipeline.lineage_edge.from_kind IS 'source, dataset, column, metric, tile, report, skill, agent, data_product';
COMMENT ON COLUMN pipeline.lineage_edge.via IS 'Ví dụ pipeline, semantic, query';
COMMENT ON COLUMN pipeline.lineage_edge.valid_to IS 'Đóng khi quan hệ không còn';

CREATE TABLE pipeline.data_mart (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  name text NOT NULL,
  fact_dataset_id uuid NOT NULL,
  grain text NOT NULL,
  measures jsonb NOT NULL,
  dimensions jsonb NOT NULL,
  relations jsonb NOT NULL,
  checks jsonb NOT NULL DEFAULT '[]',
  suggested_dimensions jsonb,
  relation_check_passed boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_mart_pkey PRIMARY KEY (id),
  CHECK (status IN ('draft','active','retired')),
  CHECK (status <> 'active' OR relation_check_passed)
);
COMMENT ON TABLE pipeline.data_mart IS 'Data mart mô hình sao: bảng sự kiện, hạt, độ đo, chiều, kiểm tra. Use case: UC-06-06.';
COMMENT ON COLUMN pipeline.data_mart.grain IS 'Ví dụ khoản vay × ngày';
COMMENT ON COLUMN pipeline.data_mart.checks IS 'Tổng khớp nguồn, độ mới, khoá chiều duy nhất';
COMMENT ON COLUMN pipeline.data_mart.suggested_dimensions IS 'Chiều gợi ý từ quan hệ của bảng sự kiện, sinh khi tạo mart; người soạn chọn vào dimensions (UC-06-06, thêm 12/10/2026)';
COMMENT ON COLUMN pipeline.data_mart.relation_check_passed IS 'Thất bại thì không phát hành được';
COMMENT ON COLUMN pipeline.data_mart.status IS 'draft, active, retired';

CREATE TABLE pipeline.data_product (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  dataset_id uuid,
  data_mart_id uuid,
  contract jsonb NOT NULL,
  consumers uuid[] NOT NULL DEFAULT '{}',
  owner_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  breaking_notice_at timestamptz,
  retire_after timestamptz,
  approved_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT data_product_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, code, version),
  CHECK (status IN ('draft','published','deprecated','retired')),
  CHECK (dataset_id IS NOT NULL OR data_mart_id IS NOT NULL),
  CHECK (status <> 'published' OR approved_by IS NOT NULL),
  CHECK (approved_by IS NULL OR approved_by = owner_id),
  CHECK (retire_after IS NULL OR breaking_notice_at IS NULL OR retire_after >= breaking_notice_at + interval '30 days')
);
COMMENT ON TABLE pipeline.data_product IS 'Sản phẩm dữ liệu có hợp đồng, phiên bản và danh sách bên dùng; thay đổi phá vỡ báo trước 30 ngày (BR-60). Use case: UC-06-06.';
COMMENT ON COLUMN pipeline.data_product.data_space_id IS 'Data Space cung cấp';
COMMENT ON COLUMN pipeline.data_product.data_mart_id IS 'FK data_mart';
COMMENT ON COLUMN pipeline.data_product.contract IS 'Cột, kiểu, ý nghĩa, SLA';
COMMENT ON COLUMN pipeline.data_product.consumers IS 'Data Space đăng ký dùng';
COMMENT ON COLUMN pipeline.data_product.owner_id IS 'logic → org.app_user; người phụ trách duyệt phát hành, khác người soạn (thêm 12/10/2026)';
COMMENT ON COLUMN pipeline.data_product.status IS 'draft, published, deprecated, retired';

CREATE TABLE pipeline.writeback_request (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  source_id uuid NOT NULL,
  target_table text NOT NULL,
  from_dataset_id uuid NOT NULL,
  requested_by uuid NOT NULL,
  diff_summary jsonb NOT NULL DEFAULT '{}',
  diff_ref text,
  deletes integer NOT NULL DEFAULT 0,
  write_window tstzrange,
  snapshot_ref text,
  approved_by uuid,
  proposal_id uuid,
  status text NOT NULL DEFAULT 'draft',
  executed_at timestamptz,
  totals_check jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT writeback_request_pkey PRIMARY KEY (id),
  CHECK (status IN ('draft','previewed','submitted','approved','rejected','scheduled','executing','executed','cancelled_mismatch','failed','undo_requested','undone')),
  CHECK (deletes = 0),
  CHECK (approved_by IS NULL OR approved_by <> requested_by),
  CHECK (status NOT IN ('approved','scheduled','executing','executed') OR approved_by IS NOT NULL)
);
COMMENT ON TABLE pipeline.writeback_request IS 'Yêu cầu ghi ngược về nguồn qua xem trước, duyệt, bảng tạm, kiểm tổng (SD-06). Use case: UC-06-04.';
COMMENT ON COLUMN pipeline.writeback_request.source_id IS 'logic → catalog.source';
COMMENT ON COLUMN pipeline.writeback_request.from_dataset_id IS 'Bảng dẫn xuất làm đầu vào';
COMMENT ON COLUMN pipeline.writeback_request.diff_summary IS 'Số dòng thêm, sửa, xoá; mẫu trước và sau, không có cột nhạy cảm';
COMMENT ON COLUMN pipeline.writeback_request.deletes IS 'Phải bằng 0 (BR-113)';
COMMENT ON COLUMN pipeline.writeback_request.snapshot_ref IS 'Ảnh chụp bảng đích để hoàn tác 30 ngày';
COMMENT ON COLUMN pipeline.writeback_request.approved_by IS 'Phải khác người yêu cầu (BR-24)';
COMMENT ON COLUMN pipeline.writeback_request.proposal_id IS 'logic → inbox.proposal';
COMMENT ON COLUMN pipeline.writeback_request.status IS 'draft, previewed, submitted, approved, rejected, scheduled, executing, executed, cancelled_mismatch, failed, undo_requested, undone';

CREATE TABLE pipeline.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE pipeline.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON pipeline.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE pipeline.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON pipeline.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA pipeline TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON pipeline.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON pipeline.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON pipeline.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX pipeline_run_pipeline_id_started_at_idx ON pipeline.pipeline_run (pipeline_id, started_at DESC);
CREATE INDEX lineage_edge_from_kind_from_id_idx ON pipeline.lineage_edge (from_kind, from_id) WHERE valid_to IS NULL;
CREATE INDEX lineage_edge_to_kind_to_id_idx ON pipeline.lineage_edge (to_kind, to_id) WHERE valid_to IS NULL;

-- ═══ schema ingest ═══
CREATE TABLE ingest.ingestion_job (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  source_id uuid NOT NULL,
  name text NOT NULL,
  mode text NOT NULL,
  source_object text NOT NULL,
  target_dataset_id uuid,
  cursor_column text,
  cursor_value text,
  schedule_cron text,
  freshness_sla interval,
  dlq_retention_days integer NOT NULL DEFAULT 30,
  status text NOT NULL DEFAULT 'active',
  paused_reason text,
  paused_at timestamptz,
  consecutive_failures smallint NOT NULL DEFAULT 0,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT ingestion_job_pkey PRIMARY KEY (id),
  CHECK (mode IN ('full','incremental','cdc')),
  CHECK (mode <> 'incremental' OR cursor_column IS NOT NULL),
  CHECK (status IN ('draft','active','paused','failing','schema_drift')),
  CHECK (status <> 'paused' OR paused_reason IS NOT NULL)
);
COMMENT ON TABLE ingest.ingestion_job IS 'Job nạp dữ liệu từ một nguồn về vùng dữ liệu: toàn phần, gia tăng hoặc CDC. Use case: UC-04-06, UC-04-07, UC-04-09.';
COMMENT ON COLUMN ingest.ingestion_job.source_id IS 'logic → catalog.source';
COMMENT ON COLUMN ingest.ingestion_job.mode IS 'full, incremental, cdc';
COMMENT ON COLUMN ingest.ingestion_job.source_object IS 'Bảng, chủ đề Kafka, đường dẫn tệp hoặc endpoint';
COMMENT ON COLUMN ingest.ingestion_job.target_dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN ingest.ingestion_job.cursor_column IS 'Cột con trỏ khi incremental';
COMMENT ON COLUMN ingest.ingestion_job.freshness_sla IS 'Trễ quá hạn thì nguồn “Cần sửa” (BR-56)';
COMMENT ON COLUMN ingest.ingestion_job.dlq_retention_days IS 'BR-57';
COMMENT ON COLUMN ingest.ingestion_job.status IS 'draft, active, paused, failing, schema_drift';
COMMENT ON COLUMN ingest.ingestion_job.paused_reason IS 'Bắt buộc khi tạm dừng (BR-106)';
COMMENT ON COLUMN ingest.ingestion_job.deleted_at IS 'Xoá mềm';

CREATE TABLE ingest.job_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  job_id uuid NOT NULL,
  workflow_id text,
  rows_read bigint NOT NULL DEFAULT 0,
  rows_written bigint NOT NULL DEFAULT 0,
  rows_dlq bigint NOT NULL DEFAULT 0,
  cursor_from text,
  cursor_to text,
  lag_seconds integer,
  status text NOT NULL DEFAULT 'running',
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT job_run_pkey PRIMARY KEY (id),
  CHECK (status IN ('running','succeeded','failed','schema_drift','cancelled'))
);
COMMENT ON TABLE ingest.job_run IS 'Một lần chạy job nạp: số dòng đọc, ghi, vào DLQ, kết quả chất lượng. Use case: UC-04-06, UC-04-07, UC-04-09, UC-06-07.';
COMMENT ON COLUMN ingest.job_run.job_id IS 'FK ingestion_job';
COMMENT ON COLUMN ingest.job_run.lag_seconds IS 'Độ trễ so với nguồn';
COMMENT ON COLUMN ingest.job_run.status IS 'running, succeeded, failed, schema_drift, cancelled';

CREATE TABLE ingest.dlq_record (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  job_id uuid NOT NULL,
  job_run_id uuid NOT NULL,
  payload_ref text NOT NULL,
  error_kind text NOT NULL,
  error text NOT NULL,
  replay_count smallint NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'pending',
  discard_reason text,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '30 days',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT dlq_record_pkey PRIMARY KEY (id),
  CHECK (error_kind IN ('schema_mismatch','type_error','constraint','source_data')),
  CHECK (status IN ('pending','replayed','discarded','locked')),
  CHECK (status <> 'discarded' OR discard_reason IS NOT NULL),
  CHECK (replay_count <= 3 OR status IN ('locked','replayed','discarded'))
);
COMMENT ON TABLE ingest.dlq_record IS 'Bản ghi lỗi chờ xử lý; giữ 30 ngày, nạp lại lỗi quá 3 lần thì khoá tự động (UC-04-07). Use case: UC-04-07, UC-04-09.';
COMMENT ON COLUMN ingest.dlq_record.job_id IS 'FK ingestion_job';
COMMENT ON COLUMN ingest.dlq_record.job_run_id IS 'FK job_run';
COMMENT ON COLUMN ingest.dlq_record.payload_ref IS 'Bản ghi gốc trong MinIO, đã che';
COMMENT ON COLUMN ingest.dlq_record.error_kind IS 'schema_mismatch, type_error, constraint, source_data';
COMMENT ON COLUMN ingest.dlq_record.status IS 'pending, replayed, discarded, locked';
COMMENT ON COLUMN ingest.dlq_record.discard_reason IS 'Bắt buộc khi bỏ (BR-104)';

CREATE TABLE ingest.file_upload (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  uploader_id uuid NOT NULL,
  file_name text NOT NULL,
  object_key text NOT NULL,
  size_bytes bigint NOT NULL,
  sheet text,
  header_row integer,
  encoding text,
  decimal_sep text,
  column_map jsonb NOT NULL DEFAULT '[]',
  validation jsonb NOT NULL DEFAULT '{}',
  error_ratio numeric(5,4),
  target_dataset_id uuid,
  replace_mode text,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '90 days',
  status text NOT NULL DEFAULT 'uploaded',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT file_upload_pkey PRIMARY KEY (id),
  CHECK (size_bytes <= 209715200),
  CHECK (replace_mode IS NULL OR replace_mode IN ('replace','keep')),
  CHECK (status IN ('uploaded','analyzed','mapped','committed','rejected','expired')),
  CHECK (status <> 'committed' OR (error_ratio IS NOT NULL AND error_ratio <= 0.05 AND target_dataset_id IS NOT NULL))
);
COMMENT ON TABLE ingest.file_upload IS 'Tệp CSV, Excel tải lên: nhận dạng cấu trúc, ánh xạ cột, kiểm tra với dữ liệu sẵn có. Use case: UC-04-08.';
COMMENT ON COLUMN ingest.file_upload.object_key IS 'MinIO da-ingest';
COMMENT ON COLUMN ingest.file_upload.size_bytes IS 'Tối đa 200 MB';
COMMENT ON COLUMN ingest.file_upload.column_map IS 'Cột nguồn, kiểu, đơn vị, cột đích, cột dữ liệu cá nhân bị che';
COMMENT ON COLUMN ingest.file_upload.validation IS 'Ví dụ mã khớp 99,6%, 14 dòng sai định dạng';
COMMENT ON COLUMN ingest.file_upload.error_ratio IS 'Trên 5% thì không cho ghi (UC-04-08 E2)';
COMMENT ON COLUMN ingest.file_upload.replace_mode IS 'replace, keep khi ghép vào bảng có sẵn';
COMMENT ON COLUMN ingest.file_upload.expires_at IS 'BR-105';
COMMENT ON COLUMN ingest.file_upload.status IS 'uploaded, analyzed, mapped, committed, rejected, expired';

CREATE TABLE ingest.quality_rule (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  dataset_id uuid NOT NULL,
  column_name text,
  kind text NOT NULL,
  params jsonb NOT NULL DEFAULT '{}',
  severity text NOT NULL DEFAULT 'medium',
  origin text NOT NULL DEFAULT 'manual',
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT quality_rule_pkey PRIMARY KEY (id),
  CHECK (kind IN ('not_null','range','unique','in_list','sum_matches','freshness','custom_sql')),
  CHECK (severity IN ('high','medium','low')),
  CHECK (origin IN ('manual','agent_suggested','pack')),
  CHECK (status IN ('draft','active','disabled'))
);
COMMENT ON TABLE ingest.quality_rule IS 'Quy tắc chất lượng trên bảng hoặc cột kèm mức nghiêm trọng. Use case: UC-04-08, UC-06-06, UC-06-07.';
COMMENT ON COLUMN ingest.quality_rule.dataset_id IS 'logic → catalog.dataset';
COMMENT ON COLUMN ingest.quality_rule.kind IS 'not_null, range, unique, in_list, sum_matches, freshness, custom_sql';
COMMENT ON COLUMN ingest.quality_rule.severity IS 'high (chặn báo cáo, BR-116), medium, low';
COMMENT ON COLUMN ingest.quality_rule.origin IS 'manual, agent_suggested, pack';
COMMENT ON COLUMN ingest.quality_rule.status IS 'draft, active, disabled';

CREATE TABLE ingest.quality_result (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  rule_id uuid NOT NULL,
  run_kind text NOT NULL,
  run_ref uuid,
  passed boolean NOT NULL,
  violations bigint NOT NULL DEFAULT 0,
  sample_ref text,
  acknowledged_by uuid,
  acknowledged_at timestamptz,
  acknowledged_note text,
  checked_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT quality_result_pkey PRIMARY KEY (id),
  CHECK (run_kind IN ('job_run','pipeline_run','scheduled','manual')),
  CHECK (acknowledged_by IS NULL OR (acknowledged_at IS NOT NULL AND acknowledged_note IS NOT NULL))
);
COMMENT ON TABLE ingest.quality_result IS 'Kết quả một lần chạy quy tắc chất lượng sau nạp hoặc pipeline. Use case: UC-04-09, UC-06-07.';
COMMENT ON COLUMN ingest.quality_result.rule_id IS 'FK quality_rule';
COMMENT ON COLUMN ingest.quality_result.run_kind IS 'job_run, pipeline_run, scheduled, manual';
COMMENT ON COLUMN ingest.quality_result.sample_ref IS 'Mẫu dòng vi phạm, đã che';
COMMENT ON COLUMN ingest.quality_result.acknowledged_by IS 'Người xác nhận dùng tiếp khi vi phạm mức cao';
COMMENT ON COLUMN ingest.quality_result.acknowledged_at IS 'Thêm 12/10/2026';
COMMENT ON COLUMN ingest.quality_result.acknowledged_note IS 'Lý do dùng tiếp, bắt buộc khi có acknowledged_by (BR-116, thêm 12/10/2026)';

CREATE TABLE ingest.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE ingest.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON ingest.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE ingest.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON ingest.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA ingest TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON ingest.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON ingest.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON ingest.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX job_run_job_id_started_at_idx ON ingest.job_run (job_id, started_at DESC);
CREATE INDEX dlq_record_job_id_idx ON ingest.dlq_record (job_id) WHERE status = 'pending';
CREATE INDEX dlq_record_expires_at_idx ON ingest.dlq_record (expires_at);
CREATE INDEX quality_rule_dataset_id_idx ON ingest.quality_rule (dataset_id) WHERE status = 'active';
CREATE INDEX quality_result_rule_id_checked_at_idx ON ingest.quality_result (rule_id, checked_at DESC);

-- ═══ schema acquire ═══
CREATE TABLE acquire.crawl_source (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  name text NOT NULL,
  goal text NOT NULL,
  kind text NOT NULL,
  seed_urls jsonb NOT NULL DEFAULT '[]',
  allowed_domains text[] NOT NULL,
  max_depth integer NOT NULL DEFAULT 3,
  schedule_cron text,
  rate_limit_rps numeric NOT NULL DEFAULT 1,
  auth_mode text NOT NULL DEFAULT 'none',
  secret_ref text,
  openapi_url text,
  robots_checked_at timestamptz,
  terms_note text,
  terms_url text,
  terms_sha256 text,
  terms_observed_sha256 text,
  terms_checked_at timestamptz,
  legal_status text NOT NULL DEFAULT 'pending',
  legal_checklist jsonb NOT NULL DEFAULT '{}',
  legal_evidence jsonb NOT NULL DEFAULT '[]',
  legal_reviewed_by uuid,
  legal_reviewed_at timestamptz,
  legal_review_due_at timestamptz,
  review_gate text NOT NULL DEFAULT 'all',
  trust_level numeric(3,2) NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  owner_id uuid NOT NULL,
  active_schema_version_id uuid,
  consecutive_blocked integer NOT NULL DEFAULT 0,
  last_run_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT crawl_source_pkey PRIMARY KEY (id),
  CHECK (kind IN ('web_page','web_listing','public_api','feed','file_drop')),
  CHECK (auth_mode IN ('none','api_key')),
  CHECK (auth_mode <> 'api_key' OR secret_ref IS NOT NULL),
  CHECK (review_gate IN ('all','exceptions','auto')),
  CHECK (trust_level BETWEEN 0 AND 1),
  CHECK (rate_limit_rps > 0),
  CHECK (status IN ('draft','active','paused','quarantined','retired')),
  CHECK (status <> 'active' OR active_schema_version_id IS NOT NULL),
  UNIQUE (data_space_id, name),
  CHECK (legal_status IN ('pending','approved','rejected','expired')),
  CHECK (legal_reviewed_by IS NULL OR legal_reviewed_by <> owner_id)
);
COMMENT ON TABLE acquire.crawl_source IS 'Nguồn thu thập bên ngoài cùng phạm vi, lịch và cổng duyệt, ví dụ trang lãi suất huy động của một ngân hàng. Thay KBSource của code hiện tại. Use case: UC-14-01, UC-14-02, UC-14-06.';
COMMENT ON COLUMN acquire.crawl_source.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN acquire.crawl_source.goal IS 'Mô tả dữ liệu cần thu, ví dụ “lãi suất huy động 12 tháng của các ngân hàng hằng ngày”';
COMMENT ON COLUMN acquire.crawl_source.kind IS 'web_page, web_listing, public_api, feed, file_drop';
COMMENT ON COLUMN acquire.crawl_source.seed_urls IS 'URL hạt giống';
COMMENT ON COLUMN acquire.crawl_source.allowed_domains IS 'Chỉ thu trong các miền này (BR-149)';
COMMENT ON COLUMN acquire.crawl_source.max_depth IS 'Độ sâu tối đa khi theo liên kết';
COMMENT ON COLUMN acquire.crawl_source.rate_limit_rps IS 'Số yêu cầu mỗi giây mỗi miền (BR-149)';
COMMENT ON COLUMN acquire.crawl_source.auth_mode IS 'none, api_key';
COMMENT ON COLUMN acquire.crawl_source.secret_ref IS 'Đường dẫn bí mật trong OpenBao; bắt buộc khi api_key';
COMMENT ON COLUMN acquire.crawl_source.openapi_url IS 'URL tài liệu OpenAPI khi kind = public_api; có thì đọc schema từ tài liệu thay cho suy ngược (UC-14-01)';
COMMENT ON COLUMN acquire.crawl_source.robots_checked_at IS 'Lần kiểm robots.txt gần nhất';
COMMENT ON COLUMN acquire.crawl_source.terms_note IS 'Ghi chú điều khoản sử dụng, lý do chặn nếu có';
COMMENT ON COLUMN acquire.crawl_source.terms_url IS 'Trang điều khoản sử dụng hoặc giấy phép dữ liệu của nguồn (BR-174)';
COMMENT ON COLUMN acquire.crawl_source.terms_sha256 IS 'Băm SHA-256 văn bản điều khoản đã chuẩn hoá tại lần duyệt pháp lý (BR-174)';
COMMENT ON COLUMN acquire.crawl_source.terms_observed_sha256 IS 'Băm lần kiểm gần nhất (mỗi ngày và trước mỗi lượt); khác terms_sha256 thì duyệt hết hiệu lực, nguồn tự tạm ngưng (BR-174)';
COMMENT ON COLUMN acquire.crawl_source.terms_checked_at IS 'Lần kiểm trang điều khoản gần nhất';
COMMENT ON COLUMN acquire.crawl_source.legal_status IS 'pending, approved, rejected, expired; nguồn chỉ active khi approved và chưa quá hạn xem lại (BR-174)';
COMMENT ON COLUMN acquire.crawl_source.legal_checklist IS 'Kết quả bốn mục duyệt {terms, robots, copyright, personal_data}, mỗi mục {result, note}';
COMMENT ON COLUMN acquire.crawl_source.legal_evidence IS 'Bằng chứng: ảnh chụp trang điều khoản, robots.txt, ghi chú bản quyền {kind, object_key, sha256, captured_at} ở MinIO da-raw-crawl/legal; tối thiểu 1 khi approved';
COMMENT ON COLUMN acquire.crawl_source.legal_reviewed_by IS 'logic → org.app_user; người duyệt pháp lý (AC06), khác owner_id';
COMMENT ON COLUMN acquire.crawl_source.legal_reviewed_at IS 'Lúc duyệt pháp lý';
COMMENT ON COLUMN acquire.crawl_source.legal_review_due_at IS 'Hạn xem lại, mặc định 6 tháng, tối đa 184 ngày sau legal_reviewed_at (BR-174)';
COMMENT ON COLUMN acquire.crawl_source.review_gate IS 'all, exceptions, auto; auto chỉ bật khi độ chính xác mẫu ≥ 98% trong 4 lượt liên tiếp (UC-14-04)';
COMMENT ON COLUMN acquire.crawl_source.trust_level IS 'Mức tin cậy nguồn 0 đến 1; dữ liệu mang nhãn “nguồn ngoài” (BR-156)';
COMMENT ON COLUMN acquire.crawl_source.status IS 'draft, active, paused, quarantined, retired';
COMMENT ON COLUMN acquire.crawl_source.owner_id IS 'logic → org.app_user; người phụ trách nguồn';
COMMENT ON COLUMN acquire.crawl_source.active_schema_version_id IS 'FK crawl_schema_version đang active';
COMMENT ON COLUMN acquire.crawl_source.consecutive_blocked IS 'Bị chặn 3 lượt liên tiếp thì tạm ngưng (UC-14-06)';

CREATE TABLE acquire.crawl_schema_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  source_id uuid NOT NULL,
  version integer NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  record_selector text NOT NULL,
  fields jsonb NOT NULL DEFAULT '[]',
  template_fingerprint jsonb,
  value_rules jsonb NOT NULL DEFAULT '[]',
  sample_page_ids uuid[] NOT NULL DEFAULT '{}',
  test_required_accuracy numeric(5,4),
  parent_version_id uuid,
  inferred_by_run_id uuid,
  approved_by uuid,
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT crawl_schema_version_pkey PRIMARY KEY (id),
  UNIQUE (source_id, version),
  CHECK (status IN ('draft','testing','active','superseded','rejected')),
  CHECK (status NOT IN ('active','superseded') OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)),
  CHECK (status <> 'active' OR test_required_accuracy >= 0.95),
  CHECK (jsonb_typeof(value_rules) = 'array'),
  CHECK (acquire.value_constraints_ok(fields, false)),
  CHECK (status <> 'active' OR acquire.value_constraints_ok(fields, true))
);
COMMENT ON TABLE acquire.crawl_schema_version IS 'Phiên bản schema thu thập của một nguồn: vùng bản ghi, trường, vị trí trích, ánh xạ thuộc tính chuẩn; sửa luôn tạo phiên bản mới, hoàn tác quay về phiên bản đúng gần nhất (BR-151, BR-152). Thay “schema crawler” trong Connector service. Use case: UC-14-02, UC-14-03.';
COMMENT ON COLUMN acquire.crawl_schema_version.source_id IS 'FK crawl_source';
COMMENT ON COLUMN acquire.crawl_schema_version.status IS 'draft, testing, active, superseded, rejected';
COMMENT ON COLUMN acquire.crawl_schema_version.record_selector IS 'Vùng bản ghi lặp: CSS/XPath, JSONPath, bảng hoặc vùng trang PDF';
COMMENT ON COLUMN acquire.crawl_schema_version.fields IS 'Mảng {name, type, unit, required, is_key, locator, canonical_attr, value_constraints}; canonical_attr trỏ tới thuộc tính chuẩn của lớp ngữ cảnh hoặc gói ngành; value_constraints là miền hợp lệ {min, max, unit, scale, max_change_pp, label_terms}, bắt buộc min, max, unit với trường number, percent, money khi active (BR-168). Ví dụ lãi suất 12 tháng: {min: 0, max: 15, unit: “%/năm”, max_change_pp: 1,5, label_terms: [“tại quầy”]}';
COMMENT ON COLUMN acquire.crawl_schema_version.template_fingerprint IS 'Dấu vân tay mẫu: cấu trúc DOM, tập khoá JSON, tiêu đề cột; dùng phát hiện thay đổi (UC-14-03)';
COMMENT ON COLUMN acquire.crawl_schema_version.value_rules IS 'Quan hệ nội tại giữa trường, chỉ cảnh báo, ví dụ {rule: gte, left: rate_24m, right: rate_12m, tolerance_pp: 0.3} (BR-168)';
COMMENT ON COLUMN acquire.crawl_schema_version.sample_page_ids IS 'logic → crawl_page; mẫu giữ lại để chạy thử (tối thiểu 20 trang hoặc toàn bộ nếu ít hơn)';
COMMENT ON COLUMN acquire.crawl_schema_version.test_required_accuracy IS 'Tỷ lệ trường bắt buộc trích đúng khi chạy thử; từ 0,95 mới được duyệt (BR-151)';
COMMENT ON COLUMN acquire.crawl_schema_version.parent_version_id IS 'FK crawl_schema_version; phiên bản gốc khi ánh xạ lại hoặc hoàn tác';
COMMENT ON COLUMN acquire.crawl_schema_version.inferred_by_run_id IS 'logic → agent.agent_run; lượt suy ngược của Agent Thu thập';
COMMENT ON COLUMN acquire.crawl_schema_version.approved_by IS 'logic → org.app_user';

CREATE TABLE acquire.crawl_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  source_id uuid NOT NULL,
  schema_version_id uuid,
  trigger text NOT NULL,
  status text NOT NULL DEFAULT 'queued',
  pages_fetched integer NOT NULL DEFAULT 0,
  pages_changed integer NOT NULL DEFAULT 0,
  records_extracted integer NOT NULL DEFAULT 0,
  records_flagged integer NOT NULL DEFAULT 0,
  sample_accuracy numeric(5,4),
  drift_score numeric(5,4),
  cost numeric(12,4),
  agent_run_id uuid,
  started_at timestamptz,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT crawl_run_pkey PRIMARY KEY (id),
  CHECK (trigger IN ('schedule','manual','retry')),
  CHECK (status IN ('queued','fetching','extracting','in_review','published','quarantined','failed')),
  CHECK (status <> 'published' OR schema_version_id IS NOT NULL),
  CHECK (sample_accuracy IS NULL OR sample_accuracy BETWEEN 0 AND 1)
);
COMMENT ON TABLE acquire.crawl_run IS 'Một lượt thu của một nguồn: tải, trích, duyệt, phát hành sang lớp hợp nhất. Thay KBSourceRun của code hiện tại. Use case: UC-14-03, UC-14-04, UC-14-06.';
COMMENT ON COLUMN acquire.crawl_run.source_id IS 'FK crawl_source';
COMMENT ON COLUMN acquire.crawl_run.schema_version_id IS 'FK crawl_schema_version dùng để trích';
COMMENT ON COLUMN acquire.crawl_run.trigger IS 'schedule, manual, retry';
COMMENT ON COLUMN acquire.crawl_run.status IS 'queued, fetching, extracting, in_review, published, quarantined, failed';
COMMENT ON COLUMN acquire.crawl_run.pages_changed IS 'Trang có SHA-256 khác lượt trước';
COMMENT ON COLUMN acquire.crawl_run.records_flagged IS 'Bản ghi vào hàng duyệt';
COMMENT ON COLUMN acquire.crawl_run.sample_accuracy IS 'Độ chính xác trên mẫu ngẫu nhiên 2% (UC-14-04)';
COMMENT ON COLUMN acquire.crawl_run.drift_score IS 'Điểm lệch cấu trúc so với phiên bản active (UC-14-03)';
COMMENT ON COLUMN acquire.crawl_run.cost IS 'Chi phí mô hình của lượt';
COMMENT ON COLUMN acquire.crawl_run.agent_run_id IS 'logic → agent.agent_run';

CREATE TABLE acquire.crawl_page (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  source_id uuid NOT NULL,
  url text NOT NULL,
  fetched_at timestamptz NOT NULL,
  http_status smallint,
  content_type text,
  sha256 text NOT NULL,
  object_key text,
  byte_size bigint,
  changed boolean NOT NULL DEFAULT true,
  fingerprint jsonb,
  retain_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT crawl_page_pkey PRIMARY KEY (id),
  CHECK (http_status IS NULL OR http_status BETWEEN 100 AND 599),
  CHECK (sha256 ~ '^[0-9a-f]{64}$')
);
COMMENT ON TABLE acquire.crawl_page IS 'Một trang, tệp hoặc phản hồi API đã tải; bản gốc giữ nguyên trong MinIO có object lock, mọi bản ghi trích truy về đây (BR-150). Thay KBSourceCrawlQueue của code hiện tại. Use case: UC-14-02, UC-14-03, UC-14-06.';
COMMENT ON COLUMN acquire.crawl_page.run_id IS 'FK crawl_run';
COMMENT ON COLUMN acquire.crawl_page.source_id IS 'FK crawl_source';
COMMENT ON COLUMN acquire.crawl_page.content_type IS 'Ví dụ text/html, application/json, application/pdf';
COMMENT ON COLUMN acquire.crawl_page.sha256 IS 'Mã băm bản gốc (BR-150)';
COMMENT ON COLUMN acquire.crawl_page.object_key IS 'MinIO da-raw-crawl (object lock, giữ 400 ngày); null khi tải lỗi';
COMMENT ON COLUMN acquire.crawl_page.changed IS 'Khác bản gốc lượt trước';
COMMENT ON COLUMN acquire.crawl_page.fingerprint IS 'Dấu vân tay cấu trúc của trang';
COMMENT ON COLUMN acquire.crawl_page.retain_until IS 'Hạn giữ bản gốc; quá hạn thì không trích lại được (UC-14-03)';

CREATE TABLE acquire.extracted_record (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  run_id uuid NOT NULL,
  page_id uuid NOT NULL,
  schema_version_id uuid NOT NULL,
  entity_key text NOT NULL,
  period text NOT NULL,
  values jsonb NOT NULL,
  field_confidence jsonb NOT NULL DEFAULT '{}',
  record_confidence numeric(5,4) NOT NULL,
  status text NOT NULL DEFAULT 'pending',
  review_reasons text[] NOT NULL DEFAULT '{}',
  is_random_sample boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT extracted_record_pkey PRIMARY KEY (id),
  CHECK (status IN ('pending','flagged','approved','corrected','rejected','superseded')),
  CHECK (record_confidence BETWEEN 0 AND 1),
  CHECK (review_reasons <@ ARRAY['low_confidence','missing_required','outlier','new_category','entity_uncertain','random_sample','out_of_domain','relation_warning','semantic_shift','label_changed']),
  CHECK (status <> 'flagged' OR cardinality(review_reasons) > 0)
);
COMMENT ON TABLE acquire.extracted_record IS 'Bản ghi trích từ một trang gốc theo một phiên bản schema, kèm độ tin từng trường; chỉ bản ghi approved hoặc corrected của lượt đã phát hành mới sang lớp hợp nhất (BR-153). Khi hoàn tác schema, bản ghi trích bằng phiên bản lỗi chuyển superseded. Use case: UC-14-03, UC-14-04, UC-14-05.';
COMMENT ON COLUMN acquire.extracted_record.run_id IS 'FK crawl_run';
COMMENT ON COLUMN acquire.extracted_record.page_id IS 'FK crawl_page; truy về bản gốc (BR-150)';
COMMENT ON COLUMN acquire.extracted_record.schema_version_id IS 'FK crawl_schema_version';
COMMENT ON COLUMN acquire.extracted_record.entity_key IS 'Khoá thực thể như nguồn ghi, ví dụ tên ngân hàng trên trang';
COMMENT ON COLUMN acquire.extracted_record.period IS 'Kỳ của giá trị, ví dụ 2026-10-10 hoặc 2026-W41';
COMMENT ON COLUMN acquire.extracted_record.values IS 'Giá trị theo tên trường';
COMMENT ON COLUMN acquire.extracted_record.field_confidence IS 'Độ tin từng trường, 0 đến 1';
COMMENT ON COLUMN acquire.extracted_record.record_confidence IS 'Dưới 0,85 thì vào hàng duyệt (UC-14-04)';
COMMENT ON COLUMN acquire.extracted_record.status IS 'pending, flagged, approved, corrected, rejected, superseded';
COMMENT ON COLUMN acquire.extracted_record.review_reasons IS 'low_confidence, missing_required, outlier, new_category, entity_uncertain, random_sample, out_of_domain, relation_warning, semantic_shift, label_changed; relation_warning chỉ cảnh báo, không chặn (BR-168)';
COMMENT ON COLUMN acquire.extracted_record.is_random_sample IS 'Mẫu ngẫu nhiên 2%, tối thiểu 5 bản ghi mỗi lượt';

CREATE TABLE acquire.review_decision (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  record_id uuid NOT NULL,
  decision text NOT NULL,
  corrected_values jsonb,
  reason text,
  decided_by uuid NOT NULL,
  decided_at timestamptz NOT NULL DEFAULT now(),
  used_as_example boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT review_decision_pkey PRIMARY KEY (id),
  CHECK (decision IN ('confirm','correct','reject')),
  CHECK (decision <> 'correct' OR corrected_values IS NOT NULL),
  CHECK (decision <> 'reject' OR reason IS NOT NULL)
);
COMMENT ON TABLE acquire.review_decision IS 'Quyết định của người duyệt trên một bản ghi trích; bản ghi người sửa được giữ làm ví dụ cho bộ trích (BR-153). Use case: UC-14-04.';
COMMENT ON COLUMN acquire.review_decision.record_id IS 'FK extracted_record';
COMMENT ON COLUMN acquire.review_decision.decision IS 'confirm, correct, reject';
COMMENT ON COLUMN acquire.review_decision.corrected_values IS 'Giá trị sau sửa; bắt buộc khi correct';
COMMENT ON COLUMN acquire.review_decision.reason IS 'Bắt buộc khi reject';
COMMENT ON COLUMN acquire.review_decision.decided_by IS 'logic → org.app_user';
COMMENT ON COLUMN acquire.review_decision.used_as_example IS 'Đã đưa vào ví dụ cho bộ trích';

CREATE TABLE acquire.schema_drift (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  source_id uuid NOT NULL,
  run_id uuid NOT NULL,
  from_version_id uuid NOT NULL,
  drift_kind text NOT NULL DEFAULT 'structural',
  severity text NOT NULL,
  signals jsonb NOT NULL DEFAULT '{}',
  action text NOT NULL,
  proposed_version_id uuid,
  resolution text,
  resolved_by uuid,
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT schema_drift_pkey PRIMARY KEY (id),
  CHECK (severity IN ('minor','major')),
  CHECK (action IN ('auto_remap','revert','paused')),
  CHECK ((severity = 'minor') = (action = 'auto_remap')),
  CHECK (resolution IS NULL OR resolution IN ('approved_new','manual_fix','reverted')),
  CHECK ((resolution IS NULL) = (resolved_at IS NULL))
);
COMMENT ON TABLE acquire.schema_drift IS 'Thay đổi cấu trúc nguồn phát hiện ở một lượt thu và cách xử lý: nhẹ thì agent ánh xạ lại thành phiên bản nháp, nặng thì tạm ngưng nguồn, cách ly dữ liệu lượt và tạo yêu cầu Cần bạn (BR-152). Use case: UC-14-03.';
COMMENT ON COLUMN acquire.schema_drift.source_id IS 'FK crawl_source';
COMMENT ON COLUMN acquire.schema_drift.run_id IS 'FK crawl_run phát hiện thay đổi';
COMMENT ON COLUMN acquire.schema_drift.from_version_id IS 'FK crawl_schema_version đang active khi phát hiện';
COMMENT ON COLUMN acquire.schema_drift.drift_kind IS 'structural, semantic; semantic là lệch ngầm: cấu trúc giữ nguyên nhưng nghĩa giá trị đổi (BR-168)';
COMMENT ON COLUMN acquire.schema_drift.severity IS 'minor, major; major khi mất trường khoá, tỷ lệ trích bắt buộc dưới 80% hoặc đổi định dạng';
COMMENT ON COLUMN acquire.schema_drift.signals IS 'Điểm lệch, trường mất, tỷ lệ trích bắt buộc, đổi định dạng';
COMMENT ON COLUMN acquire.schema_drift.action IS 'auto_remap, revert, paused, quarantine; quarantine chỉ dùng cho semantic: cách ly lượt, không tự hoàn tác';
COMMENT ON COLUMN acquire.schema_drift.proposed_version_id IS 'FK crawl_schema_version agent đề xuất';
COMMENT ON COLUMN acquire.schema_drift.resolution IS 'approved_new, manual_fix, reverted, false_alarm; null khi còn mở; false_alarm chỉ cho semantic; semantic đóng phải có resolved_by';
COMMENT ON COLUMN acquire.schema_drift.resolved_by IS 'logic → org.app_user';

CREATE TABLE acquire.entity_link (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  entity_type text NOT NULL,
  canonical_key text NOT NULL,
  reference_entity_id uuid,
  source_id uuid NOT NULL,
  source_key text NOT NULL,
  match_score numeric(5,4),
  method text NOT NULL,
  status text NOT NULL DEFAULT 'pending',
  decided_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT entity_link_pkey PRIMARY KEY (id),
  CHECK (method IN ('exact','fuzzy','human')),
  CHECK (status IN ('pending','confirmed','rejected')),
  CHECK (match_score IS NULL OR match_score BETWEEN 0 AND 1),
  CHECK (method <> 'human' OR decided_by IS NOT NULL)
);
COMMENT ON TABLE acquire.entity_link IS 'Liên kết khoá thực thể của một nguồn với khoá chuẩn, ví dụ tên viết tắt và tên đầy đủ của một ngân hàng cùng về một mã chuẩn; không chắc thì hỏi người. Use case: UC-14-05.';
COMMENT ON COLUMN acquire.entity_link.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN acquire.entity_link.entity_type IS 'Loại thực thể, ví dụ bank';
COMMENT ON COLUMN acquire.entity_link.canonical_key IS 'Khoá chuẩn, ví dụ SBV:<mã ngân hàng do NHNN cấp>; chép từ reference_entity khi có (BR-169)';
COMMENT ON COLUMN acquire.entity_link.reference_entity_id IS 'FK reference_entity; bắt buộc khi confirmed (BR-169)';
COMMENT ON COLUMN acquire.entity_link.source_id IS 'FK crawl_source';
COMMENT ON COLUMN acquire.entity_link.source_key IS 'Khoá như nguồn ghi';
COMMENT ON COLUMN acquire.entity_link.match_score IS '0 đến 1';
COMMENT ON COLUMN acquire.entity_link.method IS 'identifier, exact, fuzzy, human; fuzzy chỉ tự xác nhận khi match_score ≥ 0,95, dưới đó người duyệt (BR-169)';
COMMENT ON COLUMN acquire.entity_link.status IS 'pending, confirmed, rejected';
COMMENT ON COLUMN acquire.entity_link.decided_by IS 'logic → org.app_user';

CREATE TABLE acquire.reference_entity (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  entity_type text NOT NULL,
  canonical_key text NOT NULL,
  legal_name text NOT NULL,
  short_names text[] NOT NULL DEFAULT '{}',
  sbv_code text,
  swift_bic text,
  tax_code text,
  official_domains text[] NOT NULL DEFAULT '{}',
  registry_source text NOT NULL,
  registry_ref text,
  registry_checked_at timestamptz,
  status text NOT NULL DEFAULT 'active',
  successor_id uuid,
  valid_from date,
  valid_to date,
  verified_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT reference_entity_pkey PRIMARY KEY (id),
  CHECK (entity_type IN ('bank','credit_institution','foreign_bank_branch','gov_agency','enterprise')),
  CHECK (registry_source IN ('sbv_registry','swift_directory','tax_registry','pack','manual')),
  CHECK (status IN ('active','merged','dissolved')),
  CHECK (canonical_key ~ '^(SBV|BIC|MST):[0-9A-Z-]+$'),
  CHECK (sbv_code IS NULL OR sbv_code ~ '^[0-9]{8}$'),
  CHECK (swift_bic IS NULL OR swift_bic ~ '^[A-Z]{6}[A-Z0-9]{2}([A-Z0-9]{3})?$'),
  CHECK (tax_code IS NULL OR tax_code ~ '^[0-9]{10}(-[0-9]{3})?$'),
  CHECK (sbv_code IS NOT NULL OR swift_bic IS NOT NULL OR tax_code IS NOT NULL),
  CHECK (registry_source <> 'manual' OR verified_by IS NOT NULL),
  CHECK ((status = 'merged') = (successor_id IS NOT NULL) AND (successor_id IS NULL OR successor_id <> id)),
  CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from),
  UNIQUE (org_id, entity_type, canonical_key)
);
COMMENT ON TABLE acquire.reference_entity IS 'Danh mục thực thể chuẩn của tổ chức: ngân hàng, tổ chức tín dụng, chi nhánh ngân hàng nước ngoài, cơ quan, doanh nghiệp. Khoá là mã định danh gốc (mã ngân hàng do NHNN cấp, SWIFT/BIC, mã số thuế); tên, tên viết tắt và tên miền chính thức chỉ là thuộc tính để so khớp dự phòng (BR-169). Dùng chung cho mọi Data Space của tổ chức; nạp từ danh mục NHNN, danh bạ SWIFT, tra cứu mã số thuế hoặc gói ngành. pack.canonical_entity và context.semantic_entity mô tả loại thực thể, không giữ từng thực thể, nên không dùng lại được cho việc này. Use case: UC-14-05.';
COMMENT ON COLUMN acquire.reference_entity.entity_type IS 'bank, credit_institution, foreign_bank_branch, gov_agency, enterprise';
COMMENT ON COLUMN acquire.reference_entity.canonical_key IS 'SBV:<mã NHNN>, nếu không có thì BIC:<8 ký tự đầu>, rồi MST:<mã số thuế>; đặt một lần, không đổi';
COMMENT ON COLUMN acquire.reference_entity.legal_name IS 'Tên pháp lý, ví dụ Ngân hàng TMCP A';
COMMENT ON COLUMN acquire.reference_entity.short_names IS 'Tên viết tắt, tên thương mại, tên cũ đã duyệt';
COMMENT ON COLUMN acquire.reference_entity.sbv_code IS 'Mã ngân hàng do NHNN cấp, 8 chữ số';
COMMENT ON COLUMN acquire.reference_entity.swift_bic IS '8 hoặc 11 ký tự theo ISO 9362';
COMMENT ON COLUMN acquire.reference_entity.tax_code IS 'Mã số thuế 10 số, hoặc 13 số dạng 10-3 cho đơn vị phụ thuộc';
COMMENT ON COLUMN acquire.reference_entity.official_domains IS 'Tên miền chính thức, dùng khớp trang nguồn';
COMMENT ON COLUMN acquire.reference_entity.registry_source IS 'sbv_registry, swift_directory, tax_registry, pack, manual';
COMMENT ON COLUMN acquire.reference_entity.registry_ref IS 'Số văn bản, ngày trích danh mục gốc';
COMMENT ON COLUMN acquire.reference_entity.registry_checked_at IS 'Lần đối chiếu danh mục gốc gần nhất';
COMMENT ON COLUMN acquire.reference_entity.status IS 'active, merged, dissolved; đổi tên vẫn active, tên cũ vào short_names';
COMMENT ON COLUMN acquire.reference_entity.successor_id IS 'FK reference_entity; bắt buộc khi merged';
COMMENT ON COLUMN acquire.reference_entity.valid_from IS 'Ngày bắt đầu hiệu lực';
COMMENT ON COLUMN acquire.reference_entity.valid_to IS 'Ngày hết hiệu lực (sáp nhập, giải thể)';
COMMENT ON COLUMN acquire.reference_entity.verified_by IS 'logic → org.app_user; bắt buộc khi registry_source = manual';

CREATE TABLE acquire.consolidation_spec (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  name text NOT NULL,
  entity_type text NOT NULL,
  grain text NOT NULL,
  source_ids uuid[] NOT NULL,
  normalization jsonb NOT NULL DEFAULT '{}',
  source_priority jsonb NOT NULL DEFAULT '[]',
  aggregates jsonb NOT NULL DEFAULT '[]',
  summary_template text,
  allow_interpolation boolean NOT NULL DEFAULT false,
  target_dataset_id uuid,
  owner_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  last_edited_by uuid NOT NULL,
  last_edited_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT consolidation_spec_pkey PRIMARY KEY (id),
  UNIQUE (data_space_id, name),
  CHECK (status IN ('draft','active','retired')),
  CHECK (cardinality(source_ids) > 0),
  CHECK (status <> 'active' OR target_dataset_id IS NOT NULL)
);
COMMENT ON TABLE acquire.consolidation_spec IS 'Đặc tả hợp nhất cho một loại thực thể: nguồn, chuẩn hoá, ưu tiên nguồn, bảng tổng hợp, mẫu đoạn tóm tắt và dataset đích. Use case: UC-14-05.';
COMMENT ON COLUMN acquire.consolidation_spec.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN acquire.consolidation_spec.grain IS 'Khoá thực thể × kỳ, ví dụ bank × day';
COMMENT ON COLUMN acquire.consolidation_spec.source_ids IS 'logic → crawl_source';
COMMENT ON COLUMN acquire.consolidation_spec.normalization IS 'Đơn vị, tiền tệ, kỳ, múi giờ, bảng mã, văn bản';
COMMENT ON COLUMN acquire.consolidation_spec.source_priority IS 'Thứ tự ưu tiên nguồn khi lệch';
COMMENT ON COLUMN acquire.consolidation_spec.aggregates IS 'Bảng tổng hợp theo chiều: trung bình, trung vị, nhỏ nhất, lớn nhất, số nguồn theo ngày, tuần, tháng';
COMMENT ON COLUMN acquire.consolidation_spec.summary_template IS 'Mẫu đoạn tóm tắt sinh tự động có trích nguồn';
COMMENT ON COLUMN acquire.consolidation_spec.allow_interpolation IS 'Thiếu nguồn cho một kỳ thì đánh dấu thiếu, chỉ nội suy khi bật';
COMMENT ON COLUMN acquire.consolidation_spec.target_dataset_id IS 'logic → catalog.dataset (origin = ''consolidated'')';
COMMENT ON COLUMN acquire.consolidation_spec.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN acquire.consolidation_spec.status IS 'draft, active, retired';
COMMENT ON COLUMN acquire.consolidation_spec.last_edited_by IS 'logic → org.app_user; người sửa nội dung đặc tả gần nhất, trigger ghi; thành created_by của phiên bản dataset phát hành (BR-156)';
COMMENT ON COLUMN acquire.consolidation_spec.last_edited_at IS 'Lúc sửa nội dung đặc tả gần nhất';

CREATE TABLE acquire.consolidation_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  spec_id uuid NOT NULL,
  input_run_ids uuid[] NOT NULL,
  status text NOT NULL DEFAULT 'running',
  records_in integer NOT NULL DEFAULT 0,
  records_out integer NOT NULL DEFAULT 0,
  conflicts_opened integer NOT NULL DEFAULT 0,
  dataset_version_id uuid,
  claims_created integer NOT NULL DEFAULT 0,
  chunks_embedded integer NOT NULL DEFAULT 0,
  started_at timestamptz NOT NULL,
  finished_at timestamptz,
  spec_editor_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT consolidation_run_pkey PRIMARY KEY (id),
  CHECK (status IN ('running','published','failed')),
  CHECK (status <> 'published' OR dataset_version_id IS NOT NULL),
  CHECK (cardinality(input_run_ids) > 0)
);
COMMENT ON TABLE acquire.consolidation_run IS 'Một lượt hợp nhất: chuẩn hoá, nhận diện thực thể, khử trùng lặp, đối chiếu xung đột, phát hành dataset phiên bản mới; chỉ bảng tổng hợp, khẳng định và đoạn tóm tắt được nhúng vector (BR-154, BR-155). Use case: UC-14-05.';
COMMENT ON COLUMN acquire.consolidation_run.spec_id IS 'FK consolidation_spec';
COMMENT ON COLUMN acquire.consolidation_run.input_run_ids IS 'logic → crawl_run đã published';
COMMENT ON COLUMN acquire.consolidation_run.status IS 'running, published, failed';
COMMENT ON COLUMN acquire.consolidation_run.conflicts_opened IS 'Số vụ mở ở conflict.conflict (BR-155)';
COMMENT ON COLUMN acquire.consolidation_run.dataset_version_id IS 'logic → catalog.dataset_version phát hành';
COMMENT ON COLUMN acquire.consolidation_run.claims_created IS 'Số khẳng định ghi vào conflict.claim';
COMMENT ON COLUMN acquire.consolidation_run.chunks_embedded IS 'Số điểm vector Qdrant từ bảng tổng hợp, khẳng định, đoạn tóm tắt (BR-154)';
COMMENT ON COLUMN acquire.consolidation_run.spec_editor_id IS 'logic → org.app_user; chép consolidation_spec.last_edited_by lúc bắt đầu lượt, trigger ghi; Agent Hợp nhất ghi giá trị này vào catalog.dataset_version.created_by khi phát hành (BR-156)';

CREATE TABLE acquire.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE acquire.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON acquire.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE acquire.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON acquire.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA acquire TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON acquire.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON acquire.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON acquire.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX crawl_source_data_space_id_status_idx ON acquire.crawl_source (data_space_id, status);
CREATE INDEX crawl_source_last_run_at_idx ON acquire.crawl_source (last_run_at) WHERE status = 'active';
CREATE INDEX crawl_source_legal_review_due_at_idx ON acquire.crawl_source (legal_review_due_at) WHERE legal_status = 'approved';
CREATE UNIQUE INDEX crawl_schema_version_source_id_key ON acquire.crawl_schema_version (source_id) WHERE status = 'active';
CREATE INDEX crawl_run_source_id_started_at_idx ON acquire.crawl_run (source_id, started_at DESC);
CREATE UNIQUE INDEX crawl_run_source_id_key ON acquire.crawl_run (source_id) WHERE status IN ('queued','fetching','extracting');
CREATE INDEX crawl_page_run_id_idx ON acquire.crawl_page (run_id);
CREATE INDEX crawl_page_source_id_url_fetched_at_idx ON acquire.crawl_page (source_id, url, fetched_at DESC);
CREATE INDEX crawl_page_retain_until_idx ON acquire.crawl_page (retain_until);
CREATE INDEX extracted_record_run_id_status_idx ON acquire.extracted_record (run_id, status);
CREATE INDEX extracted_record_schema_version_id_idx ON acquire.extracted_record (schema_version_id) WHERE status <> 'superseded';
CREATE INDEX extracted_record_entity_key_period_idx ON acquire.extracted_record (entity_key, period);
CREATE INDEX review_decision_record_id_decided_at_idx ON acquire.review_decision (record_id, decided_at DESC);
CREATE INDEX review_decision_decided_by_decided_at_idx ON acquire.review_decision (decided_by, decided_at);
CREATE INDEX schema_drift_source_id_idx ON acquire.schema_drift (source_id) WHERE resolution IS NULL;
CREATE UNIQUE INDEX entity_link_source_id_entity_type_source_key_key ON acquire.entity_link (source_id, entity_type, source_key) WHERE status <> 'rejected';
CREATE INDEX entity_link_data_space_id_entity_type_canonical_key_idx ON acquire.entity_link (data_space_id, entity_type, canonical_key);
CREATE INDEX entity_link_data_space_id_idx ON acquire.entity_link (data_space_id) WHERE status = 'pending';
CREATE UNIQUE INDEX reference_entity_org_id_sbv_code_key ON acquire.reference_entity (org_id, sbv_code);
CREATE INDEX reference_entity_org_id_swift_bic_idx ON acquire.reference_entity (org_id, swift_bic);
CREATE INDEX reference_entity_org_id_tax_code_idx ON acquire.reference_entity (org_id, tax_code);
CREATE INDEX consolidation_run_spec_id_started_at_idx ON acquire.consolidation_run (spec_id, started_at DESC);
CREATE UNIQUE INDEX consolidation_run_spec_id_key ON acquire.consolidation_run (spec_id) WHERE status = 'running';

-- ═══ schema forecast ═══
CREATE TABLE forecast.forecast_job (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  question_id uuid,
  requested_by uuid NOT NULL,
  metric_code text NOT NULL,
  scope jsonb NOT NULL DEFAULT '{}',
  assumptions jsonb NOT NULL DEFAULT '[]',
  frequency text NOT NULL,
  horizon integer NOT NULL,
  cutoff_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'queued',
  eta_at timestamptz,
  notify_channels text[] NOT NULL DEFAULT '{}',
  progress jsonb NOT NULL DEFAULT '{}',
  model_version_id uuid,
  agent_run_id uuid,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT forecast_job_pkey PRIMARY KEY (id),
  CHECK (frequency IN ('day','week','month','quarter')),
  CHECK (horizon > 0),
  CHECK (status IN ('queued','preparing','waiting_human','training','backtesting','ready','failed','cancelled')),
  CHECK (status <> 'ready' OR model_version_id IS NOT NULL)
);
COMMENT ON TABLE forecast.forecast_job IS 'Việc dự báo bất đồng bộ tạo từ câu hỏi hoặc lịch; chạy như lượt agent nền, xong thì đẩy kết quả vào đúng hội thoại (BR-159). Use case: UC-15-01, UC-15-02.';
COMMENT ON COLUMN forecast.forecast_job.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN forecast.forecast_job.question_id IS 'logic → qa.question; null khi chạy theo lịch';
COMMENT ON COLUMN forecast.forecast_job.requested_by IS 'logic → org.app_user';
COMMENT ON COLUMN forecast.forecast_job.metric_code IS 'logic → context.metric';
COMMENT ON COLUMN forecast.forecast_job.scope IS 'Phạm vi theo chiều, ví dụ khối bán lẻ';
COMMENT ON COLUMN forecast.forecast_job.assumptions IS 'Giả định người hỏi đặt cho biến ngoại sinh, mảng {feature, from_period, change_kind, value} như scenario.assumptions; trả kèm kết quả (UC-15-01)';
COMMENT ON COLUMN forecast.forecast_job.frequency IS 'day, week, month, quarter';
COMMENT ON COLUMN forecast.forecast_job.horizon IS 'Số kỳ dự báo, ví dụ 3 tháng';
COMMENT ON COLUMN forecast.forecast_job.cutoff_at IS 'Thời điểm cắt; chỉ dùng dữ liệu ghi nhận trước đó (BR-157)';
COMMENT ON COLUMN forecast.forecast_job.status IS 'queued, preparing, waiting_human, training, backtesting, ready, failed, cancelled';
COMMENT ON COLUMN forecast.forecast_job.eta_at IS 'Thời gian dự kiến báo cho người hỏi';
COMMENT ON COLUMN forecast.forecast_job.notify_channels IS 'Kênh người dùng chọn để báo khi xong, ngoài thông báo trong ứng dụng (UC-15-01)';
COMMENT ON COLUMN forecast.forecast_job.progress IS 'Bước đang làm, hiện ở màn Đang làm gì';
COMMENT ON COLUMN forecast.forecast_job.model_version_id IS 'FK model_version dùng cho kết quả';
COMMENT ON COLUMN forecast.forecast_job.agent_run_id IS 'logic → agent.agent_run';

CREATE TABLE forecast.forecast_model (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  data_space_id uuid NOT NULL,
  metric_code text NOT NULL,
  scope jsonb NOT NULL DEFAULT '{}',
  frequency text NOT NULL,
  owner_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'active',
  current_version_id uuid,
  retrain_cron text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT forecast_model_pkey PRIMARY KEY (id),
  CHECK (frequency IN ('day','week','month','quarter')),
  CHECK (status IN ('active','degraded','retired')),
  UNIQUE (data_space_id, metric_code, frequency, scope)
);
COMMENT ON TABLE forecast.forecast_model IS 'Mô hình dự báo cho một chỉ số, phạm vi, tần suất; trỏ tới phiên bản đang phát hành. Use case: UC-15-01, UC-15-04, UC-15-05, UC-15-06.';
COMMENT ON COLUMN forecast.forecast_model.data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN forecast.forecast_model.metric_code IS 'logic → context.metric';
COMMENT ON COLUMN forecast.forecast_model.frequency IS 'day, week, month, quarter';
COMMENT ON COLUMN forecast.forecast_model.owner_id IS 'logic → org.app_user; người phụ trách chỉ số, duyệt phiên bản';
COMMENT ON COLUMN forecast.forecast_model.status IS 'active, degraded, retired; degraded theo BR-160';
COMMENT ON COLUMN forecast.forecast_model.current_version_id IS 'FK model_version đang phát hành';
COMMENT ON COLUMN forecast.forecast_model.retrain_cron IS 'Mặc định mỗi kỳ dữ liệu mới với chuỗi tháng, mỗi tuần với chuỗi ngày';

CREATE TABLE forecast.model_version (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_id uuid NOT NULL,
  version integer NOT NULL,
  algorithm text NOT NULL,
  ensemble_of jsonb,
  features jsonb NOT NULL DEFAULT '[]',
  params jsonb NOT NULL DEFAULT '{}',
  training_from date NOT NULL,
  training_to date NOT NULL,
  data_snapshot_refs jsonb NOT NULL DEFAULT '[]',
  n_points integer,
  n_exog smallint NOT NULL DEFAULT 0,
  pooled_series smallint NOT NULL DEFAULT 1,
  backtest_id uuid,
  status text NOT NULL DEFAULT 'draft',
  model_card jsonb NOT NULL DEFAULT '{}',
  artifact_key text,
  approved_by uuid,
  approved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT model_version_pkey PRIMARY KEY (id),
  UNIQUE (model_id, version),
  CHECK (algorithm IN ('naive','seasonal_naive','ets','theta','arima','sarimax','lightgbm','ensemble','formula_mc')),
  CHECK (status IN ('draft','pending_approval','published','degraded','retired','rejected')),
  CHECK (training_to > training_from),
  CHECK (algorithm <> 'ensemble' OR ensemble_of IS NOT NULL),
  CHECK (status NOT IN ('published','degraded') OR (approved_by IS NOT NULL AND approved_at IS NOT NULL AND backtest_id IS NOT NULL)),
  CHECK (approved_by IS NULL OR approved_by <> created_by),
  CHECK (n_points IS NULL OR n_points >= 24),
  CHECK (pooled_series >= 1),
  CHECK (algorithm <> 'lightgbm' OR coalesce(n_points, 0) >= 60 OR (coalesce(n_points, 0) >= 36 AND pooled_series >= 5)),
  CHECK (n_exog >= 0 AND n_exog <= least(8, coalesce(n_points, 0) / 12))
);
COMMENT ON TABLE forecast.model_version IS 'Phiên bản mô hình: thuật toán, biến và giả định, dữ liệu huấn luyện, thẻ mô hình; chỉ phát hành khi MASE < 1 trên backtest và người phụ trách chỉ số duyệt, người tạo không tự duyệt (BR-158). Use case: UC-15-02, UC-15-03, UC-15-04, UC-15-06.';
COMMENT ON COLUMN forecast.model_version.model_id IS 'FK forecast_model';
COMMENT ON COLUMN forecast.model_version.algorithm IS 'naive, seasonal_naive, ets, theta, arima, sarimax, lightgbm, ensemble, formula_mc (dự báo theo công thức và Monte Carlo, G8.9)';
COMMENT ON COLUMN forecast.model_version.ensemble_of IS 'Mô hình thành phần khi ensemble trung bình 3 mô hình đầu';
COMMENT ON COLUMN forecast.model_version.features IS 'Mảng {name, source, lag, transform, future_assumption}; source là chuỗi hợp nhất P14, skill.external_observation, lịch hoặc sự kiện';
COMMENT ON COLUMN forecast.model_version.data_snapshot_refs IS 'dataset_version, query_run dùng để huấn luyện';
COMMENT ON COLUMN forecast.model_version.n_points IS 'Số điểm chuỗi huấn luyện, từ 24; bắt buộc khi phát hành (BR-172)';
COMMENT ON COLUMN forecast.model_version.n_exog IS 'Số biến ngoại sinh; tối đa min(8, n_points / 12) (BR-172)';
COMMENT ON COLUMN forecast.model_version.pooled_series IS 'Số chuỗi cùng loại huấn luyện chung; LightGBM cần n_points ≥ 60, hoặc ≥ 36 khi pooled_series ≥ 5 (BR-172)';
COMMENT ON COLUMN forecast.model_version.backtest_id IS 'FK backtest_run';
COMMENT ON COLUMN forecast.model_version.status IS 'draft, pending_approval, published, degraded, retired, rejected';
COMMENT ON COLUMN forecast.model_version.model_card IS 'Mục tiêu, phạm vi, dữ liệu, biến và giả định, thuật toán, kết quả backtest, giới hạn đã biết (UC-15-04)';
COMMENT ON COLUMN forecast.model_version.artifact_key IS 'MinIO da-forecast-models';
COMMENT ON COLUMN forecast.model_version.approved_by IS 'logic → org.app_user';

CREATE TABLE forecast.backtest_run (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_version_id uuid NOT NULL,
  frequency text NOT NULL,
  cutoffs date[] NOT NULL,
  horizon integer NOT NULL,
  metrics jsonb NOT NULL,
  baseline_metrics jsonb NOT NULL,
  mase numeric(8,4) NOT NULL,
  in_sample_mase numeric(8,4),
  candidates jsonb NOT NULL DEFAULT '[]',
  started_at timestamptz NOT NULL,
  finished_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT backtest_run_pkey PRIMARY KEY (id),
  CHECK (frequency IN ('day','week','month','quarter')),
  CHECK (cardinality(cutoffs) >= CASE WHEN frequency IN ('day','week') THEN 20 ELSE 6 END),
  CHECK (mase >= 0),
  CHECK (in_sample_mase IS NULL OR in_sample_mase > 0),
  CHECK (horizon > 0)
);
COMMENT ON TABLE forecast.backtest_run IS 'Backtest cuốn chiếu của một phiên bản: tối thiểu 20 điểm cắt với chuỗi ngày, tuần và 6 điểm cắt với chuỗi tháng, quý (ADR-15), mỗi điểm dự báo đủ tầm, so với mô hình chuẩn seasonal naive. Use case: UC-15-03, UC-15-04.';
COMMENT ON COLUMN forecast.backtest_run.model_version_id IS 'FK model_version';
COMMENT ON COLUMN forecast.backtest_run.frequency IS 'day, week, month, quarter; chép từ forecast_model khi tạo; quyết định số điểm cắt tối thiểu (ADR-15)';
COMMENT ON COLUMN forecast.backtest_run.cutoffs IS 'Các điểm cắt';
COMMENT ON COLUMN forecast.backtest_run.metrics IS '{mase, smape, coverage80, coverage95, n_errors, interval_method} theo từng bước tầm; n_errors là số sai số dùng cho khoảng, kể cả sai số gộp từ chuỗi con (G8.5)';
COMMENT ON COLUMN forecast.backtest_run.baseline_metrics IS 'Cùng chỉ số của seasonal naive';
COMMENT ON COLUMN forecast.backtest_run.mase IS 'MASE tổng hợp trên mọi điểm cắt và tầm; phiên bản chỉ phát hành khi < 1 (BR-158)';
COMMENT ON COLUMN forecast.backtest_run.in_sample_mase IS 'MASE trong mẫu của mô hình được chọn; mase / in_sample_mase > 2 là quá khớp, không phát hành (BR-172). CHECK (in_sample_mase IS NULL OR in_sample_mase > 0)';
COMMENT ON COLUMN forecast.backtest_run.candidates IS 'Kết quả mọi mô hình ứng viên; mô hình MASE ≥ 1 bị loại';

CREATE TABLE forecast.prediction (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_version_id uuid NOT NULL,
  job_id uuid,
  scenario_id uuid,
  cutoff_at timestamptz NOT NULL,
  period date NOT NULL,
  point numeric NOT NULL,
  lo80 numeric NOT NULL,
  hi80 numeric NOT NULL,
  lo95 numeric NOT NULL,
  hi95 numeric NOT NULL,
  interval_method text NOT NULL DEFAULT 'conformal',
  exog_uncertainty text NOT NULL DEFAULT 'none',
  contributions jsonb NOT NULL DEFAULT '{}',
  is_experimental boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT prediction_pkey PRIMARY KEY (id),
  CHECK (interval_method IN ('conformal','conformal_pooled','parametric','monte_carlo')),
  CHECK (lo95 <= lo80 AND lo80 <= point AND point <= hi80 AND hi80 <= hi95),
  UNIQUE NULLS NOT DISTINCT (model_version_id, scenario_id, cutoff_at, period),
  CHECK (exog_uncertainty IN ('none','simulated','scenario_fixed')),
  CHECK ((scenario_id IS NOT NULL) = (exog_uncertainty = 'scenario_fixed'))
);
COMMENT ON TABLE forecast.prediction IS 'Giá trị dự báo một kỳ kèm khoảng 80% và 95% và đóng góp biến; kết quả của mô hình chưa duyệt gắn is_experimental, không dùng cho báo cáo, cảnh báo (BR-158). Use case: UC-15-01, UC-15-05.';
COMMENT ON COLUMN forecast.prediction.model_version_id IS 'FK model_version';
COMMENT ON COLUMN forecast.prediction.job_id IS 'FK forecast_job';
COMMENT ON COLUMN forecast.prediction.scenario_id IS 'FK scenario; null là kịch bản gốc';
COMMENT ON COLUMN forecast.prediction.period IS 'Ngày đầu kỳ dự báo';
COMMENT ON COLUMN forecast.prediction.lo80 IS 'Cận dưới khoảng 80%, cách tính theo interval_method';
COMMENT ON COLUMN forecast.prediction.lo95 IS 'Cận dưới khoảng 95%, cách tính theo interval_method';
COMMENT ON COLUMN forecast.prediction.interval_method IS 'conformal (từ 20 sai số của chính chuỗi ở bước tầm này), conformal_pooled (gộp sai số chuẩn hoá của các chuỗi con cùng chỉ số), parametric (khoảng tham số, hiện nhãn “khoảng tham số”) (G8.5, ADR-15), monte_carlo (phân vị của các lần mô phỏng, dự báo theo công thức G8.9, ADR-44)';
COMMENT ON COLUMN forecast.prediction.exog_uncertainty IS 'none, simulated, scenario_fixed; dự báo gốc có biến ngoại sinh phải là simulated, kịch bản là scenario_fixed (BR-173)';
COMMENT ON COLUMN forecast.prediction.contributions IS 'Đóng góp từng biến: hệ số SARIMAX hoặc SHAP';
COMMENT ON COLUMN forecast.prediction.is_experimental IS 'Nhãn “thử nghiệm, chưa duyệt” (UC-15-01)';

CREATE TABLE forecast.scenario (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_id uuid NOT NULL,
  name text NOT NULL,
  assumptions jsonb NOT NULL DEFAULT '[]',
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT scenario_pkey PRIMARY KEY (id),
  UNIQUE (model_id, created_by, name)
);
COMMENT ON TABLE forecast.scenario IS 'Kịch bản giả định giá trị tương lai của biến ngoại sinh, ví dụ lãi suất điều hành +0,5 điểm từ tháng 12. Use case: UC-15-05.';
COMMENT ON COLUMN forecast.scenario.model_id IS 'FK forecast_model';
COMMENT ON COLUMN forecast.scenario.assumptions IS 'Mảng {feature, from_period, change_kind, value}';

CREATE TABLE forecast.accuracy_log (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_version_id uuid NOT NULL,
  period date NOT NULL,
  actual numeric NOT NULL,
  point numeric NOT NULL,
  abs_scaled_error numeric NOT NULL,
  in80 boolean NOT NULL,
  in95 boolean NOT NULL,
  rolling_mase numeric,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT accuracy_log_pkey PRIMARY KEY (id),
  UNIQUE (model_version_id, period),
  CHECK (abs_scaled_error >= 0)
);
COMMENT ON TABLE forecast.accuracy_log IS 'Sai số khi kỳ đã dự báo có số thực tế; cơ sở phát hiện suy giảm khi MASE cuốn chiếu vượt 1,2 lần mức backtest hoặc hai kỳ liền nằm ngoài khoảng 95% (BR-160). Use case: UC-15-06.';
COMMENT ON COLUMN forecast.accuracy_log.model_version_id IS 'FK model_version';
COMMENT ON COLUMN forecast.accuracy_log.actual IS 'Số thực tế';
COMMENT ON COLUMN forecast.accuracy_log.point IS 'Số đã dự báo';
COMMENT ON COLUMN forecast.accuracy_log.abs_scaled_error IS 'Sai số tuyệt đối chia sai số seasonal naive trong mẫu';
COMMENT ON COLUMN forecast.accuracy_log.rolling_mase IS 'MASE cuốn chiếu 6 kỳ';

CREATE TABLE forecast.formula_model (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  model_version_id uuid NOT NULL,
  metric_version_id uuid NOT NULL,
  product_code text NOT NULL,
  formula jsonb NOT NULL,
  window_rule jsonb NOT NULL DEFAULT '{}',
  input_series jsonb NOT NULL DEFAULT '{}',
  nowcast_method text NOT NULL DEFAULT 'bridge_regression',
  fund_model jsonb NOT NULL DEFAULT '{}',
  n_draws integer NOT NULL DEFAULT 10000,
  miss_abs_threshold numeric NOT NULL DEFAULT 300,
  rounding text NOT NULL DEFAULT 'integer',
  owner_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT formula_model_pkey PRIMARY KEY (id),
  UNIQUE (model_version_id),
  CHECK (nowcast_method IN ('bridge_regression','published_only')),
  CHECK (n_draws >= 10000),
  CHECK (miss_abs_threshold > 0),
  CHECK (rounding IN ('integer','ten')),
  CHECK (product_code ~ '^[a-z0-9_]+$'),
  CHECK (jsonb_typeof(formula) = 'object')
);
COMMENT ON TABLE forecast.formula_model IS 'Mô hình dự báo theo công thức cho một chỉ số điều hành của một mặt hàng, ví dụ giá trần xăng E5RON92: trỏ phiên bản công thức chỉ số đã chứng nhận, cách nowcast giá thế giới, mô hình quyết định Quỹ bình ổn và số lần mô phỏng; gắn một-một với một forecast.model_version có algorithm = formula_mc (BR-183, ADR-44). Use case: UC-15-07, UC-15-08.';
COMMENT ON COLUMN forecast.formula_model.model_version_id IS 'FK model_version; phiên bản có algorithm = ''formula_mc''';
COMMENT ON COLUMN forecast.formula_model.metric_version_id IS 'logic → context.metric_version; công thức giá cơ sở đã chứng nhận (expression, legal_basis)';
COMMENT ON COLUMN forecast.formula_model.product_code IS 'Mặt hàng: e5ron92, ron95iii, do005s, dau_hoa, mazut180';
COMMENT ON COLUMN forecast.formula_model.formula IS 'Cây biểu thức biên dịch từ metric_version.expression: mảng hạng {code, op, inputs}; chỉ tham chiếu formula_component.code và hai biến đầu vào world_avg, fx_rate';
COMMENT ON COLUMN forecast.formula_model.window_rule IS 'Cách lấy kỳ bình quân giá thế giới theo văn bản, ví dụ {from: previous_event, to: day_before_event, days: trading}; người phụ trách chứng nhận cùng công thức';
COMMENT ON COLUMN forecast.formula_model.input_series IS 'Chuỗi công khai cho nowcast {world_proxy: [series_code], fx: series_code, published_world_avg: trường của dataset giá xăng dầu}; không dùng Platts, MOPS khi chưa có giấy phép (ADR-45)';
COMMENT ON COLUMN forecast.formula_model.nowcast_method IS 'bridge_regression (hồi quy cầu nối từ chuỗi công khai về giá thế giới bình quân Bộ Công Thương công bố), published_only (chỉ dùng số đã công bố, không nowcast)';
COMMENT ON COLUMN forecast.formula_model.fund_model IS 'Mô hình xác suất quyết định Quỹ: {method, contribute_levels, use_levels, coefficients, trained_periods, log_score, baseline_log_score} (G8.9)';
COMMENT ON COLUMN forecast.formula_model.n_draws IS 'Số lần mô phỏng Monte Carlo mỗi lần chạy (BR-184)';
COMMENT ON COLUMN forecast.formula_model.miss_abs_threshold IS 'Ngưỡng sai tuyệt đối, đ/lít, để tạo mục Error Book forecast_miss (BR-186)';
COMMENT ON COLUMN forecast.formula_model.rounding IS 'Cách làm tròn giá công bố: integer (đồng), ten (bội 10 đồng)';
COMMENT ON COLUMN forecast.formula_model.owner_id IS 'logic → org.app_user; người phụ trách data product, chứng nhận tham số';

CREATE TABLE forecast.formula_component (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  code text NOT NULL,
  product_code text NOT NULL,
  value numeric NOT NULL,
  unit text NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_to timestamptz,
  legal_doc_number text NOT NULL,
  legal_doc_url text NOT NULL,
  document_id uuid,
  extracted_record_id uuid,
  status text NOT NULL DEFAULT 'draft',
  certified_by uuid,
  certified_at timestamptz,
  hitl_request_id uuid,
  note text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT formula_component_pkey PRIMARY KEY (id),
  CHECK (unit IN ('percent','vnd_per_litre','vnd_per_kg','usd_per_bbl','ratio')),
  CHECK (status IN ('draft','pending_review','certified','superseded','rejected')),
  CHECK (valid_to IS NULL OR valid_to > valid_from),
  CHECK (status NOT IN ('certified','superseded') OR (certified_by IS NOT NULL AND certified_at IS NOT NULL)),
  CHECK (certified_by IS NULL OR certified_by <> created_by),
  CHECK (legal_doc_url ~ '^https?://'),
  CHECK (length(btrim(legal_doc_number)) > 0),
  CHECK (unit <> 'percent' OR (value >= 0 AND value <= 100))
);
COMMENT ON TABLE forecast.formula_component IS 'Tham số của công thức giá cơ sở theo ngày hiệu lực: thuế nhập khẩu bình quân gia quyền, thuế tiêu thụ đặc biệt, thuế bảo vệ môi trường, thuế giá trị gia tăng, chi phí định mức, lợi nhuận định mức và các hệ số quy đổi. Mỗi giá trị lấy từ văn bản gốc, có số hiệu và link, do người khác người nhập chứng nhận; mô hình ngôn ngữ không đặt giá trị (BR-182). Use case: UC-15-07.';
COMMENT ON COLUMN forecast.formula_component.code IS 'Mã tham số, ví dụ import_tax_rate, excise_tax_rate, env_tax, vat_rate, cost_norm, profit_norm, litre_per_bbl, blend_ratio';
COMMENT ON COLUMN forecast.formula_component.product_code IS 'Mặt hàng như formula_model.product_code; ''*'' khi áp cho mọi mặt hàng (ví dụ vat_rate)';
COMMENT ON COLUMN forecast.formula_component.value IS 'Giá trị theo unit, đúng như văn bản';
COMMENT ON COLUMN forecast.formula_component.unit IS 'percent, vnd_per_litre, vnd_per_kg, usd_per_bbl, ratio';
COMMENT ON COLUMN forecast.formula_component.valid_from IS 'Thời điểm hiệu lực theo văn bản';
COMMENT ON COLUMN forecast.formula_component.valid_to IS 'Thời điểm hết hiệu lực; đặt khi có giá trị mới hoặc khi văn bản ghi thời hạn (ví dụ mức gia hạn đến hết một ngày)';
COMMENT ON COLUMN forecast.formula_component.legal_doc_number IS 'Số hiệu văn bản, ví dụ 9017/BTC-QLG, 9149/BTC-QLG, 34/2026/NQ-CP, 66/2025/QH15';
COMMENT ON COLUMN forecast.formula_component.legal_doc_url IS 'Link văn bản gốc';
COMMENT ON COLUMN forecast.formula_component.document_id IS 'logic → document.document; bản lưu trong kho tài liệu, dùng kiểm độ tươi và trích dẫn';
COMMENT ON COLUMN forecast.formula_component.extracted_record_id IS 'logic → acquire.extracted_record khi giá trị được trích từ trang nguồn';
COMMENT ON COLUMN forecast.formula_component.status IS 'draft, pending_review, certified, superseded, rejected';
COMMENT ON COLUMN forecast.formula_component.certified_by IS 'logic → org.app_user';
COMMENT ON COLUMN forecast.formula_component.hitl_request_id IS 'logic → inbox.hitl_request kind formula_component';
COMMENT ON COLUMN forecast.formula_component.note IS 'Ví dụ “mức gia hạn theo Nghị quyết 34/2026/NQ-CP”';

CREATE TABLE forecast.ledger_entry (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  forecast_model_id uuid NOT NULL,
  model_version_id uuid NOT NULL,
  prediction_id uuid NOT NULL,
  job_id uuid,
  period date NOT NULL,
  scope jsonb NOT NULL DEFAULT '{}',
  issued_at timestamptz NOT NULL,
  issued_via text NOT NULL,
  event_id uuid,
  event_at timestamptz,
  baseline_value numeric NOT NULL,
  point numeric NOT NULL,
  quantiles jsonb NOT NULL,
  prob_up numeric(5,4),
  fund_probs jsonb NOT NULL DEFAULT '{}',
  contributions jsonb NOT NULL DEFAULT '{}',
  status text NOT NULL DEFAULT 'open',
  actual numeric,
  actual_source_ref jsonb,
  actual_components jsonb,
  abs_error numeric,
  crps numeric,
  pit numeric(5,4),
  in80 boolean,
  in95 boolean,
  miss boolean,
  miss_attribution jsonb,
  error_book_entry_id uuid,
  accuracy_log_id uuid,
  scored_at timestamptz,
  void_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT ledger_entry_pkey PRIMARY KEY (id),
  CHECK (issued_via IN ('bulletin','answer','monitor','manual')),
  CHECK (status IN ('open','scored','void')),
  CHECK (status <> 'scored' OR (actual IS NOT NULL AND abs_error IS NOT NULL AND in80 IS NOT NULL AND in95 IS NOT NULL AND miss IS NOT NULL AND scored_at IS NOT NULL)),
  CHECK (status <> 'void' OR (actual IS NULL AND void_reason IS NOT NULL AND length(btrim(void_reason)) > 0)),
  CHECK (event_at IS NULL OR issued_at < event_at),
  CHECK (abs_error IS NULL OR abs_error >= 0),
  CHECK (crps IS NULL OR crps >= 0),
  CHECK (prob_up IS NULL OR (prob_up >= 0 AND prob_up <= 1)),
  CHECK (pit IS NULL OR (pit >= 0 AND pit <= 1)),
  CHECK (in80 IS NOT TRUE OR in95 IS TRUE),
  CHECK (in95 IS NOT FALSE OR miss IS TRUE),
  UNIQUE (prediction_id, issued_via)
);
COMMENT ON TABLE forecast.ledger_entry IS 'Sổ dự báo: mỗi dự báo đã phát hành (bản tin, câu trả lời, theo dõi) cho một kỳ của một phạm vi là một dòng ghi trước kỳ; phần dự báo bất biến, phần chấm điểm điền khi có số công bố; kỳ sai vẫn giữ và hiện trên sổ (BR-185, BR-186). Use case: UC-15-07, UC-15-08, UC-08-08.';
COMMENT ON COLUMN forecast.ledger_entry.forecast_model_id IS 'FK forecast_model';
COMMENT ON COLUMN forecast.ledger_entry.model_version_id IS 'FK model_version';
COMMENT ON COLUMN forecast.ledger_entry.prediction_id IS 'FK prediction; dự báo gốc (scenario_id null)';
COMMENT ON COLUMN forecast.ledger_entry.job_id IS 'FK forecast_job';
COMMENT ON COLUMN forecast.ledger_entry.period IS 'Kỳ được dự báo, ví dụ 2026-07-09 (kỳ điều hành)';
COMMENT ON COLUMN forecast.ledger_entry.scope IS 'Ví dụ {product_code: e5ron92}';
COMMENT ON COLUMN forecast.ledger_entry.issued_at IS 'Thời điểm phát hành, ví dụ 2026-07-08 20:00 +07';
COMMENT ON COLUMN forecast.ledger_entry.issued_via IS 'bulletin, answer, monitor, manual';
COMMENT ON COLUMN forecast.ledger_entry.event_id IS 'logic → monitor.external_event';
COMMENT ON COLUMN forecast.ledger_entry.event_at IS 'Thời điểm kỳ áp dụng dự kiến lúc phát hành';
COMMENT ON COLUMN forecast.ledger_entry.baseline_value IS 'Giá kỳ trước, ví dụ 19.730 đ/lít kỳ 02/7/2026';
COMMENT ON COLUMN forecast.ledger_entry.point IS 'Trung vị phân phối';
COMMENT ON COLUMN forecast.ledger_entry.quantiles IS '{p02_5, p10, p25, p50, p75, p90, p97_5}';
COMMENT ON COLUMN forecast.ledger_entry.prob_up IS 'Xác suất giá kỳ tới cao hơn baseline_value';
COMMENT ON COLUMN forecast.ledger_entry.fund_probs IS 'Xác suất các mức trích lập và chi Quỹ, ví dụ {contribute: {"0": 0.12, "200": 0.70, "300": 0.18}, use: {"0": 0.92, "300": 0.08}}';
COMMENT ON COLUMN forecast.ledger_entry.contributions IS 'Phân rã {world, fx, tax, fund, proxy_error}, mỗi phần {vnd_per_litre, source_refs} (BR-184)';
COMMENT ON COLUMN forecast.ledger_entry.status IS 'open, scored, void';
COMMENT ON COLUMN forecast.ledger_entry.actual IS 'Giá công bố của kỳ';
COMMENT ON COLUMN forecast.ledger_entry.actual_source_ref IS '{extracted_record_id, dataset_version_id, url} của bản tin công bố';
COMMENT ON COLUMN forecast.ledger_entry.actual_components IS 'Thành phần công bố: world_avg, fund_contribute, fund_use';
COMMENT ON COLUMN forecast.ledger_entry.abs_error IS 'abs(actual − point), đ/lít';
COMMENT ON COLUMN forecast.ledger_entry.crps IS 'CRPS tính trên mẫu mô phỏng đã lưu';
COMMENT ON COLUMN forecast.ledger_entry.pit IS 'Phân vị của actual trong phân phối dự báo';
COMMENT ON COLUMN forecast.ledger_entry.miss IS 'Ngoài khoảng 95% hoặc abs_error vượt ngưỡng của mô hình (BR-186)';
COMMENT ON COLUMN forecast.ledger_entry.miss_attribution IS 'Phần lệch nhiều nhất, ví dụ {component: fund, predicted_mode: 200, actual: 0}';
COMMENT ON COLUMN forecast.ledger_entry.error_book_entry_id IS 'logic → eval.error_book_entry (source_kind forecast_miss, UC-07-14); Forecast service ghi khi nhận eval.error_book.opened của mục Eval service tạo từ sự kiện forecast.ledger.missed (BR-186)';
COMMENT ON COLUMN forecast.ledger_entry.accuracy_log_id IS 'FK accuracy_log';
COMMENT ON COLUMN forecast.ledger_entry.void_reason IS 'Chỉ khi kỳ bị huỷ hoặc không diễn ra, không dùng khi dự báo sai';

CREATE TABLE forecast.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE forecast.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON forecast.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE forecast.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON forecast.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT USAGE ON SCHEMA forecast TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON forecast.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON forecast.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON forecast.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX forecast_job_question_id_idx ON forecast.forecast_job (question_id);
CREATE INDEX forecast_job_status_eta_at_idx ON forecast.forecast_job (status, eta_at) WHERE status NOT IN ('ready','failed','cancelled');
CREATE INDEX forecast_job_data_space_id_metric_code_created_at_idx ON forecast.forecast_job (data_space_id, metric_code, created_at DESC);
CREATE UNIQUE INDEX model_version_model_id_key ON forecast.model_version (model_id) WHERE status IN ('published','degraded');
CREATE INDEX backtest_run_model_version_id_idx ON forecast.backtest_run (model_version_id);
CREATE INDEX prediction_job_id_idx ON forecast.prediction (job_id);
CREATE INDEX prediction_model_version_id_cutoff_at_idx ON forecast.prediction (model_version_id, cutoff_at DESC);
CREATE INDEX accuracy_log_model_version_id_period_idx ON forecast.accuracy_log (model_version_id, period DESC);
CREATE INDEX formula_model_metric_version_id_idx ON forecast.formula_model (metric_version_id);
CREATE INDEX formula_model_product_code_idx ON forecast.formula_model (product_code);
CREATE UNIQUE INDEX formula_component_org_id_code_product_code_valid_from_key ON forecast.formula_component (org_id, code, product_code, valid_from) WHERE status = 'certified';
CREATE INDEX formula_component_code_product_code_valid_from_idx ON forecast.formula_component (code, product_code, valid_from DESC);
CREATE INDEX ledger_entry_forecast_model_id_period_idx ON forecast.ledger_entry (forecast_model_id, period DESC);
CREATE INDEX ledger_entry_status_period_idx ON forecast.ledger_entry (status, period) WHERE status = 'open';
CREATE INDEX ledger_entry_event_id_idx ON forecast.ledger_entry (event_id);

-- ═══ schema exec ═══
CREATE TABLE exec.vault (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'active',
  aead_alg text NOT NULL DEFAULT 'xchacha20poly1305',
  box_public_key bytea NOT NULL,
  box_private_key_ct bytea NOT NULL,
  transit_key_name text NOT NULL,
  transit_key_version integer NOT NULL DEFAULT 1,
  exit_policy text NOT NULL DEFAULT 'seal',
  contract_ref text,
  sealed_read_until date,
  recovery_checked_at timestamptz,
  sealed_at timestamptz,
  shredded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT vault_pkey PRIMARY KEY (id),
  CHECK (status IN ('active','sealed','shredded')),
  CHECK (aead_alg IN ('xchacha20poly1305')),
  CHECK (exit_policy IN ('seal','selective_handover','shred')),
  CHECK (octet_length(box_public_key) = 32),
  CHECK (status = 'shredded' OR octet_length(box_private_key_ct) = 72),
  CHECK (transit_key_version > 0),
  CHECK (status <> 'sealed' OR sealed_at IS NOT NULL),
  CHECK (status <> 'shredded' OR shredded_at IS NOT NULL),
  UNIQUE (org_id, owner_id),
  UNIQUE (transit_key_name)
);
COMMENT ON TABLE exec.vault IS 'Kho riêng của một lãnh đạo: khoá công khai X25519 để workflow niêm phong kết quả gửi chủ kho, khoá riêng đã bọc bằng khoá kho (VMK), tên khoá điều kiện trong OpenBao, chính sách rời vị trí. Máy chủ không giữ VMK hay bản rõ (BR-189, ADR-46). Use case: UC-16-01, UC-16-06.';
COMMENT ON COLUMN exec.vault.owner_id IS 'logic → org.app_user; chủ kho, mỗi người một kho';
COMMENT ON COLUMN exec.vault.status IS 'active, sealed, shredded';
COMMENT ON COLUMN exec.vault.aead_alg IS 'Thuật toán AEAD của VMK và DEK';
COMMENT ON COLUMN exec.vault.box_public_key IS 'Khoá công khai X25519, 32 byte';
COMMENT ON COLUMN exec.vault.box_private_key_ct IS 'Khoá riêng X25519 mã hoá bằng VMK trên thiết bị; ghi rỗng khi huỷ khoá';
COMMENT ON COLUMN exec.vault.transit_key_name IS 'Khoá điều kiện trong OpenBao Transit, dạng exec-cond-{org_id}-{owner_id}; RSA-4096 riêng mỗi kho';
COMMENT ON COLUMN exec.vault.transit_key_version IS 'Phiên bản khoá Transit hiện hành';
COMMENT ON COLUMN exec.vault.exit_policy IS 'seal, selective_handover, shred; theo hợp đồng (BR-195)';
COMMENT ON COLUMN exec.vault.contract_ref IS 'Số hợp đồng hoặc phụ lục quy định exit_policy';
COMMENT ON COLUMN exec.vault.sealed_read_until IS 'Hạn chủ kho còn mở kho đã niêm phong; quá hạn thì huỷ khoá';
COMMENT ON COLUMN exec.vault.recovery_checked_at IS 'Lần gần nhất chủ kho mở thử bằng mã khôi phục giấy (R-34)';

CREATE TABLE exec.vault_key_wrap (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  vault_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  kind text NOT NULL,
  credential_id bytea,
  label text NOT NULL,
  kdf text NOT NULL,
  kdf_salt bytea NOT NULL,
  wrapped_vmk bytea NOT NULL,
  last_used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT vault_key_wrap_pkey PRIMARY KEY (id),
  CHECK (kind IN ('passkey_prf','hardware_key','recovery_code')),
  CHECK ((kind = 'recovery_code') = (credential_id IS NULL)),
  CHECK (kdf IN ('hkdf_sha256','argon2id')),
  CHECK ((kind = 'recovery_code') = (kdf = 'argon2id')),
  CHECK (octet_length(kdf_salt) = 32),
  CHECK (octet_length(wrapped_vmk) = 72)
);
COMMENT ON TABLE exec.vault_key_wrap IS 'Một cách mở kho: VMK bọc bằng khoá dẫn xuất từ đầu ra WebAuthn PRF của passkey, hmac-secret của khoá phần cứng, hoặc mã khôi phục giấy 24 từ qua Argon2id. Kho cần ít nhất 2 khoá bọc còn hiệu lực, một khoá ngoại tuyến (BR-189). Use case: UC-16-01, UC-16-06.';
COMMENT ON COLUMN exec.vault_key_wrap.vault_id IS 'FK vault';
COMMENT ON COLUMN exec.vault_key_wrap.owner_id IS 'logic → org.app_user; bằng vault.owner_id';
COMMENT ON COLUMN exec.vault_key_wrap.kind IS 'passkey_prf, hardware_key, recovery_code';
COMMENT ON COLUMN exec.vault_key_wrap.credential_id IS 'Mã credential WebAuthn; null với recovery_code';
COMMENT ON COLUMN exec.vault_key_wrap.label IS 'Tên chủ kho đặt, ví dụ “iPhone”, “YubiKey két sắt”, “Mã giấy 10/2026”';
COMMENT ON COLUMN exec.vault_key_wrap.kdf IS 'hkdf_sha256 với PRF và hmac-secret; argon2id với mã giấy';
COMMENT ON COLUMN exec.vault_key_wrap.kdf_salt IS 'Muối 32 byte gửi vào PRF hoặc KDF';
COMMENT ON COLUMN exec.vault_key_wrap.wrapped_vmk IS 'VMK mã hoá AEAD bằng khoá dẫn xuất, 72 byte';

CREATE TABLE exec.thesis (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  vault_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  content_ct bytea NOT NULL,
  wrapped_dek bytea NOT NULL,
  content_version smallint NOT NULL DEFAULT 1,
  cond_ct bytea NOT NULL,
  cond_key_version integer NOT NULL,
  due_at timestamptz NOT NULL,
  committed_at timestamptz NOT NULL DEFAULT now(),
  status text NOT NULL DEFAULT 'open',
  evidence_state text NOT NULL DEFAULT 'pending',
  evidence_refreshed_at timestamptz,
  supersedes_id uuid,
  withdrawn_at timestamptz,
  workflow_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT thesis_pkey PRIMARY KEY (id),
  CHECK (status IN ('open','invalid_condition','scoring','scored','unresolvable','withdrawn')),
  CHECK (evidence_state IN ('pending','two_sided','one_sided','insufficient')),
  CHECK (due_at >= committed_at + interval '1 day'),
  CHECK (content_version > 0),
  CHECK (octet_length(content_ct) BETWEEN 41 AND 65536),
  CHECK (octet_length(wrapped_dek) = 72),
  CHECK (octet_length(cond_ct) = 512),
  CHECK (cond_key_version > 0),
  CHECK ((status = 'withdrawn') = (withdrawn_at IS NOT NULL)),
  CHECK (withdrawn_at IS NULL OR withdrawn_at < due_at),
  CHECK (supersedes_id IS NULL OR supersedes_id <> id)
);
COMMENT ON TABLE exec.thesis IS 'Luận điểm: nội dung (nhận định, lý do, mức tự tin, thẻ, bản sao điều kiện) là bản mã AEAD bằng DEK riêng; điều kiện chấm là bản mã RSA-OAEP bằng khoá Transit của kho; due_at và status bản rõ để workflow lập lịch. Nội dung bất biến sau khi ghi (BR-188). Use case: UC-16-01, UC-16-03, UC-16-04, UC-16-05.';
COMMENT ON COLUMN exec.thesis.vault_id IS 'FK vault';
COMMENT ON COLUMN exec.thesis.owner_id IS 'logic → org.app_user; bằng vault.owner_id';
COMMENT ON COLUMN exec.thesis.content_ct IS 'Nonce và bản mã XChaCha20-Poly1305 của JSON {statement, rationale, confidence, tags, condition}; dữ liệu kèm (AAD) là id, owner_id, content_version';
COMMENT ON COLUMN exec.thesis.wrapped_dek IS 'DEK 256 bit bọc bằng VMK, 72 byte';
COMMENT ON COLUMN exec.thesis.content_version IS 'Phiên bản định dạng bản rõ';
COMMENT ON COLUMN exec.thesis.cond_ct IS 'RSA-OAEP SHA-256 của JSON {metric_ref, ref_kind, scope, period, comparator, threshold, threshold_hi, unit}; chỉ svc_exec_worker giải mã qua OpenBao (BR-189)';
COMMENT ON COLUMN exec.thesis.cond_key_version IS 'Phiên bản khoá Transit đã dùng';
COMMENT ON COLUMN exec.thesis.due_at IS 'Thời điểm chấm, làm tròn tới giờ (R-35); ví dụ 2026-10-22 18:00 với kỳ điều hành 22/10/2026';
COMMENT ON COLUMN exec.thesis.committed_at IS 'Mốc ghi, dùng xếp hiệu chỉnh theo thời gian';
COMMENT ON COLUMN exec.thesis.status IS 'open, invalid_condition, scoring, scored, unresolvable, withdrawn';
COMMENT ON COLUMN exec.thesis.evidence_state IS 'pending, two_sided, one_sided, insufficient; trigger của thesis_evidence cập nhật';
COMMENT ON COLUMN exec.thesis.supersedes_id IS 'FK thesis; luận điểm mà luận điểm này thay';
COMMENT ON COLUMN exec.thesis.workflow_id IS 'Mã ExecThesisWorkflow trên Temporal';

CREATE TABLE exec.thesis_evidence (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  thesis_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  batch_no integer NOT NULL,
  side text NOT NULL,
  item_kind text NOT NULL,
  strength text,
  freshness_ok boolean NOT NULL,
  sealed_ct bytea NOT NULL,
  agent_run_id uuid NOT NULL,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT thesis_evidence_pkey PRIMARY KEY (id),
  CHECK (side IN ('support','against')),
  CHECK (item_kind IN ('evidence','none_found','insufficient')),
  CHECK (strength IS NULL OR strength IN ('weak','moderate','strong')),
  CHECK ((item_kind = 'evidence') = (strength IS NOT NULL)),
  CHECK (item_kind <> 'evidence' OR freshness_ok),
  CHECK (batch_no > 0),
  CHECK (octet_length(sealed_ct) BETWEEN 49 AND 65536)
);
COMMENT ON TABLE exec.thesis_evidence IS 'Một mục trong lô bằng chứng do Agent Bằng chứng tìm mù (BR-190): phía, loại, độ mạnh bản rõ; nội dung (tóm tắt, số, query_run_id, nguồn, kỳ, độ mới) niêm phong bằng box_public_key của kho nên chỉ chủ kho mở được. Lô mới không xoá lô cũ. Use case: UC-16-03.';
COMMENT ON COLUMN exec.thesis_evidence.thesis_id IS 'FK thesis';
COMMENT ON COLUMN exec.thesis_evidence.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN exec.thesis_evidence.batch_no IS 'Lô thứ mấy của luận điểm; màn hiện lô lớn nhất, so với lô trước';
COMMENT ON COLUMN exec.thesis_evidence.side IS 'support, against (so với điều kiện đúng)';
COMMENT ON COLUMN exec.thesis_evidence.item_kind IS 'evidence, none_found, insufficient';
COMMENT ON COLUMN exec.thesis_evidence.strength IS 'weak, moderate, strong; chỉ có với evidence (luật ở tab 5 G10.3)';
COMMENT ON COLUMN exec.thesis_evidence.freshness_ok IS 'Nguồn còn trong hạn độ mới lúc tìm';
COMMENT ON COLUMN exec.thesis_evidence.sealed_ct IS 'Hộp niêm phong X25519 cho chủ kho';
COMMENT ON COLUMN exec.thesis_evidence.agent_run_id IS 'logic → agent.agent_run của Agent Bằng chứng';

CREATE TABLE exec.thesis_score (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  thesis_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  kind text NOT NULL,
  outcome text NOT NULL,
  as_of timestamptz NOT NULL,
  attempt_no smallint NOT NULL DEFAULT 1,
  sealed_ct bytea NOT NULL,
  workflow_run_id text NOT NULL,
  scored_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT thesis_score_pkey PRIMARY KEY (id),
  CHECK (kind IN ('final','restatement')),
  CHECK (outcome IN ('correct','incorrect','unresolvable')),
  CHECK (kind = 'final' OR outcome <> 'unresolvable'),
  CHECK (attempt_no BETWEEN 1 AND 14),
  CHECK (octet_length(sealed_ct) BETWEEN 49 AND 16384)
);
COMMENT ON TABLE exec.thesis_score IS 'Điểm chấm của luận điểm, chỉ ghi thêm (BR-191): kết quả bản rõ; giá trị quan sát, điều kiện đã dùng, phiên bản chỉ số hoặc data product, query_run_id và biên nhận niêm phong cho chủ kho. Brier tính trên thiết bị vì mức tự tin là bản mã. Use case: UC-16-04.';
COMMENT ON COLUMN exec.thesis_score.thesis_id IS 'FK thesis';
COMMENT ON COLUMN exec.thesis_score.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN exec.thesis_score.kind IS 'final, restatement';
COMMENT ON COLUMN exec.thesis_score.outcome IS 'correct, incorrect, unresolvable';
COMMENT ON COLUMN exec.thesis_score.as_of IS 'Thời điểm dữ liệu dùng để chấm, bằng thesis.due_at';
COMMENT ON COLUMN exec.thesis_score.attempt_no IS 'Lần thử chấm thành công; tối đa 14';
COMMENT ON COLUMN exec.thesis_score.sealed_ct IS 'Hộp niêm phong cho chủ kho';
COMMENT ON COLUMN exec.thesis_score.workflow_run_id IS 'Mã lượt Temporal';

CREATE TABLE exec.memory_item (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  vault_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  kind text NOT NULL,
  content_ct bytea,
  wrapped_dek bytea,
  content_version smallint NOT NULL DEFAULT 1,
  related_thesis_id uuid,
  handover_item_id uuid,
  shredded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT memory_item_pkey PRIMARY KEY (id),
  CHECK (kind IN ('priority','decision_reason','question','answer_snapshot','note')),
  CHECK ((shredded_at IS NULL) = (content_ct IS NOT NULL AND wrapped_dek IS NOT NULL)),
  CHECK (shredded_at IS NOT NULL OR (octet_length(wrapped_dek) = 72 AND octet_length(content_ct) BETWEEN 41 AND 262144)),
  CHECK (handover_item_id IS NULL OR kind = 'note')
);
COMMENT ON TABLE exec.memory_item IS 'Mục bộ nhớ riêng: ưu tiên, lý do quyết định, câu hỏi đã hỏi, bản chụp câu trả lời, ghi chú (gồm mục nhận bàn giao). Huỷ một mục là xoá DEK đã bọc và bản mã. Use case: UC-16-02, UC-16-06.';
COMMENT ON COLUMN exec.memory_item.vault_id IS 'FK vault';
COMMENT ON COLUMN exec.memory_item.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN exec.memory_item.kind IS 'priority, decision_reason, question, answer_snapshot, note';
COMMENT ON COLUMN exec.memory_item.content_ct IS 'Bản mã AEAD của nội dung; null sau khi huỷ';
COMMENT ON COLUMN exec.memory_item.wrapped_dek IS 'DEK bọc bằng VMK, 72 byte; null sau khi huỷ';
COMMENT ON COLUMN exec.memory_item.related_thesis_id IS 'FK thesis';
COMMENT ON COLUMN exec.memory_item.handover_item_id IS 'logic → exec.handover_item của kho người bàn giao; có với mục nhận bàn giao';

CREATE TABLE exec.key_access_log (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  vault_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  thesis_id uuid,
  key_kind text NOT NULL,
  action text NOT NULL,
  purpose text NOT NULL,
  actor_kind text NOT NULL,
  actor_ref text NOT NULL,
  correlation_id uuid NOT NULL,
  at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT key_access_log_pkey PRIMARY KEY (id),
  CHECK (key_kind IN ('condition_transit','vault_key','box_key')),
  CHECK (action IN ('decrypt_condition','unlock','seal_evidence','seal_score','rewrap_handover','rotate','shred')),
  CHECK (purpose IN ('validate','evidence_refresh','scoring','unlock','handover','rotation','shred')),
  CHECK (actor_kind IN ('workflow','owner_device','admin_request')),
  CHECK (action <> 'decrypt_condition' OR (key_kind = 'condition_transit' AND actor_kind = 'workflow' AND thesis_id IS NOT NULL)),
  UNIQUE (correlation_id)
);
COMMENT ON TABLE exec.key_access_log IS 'Sổ truy cập khoá, chỉ ghi thêm (BR-192): mỗi lần workflow giải mã điều kiện, niêm phong kết quả, mỗi lần thiết bị mở kho, bọc lại để bàn giao, xoay hoặc huỷ khoá. Ghi trước khi gọi OpenBao, kèm correlation_id mà OpenBao ghi ở nhật ký audit (header X-Exec-Correlation) để đối chiếu hai phía. Use case: UC-16-03, UC-16-04, UC-16-06.';
COMMENT ON COLUMN exec.key_access_log.vault_id IS 'logic → exec.vault';
COMMENT ON COLUMN exec.key_access_log.owner_id IS 'logic → org.app_user; chủ kho';
COMMENT ON COLUMN exec.key_access_log.thesis_id IS 'logic → exec.thesis; null với sự kiện mức kho';
COMMENT ON COLUMN exec.key_access_log.key_kind IS 'condition_transit, vault_key, box_key';
COMMENT ON COLUMN exec.key_access_log.action IS 'decrypt_condition, unlock, seal_evidence, seal_score, rewrap_handover, rotate, shred';
COMMENT ON COLUMN exec.key_access_log.purpose IS 'validate, evidence_refresh, scoring, unlock, handover, rotation, shred';
COMMENT ON COLUMN exec.key_access_log.actor_kind IS 'workflow, owner_device, admin_request';
COMMENT ON COLUMN exec.key_access_log.actor_ref IS 'Mã workflow và activity, nhãn khoá bọc, hoặc mã handover';
COMMENT ON COLUMN exec.key_access_log.correlation_id IS 'Gửi kèm lời gọi OpenBao, có trong nhật ký audit của OpenBao';

CREATE TABLE exec.handover (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  vault_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  kind text NOT NULL,
  reason text NOT NULL,
  requested_by uuid NOT NULL,
  owner_participates boolean NOT NULL,
  approved_by uuid,
  approved_at timestamptz,
  successor_id uuid,
  status text NOT NULL DEFAULT 'requested',
  items_total integer NOT NULL DEFAULT 0,
  contract_ref text,
  certificate_sha256 text,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT handover_pkey PRIMARY KEY (id),
  CHECK (kind IN ('seal','selective_handover','shred')),
  CHECK (reason IN ('leave_position','contract_end','owner_request','sealed_expired')),
  CHECK (status IN ('requested','approved','in_progress','completed','rejected','cancelled')),
  CHECK (kind <> 'selective_handover' OR (successor_id IS NOT NULL AND owner_participates)),
  CHECK (successor_id IS NULL OR successor_id <> owner_id),
  CHECK (kind <> 'shred' OR owner_participates OR reason = 'sealed_expired' OR status IN ('requested','rejected','cancelled') OR approved_by IS NOT NULL),
  CHECK (approved_by IS NULL OR approved_by <> requested_by),
  CHECK (items_total >= 0),
  CHECK (status <> 'completed' OR completed_at IS NOT NULL),
  CHECK (kind <> 'shred' OR status <> 'completed' OR certificate_sha256 ~ '^[0-9a-f]{64}$')
);
COMMENT ON TABLE exec.handover IS 'Yêu cầu xử lý kho khi chủ kho rời vị trí: niêm phong, bàn giao có chọn lọc hoặc huỷ khoá theo hợp đồng (BR-195). Bảng không có cột bản mã nên AC05, AC06 đọc được qua chính sách exec_admin. Use case: UC-16-06.';
COMMENT ON COLUMN exec.handover.vault_id IS 'FK vault';
COMMENT ON COLUMN exec.handover.owner_id IS 'logic → org.app_user; chủ kho rời vị trí';
COMMENT ON COLUMN exec.handover.kind IS 'seal, selective_handover, shred';
COMMENT ON COLUMN exec.handover.reason IS 'leave_position, contract_end, owner_request, sealed_expired';
COMMENT ON COLUMN exec.handover.requested_by IS 'logic → org.app_user; chủ kho hoặc AC05';
COMMENT ON COLUMN exec.handover.owner_participates IS 'Chủ kho tự xác nhận bằng passkey';
COMMENT ON COLUMN exec.handover.approved_by IS 'logic → org.app_user; AC06, bắt buộc với shred khi chủ kho không tham gia';
COMMENT ON COLUMN exec.handover.successor_id IS 'logic → org.app_user; bắt buộc với selective_handover';
COMMENT ON COLUMN exec.handover.status IS 'requested, approved, in_progress, completed, rejected, cancelled';
COMMENT ON COLUMN exec.handover.items_total IS 'Số mục bàn giao';
COMMENT ON COLUMN exec.handover.contract_ref IS 'Số hợp đồng hoặc phụ lục';
COMMENT ON COLUMN exec.handover.certificate_sha256 IS 'Băm biên bản huỷ khoá (tên và phiên bản khoá Transit, số khoá bọc đã xoá, thời điểm, ngày hết hạn sao lưu OpenBao)';

CREATE TABLE exec.handover_item (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  handover_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  successor_id uuid NOT NULL,
  source_kind text NOT NULL,
  source_id uuid NOT NULL,
  payload_sealed bytea NOT NULL,
  imported_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  CONSTRAINT handover_item_pkey PRIMARY KEY (id),
  CHECK (source_kind IN ('memory_item','thesis_note')),
  CHECK (octet_length(payload_sealed) BETWEEN 49 AND 262144),
  CHECK (successor_id <> owner_id),
  UNIQUE (handover_id, source_kind, source_id)
);
COMMENT ON TABLE exec.handover_item IS 'Một mục bàn giao đang trung chuyển: chủ kho cũ giải mã trên thiết bị và niêm phong lại bằng box_public_key của kho người kế nhiệm; người nhận mở, mã hoá lại vào kho mình rồi dòng bị xoá. Luận điểm và điểm chấm không bàn giao. Use case: UC-16-06.';
COMMENT ON COLUMN exec.handover_item.handover_id IS 'FK handover';
COMMENT ON COLUMN exec.handover_item.owner_id IS 'logic → org.app_user; chủ kho bàn giao';
COMMENT ON COLUMN exec.handover_item.successor_id IS 'logic → org.app_user; người nhận';
COMMENT ON COLUMN exec.handover_item.source_kind IS 'memory_item, thesis_note';
COMMENT ON COLUMN exec.handover_item.source_id IS 'logic → exec.memory_item hoặc exec.thesis của kho cũ';
COMMENT ON COLUMN exec.handover_item.payload_sealed IS 'Hộp niêm phong X25519 cho kho người nhận';
COMMENT ON COLUMN exec.handover_item.imported_at IS 'Người nhận đã nhập vào kho mình';

CREATE TABLE exec.publication (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  thesis_id uuid NOT NULL,
  owner_id uuid NOT NULL,
  title text NOT NULL,
  statement_public text NOT NULL,
  ref_kind text NOT NULL,
  metric_ref text NOT NULL,
  scope jsonb NOT NULL DEFAULT '{}',
  period_label text NOT NULL,
  comparator text NOT NULL,
  threshold numeric NOT NULL,
  threshold_hi numeric,
  unit text NOT NULL,
  due_at timestamptz NOT NULL,
  attribution text NOT NULL DEFAULT 'role_only',
  attribution_label text NOT NULL,
  confidence_public numeric(3,2),
  rationale_public text,
  target_data_space_id uuid NOT NULL,
  knowledge_page_id uuid,
  status text NOT NULL DEFAULT 'pending_review',
  published_at timestamptz,
  withdrawn_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  CONSTRAINT publication_pkey PRIMARY KEY (id),
  CHECK (ref_kind IN ('metric','data_product')),
  CHECK (comparator IN ('gte','lte','gt','lt','between')),
  CHECK ((comparator = 'between') = (threshold_hi IS NOT NULL)),
  CHECK (threshold_hi IS NULL OR threshold_hi > threshold),
  CHECK (attribution IN ('named','role_only')),
  CHECK (confidence_public IS NULL OR confidence_public BETWEEN 0.50 AND 0.99),
  CHECK (status IN ('pending_review','published','rejected','withdrawn')),
  CHECK (status <> 'published' OR (published_at IS NOT NULL AND knowledge_page_id IS NOT NULL)),
  CHECK (status <> 'withdrawn' OR withdrawn_at IS NOT NULL),
  CHECK (statement_public !~ '[0-9]')
);
COMMENT ON TABLE exec.publication IS 'Bản công bố của một luận điểm, là bản rõ do lãnh đạo chọn câu chữ; nguồn của trang tri thức kind hypothesis (BR-194). Điều kiện ở cột có cấu trúc để thân trang không có số viết tay (BR-162). Use case: UC-16-05.';
COMMENT ON COLUMN exec.publication.thesis_id IS 'FK thesis';
COMMENT ON COLUMN exec.publication.owner_id IS 'logic → org.app_user';
COMMENT ON COLUMN exec.publication.statement_public IS 'Câu giả thuyết trung tính, không chứa số viết tay';
COMMENT ON COLUMN exec.publication.ref_kind IS 'metric, data_product';
COMMENT ON COLUMN exec.publication.metric_ref IS 'Mã chỉ số (context.metric) hoặc mã data product (context.data_product)';
COMMENT ON COLUMN exec.publication.scope IS 'Phạm vi theo chiều, ví dụ {"product": "E5RON92"}';
COMMENT ON COLUMN exec.publication.period_label IS 'Ví dụ 2026-10-22, 2026-W45';
COMMENT ON COLUMN exec.publication.comparator IS 'gte, lte, gt, lt, between';
COMMENT ON COLUMN exec.publication.threshold_hi IS 'Bắt buộc khi between';
COMMENT ON COLUMN exec.publication.unit IS 'Ví dụ VND/l, %';
COMMENT ON COLUMN exec.publication.due_at IS 'Bằng thesis.due_at';
COMMENT ON COLUMN exec.publication.attribution IS 'named, role_only';
COMMENT ON COLUMN exec.publication.attribution_label IS 'Tên hoặc chức danh hiển thị, ví dụ “Thành viên Ban điều hành”';
COMMENT ON COLUMN exec.publication.confidence_public IS 'Chỉ có khi lãnh đạo chọn hiện';
COMMENT ON COLUMN exec.publication.rationale_public IS 'Chỉ có khi lãnh đạo chọn hiện';
COMMENT ON COLUMN exec.publication.target_data_space_id IS 'logic → org.data_space';
COMMENT ON COLUMN exec.publication.knowledge_page_id IS 'logic → context.knowledge_page kind hypothesis';
COMMENT ON COLUMN exec.publication.status IS 'pending_review, published, rejected, withdrawn';

CREATE TABLE exec.outbox (
  id uuid NOT NULL,
  org_id uuid NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  CONSTRAINT outbox_pkey PRIMARY KEY (id)
);
COMMENT ON TABLE exec.outbox IS 'Sự kiện chờ Debezium đẩy sang Kafka (D5.3), ghi cùng giao dịch với thay đổi nghiệp vụ.';
CREATE INDEX outbox_unpublished_idx ON exec.outbox (created_at) WHERE published_at IS NULL;
ALTER TABLE exec.outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON exec.outbox USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid) WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
ALTER TABLE exec.outbox FORCE ROW LEVEL SECURITY;
GRANT USAGE ON SCHEMA exec TO svc_outbox_relay;
GRANT SELECT, UPDATE (published_at) ON exec.outbox TO svc_outbox_relay;
CREATE POLICY outbox_relay_read ON exec.outbox FOR SELECT TO svc_outbox_relay USING (true);
CREATE POLICY outbox_relay_publish ON exec.outbox FOR UPDATE TO svc_outbox_relay USING (published_at IS NULL) WITH CHECK (published_at IS NOT NULL);
CREATE INDEX vault_status_idx ON exec.vault (status);
CREATE INDEX vault_sealed_read_until_idx ON exec.vault (sealed_read_until) WHERE status = 'sealed';
CREATE UNIQUE INDEX vault_key_wrap_vault_id_credential_id_key ON exec.vault_key_wrap (vault_id, credential_id) WHERE credential_id IS NOT NULL;
CREATE INDEX vault_key_wrap_vault_id_idx ON exec.vault_key_wrap (vault_id) WHERE revoked_at IS NULL;
CREATE INDEX thesis_owner_id_due_at_idx ON exec.thesis (owner_id, due_at);
CREATE INDEX thesis_status_due_at_idx ON exec.thesis (status, due_at) WHERE status IN ('open','scoring');
CREATE INDEX thesis_supersedes_id_idx ON exec.thesis (supersedes_id);
CREATE INDEX thesis_evidence_thesis_id_batch_no_idx ON exec.thesis_evidence (thesis_id, batch_no DESC);
CREATE UNIQUE INDEX thesis_score_thesis_id_key ON exec.thesis_score (thesis_id) WHERE kind = 'final';
