-- ─── routines/governance.sql ───
-- routines/governance.sql: what D4.2 (tab 3b) writes in words for the AI model tables of schema
-- governance (BR-180, BR-181, ADR-41): the frontier guard of model_config, the re-approval and the
-- change events of model_provider, the routing-decision guard (append-only except the four result
-- columns, audit of every frontier call, monthly budget), and who may read providers and decisions.

-- covers: governance.model_config#0
-- BR-180: tasks that see raw internal data or only run on site never get a frontier candidate.
ALTER TABLE governance.model_config ADD CONSTRAINT model_config_frontier_task_check
  CHECK (route_role <> 'frontier_candidate'
         OR task NOT IN ('embedding', 'reranking', 'ocr', 'pii_classification', 'sql_generation'));

-- covers: governance.model_config#1
-- The route role follows the provider kind, and an active frontier candidate needs a passed eval run
-- just like an on-site model (the CHECK on eval_run_id applies the same bar).
CREATE FUNCTION governance.model_config_route_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  provider_kind text;
BEGIN
  SELECT kind INTO provider_kind FROM governance.model_provider WHERE id = NEW.provider_id;
  IF provider_kind IS NULL THEN
    RAISE EXCEPTION 'Không tìm thấy provider của cấu hình mô hình' USING ERRCODE = 'check_violation';
  END IF;
  IF provider_kind = 'frontier' AND NEW.route_role <> 'frontier_candidate' THEN
    RAISE EXCEPTION 'Provider frontier chỉ dùng cho route_role frontier_candidate (BR-180)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF provider_kind = 'on_prem' AND NEW.route_role <> 'primary' THEN
    RAISE EXCEPTION 'Provider tại chỗ chỉ dùng cho route_role primary (BR-180)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.route_role = 'frontier_candidate' AND NEW.status = 'active' AND NEW.eval_run_id IS NULL THEN
    RAISE EXCEPTION 'Ứng viên frontier active phải có eval_run_id đạt như mô hình tại chỗ (BR-180)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER model_config_route_guard BEFORE INSERT OR UPDATE ON governance.model_config
  FOR EACH ROW EXECUTE FUNCTION governance.model_config_route_guard();


-- covers: governance.model_provider#0
-- Only svc_governance reads providers (admin and compliance read through the Admin service), so the
-- schema-wide read role used by other services does not include this table.
REVOKE SELECT ON governance.model_provider FROM governance_read;

-- covers: governance.model_provider#1
-- BR-181: changing where or under which contract a frontier provider receives data needs a new
-- approval, so the change switches it off. Every change is audited (audit is a separate database,
-- D1.1, hence the outbox request; the database holds no API key, only the OpenBao path) and announced
-- so the Model gateway reloads and the egress proxy allow-list is updated.
CREATE FUNCTION governance.model_provider_reapproval() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.kind = 'frontier'
     AND (NEW.endpoint, NEW.secret_ref, NEW.data_region, NEW.zero_retention)
         IS DISTINCT FROM (OLD.endpoint, OLD.secret_ref, OLD.data_region, OLD.zero_retention) THEN
    NEW.enabled := false;
    NEW.approved_by := NULL;
    NEW.approved_at := NULL;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER model_provider_reapproval BEFORE UPDATE ON governance.model_provider
  FOR EACH ROW EXECUTE FUNCTION governance.model_provider_reapproval();

CREATE FUNCTION governance.model_provider_changed() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO governance.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'model_provider', NEW.id, 'audit.requested',
          jsonb_build_object('action', 'model_provider.changed', 'object_kind', 'model_provider',
                             'object_id', NEW.id,
                             'before', CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) END,
                             'after', to_jsonb(NEW)));
  INSERT INTO governance.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'model_provider', NEW.id, 'governance.model_provider.changed',
          jsonb_build_object('provider_id', NEW.id, 'code', NEW.code, 'kind', NEW.kind,
                             'endpoint', NEW.endpoint, 'enabled', NEW.enabled, 'status', NEW.status));
  RETURN NULL;
END
$$;
CREATE TRIGGER model_provider_changed AFTER INSERT OR UPDATE ON governance.model_provider
  FOR EACH ROW EXECUTE FUNCTION governance.model_provider_changed();


-- covers: governance.model_route_decision#0
-- Decisions are read by svc_governance and by Agent runtime (svc_qa, svc_agent) for the receipt, and
-- only for the call it is recording: the app sets app.caller_id. The compliance role reads through
-- the Admin service. audit_read lives in the audit database's role set and is not granted here.
REVOKE SELECT ON governance.model_route_decision FROM governance_read;
GRANT SELECT ON governance.model_route_decision TO svc_qa, svc_agent;
CREATE POLICY model_route_decision_caller ON governance.model_route_decision AS RESTRICTIVE FOR SELECT
  TO svc_qa, svc_agent
  USING (caller_id = NULLIF(current_setting('app.caller_id', true), '')::uuid);

-- covers: governance.model_route_decision#1
-- BR-180/BR-181: a frontier call needs an enabled, active, public-only frontier provider and the
-- organisation's frontier_routing switched on for the task; any other decision runs on site. The row
-- is written before the call and only its four result columns are filled, once (D5.2: svc_governance
-- updates only those, never deletes; old rows leave by dropping partitions, which fires no trigger).
CREATE FUNCTION governance.model_route_decision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  p governance.model_provider%ROWTYPE;
  routing jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Quyết định định tuyến không được xoá; chỉ dọn theo phân vùng khi quá hạn lưu (BR-181)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.outcome <> 'pending'
       OR to_jsonb(NEW) - ARRAY['input_tokens', 'output_tokens', 'outcome', 'model_usage_id']
          IS DISTINCT FROM to_jsonb(OLD) - ARRAY['input_tokens', 'output_tokens', 'outcome', 'model_usage_id'] THEN
      RAISE EXCEPTION 'Quyết định định tuyến chỉ được điền kết quả một lần khi outcome = pending (BR-181)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO p FROM governance.model_provider WHERE id = NEW.chosen_provider_id;
  IF NEW.decision = 'frontier_allowed' THEN
    SELECT value INTO routing FROM governance.ai_setting WHERE org_id = NEW.org_id AND key = 'frontier_routing';
    IF p.kind IS DISTINCT FROM 'frontier' OR NOT p.enabled OR p.status <> 'active'
       OR p.max_classification <> 'public' THEN
      RAISE EXCEPTION 'frontier_allowed phải gọi provider frontier đang bật, active, chỉ nhận mức public (BR-180)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT coalesce((routing->>'enabled')::boolean, false)
       OR NOT coalesce(routing->'tasks' ? NEW.task, false) THEN
      RAISE EXCEPTION 'Định tuyến frontier chưa bật cho tác vụ % (BR-180)', NEW.task
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF p.kind IS DISTINCT FROM 'on_prem' THEN
    RAISE EXCEPTION 'Quyết định % phải gọi provider tại chỗ (BR-180)', NEW.decision
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER model_route_decision_guard BEFORE INSERT OR UPDATE OR DELETE ON governance.model_route_decision
  FOR EACH ROW EXECUTE FUNCTION governance.model_route_decision_guard();

-- After the call: audit every frontier call (outbox request, D1.1), and add the filled tokens to the
-- provider's spend of the month. Spend is priced from model_provider.price, read as
-- {"<model_name>": {"input": <VND per 1M tokens>, "output": <VND per 1M tokens>}}; the event fires
-- once, on the call that crosses monthly_budget_vnd, so the Model gateway stops the frontier route.
CREATE FUNCTION governance.model_route_decision_events() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  p governance.model_provider%ROWTYPE;
  spent numeric;
  this_call numeric;
BEGIN
  SELECT * INTO p FROM governance.model_provider WHERE id = NEW.chosen_provider_id;
  IF TG_OP = 'INSERT' THEN
    IF NEW.decision = 'frontier_allowed' THEN
      INSERT INTO governance.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
      VALUES (gen_random_uuid(), NEW.org_id, 'model_route_decision', NEW.id, 'audit.requested',
              jsonb_build_object('action', 'model.frontier_call', 'object_kind', 'model_route_decision',
                                 'object_id', NEW.id, 'before', NULL,
                                 'after', jsonb_build_object('provider', p.code, 'model_name', NEW.model_name,
                                                             'context_labels', to_jsonb(NEW.context_labels),
                                                             'product_scope', NEW.product_scope,
                                                             'prompt_sha256', NEW.prompt_sha256)));
    END IF;
    RETURN NULL;
  END IF;
  IF p.monthly_budget_vnd IS NULL OR (NEW.input_tokens IS NULL AND NEW.output_tokens IS NULL) THEN
    RETURN NULL;
  END IF;
  SELECT coalesce(sum((coalesce(d.input_tokens, 0) * coalesce((p.price->d.model_name->>'input')::numeric, 0)
                     + coalesce(d.output_tokens, 0) * coalesce((p.price->d.model_name->>'output')::numeric, 0))
                     / 1000000), 0)
    INTO spent
    FROM governance.model_route_decision d
   WHERE d.chosen_provider_id = NEW.chosen_provider_id
     AND d.decided_at >= date_trunc('month', NEW.decided_at)
     AND d.decided_at < date_trunc('month', NEW.decided_at) + interval '1 month';
  this_call := (coalesce(NEW.input_tokens, 0) * coalesce((p.price->NEW.model_name->>'input')::numeric, 0)
              + coalesce(NEW.output_tokens, 0) * coalesce((p.price->NEW.model_name->>'output')::numeric, 0))
              / 1000000;
  IF spent > p.monthly_budget_vnd AND spent - this_call <= p.monthly_budget_vnd THEN
    INSERT INTO governance.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'model_provider', p.id, 'governance.model_provider.budget_exceeded',
            jsonb_build_object('provider_id', p.id, 'code', p.code, 'month', to_char(NEW.decided_at, 'YYYY-MM'),
                               'spent_vnd', round(spent), 'monthly_budget_vnd', p.monthly_budget_vnd));
  END IF;
  RETURN NULL;
END
$$;
CREATE TRIGGER model_route_decision_events AFTER INSERT OR UPDATE ON governance.model_route_decision
  FOR EACH ROW EXECUTE FUNCTION governance.model_route_decision_events();

-- D5.2 (BR-181): svc_governance fills only the four result columns and never deletes.
REVOKE UPDATE, DELETE ON governance.model_route_decision FROM svc_governance;
GRANT UPDATE (input_tokens, output_tokens, outcome, model_usage_id) ON governance.model_route_decision
  TO svc_governance;

-- ─── routines/catalog.sql ───
-- routines/catalog.sql: what D4.4 (tab 3b) writes in words for schema catalog: certification of a
-- consolidated dataset version (BR-156) through the append-only history
-- catalog.dataset_version_certification, and the D5.2 grant exception of svc_catalog on it.

-- covers: catalog.dataset_version#0
-- BR-156: a version starts uncertified; a consolidated one records its creator (the last spec
-- editor), which never changes, so a second person certifies it. certified_at/certified_by are the
-- current state of the history table and only its trigger writes them (it runs one trigger level
-- deeper, pg_trigger_depth() > 1). Blocking uncertified consolidated versions from regulator figures
-- is the semantic compiler's job (tab 5 G5.2).
CREATE FUNCTION catalog.dataset_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  origin text;
BEGIN
  SELECT d.origin INTO origin FROM catalog.dataset d WHERE d.id = NEW.dataset_id;
  IF TG_OP = 'INSERT' THEN
    IF NEW.certified_at IS NOT NULL OR NEW.certified_by IS NOT NULL THEN
      RAISE EXCEPTION 'Phiên bản dataset mới ở trạng thái chưa chứng nhận (BR-156)' USING ERRCODE = 'check_violation';
    END IF;
    IF origin = 'consolidated' AND NEW.created_by IS NULL THEN
      RAISE EXCEPTION 'Phiên bản dataset hợp nhất bắt buộc có created_by (BR-156)' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
    RAISE EXCEPTION 'created_by của phiên bản dataset không sửa được (BR-156)' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.certified_at, NEW.certified_by) IS DISTINCT FROM (OLD.certified_at, OLD.certified_by) THEN
    IF pg_trigger_depth() < 2 THEN
      RAISE EXCEPTION 'Chứng nhận phiên bản dataset chỉ ghi qua catalog.dataset_version_certification (BR-156)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF origin IS DISTINCT FROM 'consolidated' THEN
      RAISE EXCEPTION 'Chỉ chứng nhận phiên bản của dataset hợp nhất (origin = consolidated, BR-156)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER dataset_version_guard BEFORE INSERT OR UPDATE ON catalog.dataset_version
  FOR EACH ROW EXECUTE FUNCTION catalog.dataset_version_guard();

-- covers: catalog.dataset_version_certification#0
-- BR-156: each certify/revoke is a new history row applied to the version in the same transaction
-- and announced through catalog.outbox. A history table rather than revoked_* columns, because a
-- second revocation would overwrite them (D1.6, append only).
CREATE FUNCTION catalog.dataset_version_certification_apply() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v catalog.dataset_version%ROWTYPE;
BEGIN
  SELECT * INTO v FROM catalog.dataset_version WHERE id = NEW.dataset_version_id FOR UPDATE;
  IF NOT FOUND OR v.org_id <> NEW.org_id THEN
    RAISE EXCEPTION 'Không tìm thấy phiên bản dataset trong tổ chức (BR-156)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.action = 'certify' THEN
    IF v.certified_at IS NOT NULL THEN
      RAISE EXCEPTION 'Phiên bản dataset đã được chứng nhận (BR-156)' USING ERRCODE = 'check_violation';
    END IF;
    UPDATE catalog.dataset_version SET certified_at = NEW.created_at, certified_by = NEW.actor_id
     WHERE id = v.id;
    INSERT INTO catalog.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'dataset_version', v.id, 'catalog.dataset_version.certified',
            jsonb_build_object('dataset_version_id', v.id, 'dataset_id', v.dataset_id,
                               'certified_by', NEW.actor_id, 'certified_at', NEW.created_at, 'note', NEW.note));
  ELSE
    IF v.certified_at IS NULL THEN
      RAISE EXCEPTION 'Phiên bản dataset chưa được chứng nhận, không thu hồi được (BR-156)'
        USING ERRCODE = 'check_violation';
    END IF;
    UPDATE catalog.dataset_version SET certified_at = NULL, certified_by = NULL WHERE id = v.id;
    INSERT INTO catalog.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'dataset_version', v.id, 'catalog.dataset_version.certification_revoked',
            jsonb_build_object('dataset_version_id', v.id, 'dataset_id', v.dataset_id,
                               'revoked_by', NEW.actor_id, 'reason', NEW.reason,
                               'previous_certified_by', v.certified_by, 'previous_certified_at', v.certified_at));
  END IF;
  RETURN NULL;
END
$$;
CREATE TRIGGER dataset_version_certification_apply AFTER INSERT ON catalog.dataset_version_certification
  FOR EACH ROW EXECUTE FUNCTION catalog.dataset_version_certification_apply();

-- D5.2 (BR-156): the history is append only for svc_catalog.
REVOKE UPDATE, DELETE ON catalog.dataset_version_certification FROM svc_catalog;

-- ─── routines/context.sql ───
-- Hand-written part of schema context: the knowledge layer (knowledge_page … knowledge_lint_finding,
-- BR-161 to BR-167, BR-194) and the data products (data_product, data_product_member, BR-175, BR-178).
-- It holds what D4.5 writes in words: CHECKs given as prose, the append-only grants of D5.2 (BR-164),
-- the reader row-level security of BR-163, the triggers and the functions the Context service calls.
-- Runs as da_owner after the generated tables, FKs, org_isolation policies and grants.
--
-- Reader contract (BR-163). The api sets these with set_config(..., true) for every reader
-- transaction; any one unset or empty hides every knowledge row (never an error):
--   app.knowledge_reader  'on' makes svc_context read as a reader (Context service answering on
--                         behalf of a user). Roles holding context_read (svc_qa, svc_agent, …) are
--                         always readers and do not need it.
--   app.data_space_ids    the Data Spaces the reader may read, as a Postgres uuid[] literal:
--                         '{8b0c…-…,1f2e…-…}' (braces, comma-separated, no spaces needed). '{}' is
--                         a reader with no Data Space: only pages without sources would pass, and a
--                         served page always has one.
--   app.clearance         the highest classification the reader may see, as its rank (an integer):
--                         0 public, 1 internal, 2 confidential, 3 restricted
--                         (context.classification_rank).

-- ─── shared helpers ──────────────────────────────────────────────────────────────────────────────

-- Classification order used by BR-163 (page = highest of its sources) and BR-180 (data product =
-- highest of its members). Unknown labels rank above restricted so they never widen access.
CREATE FUNCTION context.classification_rank(label text)
RETURNS integer LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE label WHEN 'public' THEN 0 WHEN 'internal' THEN 1
                    WHEN 'confidential' THEN 2 WHEN 'restricted' THEN 3 ELSE 99 END
$$;

-- The text left once every allowed token is removed: {{claim:a}}, {{metric:…}}, {{agg:…}},
-- {{hyp:…}} (BR-194, filled from exec.publication when rendered) and [[slug]]. Any digit or brace
-- left over is a hand-written number or a malformed placeholder (BR-162).
CREATE FUNCTION context.knowledge_strip_tokens(content text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT regexp_replace(content,
    '\{\{(?:metric|agg):[a-z0-9_]+(?:\|[a-z_]+=[^|{}]+)*\}\}'
    '|\{\{claim:[a-z][a-z0-9_]{0,31}\}\}'
    '|\{\{hyp:[a-z_]+\}\}'
    '|\[\[[a-z0-9][a-z0-9-]{1,79}\]\]',
    '', 'g')
$$;

CREATE FUNCTION context.knowledge_has_handwritten_number(content text)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT context.knowledge_strip_tokens(coalesce(content, '')) ~ '[0-9{}]'
$$;

-- BR-163 reader test on one row's policy columns, against the GUCs documented in the header.
CREATE FUNCTION context.knowledge_reader_allows(required_data_space_ids uuid[], classification text)
RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT coalesce(
    required_data_space_ids <@ NULLIF(current_setting('app.data_space_ids', true), '')::uuid[]
    AND context.classification_rank(classification)
        <= NULLIF(current_setting('app.clearance', true), '')::integer,
    false)
$$;

-- svc_context reads as a reader only when the api says so; it also writes the layer.
CREATE FUNCTION context.knowledge_reader_mode()
RETURNS boolean LANGUAGE sql STABLE AS $$
  SELECT coalesce(current_setting('app.knowledge_reader', true), '') = 'on'
$$;

-- ─── constraints written as prose ────────────────────────────────────────────────────────────────

-- covers: context.knowledge_page#2
-- P16 (BR-194) adds kind 'hypothesis'; the generated CHECK predates it, so it is replaced.
DO $$
DECLARE c text;
BEGIN
  FOR c IN SELECT conname FROM pg_constraint
           WHERE conrelid = 'context.knowledge_page'::regclass
             AND pg_get_constraintdef(oid) LIKE 'CHECK ((kind = ANY%'
  LOOP
    EXECUTE format('ALTER TABLE context.knowledge_page DROP CONSTRAINT %I', c);
  END LOOP;
END $$;
ALTER TABLE context.knowledge_page ADD CONSTRAINT knowledge_page_kind_check
  CHECK (kind IN ('metric','entity','source','topic','hypothesis'));

-- covers: context.knowledge_page#0
-- Pairs kind with subject_kind; no subject kind names a person (BR-167). A hypothesis page is
-- about one exec.publication, so its subject_ref is that publication's uuid (BR-194).
ALTER TABLE context.knowledge_page ADD CONSTRAINT knowledge_page_kind_subject_check CHECK (
  (kind = 'metric' AND subject_kind = 'metric')
  OR (kind = 'entity' AND subject_kind IN ('organization','product','segment','branch','channel'))
  OR (kind = 'source' AND subject_kind IN ('dataset','document_collection','crawl_source'))
  OR (kind = 'topic' AND subject_kind = 'topic')
  OR (kind = 'hypothesis' AND subject_kind = 'exec_publication'
      AND subject_ref ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
);

-- covers: context.knowledge_page_version#0
-- Certifier recorded with both columns and is a third person (BR-164); a certified version has one.
ALTER TABLE context.knowledge_page_version ADD CONSTRAINT knowledge_page_version_certifier_check CHECK (
  (certified_by IS NULL) = (certified_at IS NULL)
  AND (status <> 'certified' OR certified_by IS NOT NULL)
  AND (certified_by IS NULL OR (certified_by IS DISTINCT FROM created_by
                                AND certified_by IS DISTINCT FROM reviewed_by))
);

-- covers: context.knowledge_page_version#5
-- 'exec_publish' joins origin (BR-194). The {{hyp:…}} exemption lives in
-- context.knowledge_strip_tokens, used by every BR-162 check below.
DO $$
DECLARE c text;
BEGIN
  FOR c IN SELECT conname FROM pg_constraint
           WHERE conrelid = 'context.knowledge_page_version'::regclass
             AND pg_get_constraintdef(oid) LIKE 'CHECK ((origin = ANY%'
  LOOP
    EXECUTE format('ALTER TABLE context.knowledge_page_version DROP CONSTRAINT %I', c);
  END LOOP;
END $$;
ALTER TABLE context.knowledge_page_version ADD CONSTRAINT knowledge_page_version_origin_check
  CHECK (origin IN ('ingest','lint_fix','saveback','manual','exec_publish'));

-- covers: context.knowledge_source_link#0
ALTER TABLE context.knowledge_source_link ADD CONSTRAINT knowledge_source_link_classification_check
  CHECK (classification IN ('public','internal','confidential','restricted'));

-- covers: context.knowledge_source_link#3
-- 'exec_publication' joins source_kind (BR-194); the trigger knowledge_source_link_guard keeps it
-- to versions of hypothesis pages.
DO $$
DECLARE c text;
BEGIN
  FOR c IN SELECT conname FROM pg_constraint
           WHERE conrelid = 'context.knowledge_source_link'::regclass
             AND pg_get_constraintdef(oid) LIKE 'CHECK ((source_kind = ANY%'
  LOOP
    EXECUTE format('ALTER TABLE context.knowledge_source_link DROP CONSTRAINT %I', c);
  END LOOP;
END $$;
ALTER TABLE context.knowledge_source_link ADD CONSTRAINT knowledge_source_link_source_kind_check
  CHECK (source_kind IN ('conflict_claim','dataset_version','document_version','document_chunk',
                         'metric_version','answer','glossary_term','knowledge_page','exec_publication'));

-- covers: context.knowledge_figure#0
ALTER TABLE context.knowledge_figure ADD CONSTRAINT knowledge_figure_binding_check CHECK (
  (binding_kind = 'metric' AND metric_code IS NOT NULL AND token LIKE '{{metric:%')
  OR (binding_kind = 'aggregate' AND aggregate_code IS NOT NULL AND dataset_id IS NOT NULL
      AND token LIKE '{{agg:%')
);

-- covers: context.knowledge_lint_finding#0
ALTER TABLE context.knowledge_lint_finding ADD CONSTRAINT knowledge_lint_finding_kind_check
  CHECK (kind IN ('contradiction','expired_claim','orphan_page','metric_without_page',
                  'undefined_term','source_decertified','stale_condition','policy_drift'));

-- covers: context.knowledge_lint_finding#1
-- The agent picks from a fixed action set, never free text (BR-166).
ALTER TABLE context.knowledge_lint_finding ADD CONSTRAINT knowledge_lint_finding_action_check
  CHECK (action IS NULL OR action IN ('propose_edit','mark_stale','retire_page','create_page',
                                      'dismiss','reassign'));

-- covers: context.knowledge_lint_finding#2
-- Dismissing needs a reason and hides the fingerprint until suppressed_until (BR-166).
ALTER TABLE context.knowledge_lint_finding ADD CONSTRAINT knowledge_lint_finding_dismiss_check CHECK (
  (status = 'dismissed') = coalesce(action = 'dismiss', false)
  AND (status <> 'dismissed'
       OR (coalesce(btrim(action_reason), '') <> '' AND suppressed_until IS NOT NULL))
);

-- covers: context.knowledge_lint_finding#3
ALTER TABLE context.knowledge_lint_finding ADD CONSTRAINT knowledge_lint_finding_resolver_check
  CHECK (status NOT IN ('resolved','dismissed') OR (resolved_by IS NOT NULL AND resolved_at IS NOT NULL));

-- covers: context.knowledge_lint_finding#4
ALTER TABLE context.knowledge_lint_finding ADD CONSTRAINT knowledge_lint_finding_propose_edit_check
  CHECK (action IS DISTINCT FROM 'propose_edit' OR page_version_id IS NOT NULL);

-- ─── append-only grants (D5.2, BR-164) ───────────────────────────────────────────────────────────
-- These are the grant halves of knowledge_page_version#4, knowledge_claim#0, knowledge_figure#1,
-- knowledge_link#0, knowledge_source_link#2 and knowledge_lint_finding#6, whose markers sit with
-- their triggers and policies below.

-- No DELETE on the eight knowledge_ tables: pages retire, versions are superseded, history stays.
REVOKE DELETE ON context.knowledge_page, context.knowledge_page_version,
  context.knowledge_source_link, context.knowledge_claim, context.knowledge_figure,
  context.knowledge_link, context.knowledge_run, context.knowledge_lint_finding FROM svc_context;

-- Claims, figures and links are append-only.
REVOKE UPDATE ON context.knowledge_claim, context.knowledge_figure, context.knowledge_link FROM svc_context;

-- A source keeps its content; only the four permission columns follow the source when its Data
-- Space or classification changes (BR-163).
REVOKE UPDATE ON context.knowledge_source_link FROM svc_context;
GRANT UPDATE (data_space_id, classification, pii_column_refs, policy_updated_at)
  ON context.knowledge_source_link TO svc_context;

-- covers: context.knowledge_run#0
-- Runs and lint findings are the agent's working state, not reader content: only svc_context.
REVOKE SELECT ON context.knowledge_run, context.knowledge_lint_finding FROM context_read;

-- ─── page policy (BR-163) ────────────────────────────────────────────────────────────────────────

-- covers: context.knowledge_page#1
-- Readers see a page only when it is served (active, stale), its policy is computed and they hold
-- every Data Space its sources come from at a clearance not below its classification.
CREATE POLICY knowledge_reader ON context.knowledge_page AS RESTRICTIVE FOR SELECT TO context_read
  USING (status IN ('active','stale') AND policy_state = 'current'
         AND context.knowledge_reader_allows(required_data_space_ids, classification));
CREATE POLICY knowledge_reader_service ON context.knowledge_page AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR (status IN ('active','stale') AND policy_state = 'current'
             AND context.knowledge_reader_allows(required_data_space_ids, classification)));

-- Recomputes the page policy from the sources of its served version. Returns whether it changed.
CREATE FUNCTION context.knowledge_page_policy_refresh(p_page_id uuid)
RETURNS boolean LANGUAGE plpgsql AS $$
DECLARE
  pg context.knowledge_page%ROWTYPE;
  v_spaces uuid[];
  v_class text;
  v_pii text[];
  v_external boolean;
  v_changed boolean;
BEGIN
  SELECT * INTO pg FROM context.knowledge_page WHERE id = p_page_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  SELECT coalesce(array_agg(DISTINCT l.data_space_id ORDER BY l.data_space_id), '{}'),
         coalesce((array_agg(l.classification
                   ORDER BY context.classification_rank(l.classification) DESC))[1], 'internal'),
         coalesce(bool_or(l.external), false)
    INTO v_spaces, v_class, v_external
    FROM context.knowledge_source_link l
   WHERE l.page_version_id = pg.current_version_id;
  SELECT coalesce(array_agg(DISTINCT c ORDER BY c), '{}') INTO v_pii
    FROM context.knowledge_source_link l, unnest(l.pii_column_refs) AS c
   WHERE l.page_version_id = pg.current_version_id;
  v_changed := (v_spaces, v_class, v_pii, v_external)
    IS DISTINCT FROM (pg.required_data_space_ids, pg.classification, pg.pii_column_refs, pg.has_external_source);
  UPDATE context.knowledge_page
     SET required_data_space_ids = v_spaces, classification = v_class, pii_column_refs = v_pii,
         has_external_source = v_external, policy_state = 'current', policy_computed_at = now(),
         updated_at = now()
   WHERE id = p_page_id;
  IF v_changed THEN
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), pg.org_id, 'knowledge_page', pg.id, 'context.knowledge_page.policy_changed',
            jsonb_build_object(
              'page_id', pg.id, 'data_space_id', pg.data_space_id,
              'before', jsonb_build_object('required_data_space_ids', pg.required_data_space_ids,
                                           'classification', pg.classification,
                                           'pii_column_refs', pg.pii_column_refs,
                                           'has_external_source', pg.has_external_source),
              'after', jsonb_build_object('required_data_space_ids', v_spaces,
                                          'classification', v_class,
                                          'pii_column_refs', v_pii,
                                          'has_external_source', v_external)));
  END IF;
  RETURN v_changed;
END $$;

-- Hides (policy_state = pending) every page whose served version uses a source whose permissions
-- are about to change, until the Context service recomputes it. Returns the number of pages.
CREATE FUNCTION context.knowledge_policy_invalidate(p_source_kind text, p_source_ref uuid)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer;
BEGIN
  UPDATE context.knowledge_page p
     SET policy_state = 'pending', updated_at = now()
   WHERE p.policy_state = 'current'
     AND EXISTS (SELECT 1 FROM context.knowledge_source_link l
                  WHERE l.page_version_id = p.current_version_id
                    AND l.source_kind = p_source_kind AND l.source_ref = p_source_ref);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- ─── version reader policy ───────────────────────────────────────────────────────────────────────

-- SECURITY DEFINER: the check must see every source of the version, including ones the reader's own
-- policies would hide; it returns only a boolean for one version id.
CREATE FUNCTION context.knowledge_version_sources_ok(p_version_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM context.knowledge_source_link l
     WHERE l.page_version_id = p_version_id
       AND NOT context.knowledge_reader_allows(ARRAY[l.data_space_id], l.classification))
$$;
REVOKE EXECUTE ON FUNCTION context.knowledge_version_sources_ok(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION context.knowledge_version_sources_ok(uuid) TO svc_context, context_read;

-- covers: context.knowledge_page_version#4
-- A reader sees approved versions (older superseded ones included) of a page it can see, provided
-- it holds every source of that version itself: a superseded version may have wider sources.
CREATE POLICY knowledge_reader ON context.knowledge_page_version AS RESTRICTIVE FOR SELECT TO context_read
  USING (status IN ('reviewed','certified','superseded')
         AND EXISTS (SELECT 1 FROM context.knowledge_page p WHERE p.id = page_id)
         AND context.knowledge_version_sources_ok(id));
CREATE POLICY knowledge_reader_service ON context.knowledge_page_version AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR (status IN ('reviewed','certified','superseded')
             AND EXISTS (SELECT 1 FROM context.knowledge_page p WHERE p.id = page_id)
             AND context.knowledge_version_sources_ok(id)));

-- The same reader rule reaches the rows of a version (sources, claims, figures, links), otherwise
-- the claims of a draft or of a version the reader may not see would leak through these tables.
CREATE POLICY knowledge_reader ON context.knowledge_source_link AS RESTRICTIVE FOR SELECT TO context_read
  USING (EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader_service ON context.knowledge_source_link AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader ON context.knowledge_claim AS RESTRICTIVE FOR SELECT TO context_read
  USING (EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader_service ON context.knowledge_claim AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader ON context.knowledge_figure AS RESTRICTIVE FOR SELECT TO context_read
  USING (EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader_service ON context.knowledge_figure AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = page_version_id));
CREATE POLICY knowledge_reader ON context.knowledge_link AS RESTRICTIVE FOR SELECT TO context_read
  USING (EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = from_version_id));
CREATE POLICY knowledge_reader_service ON context.knowledge_link AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode()
         OR EXISTS (SELECT 1 FROM context.knowledge_page_version v WHERE v.id = from_version_id));
-- Runs and findings: svc_context only reads them as the writer (context_read has no SELECT).
CREATE POLICY knowledge_reader_service ON context.knowledge_run AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode());
CREATE POLICY knowledge_reader_service ON context.knowledge_lint_finding AS RESTRICTIVE FOR SELECT TO svc_context
  USING (NOT context.knowledge_reader_mode());

-- ─── knowledge_page_version triggers ─────────────────────────────────────────────────────────────

-- covers: context.knowledge_page_version#1
-- Versions are immutable drafts that move through review (BR-164); submitting checks that every
-- claim, figure and link the body names exists (BR-161, BR-162, BR-167); certifying needs every
-- external source certified (BR-165). catalog.dataset_version is read through catalog_read.
CREATE FUNCTION context.knowledge_page_version_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  pg context.knowledge_page%ROWTYPE;
  v_missing text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'Phiên bản trang mới phải ở trạng thái draft (BR-164)'
        USING ERRCODE = 'check_violation';
    END IF;
    -- Locking the page serialises version numbers of concurrent writers.
    SELECT * INTO pg FROM context.knowledge_page WHERE id = NEW.page_id FOR UPDATE;
    IF FOUND THEN
      IF pg.status = 'retired' THEN
        RAISE EXCEPTION 'Trang đã ngừng (retired) không nhận phiên bản mới (BR-164)'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.version := pg.latest_version_no + 1;
      NEW.parent_version_id := coalesce(NEW.parent_version_id, pg.current_version_id);
      UPDATE context.knowledge_page SET latest_version_no = NEW.version, updated_at = now()
       WHERE id = NEW.page_id;
    END IF;
    NEW.body_sha256 := encode(sha256(convert_to(NEW.body, 'UTF8')), 'hex');
    IF context.knowledge_has_handwritten_number(NEW.body)
       OR context.knowledge_has_handwritten_number(NEW.summary) THEN
      RAISE EXCEPTION 'Thân trang và tóm tắt không được có số viết tay hoặc chỗ giữ số sai mẫu; số chỉ ở dạng {{metric:…}}, {{agg:…}} (BR-162)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.org_id, NEW.page_id, NEW.version, NEW.parent_version_id, NEW.origin, NEW.body,
      NEW.body_sha256, NEW.summary, NEW.change_note, NEW.change_size, NEW.knowledge_run_id,
      NEW.agent_run_id, NEW.source_answer_id, NEW.created_at, NEW.created_by)
     IS DISTINCT FROM
     (OLD.org_id, OLD.page_id, OLD.version, OLD.parent_version_id, OLD.origin, OLD.body,
      OLD.body_sha256, OLD.summary, OLD.change_note, OLD.change_size, OLD.knowledge_run_id,
      OLD.agent_run_id, OLD.source_answer_id, OLD.created_at, OLD.created_by) THEN
    RAISE EXCEPTION 'Nội dung phiên bản trang không sửa được; sửa là tạo phiên bản mới (BR-164)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NOT ((OLD.status = 'draft' AND NEW.status IN ('pending_review','rejected'))
       OR (OLD.status = 'pending_review' AND NEW.status IN ('reviewed','rejected','draft'))
       OR (OLD.status = 'reviewed' AND NEW.status IN ('certified','superseded'))
       OR (OLD.status = 'certified' AND NEW.status = 'superseded')) THEN
    RAISE EXCEPTION 'Không chuyển được phiên bản trang từ % sang % (BR-164)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'pending_review' THEN
    IF NOT EXISTS (SELECT 1 FROM context.knowledge_claim WHERE page_version_id = NEW.id) THEN
      RAISE EXCEPTION 'Gửi duyệt cần ít nhất một khẳng định có nguồn (BR-161)'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(DISTINCT r.m[1], ', ') INTO v_missing
      FROM regexp_matches(NEW.body, '\{\{claim:([a-z][a-z0-9_]{0,31})\}\}', 'g') AS r(m)
     WHERE NOT EXISTS (SELECT 1 FROM context.knowledge_claim c
                        WHERE c.page_version_id = NEW.id AND c.anchor = r.m[1]);
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'Thân trang trích khẳng định không có: % (BR-161)', v_missing
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(DISTINCT x.token, ', ') INTO v_missing
      FROM (SELECT r.m[1] AS token
              FROM regexp_matches(NEW.body, '(\{\{(?:metric|agg):[a-z0-9_]+(?:\|[a-z_]+=[^|{}]+)*\}\})', 'g') AS r(m)
            UNION ALL
            SELECT r.m[1]
              FROM context.knowledge_claim c,
                   regexp_matches(c.statement, '(\{\{(?:metric|agg):[a-z0-9_]+(?:\|[a-z_]+=[^|{}]+)*\}\})', 'g') AS r(m)
             WHERE c.page_version_id = NEW.id) AS x
     WHERE NOT EXISTS (SELECT 1 FROM context.knowledge_figure f
                        WHERE f.page_version_id = NEW.id AND f.token = x.token);
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'Chỗ giữ số chưa ràng buộc knowledge_figure: % (BR-162)', v_missing
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT string_agg(DISTINCT r.m[1], ', ') INTO v_missing
      FROM regexp_matches(NEW.body, '\[\[([a-z0-9][a-z0-9-]{1,79})\]\]', 'g') AS r(m)
     WHERE NOT EXISTS (
       SELECT 1 FROM context.knowledge_page me
         JOIN context.knowledge_page p ON p.data_space_id = me.data_space_id AND p.slug = r.m[1]
         JOIN context.knowledge_link l ON l.from_version_id = NEW.id AND l.to_page_id = p.id
        WHERE me.id = NEW.page_id AND p.status <> 'retired');
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'Liên kết [[%]] không trỏ trang còn dùng có dòng knowledge_link (BR-167)', v_missing
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.origin = 'saveback' AND NOT EXISTS (
         SELECT 1 FROM context.knowledge_source_link l
          WHERE l.page_version_id = NEW.id AND l.source_kind = 'answer'
            AND l.source_ref = NEW.source_answer_id) THEN
      RAISE EXCEPTION 'Bản lưu ngược phải trích câu trả lời làm nguồn (BR-167)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.status = 'certified' THEN
    SELECT string_agg(l.source_label, ', ') INTO v_missing
      FROM context.knowledge_source_link l
      LEFT JOIN catalog.dataset_version dv ON dv.id = l.dataset_version_id
     WHERE l.page_version_id = NEW.id AND l.external AND dv.certified_at IS NULL;
    IF v_missing IS NOT NULL THEN
      RAISE EXCEPTION 'Chưa chứng nhận được: nguồn ngoài chưa có phiên bản dataset được chứng nhận: % (BR-165)', v_missing
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_page_version_guard BEFORE INSERT OR UPDATE ON context.knowledge_page_version
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_page_version_guard();

-- covers: context.knowledge_page_version#2
-- A reviewed version is served: the previous one is superseded, the page points at it and is
-- active again, the policy follows the new sources (BR-163). Certified only announces.
CREATE FUNCTION context.knowledge_page_version_publish()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_previous uuid;
BEGIN
  IF NEW.status = 'reviewed' AND OLD.status <> 'reviewed' THEN
    SELECT current_version_id INTO v_previous FROM context.knowledge_page WHERE id = NEW.page_id FOR UPDATE;
    IF v_previous IS NOT NULL AND v_previous <> NEW.id THEN
      UPDATE context.knowledge_page_version SET status = 'superseded'
       WHERE id = v_previous AND status IN ('reviewed','certified');
    END IF;
    UPDATE context.knowledge_page
       SET current_version_id = NEW.id, status = 'active', stale_reason = NULL,
           certification_suspended = false, updated_at = now(), updated_by = NEW.reviewed_by
     WHERE id = NEW.page_id;
    PERFORM context.knowledge_page_policy_refresh(NEW.page_id);
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'knowledge_page_version', NEW.id, 'context.knowledge_page.published',
            jsonb_build_object('page_id', NEW.page_id, 'version_id', NEW.id, 'version', NEW.version,
                               'previous_version_id', v_previous, 'reviewed_by', NEW.reviewed_by));
  ELSIF NEW.status = 'certified' AND OLD.status <> 'certified' THEN
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'knowledge_page_version', NEW.id, 'context.knowledge_page.certified',
            jsonb_build_object('page_id', NEW.page_id, 'version_id', NEW.id, 'version', NEW.version,
                               'certified_by', NEW.certified_by));
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER knowledge_page_version_publish AFTER UPDATE OF status ON context.knowledge_page_version
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_page_version_publish();

-- covers: context.knowledge_page_version#3
-- A run edits at most page_limit pages and only while it runs (BR-166); the row lock on the run
-- makes the count exact under concurrent writers.
CREATE FUNCTION context.knowledge_page_version_count_run()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r context.knowledge_run%ROWTYPE;
BEGIN
  SELECT * INTO r FROM context.knowledge_run WHERE id = NEW.knowledge_run_id FOR UPDATE;
  IF r.status NOT IN ('analyzing','writing','checking') THEN
    RAISE EXCEPTION 'Lượt Agent Tri thức không còn chạy (trạng thái %); không ghi thêm phiên bản (BR-166)', r.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF r.pages_changed >= r.page_limit THEN
    RAISE EXCEPTION 'Lượt đã sửa đủ % trang (page_limit); trang còn lại dời sang lượt sau (BR-166)', r.page_limit
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE context.knowledge_run SET pages_changed = pages_changed + 1 WHERE id = r.id;
  RETURN NULL;
END $$;
CREATE TRIGGER knowledge_page_version_count_run AFTER INSERT ON context.knowledge_page_version
  FOR EACH ROW WHEN (NEW.knowledge_run_id IS NOT NULL)
  EXECUTE FUNCTION context.knowledge_page_version_count_run();

-- ─── rows of a version: sources, claims, figures, links ──────────────────────────────────────────

-- covers: context.knowledge_source_link#1
-- Sources are fixed once the version leaves draft (BR-164); exec_publication sources belong to
-- hypothesis pages only (BR-194).
CREATE FUNCTION context.knowledge_source_link_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_status text; v_kind text;
BEGIN
  SELECT v.status, p.kind INTO v_status, v_kind
    FROM context.knowledge_page_version v JOIN context.knowledge_page p ON p.id = v.page_id
   WHERE v.id = NEW.page_version_id;
  IF FOUND AND v_status <> 'draft' THEN
    RAISE EXCEPTION 'Chỉ thêm nguồn vào phiên bản còn draft (BR-164)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.source_kind = 'exec_publication' AND v_kind IS DISTINCT FROM 'hypothesis' THEN
    RAISE EXCEPTION 'Nguồn exec_publication chỉ dùng cho trang hypothesis (BR-194)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_source_link_guard BEFORE INSERT ON context.knowledge_source_link
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_source_link_guard();

-- covers: context.knowledge_source_link#2
-- A source changing Data Space or classification re-scopes the page that serves this version in
-- the same transaction (BR-163), so a reader never sees the page under the old permissions.
CREATE FUNCTION context.knowledge_source_link_policy()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_page uuid;
BEGIN
  FOR v_page IN SELECT id FROM context.knowledge_page WHERE current_version_id = NEW.page_version_id LOOP
    PERFORM context.knowledge_page_policy_refresh(v_page);
  END LOOP;
  RETURN NULL;
END $$;
CREATE TRIGGER knowledge_source_link_policy
  AFTER UPDATE OF data_space_id, classification, pii_column_refs ON context.knowledge_source_link
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_source_link_policy();

-- covers: context.knowledge_claim#0
-- A claim cites a source of its own version (BR-161) and carries numbers only as placeholders (BR-162).
CREATE FUNCTION context.knowledge_claim_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM context.knowledge_page_version
              WHERE id = NEW.page_version_id AND status <> 'draft') THEN
    RAISE EXCEPTION 'Chỉ thêm khẳng định vào phiên bản còn draft (BR-164)' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM context.knowledge_source_link
                  WHERE id = NEW.source_link_id AND page_version_id = NEW.page_version_id) THEN
    RAISE EXCEPTION 'Nguồn của khẳng định phải thuộc chính phiên bản (BR-161)' USING ERRCODE = 'check_violation';
  END IF;
  IF context.knowledge_has_handwritten_number(NEW.statement) THEN
    RAISE EXCEPTION 'Câu khẳng định không được có số viết tay; số chỉ ở dạng chỗ giữ số (BR-162)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_claim_guard BEFORE INSERT ON context.knowledge_claim
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_claim_guard();

-- covers: context.knowledge_figure#1
CREATE FUNCTION context.knowledge_figure_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM context.knowledge_page_version
              WHERE id = NEW.page_version_id AND status <> 'draft') THEN
    RAISE EXCEPTION 'Chỉ thêm chỗ giữ số vào phiên bản còn draft (BR-164)' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM context.knowledge_source_link
                  WHERE id = NEW.source_link_id AND page_version_id = NEW.page_version_id) THEN
    RAISE EXCEPTION 'Nguồn của chỗ giữ số phải thuộc chính phiên bản (BR-162)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_figure_guard BEFORE INSERT ON context.knowledge_figure
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_figure_guard();

-- covers: context.knowledge_link#0
-- from_page_id is denormalised for the orphan scan; it must be the version's own page.
CREATE FUNCTION context.knowledge_link_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_status text; v_page uuid;
BEGIN
  SELECT status, page_id INTO v_status, v_page
    FROM context.knowledge_page_version WHERE id = NEW.from_version_id;
  IF FOUND AND v_status <> 'draft' THEN
    RAISE EXCEPTION 'Chỉ thêm liên kết vào phiên bản còn draft (BR-164)' USING ERRCODE = 'check_violation';
  END IF;
  IF FOUND AND v_page <> NEW.from_page_id THEN
    RAISE EXCEPTION 'Liên kết phải thuộc trang của chính phiên bản (from_page_id)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_link_guard BEFORE INSERT ON context.knowledge_link
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_link_guard();

-- ─── lint findings ───────────────────────────────────────────────────────────────────────────────

-- covers: context.knowledge_lint_finding#5
-- A dismissed fingerprint stays quiet until suppressed_until (BR-166); a handled finding keeps
-- the action it was handled with.
CREATE FUNCTION context.knowledge_lint_finding_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF EXISTS (SELECT 1 FROM context.knowledge_lint_finding f
                WHERE f.data_space_id = NEW.data_space_id AND f.fingerprint = NEW.fingerprint
                  AND f.status = 'dismissed' AND f.suppressed_until > now()) THEN
      RAISE EXCEPTION 'Phát hiện cùng vân tay đã bị bỏ qua và còn trong hạn ẩn (BR-166)'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF OLD.status <> 'open' AND NEW.action IS DISTINCT FROM OLD.action THEN
    RAISE EXCEPTION 'Không đổi hành động của phát hiện đã xử lý (BR-166)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER knowledge_lint_finding_guard BEFORE INSERT OR UPDATE ON context.knowledge_lint_finding
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_lint_finding_guard();

-- covers: context.knowledge_lint_finding#6
-- The chosen action takes effect on the page; the Inbox service opens and closes the Cần bạn card
-- (kind knowledge_finding) from the outbox events.
CREATE FUNCTION context.knowledge_lint_finding_apply()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.page_id IS NOT NULL AND NEW.action IN ('mark_stale','retire_page')
     AND (TG_OP = 'INSERT' OR OLD.action IS DISTINCT FROM NEW.action) THEN
    IF NEW.action = 'mark_stale' THEN
      UPDATE context.knowledge_page SET status = 'stale', stale_reason = NEW.kind, updated_at = now()
       WHERE id = NEW.page_id AND status IN ('active','stale');
    ELSE
      UPDATE context.knowledge_page SET status = 'retired', updated_at = now()
       WHERE id = NEW.page_id AND status <> 'retired';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'knowledge_lint_finding', NEW.id,
            CASE WHEN NEW.status = 'open' THEN 'context.knowledge_finding.opened'
                 ELSE 'context.knowledge_finding.' || NEW.status END,
            jsonb_build_object('finding_id', NEW.id, 'data_space_id', NEW.data_space_id,
                               'page_id', NEW.page_id, 'kind', NEW.kind, 'severity', NEW.severity,
                               'status', NEW.status, 'action', NEW.action,
                               'hitl_request_id', NEW.hitl_request_id));
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER knowledge_lint_finding_apply AFTER INSERT OR UPDATE ON context.knowledge_lint_finding
  FOR EACH ROW EXECUTE FUNCTION context.knowledge_lint_finding_apply();

-- Called on catalog.dataset_version.certification_revoked (BR-165): every page served from that
-- dataset version loses its certification effect and gets a high source_decertified finding,
-- recorded under one completed lint run per Data Space. Returns the number of pages touched.
CREATE FUNCTION context.knowledge_on_dataset_decertified(p_dataset_version_id uuid)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
  pg record;
  v_runs jsonb := '{}';
  v_run uuid;
  v_fingerprint text;
  n integer := 0;
BEGIN
  FOR pg IN
    SELECT p.id, p.org_id, p.data_space_id FROM context.knowledge_page p
     WHERE EXISTS (SELECT 1 FROM context.knowledge_source_link l
                    WHERE l.page_version_id = p.current_version_id
                      AND l.dataset_version_id = p_dataset_version_id)
     ORDER BY p.id
       FOR UPDATE
  LOOP
    UPDATE context.knowledge_page SET certification_suspended = true, updated_at = now() WHERE id = pg.id;
    n := n + 1;
    v_fingerprint := encode(sha256(convert_to('source_decertified:' || pg.id || ':' || p_dataset_version_id, 'UTF8')), 'hex');
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM context.knowledge_lint_finding f
       WHERE f.data_space_id = pg.data_space_id AND f.fingerprint = v_fingerprint
         AND (f.status IN ('open','actioned') OR (f.status = 'dismissed' AND f.suppressed_until > now())));
    v_run := (v_runs ->> pg.data_space_id::text)::uuid;
    IF v_run IS NULL THEN
      v_run := gen_random_uuid();
      INSERT INTO context.knowledge_run (id, org_id, data_space_id, kind, trigger, trigger_event,
                                         source_kind, source_ref, status, started_at, finished_at)
      VALUES (v_run, pg.org_id, pg.data_space_id, 'lint', 'event',
              'catalog.dataset_version.certification_revoked', 'dataset_version',
              p_dataset_version_id, 'completed', now(), now());
      v_runs := v_runs || jsonb_build_object(pg.data_space_id::text, v_run);
    END IF;
    INSERT INTO context.knowledge_lint_finding (id, org_id, run_id, data_space_id, page_id, kind,
                                                severity, fingerprint, detail)
    VALUES (gen_random_uuid(), pg.org_id, v_run, pg.data_space_id, pg.id, 'source_decertified',
            'high', v_fingerprint, jsonb_build_object('dataset_version_id', p_dataset_version_id));
    UPDATE context.knowledge_run SET findings_count = findings_count + 1 WHERE id = v_run;
  END LOOP;
  RETURN n;
END $$;

-- ─── data products ───────────────────────────────────────────────────────────────────────────────

-- covers: context.data_product#0 (no DDL: org_isolation is generated; Data Space access is checked by the Context service as for the other context tables)
-- covers: context.data_product_member#0 (no DDL: org_isolation is generated)

-- covers: context.data_product#1
-- Activation needs a certified metric, a primary dataset with a freshness commitment and datasets
-- that can be read as of a date (BR-175); svc_context reads catalog through catalog_read. Once out
-- of draft the code is stable, and a change of commitment on an active product is a new version.
CREATE FUNCTION context.data_product_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.code IS DISTINCT FROM OLD.code AND OLD.status <> 'draft' THEN
    RAISE EXCEPTION 'Không đổi code của data product khi đã rời draft (BR-175)' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'active' AND OLD.status <> 'active' THEN
    IF NOT EXISTS (
         SELECT 1 FROM context.data_product_member m
           JOIN context.metric mt ON mt.id = m.member_ref
           JOIN context.metric_version mv ON mv.metric_id = mt.id AND mv.version = mt.current_version
          WHERE m.data_product_id = NEW.id AND m.member_kind = 'metric' AND mv.status = 'certified') THEN
      RAISE EXCEPTION 'Kích hoạt data product cần ít nhất một chỉ số có phiên bản hiện hành đã chứng nhận (BR-175)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (
         SELECT 1 FROM context.data_product_member m
          WHERE m.data_product_id = NEW.id AND m.member_kind = 'dataset' AND m.role = 'primary'
            AND m.sla_kind <> 'none') THEN
      RAISE EXCEPTION 'Kích hoạt data product cần một dataset primary có cam kết độ tươi (BR-175)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
         SELECT 1 FROM context.data_product_member m
           LEFT JOIN catalog.dataset d ON d.id = m.member_ref
          WHERE m.data_product_id = NEW.id AND m.member_kind = 'dataset'
            AND NOT coalesce(d.history_kind <> 'none', false)
            AND NOT EXISTS (SELECT 1 FROM catalog.dataset_version dv WHERE dv.dataset_id = m.member_ref)) THEN
      RAISE EXCEPTION 'Mọi dataset của data product phải truy được theo thời điểm (BR-175)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF OLD.status = 'active' AND NEW.version = OLD.version
     AND (NEW.period_from, NEW.period_to, NEW.scope_entities, NEW.freshness_statement)
         IS DISTINCT FROM (OLD.period_from, OLD.period_to, OLD.scope_entities, OLD.freshness_statement) THEN
    NEW.version := OLD.version + 1;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER data_product_guard BEFORE UPDATE ON context.data_product
  FOR EACH ROW EXECUTE FUNCTION context.data_product_guard();

-- Agent runtime refreshes its scope catalogue from this event (cache at most 60 s).
CREATE FUNCTION context.data_product_changed()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'data_product', NEW.id, 'context.data_product.changed',
          jsonb_build_object('data_product_id', NEW.id, 'data_space_id', NEW.data_space_id,
                             'code', NEW.code, 'version', NEW.version, 'status', NEW.status,
                             'classification', NEW.classification));
  RETURN NULL;
END $$;
CREATE TRIGGER data_product_changed AFTER INSERT OR UPDATE ON context.data_product
  FOR EACH ROW EXECUTE FUNCTION context.data_product_changed();

-- A product's classification is the highest of its members' (BR-180 routes models on it). When it
-- does not change, the member change is still announced so the scope catalogue follows.
CREATE FUNCTION context.data_product_member_classify()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_product uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.data_product_id ELSE NEW.data_product_id END;
  v_class text;
BEGIN
  SELECT coalesce((array_agg(classification ORDER BY context.classification_rank(classification) DESC))[1], 'internal')
    INTO v_class FROM context.data_product_member WHERE data_product_id = v_product;
  UPDATE context.data_product SET classification = v_class, updated_at = now()
   WHERE id = v_product AND classification IS DISTINCT FROM v_class;
  IF NOT FOUND THEN
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    SELECT gen_random_uuid(), dp.org_id, 'data_product', dp.id, 'context.data_product.changed',
           jsonb_build_object('data_product_id', dp.id, 'data_space_id', dp.data_space_id,
                              'code', dp.code, 'version', dp.version, 'status', dp.status,
                              'classification', dp.classification)
      FROM context.data_product dp WHERE dp.id = v_product;
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER data_product_member_classify
  AFTER INSERT OR DELETE OR UPDATE OF classification, data_product_id, member_kind, member_ref, role
  ON context.data_product_member
  FOR EACH ROW EXECUTE FUNCTION context.data_product_member_classify();

-- Called on context.metric_version.superseded (no certified version left) or
-- catalog.dataset_version.certification_revoked (member_ref = the dataset id): active products
-- built on that primary member are suspended. Returns the number of products.
CREATE FUNCTION context.data_product_on_member_decertified(p_member_kind text, p_member_ref uuid)
RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer;
BEGIN
  UPDATE context.data_product dp
     SET status = 'suspended', updated_at = now(),
         suspended_reason = CASE p_member_kind WHEN 'metric' THEN 'metric_decertified'
                                               WHEN 'dataset' THEN 'dataset_decertified'
                                               ELSE p_member_kind || '_decertified' END
   WHERE dp.status = 'active'
     AND EXISTS (SELECT 1 FROM context.data_product_member m
                  WHERE m.data_product_id = dp.id AND m.role = 'primary'
                    AND m.member_kind = p_member_kind AND m.member_ref = p_member_ref);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- covers: context.data_product_member#1
-- A retired product takes no member changes; an active one only loses reference members: dropping
-- a primary one changes the commitment and goes through a new version (UC-07-13 6a).
CREATE FUNCTION context.data_product_member_guard()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_status text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT status INTO v_status FROM context.data_product WHERE id = OLD.data_product_id;
    IF v_status = 'active' AND OLD.role = 'primary' THEN
      RAISE EXCEPTION 'Data product đang active chỉ gỡ được thành phần reference; gỡ thành phần primary phải qua phiên bản mới (UC-07-13)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  SELECT status INTO v_status FROM context.data_product WHERE id = NEW.data_product_id;
  IF v_status = 'retired' THEN
    RAISE EXCEPTION 'Data product đã ngừng (retired) không nhận thay đổi thành phần (BR-175)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER data_product_member_guard BEFORE INSERT OR UPDATE OR DELETE ON context.data_product_member
  FOR EACH ROW EXECUTE FUNCTION context.data_product_member_guard();

-- Cron (5 fields, local time) matching for the freshness schedule: '*', 'a', 'a-b', lists and '/n'.
CREATE FUNCTION context.cron_field_matches(field text, val integer, field_min integer, field_max integer)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
  part text; range_part text; step integer; lo integer; hi integer;
BEGIN
  FOREACH part IN ARRAY string_to_array(field, ',') LOOP
    step := 1;
    range_part := part;
    IF position('/' IN part) > 0 THEN
      step := split_part(part, '/', 2)::integer;
      range_part := split_part(part, '/', 1);
    END IF;
    IF range_part = '*' THEN
      lo := field_min; hi := field_max;
    ELSIF position('-' IN range_part) > 0 THEN
      lo := split_part(range_part, '-', 1)::integer; hi := split_part(range_part, '-', 2)::integer;
    ELSE
      lo := range_part::integer;
      hi := CASE WHEN position('/' IN part) > 0 THEN field_max ELSE lo END;
    END IF;
    IF val BETWEEN lo AND hi AND (val - lo) % step = 0 THEN
      RETURN true;
    END IF;
  END LOOP;
  RETURN false;
END $$;

-- Day part of a cron: day of month and month, and day of week (0 or 7 = Sunday); when both day
-- fields are restricted either one matching is enough, as in cron.
CREATE FUNCTION context.cron_day_matches(fields text[], d date)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT context.cron_field_matches(fields[4], extract(month FROM d)::integer, 1, 12)
     AND CASE
           WHEN fields[3] <> '*' AND fields[5] <> '*' THEN
             context.cron_field_matches(fields[3], extract(day FROM d)::integer, 1, 31)
             OR context.cron_field_matches(fields[5], extract(dow FROM d)::integer, 0, 7)
             OR (extract(dow FROM d) = 0 AND context.cron_field_matches(fields[5], 7, 0, 7))
           ELSE
             context.cron_field_matches(fields[3], extract(day FROM d)::integer, 1, 31)
             AND (context.cron_field_matches(fields[5], extract(dow FROM d)::integer, 0, 7)
                  OR (extract(dow FROM d) = 0 AND context.cron_field_matches(fields[5], 7, 0, 7)))
         END
$$;

-- A deadline on a non-working day of the work calendar moves to the next working day, same local
-- time. svc_context reads org.work_calendar* through org_read.
CREATE FUNCTION context.data_product_shift_deadline(p_deadline timestamptz, p_calendar_id uuid, p_timezone text)
RETURNS timestamptz LANGUAGE plpgsql STABLE AS $$
DECLARE
  v_local timestamp := p_deadline AT TIME ZONE p_timezone;
  v_day date := (p_deadline AT TIME ZONE p_timezone)::date;
  v_weekend smallint[];
  v_kind text;
BEGIN
  IF p_calendar_id IS NULL THEN
    RETURN p_deadline;
  END IF;
  SELECT weekend_days INTO v_weekend FROM org.work_calendar WHERE id = p_calendar_id;
  FOR i IN 0 .. 60 LOOP
    SELECT kind INTO v_kind FROM org.work_calendar_day WHERE calendar_id = p_calendar_id AND day = v_day;
    EXIT WHEN v_kind = 'working_override'
           OR (v_kind IS NULL AND NOT coalesce(extract(isodow FROM v_day)::smallint = ANY (v_weekend), false));
    v_day := v_day + 1;
  END LOOP;
  RETURN (v_day + v_local::time) AT TIME ZONE p_timezone;
END $$;

-- SECURITY DEFINER: svc_context has no monitor_read (D5.2) but the schedule of a member may follow
-- an external event calendar (P08). It returns only the event times of the caller's organisation.
CREATE FUNCTION context.data_product_calendar_events(p_data_space_id uuid, p_code text)
RETURNS SETOF timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT coalesce(e.occurred_at, e.expected_at)
    FROM monitor.external_calendar c
    JOIN monitor.external_event e ON e.calendar_id = c.id AND e.org_id = c.org_id
   WHERE c.org_id = NULLIF(current_setting('app.org_id', true), '')::uuid
     AND c.data_space_id = p_data_space_id AND c.code = p_code AND e.status <> 'cancelled'
$$;
REVOKE EXECUTE ON FUNCTION context.data_product_calendar_events(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION context.data_product_calendar_events(uuid, text) TO svc_context;

-- The scheduled deadline of a member closest to p_bound: the latest one not after it, or with
-- p_next the earliest one after it (both already moved off non-working days). With an event
-- calendar the days come from its events and the cron only gives the time of day.
CREATE FUNCTION context.data_product_sla_deadline(p_member_id uuid, p_bound timestamptz, p_next boolean)
RETURNS timestamptz LANGUAGE plpgsql STABLE AS $$
DECLARE
  m record;
  f text[];
  v_tz text;
  v_day date;
  v_raw timestamptz;
  v_shifted timestamptz;
  v_best timestamptz;
  v_hours integer[];
  v_minutes integer[];
  h integer;
  mi integer;
BEGIN
  SELECT mb.*, dp.data_space_id INTO m
    FROM context.data_product_member mb JOIN context.data_product dp ON dp.id = mb.data_product_id
   WHERE mb.id = p_member_id;
  IF NOT FOUND OR m.sla_kind <> 'schedule' THEN
    RETURN NULL;
  END IF;
  v_tz := m.sla_timezone;
  IF m.sla_cron IS NOT NULL THEN
    f := regexp_split_to_array(btrim(m.sla_cron), '\s+');
    SELECT array_agg(x ORDER BY x) INTO v_hours FROM generate_series(0, 23) x
     WHERE context.cron_field_matches(f[2], x, 0, 23);
    SELECT array_agg(x ORDER BY x) INTO v_minutes FROM generate_series(0, 59) x
     WHERE context.cron_field_matches(f[1], x, 0, 59);
  END IF;

  IF m.sla_event_calendar_code IS NOT NULL THEN
    FOR v_raw IN SELECT * FROM context.data_product_calendar_events(m.data_space_id, m.sla_event_calendar_code) LOOP
      IF f IS NOT NULL THEN
        v_raw := (((v_raw AT TIME ZONE v_tz)::date) + make_time(v_hours[1], v_minutes[1], 0)) AT TIME ZONE v_tz;
      END IF;
      v_shifted := context.data_product_shift_deadline(v_raw, m.sla_work_calendar_id, v_tz);
      IF NOT p_next AND v_shifted <= p_bound AND (v_best IS NULL OR v_shifted > v_best) THEN
        v_best := v_shifted;
      ELSIF p_next AND v_shifted > p_bound AND (v_best IS NULL OR v_shifted < v_best) THEN
        v_best := v_shifted;
      END IF;
    END LOOP;
    RETURN v_best;
  END IF;

  IF f IS NULL OR v_hours IS NULL OR v_minutes IS NULL THEN
    RETURN NULL;
  END IF;
  -- Shifting is monotone, so scanning raw deadlines in order gives the closest shifted one first.
  -- A year of days covers any five-field cron; the forward scan starts a little early because a
  -- deadline before the bound can be shifted past it.
  IF NOT p_next THEN
    v_day := (p_bound AT TIME ZONE v_tz)::date;
    FOR i IN 0 .. 400 LOOP
      IF context.cron_day_matches(f, v_day) THEN
        FOR hi IN REVERSE array_length(v_hours, 1) .. 1 LOOP
          FOR mj IN REVERSE array_length(v_minutes, 1) .. 1 LOOP
            v_raw := (v_day + make_time(v_hours[hi], v_minutes[mj], 0)) AT TIME ZONE v_tz;
            CONTINUE WHEN v_raw > p_bound;
            v_shifted := context.data_product_shift_deadline(v_raw, m.sla_work_calendar_id, v_tz);
            IF v_shifted <= p_bound THEN
              RETURN v_shifted;
            END IF;
          END LOOP;
        END LOOP;
      END IF;
      v_day := v_day - 1;
    END LOOP;
  ELSE
    v_day := (p_bound AT TIME ZONE v_tz)::date - 31;
    FOR i IN 0 .. 431 LOOP
      IF context.cron_day_matches(f, v_day) THEN
        FOREACH h IN ARRAY v_hours LOOP
          FOREACH mi IN ARRAY v_minutes LOOP
            v_raw := (v_day + make_time(h, mi, 0)) AT TIME ZONE v_tz;
            v_shifted := context.data_product_shift_deadline(v_raw, m.sla_work_calendar_id, v_tz);
            IF v_shifted > p_bound THEN
              RETURN v_shifted;
            END IF;
          END LOOP;
        END LOOP;
      END IF;
      v_day := v_day + 1;
    END LOOP;
  END IF;
  RETURN NULL;
END $$;

-- Freshness of one member at p_at (BR-178), run after each load, every 5 minutes for members whose
-- next_due_at has passed and by the freshness.check tool. Returns the new freshness_state.
CREATE FUNCTION context.data_product_freshness_refresh(p_member_id uuid, p_at timestamptz DEFAULT now())
RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  m context.data_product_member%ROWTYPE;
  v_due timestamptz;
  v_expected timestamptz;
  v_next timestamptz;
  v_state text;
BEGIN
  SELECT * INTO m FROM context.data_product_member WHERE id = p_member_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  IF m.sla_kind = 'schedule' THEN
    v_due := context.data_product_sla_deadline(m.id, p_at - m.sla_grace, false);
    v_next := context.data_product_sla_deadline(m.id, p_at - m.sla_grace, true);
    v_expected := ((v_due AT TIME ZONE m.sla_timezone)::date)::timestamp AT TIME ZONE m.sla_timezone;
    v_state := CASE WHEN v_due IS NULL THEN 'unknown'
                    WHEN m.last_as_of IS NULL THEN 'missing'
                    WHEN m.last_as_of >= v_expected THEN 'fresh'
                    ELSE 'overdue' END;
  ELSIF m.sla_kind = 'max_age' THEN
    v_expected := p_at - m.sla_max_age - m.sla_grace;
    v_next := m.last_as_of + m.sla_max_age + m.sla_grace;
    v_state := CASE WHEN m.last_as_of IS NULL THEN 'missing'
                    WHEN p_at - m.last_as_of <= m.sla_max_age + m.sla_grace THEN 'fresh'
                    ELSE 'overdue' END;
  ELSE
    v_state := 'unknown';
  END IF;
  UPDATE context.data_product_member
     SET expected_as_of = v_expected, next_due_at = v_next, freshness_state = v_state,
         last_checked_at = p_at
   WHERE id = m.id;
  IF v_state IS DISTINCT FROM m.freshness_state THEN
    INSERT INTO context.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), m.org_id, 'data_product_member', m.id, 'context.data_product.freshness_changed',
            jsonb_build_object('data_product_id', m.data_product_id, 'member_id', m.id,
                               'from', m.freshness_state, 'to', v_state,
                               'expected_as_of', v_expected, 'last_as_of', m.last_as_of,
                               'checked_at', p_at));
  END IF;
  RETURN v_state;
END $$;

-- ─── routines/qa.sql ───
-- routines/qa.sql: what D4.6 (tab 3b) writes in words for schema qa: the number-check and scope
-- CHECKs of qa.answer, the answer receipt (BR-175, BR-176: numbered, sealed with a SHA-256, append
-- only, kept until retain_until), its figures, the receipt replay (BR-179), the extra RLS that
-- ties figures and replays to a visible receipt, and the D5.2 grant exception of svc_qa.

-- covers: qa.answer#0
-- BR-171: an answer is stored only once every number in it traces to a source.
ALTER TABLE qa.answer ADD CONSTRAINT answer_untraceable_final_check
  CHECK (jsonb_typeof(number_check) = 'object' AND coalesce((number_check->>'untraceable_final')::int, 0) = 0);

-- covers: qa.answer#1
-- BR-175: only answers that carry numbers can be in the scope of a data product.
ALTER TABLE qa.answer ADD CONSTRAINT answer_in_scope_kind_check
  CHECK (product_scope <> 'in_scope' OR kind IN ('data', 'mixed', 'forecast'));


-- covers: qa.answer_receipt#0
-- Whoever reads a receipt must be able to read its answer (qa.answer's own RLS decides). Masking the
-- numbers by the viewer's rights is done by the Policy engine in the application, as for qa.answer
-- (D1.3: rights inside a Data Space are checked in the application).
CREATE POLICY answer_receipt_answer_visible ON qa.answer_receipt AS RESTRICTIVE FOR SELECT
  USING (EXISTS (SELECT 1 FROM qa.answer a WHERE a.id = answer_id));

-- covers: qa.answer_receipt#1
-- BR-175/BR-176: a receipt belongs to an in-scope answer of the same data product, is numbered per
-- organisation and day of answered_at (UTC, D1.9), and starts unsealed: figures are added, then the
-- receipt is sealed once. After that nothing changes; only the retention job removes it once
-- retain_until has passed. Writing the receipt in the answer's transaction and hiding numbers of an
-- in-scope answer without a sealed receipt are Agent runtime rules.
-- The receipt's SHA-256: the normalised JSON of the row (minus the hash and the retention columns)
-- and its figures ordered by figure_key. jsonb prints keys in a fixed order, but a timestamptz in
-- it is printed in the session's TimeZone, so the function pins TimeZone to UTC: the seal and a
-- later ?verify (GET /v1/receipts/{no}) from another session must produce the same digest.
CREATE FUNCTION qa.receipt_digest(r qa.answer_receipt) RETURNS text
LANGUAGE sql STABLE SET TimeZone = 'UTC' AS $$
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'receipt', to_jsonb(r) - ARRAY['receipt_sha256', 'sealed_at', 'retain_until', 'created_at'],
    'figures', coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.figure_key)
                         FROM qa.answer_receipt_figure f WHERE f.receipt_id = r.id), '[]'::jsonb)
  )::text, 'UTF8')), 'hex')
$$;

CREATE FUNCTION qa.answer_receipt_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  a_scope text;
  a_product uuid;
  prefix text;
  last_no integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT product_scope, data_product_id INTO a_scope, a_product FROM qa.answer WHERE id = NEW.answer_id;
    IF a_scope IS DISTINCT FROM 'in_scope' OR a_product IS DISTINCT FROM NEW.data_product_id THEN
      RAISE EXCEPTION 'Biên nhận chỉ cấp cho câu trả lời trong phạm vi cùng data product (BR-175)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.sealed_at IS NOT NULL OR NEW.receipt_sha256 IS NOT NULL THEN
      RAISE EXCEPTION 'Biên nhận mới chưa được khoá; khoá sau khi ghi đủ số (BR-176)'
        USING ERRCODE = 'check_violation';
    END IF;
    -- Serialise numbering per organisation and day so two answers never get the same receipt_no.
    prefix := 'BN-' || to_char(NEW.answered_at AT TIME ZONE 'UTC', 'YYYYMMDD') || '-';
    PERFORM pg_advisory_xact_lock(hashtextextended('qa.answer_receipt:' || NEW.org_id || ':' || prefix, 0));
    SELECT max(substr(receipt_no, 13)::integer) INTO last_no
      FROM qa.answer_receipt WHERE org_id = NEW.org_id AND receipt_no LIKE prefix || '%';
    NEW.receipt_no := prefix || lpad((coalesce(last_no, 0) + 1)::text, 6, '0');
    NEW.figure_count := 0;
    NEW.masked_count := 0;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.sealed_at IS NOT NULL OR NEW.sealed_at IS NULL
       OR to_jsonb(NEW) - ARRAY['sealed_at', 'figure_count', 'masked_count', 'receipt_sha256']
          IS DISTINCT FROM to_jsonb(OLD) - ARRAY['sealed_at', 'figure_count', 'masked_count', 'receipt_sha256'] THEN
      RAISE EXCEPTION 'Biên nhận chỉ ghi thêm: chỉ được đặt sealed_at một lần (BR-176)'
        USING ERRCODE = 'check_violation';
    END IF;
    SELECT count(*), count(*) FILTER (WHERE display_state <> 'shown')
      INTO NEW.figure_count, NEW.masked_count
      FROM qa.answer_receipt_figure WHERE receipt_id = NEW.id;
    NEW.receipt_sha256 := qa.receipt_digest(NEW);
    RETURN NEW;
  ELSE
    IF OLD.retain_until >= current_date THEN
      RAISE EXCEPTION 'Biên nhận còn trong hạn lưu giữ, không được xoá (BR-176)'
        USING ERRCODE = 'check_violation';
    END IF;
    PERFORM qa.answer_receipt_purge_figures(OLD.id);
    RETURN OLD;
  END IF;
END
$$;

-- Figures go with their receipt. svc_qa has no DELETE on qa.answer_receipt_figure (D5.2), so the
-- receipt's retention delete removes them as the owner; the figure trigger still checks the date.
CREATE FUNCTION qa.answer_receipt_purge_figures(receipt uuid) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  DELETE FROM qa.answer_receipt_figure WHERE receipt_id = receipt;
$$;
REVOKE ALL ON FUNCTION qa.answer_receipt_purge_figures(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION qa.answer_receipt_purge_figures(uuid) TO svc_qa;

CREATE TRIGGER answer_receipt_guard BEFORE INSERT OR UPDATE OR DELETE ON qa.answer_receipt
  FOR EACH ROW EXECUTE FUNCTION qa.answer_receipt_guard();

-- D5.2 (BR-176): svc_qa may only set sealed_at; DELETE stays for the retention job (trigger above).
REVOKE UPDATE ON qa.answer_receipt FROM svc_qa;
GRANT UPDATE (sealed_at) ON qa.answer_receipt TO svc_qa;


-- covers: qa.answer_receipt_figure#0
CREATE POLICY answer_receipt_figure_receipt_visible ON qa.answer_receipt_figure AS RESTRICTIVE FOR SELECT
  USING (EXISTS (SELECT 1 FROM qa.answer_receipt r WHERE r.id = receipt_id));

-- covers: qa.answer_receipt_figure#1
-- BR-176: figures are added only before the seal and never change; they are deleted only together
-- with a receipt past retain_until.
CREATE FUNCTION qa.answer_receipt_figure_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  sealed timestamptz;
  keep_until date;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- FOR SHARE waits for a concurrent seal, so no figure slips in after the hash is taken.
    SELECT sealed_at INTO sealed FROM qa.answer_receipt WHERE id = NEW.receipt_id FOR SHARE;
    IF sealed IS NOT NULL THEN
      RAISE EXCEPTION 'Biên nhận đã khoá, không thêm số (BR-176)' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'Số trong biên nhận chỉ ghi thêm, không sửa (BR-176)' USING ERRCODE = 'check_violation';
  END IF;
  SELECT retain_until INTO keep_until FROM qa.answer_receipt WHERE id = OLD.receipt_id;
  IF keep_until >= current_date THEN
    RAISE EXCEPTION 'Số trong biên nhận còn trong hạn lưu giữ, không được xoá (BR-176)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END
$$;
CREATE TRIGGER answer_receipt_figure_guard BEFORE INSERT OR UPDATE OR DELETE ON qa.answer_receipt_figure
  FOR EACH ROW EXECUTE FUNCTION qa.answer_receipt_figure_guard();

-- D5.2 (BR-176): svc_qa only SELECT, INSERT on figures.
REVOKE UPDATE, DELETE ON qa.answer_receipt_figure FROM svc_qa;


-- covers: qa.receipt_replay#0
CREATE POLICY receipt_replay_receipt_visible ON qa.receipt_replay AS RESTRICTIVE FOR SELECT
  USING (EXISTS (SELECT 1 FROM qa.answer_receipt r WHERE r.id = receipt_id));

-- covers: qa.receipt_replay#1
-- BR-179: an unexplained difference becomes an Error Book entry; the Eval service creates it from
-- the event and Agent runtime writes error_book_entry_id back. Every replay is audited; audit is a
-- separate database (D1.1), so the audit row is requested through the outbox.
CREATE FUNCTION qa.receipt_replay_events() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO qa.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'receipt_replay', NEW.id, 'audit.requested',
            jsonb_build_object('action', 'receipt.replay', 'object_kind', 'answer_receipt',
                               'object_id', NEW.receipt_id, 'before', NULL,
                               'after', jsonb_build_object('replay_id', NEW.id, 'requested_by', NEW.requested_by,
                                                           'mode', NEW.mode, 'reason', NEW.reason)));
  ELSIF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed'
        AND NEW.outcome IN ('differs', 'not_reproducible') THEN
    INSERT INTO qa.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'receipt_replay', NEW.id, 'qa.receipt_replay.mismatch',
            jsonb_build_object('replay_id', NEW.id, 'receipt_id', NEW.receipt_id, 'outcome', NEW.outcome,
                               'differs_count', NEW.differs_count, 'figure_results', NEW.figure_results));
  END IF;
  RETURN NULL;
END
$$;
CREATE TRIGGER receipt_replay_events AFTER INSERT OR UPDATE OF status ON qa.receipt_replay
  FOR EACH ROW EXECUTE FUNCTION qa.receipt_replay_events();

-- ─── routines/agent.sql ───
-- routines/agent.sql: what D4.8 (tab 3b) writes in words for schema agent: the depth guard of
-- multi-agent runs (BR-77) and the indexes Agent runtime uses to detect loops (BR-170).

-- covers: agent.agent_run#0
-- BR-170: the "Lượt chạy" screen lists runs an agent stopped for looping or making no progress.
CREATE INDEX agent_run_agent_id_stop_reason_idx ON agent.agent_run (agent_id, stop_reason)
  WHERE stop_reason IN ('loop_detected', 'no_progress');

-- covers: agent.agent_run#1
-- BR-77: the depth is derived from the parent, never trusted from the service; a parent of another
-- organisation (invisible under RLS, or visible to an admin) or a fourth level is refused.
CREATE FUNCTION agent.agent_run_depth_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  parent_org uuid;
  parent_depth smallint;
BEGIN
  IF NEW.parent_run_id IS NULL THEN
    NEW.depth := 0;
    RETURN NEW;
  END IF;
  SELECT org_id, depth INTO parent_org, parent_depth FROM agent.agent_run WHERE id = NEW.parent_run_id;
  IF NOT FOUND OR parent_org <> NEW.org_id THEN
    RAISE EXCEPTION 'Lượt cha không thuộc tổ chức của lượt con (BR-77)' USING ERRCODE = 'check_violation';
  END IF;
  IF parent_depth >= 3 THEN
    RAISE EXCEPTION 'Lượt chạy con sâu quá 3 tầng (BR-77)' USING ERRCODE = 'check_violation';
  END IF;
  NEW.depth := parent_depth + 1;
  RETURN NEW;
END
$$;
CREATE TRIGGER agent_run_depth_guard BEFORE INSERT OR UPDATE OF parent_run_id, depth ON agent.agent_run
  FOR EACH ROW EXECUTE FUNCTION agent.agent_run_depth_guard();

-- covers: agent.agent_step#0
-- BR-170: Agent runtime counts repeated calls per run; the database only provides the index.
CREATE INDEX agent_step_run_id_call_fingerprint_idx ON agent.agent_step (run_id, call_fingerprint)
  WHERE call_fingerprint IS NOT NULL;

-- covers: agent.tool_def#0
-- ADR-54: the tool register is shared by every organisation and written only by migrations
-- (its rows ship with a release); every service reads it to describe, check and expose tools.
REVOKE INSERT, UPDATE, DELETE ON agent.tool_def FROM svc_agent;
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT rolname FROM pg_roles WHERE rolname LIKE 'svc\_%' LOOP
    EXECUTE format('GRANT USAGE ON SCHEMA agent TO %I', r.rolname);
    EXECUTE format('GRANT SELECT ON agent.tool_def TO %I', r.rolname);
  END LOOP;
END $$;

-- ─── routines/eval.sql ───
-- routines/eval.sql: what D4.9 (tab 3b) writes in words for schema eval: the Error Book (BR-179):
-- entry numbering, the status machine with its regression proof, the opened/reopened events and the
-- function that reopens an entry when its regression case fails again.

-- covers: eval.error_book_entry#0 (no DDL beyond org_isolation: rights inside a Data Space and masking of detail are checked by the Policy engine in the Eval service, D1.3)

-- covers: eval.error_book_entry#1
-- BR-179: EB-0001… per organisation; open → fixed → regression_added, open → dismissed, and
-- regression_added → open on reopening (a fixed entry does not go back to open). regression_added
-- needs the regression case to pass in a deploy or nightly run started after fixed_at. Filling
-- assignee_id with the product steward and checking that fix_proposal_id is accepted are done by the
-- Eval service (the proposal lives in schema inbox).
CREATE FUNCTION eval.error_book_entry_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  last_no integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('eval.error_book_entry:' || NEW.org_id, 0));
    SELECT max(substr(entry_no, 4)::integer) INTO last_no
      FROM eval.error_book_entry WHERE org_id = NEW.org_id AND entry_no ~ '^EB-[0-9]+$';
    last_no := coalesce(last_no, 0) + 1;
    NEW.entry_no := 'EB-' || lpad(last_no::text, greatest(4, length(last_no::text)), '0');
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND (OLD.status, NEW.status) NOT IN (('open', 'fixed'), ('fixed', 'regression_added'),
                                          ('open', 'dismissed'), ('regression_added', 'open')) THEN
    RAISE EXCEPTION 'Mục Error Book không chuyển được từ % sang % (BR-179)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'regression_added' AND OLD.status = 'fixed' AND NOT EXISTS (
       SELECT 1
         FROM eval.eval_result r
         JOIN eval.eval_run e ON e.id = r.eval_run_id
        WHERE r.eval_item_id = NEW.eval_item_id AND r.passed
          AND e.id = NEW.regression_run_id
          AND e.trigger IN ('deploy', 'nightly')
          AND e.started_at > NEW.fixed_at) THEN
    RAISE EXCEPTION 'Ca hồi quy chưa đạt trong lần chạy deploy hoặc nightly sau fixed_at (BR-179)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER error_book_entry_guard BEFORE INSERT OR UPDATE ON eval.error_book_entry
  FOR EACH ROW EXECUTE FUNCTION eval.error_book_entry_guard();

-- The Notification service tells the assignee.
CREATE FUNCTION eval.error_book_entry_opened() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO eval.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'error_book_entry', NEW.id, 'eval.error_book.opened',
          jsonb_build_object('entry_id', NEW.id, 'entry_no', NEW.entry_no, 'source_kind', NEW.source_kind,
                             'data_space_id', NEW.data_space_id, 'data_product_id', NEW.data_product_id,
                             'assignee_id', NEW.assignee_id, 'severity', NEW.severity, 'title', NEW.title));
  RETURN NULL;
END
$$;
CREATE TRIGGER error_book_entry_opened AFTER INSERT ON eval.error_book_entry
  FOR EACH ROW EXECUTE FUNCTION eval.error_book_entry_opened();

-- Called by the Eval service when an eval_result of the item has passed = false: the closed entries
-- of that regression case reopen. Returns how many reopened.
CREATE FUNCTION eval.error_book_on_regression_failed(item_id uuid) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  e eval.error_book_entry%ROWTYPE;
  n integer := 0;
BEGIN
  FOR e IN
    UPDATE eval.error_book_entry
       SET status = 'open', reopened_count = reopened_count + 1, updated_at = now()
     WHERE eval_item_id = item_id AND status = 'regression_added'
    RETURNING *
  LOOP
    INSERT INTO eval.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), e.org_id, 'error_book_entry', e.id, 'eval.error_book.reopened',
            jsonb_build_object('entry_id', e.id, 'entry_no', e.entry_no, 'eval_item_id', item_id,
                               'reopened_count', e.reopened_count, 'assignee_id', e.assignee_id));
    n := n + 1;
  END LOOP;
  RETURN n;
END
$$;
REVOKE ALL ON FUNCTION eval.error_book_on_regression_failed(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION eval.error_book_on_regression_failed(uuid) TO svc_eval;

-- ─── nightly runs ────────────────────────────────────────────────────────────────────────────────

-- SECURITY DEFINER: the nightly scheduler (worker_agent/nightly_evals.py, a CronJob) runs for every
-- organisation, and every eval table is org_isolated. This lists only what a nightly run needs to
-- be requested, the active context eval sets of active Data Spaces whose steward is an active user,
-- whom the run is requested for (each item is answered as its author, eval_runs.run_eval); it reads
-- no item, result or answer, and only svc_eval may call it.
CREATE FUNCTION eval.nightly_eval_sets()
RETURNS TABLE (org_id uuid, eval_set_id uuid, data_space_id uuid, steward_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT s.org_id, s.id, s.data_space_id, d.steward_id
    FROM eval.eval_set s
    JOIN org.data_space d ON d.id = s.data_space_id AND d.org_id = s.org_id
    JOIN org.app_user u ON u.id = d.steward_id AND u.org_id = d.org_id
   WHERE s.subject_type = 'context' AND s.status = 'active' AND d.status = 'active'
     AND u.status = 'active'
$$;
REVOKE EXECUTE ON FUNCTION eval.nightly_eval_sets() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION eval.nightly_eval_sets() TO svc_eval;

-- ─── routines/workspace.sql ───
-- routines/workspace.sql: what D4.11 (tab 3b) writes in words for schema workspace: the tile
-- position uniqueness, deferred so a reorder can swap positions inside one transaction.

-- covers: workspace.tile#0
ALTER TABLE workspace.tile ADD CONSTRAINT tile_workspace_id_position_key
  UNIQUE (workspace_id, position) DEFERRABLE INITIALLY DEFERRED;

-- The upload worker writes rows through a SECURITY DEFINER boundary so it never needs DDL
-- privileges on workspace. Explicit JSON element aliases avoid collisions with PL/pgSQL variables
-- when an uploaded header is named `value`.
GRANT USAGE ON SCHEMA workspace TO svc_query;
CREATE OR REPLACE FUNCTION public.da_materialize_upload(
  p_table_name text,
  p_columns jsonb,
  p_rows jsonb,
  p_replace boolean DEFAULT false
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $fn$
DECLARE
  column_def text := '';
  column_names text := '';
  values_sql text;
  item jsonb;
  value jsonb;
  row_index integer;
  first_column boolean := true;
BEGIN
  IF p_table_name !~ '^[a-z][a-z0-9_]{0,62}$' THEN
    RAISE EXCEPTION 'invalid upload table name';
  END IF;
  IF jsonb_array_length(p_columns) = 0 OR jsonb_array_length(p_columns) > 2000 THEN
    RAISE EXCEPTION 'invalid upload columns';
  END IF;
  FOR item IN SELECT column_item FROM jsonb_array_elements(p_columns) AS elements(column_item)
  LOOP
    IF (item->>'name') !~ '^[a-z][a-z0-9_]{0,62}$' THEN
      RAISE EXCEPTION 'invalid upload column name';
    END IF;
    IF (item->>'type') NOT IN ('text', 'numeric', 'boolean', 'date') THEN
      RAISE EXCEPTION 'invalid upload column type';
    END IF;
    IF NOT first_column THEN
      column_def := column_def || ', ';
      column_names := column_names || ', ';
    END IF;
    first_column := false;
    column_def := column_def || format('%I %s', item->>'name', item->>'type');
    column_names := column_names || format('%I', item->>'name');
  END LOOP;
  IF p_replace OR to_regclass(format('workspace.%I', p_table_name)) IS NULL THEN
    EXECUTE format('DROP TABLE IF EXISTS workspace.%I', p_table_name);
    EXECUTE format('CREATE TABLE workspace.%I (%s)', p_table_name, column_def);
    EXECUTE format('GRANT SELECT ON TABLE workspace.%I TO svc_query', p_table_name);
  END IF;
  row_index := 0;
  FOR item IN SELECT row_item FROM jsonb_array_elements(p_rows) AS elements(row_item)
  LOOP
    values_sql := '';
    FOR value IN SELECT row_value FROM jsonb_array_elements(item) AS elements(row_value)
    LOOP
      IF row_index > 0 THEN
        values_sql := values_sql || ', ';
      END IF;
      values_sql := values_sql || CASE
        WHEN value IS NULL OR value = 'null'::jsonb OR value #>> '{}' = '' THEN 'NULL'
        ELSE quote_nullable(value #>> '{}')
      END;
      row_index := row_index + 1;
    END LOOP;
    EXECUTE format('INSERT INTO workspace.%I (%s) VALUES (%s)', p_table_name, column_names, values_sql);
    row_index := 0;
  END LOOP;
END
$fn$;
ALTER FUNCTION public.da_materialize_upload(text, jsonb, jsonb, boolean) OWNER TO da_owner;
GRANT EXECUTE ON FUNCTION public.da_materialize_upload(text, jsonb, jsonb, boolean) TO svc_ingest;

-- ─── routines/skill.sql ───
-- routines/skill.sql: what the skill schema enforces beyond its CHECKs (tab 3b D4, tab 8).

-- AC-03-06-04, BR-97: a version that has run is never deleted, so an old skill_run still shows
-- how it computed; retiring hides it from the library instead.
CREATE FUNCTION skill.skill_version_keep_if_run() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM skill.skill_run r WHERE r.skill_version_id = OLD.id) THEN
    RAISE EXCEPTION 'Phiên bản kỹ năng đã chạy không xoá được; hãy ngừng dùng (BR-97)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN OLD;
END $$;
CREATE TRIGGER skill_version_keep_if_run BEFORE DELETE ON skill.skill_version
  FOR EACH ROW EXECUTE FUNCTION skill.skill_version_keep_if_run();

-- ─── routines/monitor.sql ───
-- routines/monitor.sql: what D4.13 (tab 3b) writes in words for schema monitor: the status machine
-- of an external calendar event and the bulletin time derived from its calendar (BR-187).

-- covers: monitor.external_event#0
-- BR-187: expected → confirmed, shifted, cancelled, occurred; confirmed → shifted, cancelled,
-- occurred; shifted → confirmed, cancelled, occurred (occurred and cancelled are final). When the
-- period moves, the old time is kept in shifted_from and the pre-bulletin time is recomputed from the
-- calendar: pre_bulletin_days_before days earlier at pre_bulletin_local_time, in the calendar's
-- timezone. The time is also derived on insert when the service does not give one. Every change is
-- announced on monitor.outbox for the bulletin workflow.
CREATE FUNCTION monitor.external_event_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  cal monitor.external_calendar%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status
     AND (OLD.status, NEW.status) NOT IN (
       ('expected', 'confirmed'), ('expected', 'shifted'), ('expected', 'cancelled'), ('expected', 'occurred'),
       ('confirmed', 'shifted'), ('confirmed', 'cancelled'), ('confirmed', 'occurred'),
       ('shifted', 'confirmed'), ('shifted', 'cancelled'), ('shifted', 'occurred')) THEN
    RAISE EXCEPTION 'Kỳ sự kiện không chuyển được từ % sang % (BR-187)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.pre_bulletin_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' OR NEW.expected_at IS DISTINCT FROM OLD.expected_at THEN
    IF TG_OP = 'UPDATE' THEN
      NEW.shifted_from := OLD.expected_at;
    END IF;
    SELECT * INTO cal FROM monitor.external_calendar WHERE id = NEW.calendar_id;
    IF FOUND THEN
      NEW.pre_bulletin_at :=
        ((NEW.expected_at AT TIME ZONE cal.timezone)::date - cal.pre_bulletin_days_before
         + cal.pre_bulletin_local_time) AT TIME ZONE cal.timezone;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER external_event_guard BEFORE INSERT OR UPDATE ON monitor.external_event
  FOR EACH ROW EXECUTE FUNCTION monitor.external_event_guard();

CREATE FUNCTION monitor.external_event_changed() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF to_jsonb(NEW) - 'updated_at' IS DISTINCT FROM to_jsonb(OLD) - 'updated_at' THEN
    INSERT INTO monitor.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'external_event', NEW.id, 'monitor.external_event.changed',
            jsonb_build_object('event_id', NEW.id, 'calendar_id', NEW.calendar_id,
                               'period_label', NEW.period_label, 'status', NEW.status,
                               'previous_status', OLD.status, 'expected_at', NEW.expected_at,
                               'shifted_from', NEW.shifted_from, 'pre_bulletin_at', NEW.pre_bulletin_at,
                               'occurred_at', NEW.occurred_at));
  END IF;
  RETURN NULL;
END
$$;
CREATE TRIGGER external_event_changed AFTER UPDATE ON monitor.external_event
  FOR EACH ROW EXECUTE FUNCTION monitor.external_event_changed();

-- ─── routines/document.sql ───
-- routines/document.sql: what D4.15 (tab 3b) writes in words for schema document: the full-text
-- index on chunk text used for keyword search next to the Qdrant vectors.

-- covers: document.chunk#0
-- 'simple' configuration: no stemming dictionary fits Vietnamese, so words are matched as written.
CREATE INDEX chunk_text_idx ON document.chunk USING gin (to_tsvector('simple', text));

-- ─── routines/conflict.sql ───
-- routines/conflict.sql: what the conflict schema enforces beyond its CHECKs (tab 3b D4.16).

-- covers: conflict.source_authority#0
-- UC-07-05: editing an active ranking makes a new draft; the active one keeps applying until the
-- draft is approved. Approving the draft supersedes the active one in the same statement, before
-- the partial unique index (one active per data_space_id, data_kind) checks the new row.
CREATE FUNCTION conflict.source_authority_supersede() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE conflict.source_authority SET status = 'superseded', updated_at = now()
   WHERE data_space_id = NEW.data_space_id AND data_kind = NEW.data_kind
     AND status = 'active' AND id <> NEW.id;
  RETURN NEW;
END $$;
CREATE TRIGGER source_authority_supersede BEFORE UPDATE OF status ON conflict.source_authority
  FOR EACH ROW WHEN (NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active')
  EXECUTE FUNCTION conflict.source_authority_supersede();

-- ─── routines/acquire.sql ───
-- routines/acquire.sql: what D4.22 (tab 3b) writes in words for the acquire schema (P14 crawl
-- sources, legal review, schema drift, reference entities, consolidation): prose CHECKs and
-- indexes, the "Bổ sung 10/10/2026" amendments, the guard triggers, and the D5.2 append-only
-- exception on crawl_page. Runs as da_owner after the generated tables, FKs, RLS and grants.


-- ═══ crawl_source ═══

-- covers: acquire.crawl_source#0
-- UC-14-04: the review gate may skip human review only after the four most recent sampled runs
-- of the source all reached 98% on the random sample. Runs without a sample (failed, still
-- fetching) do not count as a lượt mẫu.
CREATE FUNCTION acquire.crawl_source_review_gate_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  good integer;
BEGIN
  IF NEW.review_gate = 'auto' AND (TG_OP = 'INSERT' OR OLD.review_gate IS DISTINCT FROM 'auto') THEN
    SELECT count(*) FILTER (WHERE r.sample_accuracy >= 0.98) INTO good
    FROM (
      SELECT sample_accuracy FROM acquire.crawl_run
      WHERE source_id = NEW.id AND sample_accuracy IS NOT NULL
      ORDER BY coalesce(finished_at, started_at, created_at) DESC
      LIMIT 4
    ) r;
    IF good < 4 THEN
      RAISE EXCEPTION 'Cổng tự động chỉ bật khi 4 lượt gần nhất có độ chính xác mẫu ≥ 98%% (UC-14-04)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER crawl_source_review_gate_guard
  BEFORE INSERT OR UPDATE OF review_gate ON acquire.crawl_source
  FOR EACH ROW EXECUTE FUNCTION acquire.crawl_source_review_gate_guard();

-- covers: acquire.crawl_source#1
-- BR-174: an approval is complete (reviewer, time, terms page and its hash, the four checklist
-- items, at least one piece of evidence) and is due for review within 184 days.
ALTER TABLE acquire.crawl_source ADD CONSTRAINT crawl_source_legal_approval_check CHECK (
  legal_status <> 'approved' OR (
    legal_reviewed_by IS NOT NULL AND legal_reviewed_at IS NOT NULL
    AND terms_url IS NOT NULL AND terms_sha256 IS NOT NULL
    AND legal_review_due_at > legal_reviewed_at
    AND legal_review_due_at <= legal_reviewed_at + interval '184 days'
    AND legal_checklist ?& ARRAY['terms','robots','copyright','personal_data']
    AND jsonb_array_length(legal_evidence) >= 1
  )
);

-- covers: acquire.crawl_source#2
ALTER TABLE acquire.crawl_source ADD CONSTRAINT crawl_source_terms_sha256_check
  CHECK (terms_sha256 IS NULL OR terms_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE acquire.crawl_source ADD CONSTRAINT crawl_source_terms_observed_sha256_check
  CHECK (terms_observed_sha256 IS NULL OR terms_observed_sha256 ~ '^[0-9a-f]{64}$');

-- covers: acquire.crawl_source#3
-- BR-174: changed terms void the approval; a source that was active and loses its approval
-- (changed terms, or the review date has passed) pauses itself instead of failing the write of
-- the daily terms check; turning a source on without a valid approval is refused.
CREATE FUNCTION acquire.crawl_source_legal_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.legal_status = 'approved' AND NEW.terms_observed_sha256 IS NOT NULL
     AND NEW.terms_observed_sha256 IS DISTINCT FROM NEW.terms_sha256 THEN
    NEW.legal_status := 'expired';
  END IF;
  IF NEW.status = 'active'
     AND (NEW.legal_status <> 'approved' OR NEW.legal_review_due_at <= now()) THEN
    IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN
      NEW.status := 'paused';
    ELSE
      RAISE EXCEPTION 'Nguồn chỉ bật khi đã duyệt pháp lý và chưa quá hạn xem lại (BR-174)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER crawl_source_legal_guard
  BEFORE INSERT OR UPDATE ON acquire.crawl_source
  FOR EACH ROW EXECUTE FUNCTION acquire.crawl_source_legal_guard();

-- Same rule seen from the crawler (tab 3 D5.4 "tải khi duyệt hết hiệu lực"): no page is stored
-- for a source whose legal approval is not in force, even if its run started before it lapsed.
CREATE FUNCTION acquire.crawl_page_legal_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM acquire.crawl_source s
    WHERE s.id = NEW.source_id AND s.legal_status = 'approved' AND s.legal_review_due_at > now()
  ) THEN
    RAISE EXCEPTION 'Không tải trang khi duyệt pháp lý của nguồn hết hiệu lực (BR-174)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER crawl_page_legal_guard
  BEFORE INSERT ON acquire.crawl_page
  FOR EACH ROW EXECUTE FUNCTION acquire.crawl_page_legal_guard();

-- D5.2 (BR-150): raw pages are append-only. The generated grants already give svc_acquire only
-- SELECT, INSERT on this "Bản ghi bất biến" table; the revoke states the exception explicitly.
REVOKE UPDATE, DELETE ON acquire.crawl_page FROM svc_acquire;


-- ═══ crawl_run ═══

-- covers: acquire.crawl_run#0
-- covers: acquire.schema_drift#1
-- crawl_run_publish_guard. BR-152: only an approved schema version (active, or superseded after
-- it was active) may publish. BR-153: nothing pending or flagged may remain in the run.
-- BR-168: an open semantic drift on the source blocks publishing every run of that source,
-- including later ones, until a human resolves it.
CREATE FUNCTION acquire.crawl_run_publish_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = 'published' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'published') THEN
    IF NOT EXISTS (
      SELECT 1 FROM acquire.crawl_schema_version v
      WHERE v.id = NEW.schema_version_id AND v.status IN ('active','superseded')
    ) THEN
      RAISE EXCEPTION 'Chỉ phát hành lượt trích bằng phiên bản schema active hoặc superseded (BR-152)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1 FROM acquire.extracted_record r
      WHERE r.run_id = NEW.id AND r.status IN ('pending','flagged')
    ) THEN
      RAISE EXCEPTION 'Lượt còn bản ghi pending hoặc flagged, chưa phát hành được (BR-153)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1 FROM acquire.schema_drift d
      WHERE d.source_id = NEW.source_id AND d.drift_kind = 'semantic' AND d.resolution IS NULL
    ) THEN
      RAISE EXCEPTION 'Nguồn còn lệch ngầm chưa đóng, không phát hành lượt nào của nguồn (BR-168)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER crawl_run_publish_guard
  BEFORE INSERT OR UPDATE OF status ON acquire.crawl_run
  FOR EACH ROW EXECUTE FUNCTION acquire.crawl_run_publish_guard();


-- ═══ schema_drift ═══

-- covers: acquire.schema_drift#0
-- BR-168 amendment: semantic drift (same structure, changed meaning) quarantines the run, is
-- always major, carries its evidence, and only a named person closes it, possibly as a false
-- alarm. The generated action / resolution CHECKs predate the amendment, so they are replaced.
DO $$
DECLARE
  c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'acquire.schema_drift'::regclass AND contype = 'c'
      AND (pg_get_constraintdef(oid) LIKE '%action = ANY%'
           OR pg_get_constraintdef(oid) LIKE '%resolution = ANY%')
  LOOP
    EXECUTE format('ALTER TABLE acquire.schema_drift DROP CONSTRAINT %I', c.conname);
  END LOOP;
END
$$;
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_action_check
  CHECK (action IN ('auto_remap','revert','paused','quarantine'));
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_resolution_check
  CHECK (resolution IS NULL OR resolution IN ('approved_new','manual_fix','reverted','false_alarm'));
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_drift_kind_check
  CHECK (drift_kind IN ('structural','semantic'));
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_semantic_action_check
  CHECK ((drift_kind = 'semantic') = (action = 'quarantine'));
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_semantic_severity_check
  CHECK (drift_kind <> 'semantic' OR severity = 'major');
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_semantic_evidence_check
  CHECK (drift_kind <> 'semantic' OR (signals ? 'affected_fields' AND signals ? 'evidence'));
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_false_alarm_check
  CHECK (resolution IS DISTINCT FROM 'false_alarm' OR drift_kind = 'semantic');
ALTER TABLE acquire.schema_drift ADD CONSTRAINT schema_drift_semantic_resolver_check
  CHECK (drift_kind <> 'semantic' OR resolution IS NULL OR resolved_by IS NOT NULL);


-- ═══ entity_link ═══

-- covers: acquire.entity_link#0
-- BR-169 amendment: matching by registry identifier joins the methods; a confirmed link always
-- points at the reference catalogue, and a fuzzy match confirms itself only from 0.95. The FK to
-- reference_entity is already generated (entity_link_reference_entity_id_fkey).
DO $$
DECLARE
  c record;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'acquire.entity_link'::regclass AND contype = 'c'
      AND pg_get_constraintdef(oid) LIKE '%method = ANY%'
  LOOP
    EXECUTE format('ALTER TABLE acquire.entity_link DROP CONSTRAINT %I', c.conname);
  END LOOP;
END
$$;
ALTER TABLE acquire.entity_link ADD CONSTRAINT entity_link_method_check
  CHECK (method IN ('identifier','exact','fuzzy','human'));
ALTER TABLE acquire.entity_link ADD CONSTRAINT entity_link_confirmed_reference_check
  CHECK (status <> 'confirmed' OR reference_entity_id IS NOT NULL);
ALTER TABLE acquire.entity_link ADD CONSTRAINT entity_link_identifier_reference_check
  CHECK (method <> 'identifier' OR reference_entity_id IS NOT NULL);
ALTER TABLE acquire.entity_link ADD CONSTRAINT entity_link_fuzzy_score_check
  CHECK (NOT (method = 'fuzzy' AND status = 'confirmed') OR match_score >= 0.95);

-- covers: acquire.entity_link#1
-- entity_link_reference_sync (BR-169): the canonical key is the catalogue's, never typed by the
-- matcher, and a link cannot tie a source key to an entity of another type.
CREATE FUNCTION acquire.entity_link_reference_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  ref record;
BEGIN
  IF NEW.reference_entity_id IS NOT NULL THEN
    SELECT entity_type, canonical_key INTO ref
    FROM acquire.reference_entity WHERE id = NEW.reference_entity_id;
    IF FOUND THEN
      IF ref.entity_type <> NEW.entity_type THEN
        RAISE EXCEPTION 'Loại thực thể của liên kết khác loại của thực thể chuẩn (BR-169)'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.canonical_key := ref.canonical_key;
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER entity_link_reference_sync
  BEFORE INSERT OR UPDATE OF reference_entity_id, entity_type, canonical_key ON acquire.entity_link
  FOR EACH ROW EXECUTE FUNCTION acquire.entity_link_reference_sync();


-- ═══ reference_entity ═══

-- covers: acquire.reference_entity#0
-- BR-169: each registry identifier names one entity per organisation. The generator read
-- "duy nhất (org_id, sbv_code), (org_id, swift_bic), (org_id, tax_code) khi khác null" as one
-- unique and two plain indexes; sbv_code's unique index already ignores NULLs, the other two are
-- replaced by partial unique ones. GIN indexes serve the fallback name and domain matching.
DROP INDEX acquire.reference_entity_org_id_swift_bic_idx;
DROP INDEX acquire.reference_entity_org_id_tax_code_idx;
CREATE UNIQUE INDEX reference_entity_org_id_swift_bic_key ON acquire.reference_entity (org_id, swift_bic)
  WHERE swift_bic IS NOT NULL;
CREATE UNIQUE INDEX reference_entity_org_id_tax_code_key ON acquire.reference_entity (org_id, tax_code)
  WHERE tax_code IS NOT NULL;
CREATE INDEX reference_entity_official_domains_idx ON acquire.reference_entity USING gin (official_domains);
CREATE INDEX reference_entity_short_names_idx ON acquire.reference_entity USING gin (short_names);

-- covers: acquire.reference_entity#1 (no DDL: no catalogue management API yet, open point tab 6 O4.4)


-- ═══ consolidation_spec ═══

-- covers: acquire.consolidation_spec#0
-- BR-156: last_edited_by is the person who last changed what the spec computes; it becomes the
-- created_by of the consolidated dataset version, which that person may then not certify.
-- updated_by is not used for this because activation, renames, owner changes and system jobs
-- also move it. Direct writes to the two columns are ignored.
CREATE FUNCTION acquire.consolidation_spec_last_edit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.last_edited_by := NEW.created_by;
    NEW.last_edited_at := now();
  ELSIF (NEW.entity_type, NEW.grain, NEW.source_ids, NEW.normalization, NEW.source_priority,
         NEW.aggregates, NEW.summary_template, NEW.allow_interpolation, NEW.target_dataset_id)
        IS DISTINCT FROM
        (OLD.entity_type, OLD.grain, OLD.source_ids, OLD.normalization, OLD.source_priority,
         OLD.aggregates, OLD.summary_template, OLD.allow_interpolation, OLD.target_dataset_id) THEN
    NEW.last_edited_by := NEW.updated_by;
    NEW.last_edited_at := now();
  ELSE
    NEW.last_edited_by := OLD.last_edited_by;
    NEW.last_edited_at := OLD.last_edited_at;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER consolidation_spec_last_edit
  BEFORE INSERT OR UPDATE ON acquire.consolidation_spec
  FOR EACH ROW EXECUTE FUNCTION acquire.consolidation_spec_last_edit();


-- ═══ consolidation_run ═══

-- covers: acquire.consolidation_run#0
-- BR-153: only published crawl runs feed consolidation. BR-156: the spec editor is taken from
-- the spec when the run starts, whatever the caller sends, and never changes afterwards.
CREATE FUNCTION acquire.consolidation_run_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.input_run_ids IS DISTINCT FROM OLD.input_run_ids THEN
    IF EXISTS (
      SELECT 1 FROM unnest(NEW.input_run_ids) AS i(run_id)
      WHERE NOT EXISTS (
        SELECT 1 FROM acquire.crawl_run r WHERE r.id = i.run_id AND r.status = 'published'
      )
    ) THEN
      RAISE EXCEPTION 'Hợp nhất chỉ nhận lượt thu đã phát hành (BR-153)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.spec_editor_id := (SELECT last_edited_by FROM acquire.consolidation_spec WHERE id = NEW.spec_id);
  ELSIF NEW.spec_editor_id IS DISTINCT FROM OLD.spec_editor_id THEN
    RAISE EXCEPTION 'spec_editor_id không sửa được (BR-156)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER consolidation_run_guard
  BEFORE INSERT OR UPDATE ON acquire.consolidation_run
  FOR EACH ROW EXECUTE FUNCTION acquire.consolidation_run_guard();

-- ─── routines/forecast.sql ───
-- routines/forecast.sql: what D4.23 (tab 3b) writes in words for the forecast schema (P15 model
-- versions and their release gate, backtests, predictions, formula models, the forecast ledger):
-- the guard triggers, the ledger events, and the D5.2 append-only exceptions on prediction and
-- ledger_entry. Runs as da_owner after the generated tables, FKs, RLS and grants.


-- ═══ forecast_model ═══

-- covers: forecast.forecast_model#0
-- BR-160, checked at commit because the model and its version change together (publish a
-- version and repoint the model; degrade both): the current version is a published or degraded
-- version of this model, and the model is degraded exactly when that version is. Both tables
-- get a deferred trigger, so degrading only the version while the model stays active is caught.
CREATE FUNCTION forecast.forecast_model_current_version_ok(p_model_id uuid) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
  m record;
  v record;
BEGIN
  SELECT status, current_version_id INTO m FROM forecast.forecast_model WHERE id = p_model_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  IF m.current_version_id IS NULL THEN
    IF m.status = 'degraded' THEN
      RAISE EXCEPTION 'Mô hình degraded phải trỏ phiên bản degraded (BR-160)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN;
  END IF;
  SELECT model_id, status INTO v FROM forecast.model_version WHERE id = m.current_version_id;
  IF NOT FOUND OR v.model_id <> p_model_id OR v.status NOT IN ('published','degraded') THEN
    RAISE EXCEPTION 'current_version_id phải là phiên bản published hoặc degraded của chính mô hình (BR-160)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF (m.status = 'degraded') <> (v.status = 'degraded') THEN
    RAISE EXCEPTION 'Mô hình degraded khi và chỉ khi phiên bản hiện hành degraded (BR-160)'
      USING ERRCODE = 'check_violation';
  END IF;
END
$$;

CREATE FUNCTION forecast.forecast_model_current_version_check() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM forecast.forecast_model_current_version_ok(NEW.id);
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER forecast_model_current_version_check
  AFTER INSERT OR UPDATE ON forecast.forecast_model
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION forecast.forecast_model_current_version_check();

CREATE FUNCTION forecast.model_version_current_check() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  mid uuid;
BEGIN
  FOR mid IN SELECT id FROM forecast.forecast_model WHERE current_version_id = NEW.id LOOP
    PERFORM forecast.forecast_model_current_version_ok(mid);
  END LOOP;
  RETURN NULL;
END
$$;
CREATE CONSTRAINT TRIGGER model_version_current_check
  AFTER UPDATE OF status, model_id ON forecast.model_version
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION forecast.model_version_current_check();


-- ═══ model_version ═══

-- covers: forecast.model_version#0
-- covers: forecast.model_version#1
-- covers: forecast.model_version#3
-- model_version_guard. BR-160: the version life cycle. BR-158: publish only on a finished
-- backtest of this very version with MASE < 1. BR-172: publish needs n_points and the in-sample
-- MASE, and refuses a backtest MASE more than twice the in-sample one (overfitting). BR-183 /
-- ADR-44: a formula_mc version goes to approval only with its formula_model row, and is published
-- on a weekly rolling backtest of at least 20 cutoffs that reports reconstruction_mae.
CREATE FUNCTION forecast.model_version_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  b record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('draft','pending_approval') THEN
      RAISE EXCEPTION 'Phiên bản mới phải ở draft hoặc pending_approval (BR-160)'
        USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'draft' AND NEW.status IN ('pending_approval','rejected'))
    OR (OLD.status = 'pending_approval' AND NEW.status IN ('published','rejected','draft'))
    OR (OLD.status = 'published' AND NEW.status IN ('degraded','retired'))
    OR (OLD.status = 'degraded' AND NEW.status = 'retired')
  ) THEN
    RAISE EXCEPTION 'Không chuyển phiên bản từ % sang % (BR-160)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'pending_approval' AND NEW.algorithm = 'formula_mc'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'pending_approval')
     AND (SELECT count(*) FROM forecast.formula_model f WHERE f.model_version_id = NEW.id) <> 1 THEN
    RAISE EXCEPTION 'Phiên bản formula_mc gửi duyệt cần đúng một formula_model (BR-183)'
      USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status = 'published' AND OLD.status IS DISTINCT FROM 'published' THEN
    SELECT model_version_id, finished_at, mase, in_sample_mase, frequency, cutoffs, metrics INTO b
    FROM forecast.backtest_run WHERE id = NEW.backtest_id;
    IF NOT FOUND OR b.model_version_id <> NEW.id OR b.finished_at IS NULL OR b.mase >= 1 THEN
      RAISE EXCEPTION 'Phát hành cần backtest đã xong của chính phiên bản với MASE < 1 (BR-158)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.n_points IS NULL OR b.in_sample_mase IS NULL THEN
      RAISE EXCEPTION 'Phát hành cần n_points và in_sample_mase (BR-172)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF b.mase / b.in_sample_mase > 2 THEN
      RAISE EXCEPTION 'MASE backtest quá 2 lần MASE trong mẫu, mô hình quá khớp (BR-172)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.algorithm = 'formula_mc'
       AND (b.frequency <> 'week' OR cardinality(b.cutoffs) < 20 OR NOT b.metrics ? 'reconstruction_mae') THEN
      RAISE EXCEPTION 'Backtest của phiên bản formula_mc phải theo tuần, từ 20 điểm cắt, có reconstruction_mae (BR-183)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER model_version_guard
  BEFORE INSERT OR UPDATE ON forecast.model_version
  FOR EACH ROW EXECUTE FUNCTION forecast.model_version_guard();

-- covers: forecast.model_version#2 (already in the generated CHECK on algorithm)


-- ═══ backtest_run ═══

-- covers: forecast.backtest_run#0
-- ADR-15: the minimum number of cutoffs depends on the frequency, so the frequency is the
-- model's, filled in when omitted and refused when it differs.
CREATE FUNCTION forecast.backtest_run_frequency_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  f text;
BEGIN
  SELECT m.frequency INTO f
  FROM forecast.model_version v JOIN forecast.forecast_model m ON m.id = v.model_id
  WHERE v.id = NEW.model_version_id;
  IF NEW.frequency IS NULL THEN
    NEW.frequency := f;
  ELSIF f IS NOT NULL AND NEW.frequency <> f THEN
    RAISE EXCEPTION 'Tần suất backtest (%) khác tần suất mô hình (%) (ADR-15)', NEW.frequency, f
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER backtest_run_frequency_sync
  BEFORE INSERT OR UPDATE OF frequency, model_version_id ON forecast.backtest_run
  FOR EACH ROW EXECUTE FUNCTION forecast.backtest_run_frequency_sync();


-- ═══ prediction ═══

-- covers: forecast.prediction#0
-- covers: forecast.prediction#2
-- BR-158: output of a version that is not released is labelled experimental. BR-184 / ADR-44:
-- formula_mc output is a Monte Carlo interval with simulated inputs (for the base run; a
-- scenario fixes its inputs, so it stays scenario_fixed) and decomposes like the ledger.
-- monte_carlo itself is already in the generated interval_method CHECK.
CREATE FUNCTION forecast.prediction_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v record;
BEGIN
  SELECT status, algorithm INTO v FROM forecast.model_version WHERE id = NEW.model_version_id;
  IF v.status NOT IN ('published','degraded') AND NOT NEW.is_experimental THEN
    RAISE EXCEPTION 'Dự báo từ phiên bản chưa phát hành phải có is_experimental = true (BR-158)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v.algorithm = 'formula_mc' AND (
       NEW.interval_method <> 'monte_carlo'
       OR (NEW.scenario_id IS NULL AND NEW.exog_uncertainty <> 'simulated')
       OR NOT NEW.contributions ?& ARRAY['world','fx','tax','fund','proxy_error']
  ) THEN
    RAISE EXCEPTION 'Dự báo formula_mc ghi monte_carlo, simulated và phân rã world, fx, tax, fund, proxy_error (BR-184)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER prediction_guard
  BEFORE INSERT OR UPDATE ON forecast.prediction
  FOR EACH ROW EXECUTE FUNCTION forecast.prediction_guard();

-- covers: forecast.prediction#1
-- prediction_exog_guard (BR-173): a base forecast that depends on exogenous variables must
-- carry their uncertainty; treating future inputs as known would make the interval too narrow.
CREATE FUNCTION forecast.prediction_exog_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.scenario_id IS NULL AND NEW.exog_uncertainty <> 'simulated'
     AND (SELECT n_exog FROM forecast.model_version WHERE id = NEW.model_version_id) > 0 THEN
    RAISE EXCEPTION 'Dự báo gốc của phiên bản có biến ngoại sinh phải ghi exog_uncertainty = simulated (BR-173)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER prediction_exog_guard
  BEFORE INSERT OR UPDATE ON forecast.prediction
  FOR EACH ROW EXECUTE FUNCTION forecast.prediction_exog_guard();

-- D5.2: predictions are append-only. The generated grants already give svc_forecast only
-- SELECT, INSERT on this "Bản ghi bất biến" table; the revoke states the exception explicitly.
REVOKE UPDATE, DELETE ON forecast.prediction FROM svc_forecast;


-- ═══ formula_model ═══

-- covers: forecast.formula_model#0
-- formula_model_guard (BR-183): a formula model belongs to a formula_mc version, and once that
-- version is released its formula is frozen; a new formula is a new version. Checking that the
-- metric version is still certified and the components have certified values is the Forecast
-- service's job before each run (it reads context and its own components at forecast time).
CREATE FUNCTION forecast.formula_model_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v record;
BEGIN
  SELECT algorithm, status INTO v FROM forecast.model_version WHERE id = NEW.model_version_id;
  IF v.algorithm IS DISTINCT FROM 'formula_mc' THEN
    RAISE EXCEPTION 'formula_model chỉ gắn phiên bản có algorithm = formula_mc (BR-183)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT status INTO v FROM forecast.model_version WHERE id = OLD.model_version_id;
    IF v.status IN ('published','degraded')
       AND (NEW.formula, NEW.window_rule, NEW.metric_version_id, NEW.model_version_id)
           IS DISTINCT FROM (OLD.formula, OLD.window_rule, OLD.metric_version_id, OLD.model_version_id) THEN
      RAISE EXCEPTION 'Công thức của phiên bản đã phát hành không sửa được; đổi công thức là phiên bản mới (BR-183)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER formula_model_guard
  BEFORE INSERT OR UPDATE ON forecast.formula_model
  FOR EACH ROW EXECUTE FUNCTION forecast.formula_model_guard();


-- ═══ formula_component ═══

-- covers: forecast.formula_component#0
-- formula_component_guard (BR-182): a parameter of the legal price formula is entered as a
-- draft, certified by a second person, and then frozen except for its end of validity. A newly
-- certified value closes the open one of the same (code, product_code) at its own valid_from,
-- and certified intervals never overlap. The advisory lock serialises certifications of one
-- parameter so two concurrent ones cannot both see "no overlap".
CREATE FUNCTION forecast.formula_component_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  prev record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status NOT IN ('draft','pending_review') THEN
      RAISE EXCEPTION 'Tham số mới phải ở draft hoặc pending_review, chứng nhận là bước riêng (BR-182)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
       (OLD.status = 'draft' AND NEW.status IN ('pending_review','rejected'))
    OR (OLD.status = 'pending_review' AND NEW.status IN ('certified','rejected','draft'))
    OR (OLD.status = 'certified' AND NEW.status = 'superseded')
  ) THEN
    RAISE EXCEPTION 'Không chuyển tham số từ % sang % (BR-182)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF OLD.status IN ('certified','superseded')
     AND (to_jsonb(NEW) - ARRAY['valid_to','status','updated_at','updated_by'])
         IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['valid_to','status','updated_at','updated_by']) THEN
    RAISE EXCEPTION 'Tham số đã chứng nhận chỉ sửa được valid_to và status (BR-182)'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'certified' AND (OLD.status <> 'certified' OR NEW.valid_to IS DISTINCT FROM OLD.valid_to) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text || '/' || NEW.code || '/' || NEW.product_code, 0));
    IF OLD.status <> 'certified' THEN
      FOR prev IN
        SELECT id, valid_from FROM forecast.formula_component
        WHERE org_id = NEW.org_id AND code = NEW.code AND product_code = NEW.product_code
          AND status = 'certified' AND valid_to IS NULL AND id <> NEW.id
      LOOP
        IF NEW.valid_from <= prev.valid_from THEN
          RAISE EXCEPTION 'Bản mới phải có valid_from sau valid_from của bản đang hiệu lực (BR-182)'
            USING ERRCODE = 'check_violation';
        END IF;
        UPDATE forecast.formula_component
        SET valid_to = NEW.valid_from,
            status = CASE WHEN NEW.valid_from <= now() THEN 'superseded' ELSE status END
        WHERE id = prev.id;
      END LOOP;
    END IF;
    IF EXISTS (
      SELECT 1 FROM forecast.formula_component c
      WHERE c.org_id = NEW.org_id AND c.code = NEW.code AND c.product_code = NEW.product_code
        AND c.status = 'certified' AND c.id <> NEW.id
        AND tstzrange(c.valid_from, c.valid_to) && tstzrange(NEW.valid_from, NEW.valid_to)
    ) THEN
      RAISE EXCEPTION 'Hai bản certified cùng (code, product_code) có khoảng hiệu lực chồng nhau (BR-182)'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER formula_component_guard
  BEFORE INSERT OR UPDATE ON forecast.formula_component
  FOR EACH ROW EXECUTE FUNCTION forecast.formula_component_guard();

-- "chuyển superseded khi tới valid_from": a certified value whose successor starts in the future
-- keeps status certified until then; the Forecast service's scheduler calls this to supersede
-- the ones whose valid_to has been reached. Returns the number of rows superseded.
CREATE FUNCTION forecast.formula_component_supersede_due() RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  UPDATE forecast.formula_component SET status = 'superseded'
  WHERE status = 'certified' AND valid_to IS NOT NULL AND valid_to <= now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$$;
REVOKE EXECUTE ON FUNCTION forecast.formula_component_supersede_due() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION forecast.formula_component_supersede_due() TO svc_forecast;


-- ═══ ledger_entry ═══

-- covers: forecast.ledger_entry#0
-- ledger_entry_guard (BR-185): the forecast half of a ledger line is written before the period
-- and never changes; only scoring fills in. Rescoring (scored → scored) follows a corrected
-- published price. error_book_entry_id is written once (tab 3 D5.4). No DELETE for anyone: the
-- ledger shows missed periods too (BR-186), so the trigger refuses it even for the owner, on top
-- of D5.2's revoke for svc_forecast.
CREATE FUNCTION forecast.ledger_entry_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Dòng sổ dự báo không xoá được (BR-185)' USING ERRCODE = '42501';
  END IF;
  IF (NEW.forecast_model_id, NEW.model_version_id, NEW.prediction_id, NEW.job_id, NEW.period,
      NEW.scope, NEW.issued_at, NEW.issued_via, NEW.event_id, NEW.event_at, NEW.baseline_value,
      NEW.point, NEW.quantiles, NEW.prob_up, NEW.fund_probs, NEW.contributions)
     IS DISTINCT FROM
     (OLD.forecast_model_id, OLD.model_version_id, OLD.prediction_id, OLD.job_id, OLD.period,
      OLD.scope, OLD.issued_at, OLD.issued_via, OLD.event_id, OLD.event_at, OLD.baseline_value,
      OLD.point, OLD.quantiles, OLD.prob_up, OLD.fund_probs, OLD.contributions) THEN
    RAISE EXCEPTION 'Phần dự báo của dòng sổ không sửa được sau khi ghi (BR-185)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (OLD.status = 'open' AND NEW.status IN ('scored','void')) THEN
    RAISE EXCEPTION 'Không chuyển dòng sổ từ % sang % (BR-185)', OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.error_book_entry_id IS NOT NULL AND NEW.error_book_entry_id IS DISTINCT FROM OLD.error_book_entry_id THEN
    RAISE EXCEPTION 'error_book_entry_id đã ghi không đổi được (BR-186)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER ledger_entry_guard
  BEFORE UPDATE OR DELETE ON forecast.ledger_entry
  FOR EACH ROW EXECUTE FUNCTION forecast.ledger_entry_guard();

REVOKE DELETE ON forecast.ledger_entry FROM svc_forecast;

-- Scoring events (tab 3 D5.4 Lượt 4: "chấm kỳ ngoài 95% phát forecast.ledger.scored và
-- forecast.ledger.missed"). Eval service opens the Error Book entry from .missed; its payload is
-- what eval.error_book_entry.forecast_detail needs (BR-186). A rescore emits .scored again when
-- the actual changed, and .missed only if the period was not already a miss.
CREATE FUNCTION forecast.ledger_entry_scored_event() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  detail jsonb;
BEGIN
  IF NEW.status <> 'scored' OR (OLD.status = 'scored' AND NEW.actual IS NOT DISTINCT FROM OLD.actual) THEN
    RETURN NULL;
  END IF;
  detail := jsonb_build_object(
    'ledger_entry_id', NEW.id, 'forecast_model_id', NEW.forecast_model_id,
    'model_version_id', NEW.model_version_id, 'period', NEW.period, 'scope', NEW.scope,
    'actual', NEW.actual, 'point', NEW.point,
    'lo95', NEW.quantiles->'p02_5', 'hi95', NEW.quantiles->'p97_5',
    'abs_error', NEW.abs_error, 'in80', NEW.in80, 'in95', NEW.in95, 'miss', NEW.miss,
    'miss_attribution', NEW.miss_attribution, 'accuracy_log_id', NEW.accuracy_log_id,
    'rescored', OLD.status = 'scored');
  INSERT INTO forecast.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'ledger_entry', NEW.id, 'forecast.ledger.scored', detail);
  IF NEW.miss AND (OLD.status <> 'scored' OR OLD.miss IS NOT TRUE) THEN
    INSERT INTO forecast.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'ledger_entry', NEW.id, 'forecast.ledger.missed', detail);
  END IF;
  RETURN NULL;
END
$$;
CREATE TRIGGER ledger_entry_scored_event
  AFTER UPDATE OF status, actual ON forecast.ledger_entry
  FOR EACH ROW EXECUTE FUNCTION forecast.ledger_entry_scored_event();

-- covers: forecast.ledger_entry#1 (no DDL here: formula_mc and monte_carlo are already in the generated CHECKs of model_version and prediction; hitl_request kind formula_component belongs to the inbox schema)

-- ─── routines/exec.sql ───
-- Schema exec (P16, the executive vault, D4.24): row-level security beyond org_isolation, column
-- grants, triggers and the two SECURITY DEFINER entry points of the Exec vault service.
--
-- GUC contract (set by the Gateway / the worker per transaction, read with
-- NULLIF(current_setting('app.<name>', true), '') so an unset setting denies, never errors):
--   app.org_id         uuid  organisation (generated org_isolation, every table)
--   app.user_id        uuid  the vault owner svc_exec acts for; owner_only compares owner_id to it
--   app.exec_workflow  'on'  set by svc_exec_worker (scoring workflow, Evidence agent on Temporal);
--                            without it the worker sees and writes nothing
--   app.exec_admin     'on'  set by svc_exec for AC05/AC06 requests (UC-16-06); opens exec.handover
--                            and exec.vault_admin_overview(), never a column of ciphertext
--
-- Roles: svc_exec (Exec service, acts for the owner), svc_exec_worker (column grants on vault and
-- thesis, INSERT on the three append-only tables), exec_read (granted to svc_context, only
-- exec.publication). No administrative role reads exec (BR-189). Encryption on the device and in
-- OpenBao is the primary protection (ADR-46); these rules are the second layer.
-- Functions that must act beyond the caller's rows (shred, cross-row checks the worker cannot read)
-- are SECURITY DEFINER: they run as da_owner, which FORCE RLS still keeps inside org_isolation.

-- ─── grants (D5.2: svc_exec, svc_exec_worker, exec_read) ───

-- exec_read is granted to svc_context only for the source of hypothesis pages (BR-194); the
-- generator gives every <schema>_read SELECT on all tables of its schema.
REVOKE SELECT ON exec.vault, exec.vault_key_wrap, exec.thesis, exec.thesis_evidence,
  exec.thesis_score, exec.memory_item, exec.key_access_log, exec.handover, exec.handover_item
  FROM exec_read;
-- The worker is the schema's third role (D5.2); it starts with nothing.
GRANT USAGE ON SCHEMA exec TO svc_exec_worker;

-- ─── shared helpers ───

-- BR-189: a vault takes new content only while it can still be opened without the server: at least
-- two live key wraps, one of them offline (hardware key or paper recovery code). Invoker rights:
-- svc_exec sees only the owner's wraps, so another owner's vault reads as not unlockable.
CREATE FUNCTION exec.vault_unlockable(p_vault_id uuid) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT count(*) >= 2 AND bool_or(w.kind IN ('hardware_key', 'recovery_code'))
  FROM exec.vault_key_wrap w
  WHERE w.vault_id = p_vault_id AND w.revoked_at IS NULL
$$;

-- ─── exec.vault ───

-- covers: exec.vault#0
CREATE POLICY owner_only ON exec.vault AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY workflow_only ON exec.vault AS RESTRICTIVE FOR SELECT TO svc_exec_worker
  USING (NULLIF(current_setting('app.exec_workflow', true), '') = 'on');
GRANT SELECT (owner_id, status, box_public_key, transit_key_name, transit_key_version)
  ON exec.vault TO svc_exec_worker;
-- AC05/AC06 see five operational columns, no key column. RLS cannot narrow columns for one role,
-- so the table policy has no admin branch and the read goes through this function (UC-16-06).
CREATE FUNCTION exec.vault_admin_overview()
RETURNS TABLE (id uuid, owner_id uuid, status text, exit_policy text, sealed_read_until date)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT v.id, v.owner_id, v.status, v.exit_policy, v.sealed_read_until
  FROM exec.vault v
  WHERE NULLIF(current_setting('app.exec_admin', true), '') = 'on'
    AND v.org_id = NULLIF(current_setting('app.org_id', true), '')::uuid
$$;
REVOKE EXECUTE ON FUNCTION exec.vault_admin_overview() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.vault_admin_overview() TO svc_exec;

-- covers: exec.vault#1
-- SECURITY DEFINER because shredding deletes the key wraps and svc_exec has no DELETE on them
-- (BR-195); a trigger function cannot be called directly, so this is the only path to that DELETE.
REVOKE DELETE ON exec.vault FROM svc_exec;
CREATE FUNCTION exec.vault_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NEW.box_public_key IS DISTINCT FROM OLD.box_public_key
     OR NEW.transit_key_name IS DISTINCT FROM OLD.transit_key_name THEN
    RAISE EXCEPTION 'Không đổi khoá công khai hay tên khoá Transit của kho (BR-195)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'shredded' THEN
    IF NEW.status <> 'shredded' OR NEW.box_private_key_ct IS DISTINCT FROM OLD.box_private_key_ct THEN
      RAISE EXCEPTION 'Kho đã huỷ khoá là trạng thái cuối, không mở lại (BR-195)'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT (OLD.status = 'active' AND NEW.status IN ('sealed', 'shredded'))
     AND NOT (OLD.status = 'sealed' AND NEW.status = 'shredded') THEN
    RAISE EXCEPTION 'Kho chỉ chuyển active → sealed, shredded; sealed → shredded (BR-195)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status = 'sealed' AND OLD.status <> 'sealed' THEN
    NEW.sealed_at := coalesce(NEW.sealed_at, now());
  END IF;
  IF NEW.status = 'shredded' THEN
    NEW.box_private_key_ct := '\x'::bytea;
    NEW.shredded_at := coalesce(NEW.shredded_at, now());
    DELETE FROM exec.vault_key_wrap WHERE vault_id = OLD.id;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER vault_guard_update BEFORE UPDATE ON exec.vault
  FOR EACH ROW EXECUTE FUNCTION exec.vault_guard_update();

-- ─── exec.vault_key_wrap ───

-- covers: exec.vault_key_wrap#0
CREATE POLICY owner_only ON exec.vault_key_wrap AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);

-- covers: exec.vault_key_wrap#1
-- Replacing a key is a new row; the only DELETE is exec.vault_guard_update on shred.
REVOKE DELETE, UPDATE ON exec.vault_key_wrap FROM svc_exec;
GRANT UPDATE (last_used_at, revoked_at) ON exec.vault_key_wrap TO svc_exec;
CREATE FUNCTION exec.vault_key_wrap_guard_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'last_used_at' - 'revoked_at') IS DISTINCT FROM (to_jsonb(OLD) - 'last_used_at' - 'revoked_at') THEN
    RAISE EXCEPTION 'Khoá bọc chỉ đổi last_used_at, revoked_at; thay khoá là thêm dòng mới (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'Khoá bọc đã thu hồi không khôi phục được (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  -- A revocation must leave two live wraps, one offline, unless the vault is being shredded
  -- (already shredded, or a shred handover approved or in progress).
  IF OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM exec.vault v WHERE v.id = NEW.vault_id AND v.status = 'shredded')
     AND NOT EXISTS (SELECT 1 FROM exec.handover h WHERE h.vault_id = NEW.vault_id AND h.kind = 'shred'
                       AND h.status IN ('approved', 'in_progress'))
     AND NOT (SELECT count(*) >= 2 AND coalesce(bool_or(w.kind IN ('hardware_key', 'recovery_code')), false)
              FROM exec.vault_key_wrap w
              WHERE w.vault_id = NEW.vault_id AND w.revoked_at IS NULL AND w.id <> NEW.id) THEN
    RAISE EXCEPTION 'Thu hồi làm kho còn dưới 2 khoá bọc hiệu lực hoặc không còn khoá ngoại tuyến (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER vault_key_wrap_guard_update BEFORE UPDATE ON exec.vault_key_wrap
  FOR EACH ROW EXECUTE FUNCTION exec.vault_key_wrap_guard_update();

-- ─── exec.thesis ───

-- covers: exec.thesis#0
-- Content is immutable after commit (BR-188): no updated_* columns, and only the workflow columns
-- are updatable.
REVOKE UPDATE ON exec.thesis FROM svc_exec;
GRANT UPDATE (status, evidence_state, evidence_refreshed_at, withdrawn_at, workflow_id)
  ON exec.thesis TO svc_exec;

-- covers: exec.thesis#1
CREATE POLICY owner_only ON exec.thesis AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY workflow_only ON exec.thesis AS RESTRICTIVE FOR ALL TO svc_exec_worker
  USING (NULLIF(current_setting('app.exec_workflow', true), '') = 'on')
  WITH CHECK (NULLIF(current_setting('app.exec_workflow', true), '') = 'on');
-- The worker decrypts the condition through OpenBao; it never gets content_ct or wrapped_dek.
GRANT SELECT (id, owner_id, vault_id, cond_ct, cond_key_version, due_at, status) ON exec.thesis
  TO svc_exec_worker;
GRANT UPDATE (status, evidence_state, evidence_refreshed_at) ON exec.thesis TO svc_exec_worker;

-- covers: exec.thesis#2
CREATE FUNCTION exec.thesis_guard_insert() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- svc_exec sees only the owner's vault, so another owner's vault fails here too.
  IF NOT EXISTS (SELECT 1 FROM exec.vault v WHERE v.id = NEW.vault_id AND v.status = 'active'
                   AND v.owner_id = NEW.owner_id) THEN
    RAISE EXCEPTION 'Luận điểm cần kho active của chính chủ kho (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT coalesce(exec.vault_unlockable(NEW.vault_id), false) THEN
    RAISE EXCEPTION 'Kho cần từ 2 khoá bọc còn hiệu lực, trong đó một khoá ngoại tuyến (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.supersedes_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM exec.thesis t WHERE t.id = NEW.supersedes_id AND t.owner_id = NEW.owner_id) THEN
    RAISE EXCEPTION 'Luận điểm được thay phải cùng chủ kho (BR-188)'
      USING ERRCODE = 'check_violation';
  END IF;
  -- R-35: a whole UTC hour; date_trunc on timestamptz is not immutable, so not a CHECK.
  IF NEW.due_at <> date_trunc('hour', NEW.due_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN
    RAISE EXCEPTION 'Thời điểm chấm phải tròn giờ theo UTC (R-35)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER thesis_guard_insert BEFORE INSERT ON exec.thesis
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_guard_insert();

-- covers: exec.thesis#3
REVOKE DELETE ON exec.thesis FROM svc_exec;
CREATE FUNCTION exec.thesis_guard_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- The column grants already stop svc_exec and the worker; this also binds da_owner paths.
  IF NEW.content_ct IS DISTINCT FROM OLD.content_ct OR NEW.wrapped_dek IS DISTINCT FROM OLD.wrapped_dek
     OR NEW.cond_ct IS DISTINCT FROM OLD.cond_ct OR NEW.cond_key_version IS DISTINCT FROM OLD.cond_key_version
     OR NEW.due_at IS DISTINCT FROM OLD.due_at OR NEW.committed_at IS DISTINCT FROM OLD.committed_at
     OR NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    RAISE EXCEPTION 'Nội dung, điều kiện và ngày chấm của luận điểm không sửa được (BR-188)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (OLD.status = 'open' AND NEW.status IN ('scoring', 'invalid_condition', 'withdrawn'))
       AND NOT (OLD.status = 'scoring' AND NEW.status IN ('scored', 'unresolvable', 'open')) THEN
      RAISE EXCEPTION 'Luận điểm chỉ chuyển open → scoring, invalid_condition, withdrawn; scoring → scored, unresolvable, open (BR-188)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'withdrawn' THEN
      IF now() >= OLD.due_at THEN
        RAISE EXCEPTION 'Chỉ rút luận điểm trước thời điểm chấm (BR-188)'
          USING ERRCODE = 'check_violation';
      END IF;
      NEW.withdrawn_at := coalesce(NEW.withdrawn_at, now());
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER thesis_guard_update BEFORE UPDATE ON exec.thesis
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_guard_update();

-- ─── exec.thesis_evidence ───

-- covers: exec.thesis_evidence#0
REVOKE INSERT ON exec.thesis_evidence FROM svc_exec;
CREATE POLICY owner_only ON exec.thesis_evidence AS RESTRICTIVE FOR SELECT TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY workflow_only ON exec.thesis_evidence AS RESTRICTIVE FOR INSERT TO svc_exec_worker
  WITH CHECK (NULLIF(current_setting('app.exec_workflow', true), '') = 'on');
-- created_at and recorded_at are left to their defaults: the batch check below tells this
-- transaction's rows from earlier batches by created_at = transaction_timestamp().
GRANT INSERT (id, org_id, thesis_id, owner_id, batch_no, side, item_kind, strength, freshness_ok,
  sealed_ct, agent_run_id) ON exec.thesis_evidence TO svc_exec_worker;
-- "No role has UPDATE, DELETE": refused by trigger so it binds the table owner and the DBA too.
CREATE FUNCTION exec.thesis_evidence_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Bằng chứng là bản ghi bất biến, không sửa, không xoá (BR-190)'
    USING ERRCODE = 'insufficient_privilege';
END $$;
CREATE TRIGGER thesis_evidence_append_only BEFORE UPDATE OR DELETE ON exec.thesis_evidence
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_evidence_append_only();

-- covers: exec.thesis_evidence#1
-- SECURITY DEFINER: the worker inserts but cannot read the batch it has to check.
CREATE FUNCTION exec.thesis_evidence_batch_check() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM exec.thesis t WHERE t.id = NEW.thesis_id AND t.status = 'open') THEN
    RAISE EXCEPTION 'Chỉ thêm bằng chứng cho luận điểm đang open (BR-190)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM exec.thesis_evidence e WHERE e.thesis_id = NEW.thesis_id
                   AND e.batch_no = NEW.batch_no AND e.side = 'support')
     OR NOT EXISTS (SELECT 1 FROM exec.thesis_evidence e WHERE e.thesis_id = NEW.thesis_id
                      AND e.batch_no = NEW.batch_no AND e.side = 'against') THEN
    RAISE EXCEPTION 'Lô bằng chứng cần cả phía support và phía against (BR-190)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.batch_no <> 1 + coalesce((SELECT max(e.batch_no) FROM exec.thesis_evidence e
                                    WHERE e.thesis_id = NEW.thesis_id
                                      AND e.created_at <> transaction_timestamp()), 0) THEN
    RAISE EXCEPTION 'Số lô bằng chứng phải bằng lô lớn nhất cộng 1 (BR-190)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER thesis_evidence_batch_check AFTER INSERT ON exec.thesis_evidence
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_evidence_batch_check();

-- covers: exec.thesis_evidence#2
-- SECURITY DEFINER for the same reason: the state is computed from rows the worker cannot read.
CREATE FUNCTION exec.thesis_evidence_refresh_state() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  v_state text;
BEGIN
  SELECT CASE
           WHEN bool_or(e.side = 'support' AND e.item_kind = 'evidence')
                AND bool_or(e.side = 'against' AND e.item_kind = 'evidence') THEN 'two_sided'
           WHEN bool_or(e.item_kind = 'insufficient') THEN 'insufficient'
           ELSE 'one_sided'
         END
    INTO v_state
  FROM exec.thesis_evidence e
  WHERE e.thesis_id = NEW.thesis_id AND e.batch_no = NEW.batch_no;
  UPDATE exec.thesis SET evidence_state = v_state, evidence_refreshed_at = now()
  WHERE id = NEW.thesis_id;
  RETURN NULL;
END $$;
CREATE TRIGGER thesis_evidence_refresh_state AFTER INSERT ON exec.thesis_evidence
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_evidence_refresh_state();

-- ─── exec.thesis_score ───

-- covers: exec.thesis_score#0
REVOKE INSERT ON exec.thesis_score FROM svc_exec;
CREATE POLICY owner_only ON exec.thesis_score AS RESTRICTIVE FOR SELECT TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY workflow_only ON exec.thesis_score AS RESTRICTIVE FOR INSERT TO svc_exec_worker
  WITH CHECK (NULLIF(current_setting('app.exec_workflow', true), '') = 'on');
GRANT INSERT ON exec.thesis_score TO svc_exec_worker;
-- BR-191: append-only for every role, the table owner and the DBA included.
CREATE FUNCTION exec.thesis_score_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Điểm chấm chỉ ghi thêm, không sửa, không xoá (BR-191)'
    USING ERRCODE = 'insufficient_privilege';
END $$;
CREATE TRIGGER thesis_score_append_only BEFORE UPDATE OR DELETE ON exec.thesis_score
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_score_append_only();

-- covers: exec.thesis_score#1
-- SECURITY DEFINER: a restatement must see the final row, which the worker cannot read.
CREATE FUNCTION exec.thesis_score_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NEW.kind = 'final' AND NOT EXISTS (
       SELECT 1 FROM exec.thesis t WHERE t.id = NEW.thesis_id AND t.status = 'scoring'
         AND t.due_at = NEW.as_of) THEN
    RAISE EXCEPTION 'Điểm final cần luận điểm ở scoring và as_of bằng due_at (BR-191)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.kind = 'restatement' AND NOT EXISTS (
       SELECT 1 FROM exec.thesis_score s WHERE s.thesis_id = NEW.thesis_id AND s.kind = 'final') THEN
    RAISE EXCEPTION 'Điểm restatement cần đã có điểm final (BR-191)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER thesis_score_guard_insert BEFORE INSERT ON exec.thesis_score
  FOR EACH ROW EXECUTE FUNCTION exec.thesis_score_guard_insert();

-- covers: exec.thesis_score#2
CREATE FUNCTION exec.thesis_score_close_thesis() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  UPDATE exec.thesis
  SET status = CASE WHEN NEW.outcome = 'unresolvable' THEN 'unresolvable' ELSE 'scored' END
  WHERE id = NEW.thesis_id;
  RETURN NULL;
END $$;
CREATE TRIGGER thesis_score_close_thesis AFTER INSERT ON exec.thesis_score
  FOR EACH ROW WHEN (NEW.kind = 'final') EXECUTE FUNCTION exec.thesis_score_close_thesis();

-- ─── exec.memory_item ───

-- covers: exec.memory_item#0
CREATE POLICY owner_only ON exec.memory_item AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);

-- covers: exec.memory_item#1
CREATE FUNCTION exec.memory_item_guard_insert() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM exec.vault v WHERE v.id = NEW.vault_id AND v.status = 'active'
                   AND v.owner_id = NEW.owner_id) THEN
    RAISE EXCEPTION 'Mục bộ nhớ cần kho active của chính chủ kho (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT coalesce(exec.vault_unlockable(NEW.vault_id), false) THEN
    RAISE EXCEPTION 'Kho cần từ 2 khoá bọc còn hiệu lực, trong đó một khoá ngoại tuyến (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memory_item_guard_insert BEFORE INSERT ON exec.memory_item
  FOR EACH ROW EXECUTE FUNCTION exec.memory_item_guard_insert();

-- covers: exec.memory_item#2
REVOKE DELETE ON exec.memory_item FROM svc_exec;
CREATE FUNCTION exec.memory_item_guard_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  -- Shredding drops the wrapped DEK and the ciphertext; nothing else ever changes (UC-16-02).
  IF OLD.shredded_at IS NOT NULL
     OR NEW.content_ct IS NOT NULL OR NEW.wrapped_dek IS NOT NULL
     OR (to_jsonb(NEW) - 'content_ct' - 'wrapped_dek' - 'shredded_at')
        IS DISTINCT FROM (to_jsonb(OLD) - 'content_ct' - 'wrapped_dek' - 'shredded_at') THEN
    RAISE EXCEPTION 'Mục bộ nhớ không sửa được, chỉ huỷ (BR-189)'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.shredded_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER memory_item_guard_update BEFORE UPDATE ON exec.memory_item
  FOR EACH ROW EXECUTE FUNCTION exec.memory_item_guard_update();

-- ─── exec.key_access_log ───

-- covers: exec.key_access_log#0
CREATE POLICY owner_only ON exec.key_access_log AS RESTRICTIVE FOR SELECT TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
-- An AC05/AC06 request (UC-16-06) logs against the leaving owner's vault, as actor admin_request.
CREATE POLICY owner_only_insert ON exec.key_access_log AS RESTRICTIVE FOR INSERT TO svc_exec
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid
              OR (NULLIF(current_setting('app.exec_admin', true), '') = 'on' AND actor_kind = 'admin_request'));
CREATE POLICY workflow_only ON exec.key_access_log AS RESTRICTIVE FOR ALL TO svc_exec_worker
  USING (NULLIF(current_setting('app.exec_workflow', true), '') = 'on')
  WITH CHECK (NULLIF(current_setting('app.exec_workflow', true), '') = 'on');
GRANT INSERT ON exec.key_access_log TO svc_exec_worker;
-- The workflow calls OpenBao only when INSERT ... RETURNING id returns a row (#1), and RETURNING
-- needs SELECT on the returned column: id only, nothing that says what was accessed.
GRANT SELECT (id) ON exec.key_access_log TO svc_exec_worker;
-- BR-192: append-only for every role, the table owner and the DBA included.
CREATE FUNCTION exec.key_access_log_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Sổ truy cập khoá chỉ ghi thêm, không sửa, không xoá (BR-192)'
    USING ERRCODE = 'insufficient_privilege';
END $$;
CREATE TRIGGER key_access_log_append_only BEFORE UPDATE OR DELETE ON exec.key_access_log
  FOR EACH ROW EXECUTE FUNCTION exec.key_access_log_append_only();

-- Each row says who touched which key: the vault and owner must be one pair (and the thesis theirs),
-- the actor kind must be the caller's own, and `at` is the database's clock. Without this a caller
-- could forge entries for another vault, pose as the workflow, or backdate `at` to slip past the
-- 24-hour decrypt limit below (BR-192).
CREATE FUNCTION exec.key_access_target_ok(p_org uuid, p_vault uuid, p_owner uuid, p_thesis uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  -- Definer: the worker cannot read exec.vault or exec.thesis. It answers only inside a trigger
  -- (pg_trigger_depth() > 0); called directly it would tell anyone which leader owns which vault,
  -- the very thing the owner-only policy hides.
  SELECT pg_trigger_depth() > 0 AND EXISTS (SELECT 1 FROM exec.vault v
                 WHERE v.id = p_vault AND v.owner_id = p_owner AND v.org_id = p_org)
     AND (p_thesis IS NULL OR EXISTS (SELECT 1 FROM exec.thesis t
                                      WHERE t.id = p_thesis AND t.vault_id = p_vault
                                        AND t.owner_id = p_owner AND t.org_id = p_org))
$$;
REVOKE EXECUTE ON FUNCTION exec.key_access_target_ok(uuid, uuid, uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.key_access_target_ok(uuid, uuid, uuid, uuid) TO svc_exec, svc_exec_worker;

CREATE FUNCTION exec.vault_has_open_handover(p_org uuid, p_vault uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  -- Trigger-only, like exec.key_access_target_ok.
  SELECT pg_trigger_depth() > 0 AND EXISTS (SELECT 1 FROM exec.handover h
                 WHERE h.vault_id = p_vault AND h.org_id = p_org AND h.status IN ('approved', 'in_progress'))
$$;
REVOKE EXECUTE ON FUNCTION exec.vault_has_open_handover(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.vault_has_open_handover(uuid, uuid) TO svc_exec;

-- Invoker rights on purpose: current_user is the calling service role here.
CREATE FUNCTION exec.key_access_log_check_actor() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.at := now();
  IF NOT exec.key_access_target_ok(NEW.org_id, NEW.vault_id, NEW.owner_id, NEW.thesis_id) THEN
    RAISE EXCEPTION 'Sổ truy cập khoá: kho, chủ kho và luận điểm không khớp nhau (BR-192)'
      USING ERRCODE = 'check_violation';
  END IF;
  IF current_user = 'svc_exec_worker' AND NEW.actor_kind <> 'workflow' THEN
    RAISE EXCEPTION 'Workflow chỉ ghi dòng actor_kind = workflow (BR-192)' USING ERRCODE = 'insufficient_privilege';
  ELSIF current_user = 'svc_exec' THEN
    IF NEW.owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid THEN
      IF NEW.actor_kind <> 'owner_device' THEN
        RAISE EXCEPTION 'Thiết bị của chủ kho chỉ ghi dòng owner_device (BR-192)' USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSIF NEW.actor_kind <> 'admin_request' OR NOT exec.vault_has_open_handover(NEW.org_id, NEW.vault_id) THEN
      RAISE EXCEPTION 'Quản trị chỉ ghi dòng admin_request cho kho có yêu cầu rời vị trí đã duyệt (BR-192, BR-195)'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END $$;
-- Named to sort before key_access_log_decrypt_limit: BEFORE triggers fire in name order, and the
-- limit must count against a row whose `at` is already the server's.
CREATE TRIGGER key_access_log_check_actor BEFORE INSERT ON exec.key_access_log
  FOR EACH ROW EXECUTE FUNCTION exec.key_access_log_check_actor();

-- covers: exec.key_access_log#1
-- The fourth decrypt of one condition in 24 hours is not written (RETURN NULL), so RETURNING is
-- empty and the workflow never calls OpenBao; raising would roll back the event as well. Counted
-- over decrypt_condition rows. SECURITY DEFINER: the worker can neither read the log nor write the
-- outbox. Audit is a separate database (D1.1), so the Audit service writes audit.security_event
-- from this event.
CREATE FUNCTION exec.key_access_log_decrypt_limit() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  -- Two concurrent decrypts of one condition would both count two and both pass; serialise them.
  PERFORM pg_advisory_xact_lock(hashtextextended('exec.decrypt:' || NEW.thesis_id::text, 0));
  IF (SELECT count(*) FROM exec.key_access_log l
      WHERE l.thesis_id = NEW.thesis_id AND l.action = 'decrypt_condition'
        AND l.at > now() - interval '24 hours') >= 3 THEN
    INSERT INTO exec.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'key_access_log', NEW.thesis_id, 'exec.key.decrypt_limit_exceeded',
            jsonb_build_object('thesis_id', NEW.thesis_id, 'vault_id', NEW.vault_id, 'owner_id', NEW.owner_id,
                               'actor_ref', NEW.actor_ref, 'correlation_id', NEW.correlation_id,
                               'purpose', NEW.purpose));
    RETURN NULL;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER key_access_log_decrypt_limit BEFORE INSERT ON exec.key_access_log
  FOR EACH ROW WHEN (NEW.action = 'decrypt_condition')
  EXECUTE FUNCTION exec.key_access_log_decrypt_limit();

-- ─── exec.handover ───

-- covers: exec.handover#0
REVOKE DELETE ON exec.handover FROM svc_exec;
CREATE POLICY owner_only ON exec.handover AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid
         OR NULLIF(current_setting('app.exec_admin', true), '') = 'on')
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid
              OR NULLIF(current_setting('app.exec_admin', true), '') = 'on');
-- RLS cannot narrow the columns of the admin branch, so a trigger does: AC05/AC06 change status,
-- approved_by, approved_at, plus completed_at and certificate_sha256 that the CHECKs demand when
-- they complete a shred, and the updated_* stamps.
CREATE FUNCTION exec.handover_admin_columns() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.owner_id IS DISTINCT FROM NULLIF(current_setting('app.user_id', true), '')::uuid
     AND (to_jsonb(NEW) - 'status' - 'approved_by' - 'approved_at' - 'completed_at'
            - 'certificate_sha256' - 'updated_at' - 'updated_by')
         IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'approved_by' - 'approved_at' - 'completed_at'
            - 'certificate_sha256' - 'updated_at' - 'updated_by') THEN
    RAISE EXCEPTION 'Quản trị chỉ đổi status, approved_by, approved_at của yêu cầu xử lý kho (BR-195)'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER handover_admin_columns BEFORE UPDATE ON exec.handover
  FOR EACH ROW EXECUTE FUNCTION exec.handover_admin_columns();

-- Two-person control (BR-195): requested_by and approved_by are the people acting, not values a
-- caller may type. The requester is whoever inserts the row; approval is a second, separate act by
-- whoever sets approved_by, once; the CHECK approved_by <> requested_by then means two people.
CREATE FUNCTION exec.handover_actors() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  actor uuid := NULLIF(current_setting('app.user_id', true), '')::uuid;
BEGIN
  IF current_user NOT IN ('svc_exec', 'svc_exec_worker') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF actor IS NULL OR NEW.requested_by IS DISTINCT FROM actor THEN
      RAISE EXCEPTION 'Người yêu cầu phải là người đang thao tác (BR-195)' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN
      RAISE EXCEPTION 'Duyệt là một bước riêng của người thứ hai, không ghi cùng yêu cầu (BR-195)'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.requested_by IS DISTINCT FROM OLD.requested_by THEN
    RAISE EXCEPTION 'Không đổi được người yêu cầu (BR-195)' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
    IF OLD.approved_by IS NOT NULL OR actor IS NULL OR NEW.approved_by IS DISTINCT FROM actor THEN
      RAISE EXCEPTION 'Người duyệt phải là người đang thao tác và chỉ duyệt một lần (BR-195)'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
    NEW.approved_at := now();
  ELSIF NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
    RAISE EXCEPTION 'approved_at do CSDL ghi khi duyệt (BR-195)' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER handover_actors BEFORE INSERT OR UPDATE ON exec.handover
  FOR EACH ROW EXECUTE FUNCTION exec.handover_actors();

-- A handover acts on one vault: its own owner's. Bound when the row is written, because the
-- completion below runs as definer for an admin and must never reach another leader's vault.
-- SECURITY DEFINER so the admin path (no app.user_id) can see the vault it checks.
CREATE FUNCTION exec.handover_vault_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM exec.vault v
                 WHERE v.id = NEW.vault_id AND v.owner_id = NEW.owner_id AND v.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'Yêu cầu rời vị trí phải đúng kho của chủ kho (BR-195)' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER handover_vault_guard BEFORE INSERT OR UPDATE OF vault_id, owner_id, org_id ON exec.handover
  FOR EACH ROW EXECUTE FUNCTION exec.handover_vault_guard();

-- covers: exec.handover#1
-- SECURITY DEFINER: AC05/AC06 complete a handover for another owner and the vault policy has no
-- admin branch. sealed_read_until is the vault's contract term (set with exit_policy); the seal
-- keeps it. The worker deletes the Transit key on exec.vault.shred_requested (BR-195).
CREATE FUNCTION exec.handover_complete() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  v exec.vault%ROWTYPE;
BEGIN
  IF NEW.kind IN ('seal', 'selective_handover') THEN
    -- A selective handover ends sealed too (UC-16-06 postcondition). The owner reads the sealed
    -- vault until sealed_read_until: the contract's term when the vault carries one, else the
    -- default 24 months (UC-16-06 step 3); past it the worker shreds (reason sealed_expired).
    UPDATE exec.vault SET status = 'sealed', sealed_at = coalesce(sealed_at, now()),
      sealed_read_until = coalesce(sealed_read_until, (now() + interval '24 months')::date),
      contract_ref = coalesce(NEW.contract_ref, contract_ref)
    WHERE id = NEW.vault_id AND owner_id = NEW.owner_id AND org_id = NEW.org_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Yêu cầu rời vị trí không khớp kho của chủ kho (BR-195)' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW.kind = 'shred' THEN
    UPDATE exec.vault SET status = 'shredded', shredded_at = now()
    WHERE id = NEW.vault_id AND owner_id = NEW.owner_id AND org_id = NEW.org_id
    RETURNING * INTO v;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Yêu cầu rời vị trí không khớp kho của chủ kho (BR-195)' USING ERRCODE = 'check_violation';
    END IF;
    INSERT INTO exec.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
    VALUES (gen_random_uuid(), NEW.org_id, 'vault', NEW.vault_id, 'exec.vault.shred_requested',
            jsonb_build_object('vault_id', NEW.vault_id, 'handover_id', NEW.id, 'owner_id', NEW.owner_id,
                               'transit_key_name', v.transit_key_name,
                               'transit_key_version', v.transit_key_version));
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER handover_complete AFTER UPDATE OF status ON exec.handover
  FOR EACH ROW WHEN (NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed')
  EXECUTE FUNCTION exec.handover_complete();

-- The successor cannot read or change exec.handover (owner_only), yet A3 has :accept complete
-- the handover once every item is imported. This is the one thing the successor may do to it:
-- complete a selective handover addressed to them whose items are all imported (the daily cleanup
-- may already have removed imported rows, so "none left unimported" is the test).
CREATE FUNCTION exec.handover_accept(p_handover_id uuid) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  me uuid := NULLIF(current_setting('app.user_id', true), '')::uuid;
  org uuid := NULLIF(current_setting('app.org_id', true), '')::uuid;
  h exec.handover%ROWTYPE;
BEGIN
  SELECT * INTO h FROM exec.handover
   WHERE id = p_handover_id AND org_id = org AND successor_id = me
     AND kind = 'selective_handover'
   FOR UPDATE;
  IF NOT FOUND OR me IS NULL THEN
    RETURN NULL;
  END IF;
  IF h.status NOT IN ('approved', 'in_progress') OR h.items_total = 0
     OR EXISTS (SELECT 1 FROM exec.handover_item i
                 WHERE i.handover_id = h.id AND i.imported_at IS NULL) THEN
    RETURN h.status;
  END IF;
  UPDATE exec.handover SET status = 'completed', completed_at = now(), updated_at = now()
   WHERE id = h.id;
  RETURN 'completed';
END $$;
REVOKE EXECUTE ON FUNCTION exec.handover_accept(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.handover_accept(uuid) TO svc_exec;

-- UC-16-06 precondition: the successor has an active vault. svc_exec sees only the caller's own
-- vault, so this answers yes or no for one user of the caller's organisation, nothing more.
CREATE FUNCTION exec.successor_has_active_vault(p_successor_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
  SELECT EXISTS (SELECT 1 FROM exec.vault v
                  WHERE v.owner_id = p_successor_id AND v.status = 'active'
                    AND v.org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
$$;
REVOKE EXECUTE ON FUNCTION exec.successor_has_active_vault(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.successor_has_active_vault(uuid) TO svc_exec;

-- ─── exec.handover_item ───

-- covers: exec.handover_item#0
CREATE POLICY owner_insert ON exec.handover_item AS RESTRICTIVE FOR INSERT TO svc_exec
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY successor_read ON exec.handover_item AS RESTRICTIVE FOR SELECT TO svc_exec
  USING (successor_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY successor_update ON exec.handover_item AS RESTRICTIVE FOR UPDATE TO svc_exec
  USING (successor_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (successor_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
REVOKE UPDATE, DELETE ON exec.handover_item FROM svc_exec;
GRANT UPDATE (imported_at) ON exec.handover_item TO svc_exec;

-- covers: exec.handover_item#1
CREATE FUNCTION exec.handover_item_guard_insert() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM exec.handover h WHERE h.id = NEW.handover_id
                   AND h.kind = 'selective_handover' AND h.status IN ('approved', 'in_progress')
                   AND h.owner_id = NEW.owner_id AND h.successor_id = NEW.successor_id) THEN
    RAISE EXCEPTION 'Mục bàn giao cần yêu cầu selective_handover đã duyệt hoặc đang chạy, cùng chủ kho và người nhận (BR-195)'
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE exec.handover SET items_total = items_total + 1 WHERE id = NEW.handover_id;
  RETURN NEW;
END $$;
CREATE TRIGGER handover_item_guard_insert BEFORE INSERT ON exec.handover_item
  FOR EACH ROW EXECUTE FUNCTION exec.handover_item_guard_insert();
-- The daily cleanup is the one DELETE of schema exec: imported rows, or rows older than 30 days.
-- It runs without a user (app.user_id), so it is a function svc_exec may call, scoped by
-- org_isolation, rather than a DELETE grant the successor-only policies would block.
CREATE FUNCTION exec.handover_item_cleanup() RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  n integer;
BEGIN
  DELETE FROM exec.handover_item
  WHERE org_id = NULLIF(current_setting('app.org_id', true), '')::uuid
    AND (imported_at IS NOT NULL OR created_at < now() - interval '30 days');
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;
REVOKE EXECUTE ON FUNCTION exec.handover_item_cleanup() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION exec.handover_item_cleanup() TO svc_exec;

-- ─── exec.publication ───

-- covers: exec.publication#0
REVOKE DELETE ON exec.publication FROM svc_exec;
CREATE POLICY owner_only ON exec.publication AS RESTRICTIVE FOR ALL TO svc_exec
  USING (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid)
  WITH CHECK (owner_id = NULLIF(current_setting('app.user_id', true), '')::uuid);
-- svc_context (through exec_read) reads only what a hypothesis page may show; page readers are
-- then filtered by the page's own policy (BR-163, BR-194).
CREATE POLICY context_source ON exec.publication AS RESTRICTIVE FOR SELECT TO exec_read
  USING (status IN ('pending_review', 'published'));

-- covers: exec.publication#1
CREATE FUNCTION exec.publication_guard_insert() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM exec.thesis t WHERE t.id = NEW.thesis_id AND t.owner_id = NEW.owner_id
                   AND t.status IN ('open', 'scored') AND t.due_at = NEW.due_at) THEN
    RAISE EXCEPTION 'Bản công bố cần luận điểm cùng chủ kho, ở open hoặc scored, cùng due_at (BR-194)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER publication_guard_insert BEFORE INSERT ON exec.publication
  FOR EACH ROW EXECUTE FUNCTION exec.publication_guard_insert();

-- covers: exec.publication#2
CREATE FUNCTION exec.publication_emit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO exec.outbox (id, org_id, aggregate_type, aggregate_id, event_type, payload)
  VALUES (gen_random_uuid(), NEW.org_id, 'publication', NEW.id, 'exec.publication.' || NEW.status,
          jsonb_build_object('publication_id', NEW.id, 'thesis_id', NEW.thesis_id,
                             'knowledge_page_id', NEW.knowledge_page_id,
                             'target_data_space_id', NEW.target_data_space_id, 'status', NEW.status));
  RETURN NULL;
END $$;
CREATE TRIGGER publication_emit AFTER UPDATE OF status ON exec.publication
  FOR EACH ROW WHEN (NEW.status IN ('published', 'withdrawn') AND NEW.status IS DISTINCT FROM OLD.status)
  EXECUTE FUNCTION exec.publication_emit();

-- covers: exec.publication#3 (no DDL here: the D4.5 amendment is context.knowledge_page#2, knowledge_page_version#5, knowledge_source_link#3 in routines/context.sql)
-- covers: exec.publication#4 (no DDL: page RLS unchanged; hypothesis pages excluded as figure or evidence sources by the answer and Evidence agents, G9.5, BR-190)

SELECT public.da_ensure_month_partitions(3);
RESET ROLE;
